        // v1.0.160.78: per-run MCP call collection for AI_ALERT_McpCall. LogToolEvent is STATIC, so
        // this cannot be an instance list. Bounded: capped per run, pruned by age, removed on drain --
        // a failed run never drains, and without those guards the pool would grow without limit.
        private static readonly System.Collections.Concurrent.ConcurrentDictionary<string, Tuple<DateTime, List<JObject>>>
            _mcpCollect = new System.Collections.Concurrent.ConcurrentDictionary<string, Tuple<DateTime, List<JObject>>>();
        private static readonly int _mcpMaxPerRun = ClampCfg(ReadInt("McpCallMaxPerRun", 40), 1, 200);

        private static void McpCollect(string runId, JObject entry)
        {
            try
            {
                if (!_auditDbEnabled || string.IsNullOrEmpty(runId) || entry == null) { return; }
                // prune anything abandoned by a run that never completed
                DateTime cut = DateTime.UtcNow.AddMinutes(-30);
                foreach (KeyValuePair<string, Tuple<DateTime, List<JObject>>> kv in _mcpCollect)
                {
                    if (kv.Value != null && kv.Value.Item1 < cut)
                    { Tuple<DateTime, List<JObject>> gone; _mcpCollect.TryRemove(kv.Key, out gone); }
                }
                Tuple<DateTime, List<JObject>> slot = _mcpCollect.GetOrAdd(runId,
                    k => new Tuple<DateTime, List<JObject>>(DateTime.UtcNow, new List<JObject>()));
                lock (slot.Item2)
                {
                    if (slot.Item2.Count < _mcpMaxPerRun) { slot.Item2.Add(entry); }
                }
            }
            catch { }
        }

        private static List<JObject> McpDrain(string runId)
        {
            try
            {
                Tuple<DateTime, List<JObject>> slot;
                if (string.IsNullOrEmpty(runId) || !_mcpCollect.TryRemove(runId, out slot) || slot == null) { return null; }
                return slot.Item2;
            }
            catch { return null; }
        }
