        private void AddDiag(string code)
        {
            lock (_jsonDiagLock)
            {
                if (_jsonDiag != null && _jsonDiag.Count < 8) { _jsonDiag.Add(code); }
            }
        }

        private string SnapshotDiag()
        {
            lock (_jsonDiagLock)
            {
                if (_jsonDiag == null || _jsonDiag.Count == 0) { return ""; }
                int n = Math.Min(3, _jsonDiag.Count);
                string[] copy = new string[n];
                for (int i = 0; i < n; i++) { copy[i] = _jsonDiag[i]; }
                return string.Join("; ", copy);
            }
        }

        private async Task AwaitWithCancel(Task t, System.Threading.CancellationToken ct, int bgWeight = 1)
        {
            if (!ct.CanBeCanceled) { await t.ConfigureAwait(false); return; }
            Task done = await Task.WhenAny(t, Task.Delay(System.Threading.Timeout.Infinite, ct)).ConfigureAwait(false);
            if (done != t)
            {
                RegisterAbandoned(t, bgWeight);
                ct.ThrowIfCancellationRequested();
            }
            await t.ConfigureAwait(false);
        }

