        // SL 1: set when K2 could not run on an asset where it SHOULD have; surfaced in caveats so
        // the ABSENCE of the check is visible to the reader, not just to a server log.
        private string _circuitSkipReason;

        private bool IsTrackAssetForCircuit()
        {
            try
            {
                string at = (GetCtx(_prefetchCtx, "assetType") ?? "").ToUpperInvariant();
                if (at.Length > 0) { return at.Contains("TRACK"); }
                // assetType can still be empty on some paths -- fall back to the cause code, which is
                // what every other asset-type branch in this file already does.
                string cc = (GetCtx(_prefetchCtx, "causeCode") ?? "").ToUpperInvariant();
                return cc.StartsWith("TC ") || cc.Contains("RAIL RES") || cc.Contains("BALST");
            }
            catch { return false; }
        }

        // CUT C: wisdom attribution. Ids are internal taxonomy -- trace/audit only, never a browser.
        private readonly JArray _wisdomInjected = new JArray();
        private JArray _wisdomUsed;
        private bool _wisdomIdStripLogged;

        private static readonly Regex _numberedRuleRx = new Regex(@"^\s*\d+[.)]\s", RegexOptions.Compiled);

        private string TagWisdomBlock(string block, string prefix)
        {
            if (string.IsNullOrEmpty(block)) { return block; }
            try
            {
                string[] lines = block.Split(new char[] { '\n' });
                StringBuilder sb = new StringBuilder();
                int n = 0;
                for (int i = 0; i < lines.Length; i++)
                {
                    string t = lines[i].TrimStart();
                    bool isRule = t.StartsWith("- ") || t.StartsWith("* ") || t.StartsWith("[")
                                  || _numberedRuleRx.IsMatch(t);
                    if (isRule && t.Length > 12)
                    {
                        n++;
                        string id = prefix + "-" + n.ToString("000");
                        sb.Append("[").Append(id).Append("] ").Append(lines[i]).Append("\n");
                        JObject rec = new JObject();
                        rec["id"] = id;
                        rec["chars"] = lines[i].Length;
                        rec["preview"] = t.Length > 70 ? t.Substring(0, 70) : t;
                        _wisdomInjected.Add(rec);
                    }
                    else { sb.Append(lines[i]).Append("\n"); }
                }
                return sb.ToString();
            }
            catch { return block; }
        }

        // Prose backstop: the instruction-echo scrub matches >=12-word verbatim runs and cannot catch
        // a three-token rule id. A rule id in prose discloses internal doctrine taxonomy.
        private static readonly Regex _wisdomIdRx = new Regex(
            @"\[?\b(?:DOC|FLD|CIR|CHK|LRN)-\d{2,4}\b\]?", RegexOptions.IgnoreCase | RegexOptions.Compiled);

        private string ScrubWisdomIds(string v)
        {
            if (string.IsNullOrEmpty(v)) { return v; }
            if (!_wisdomIdRx.IsMatch(v)) { return v; }
            if (!_wisdomIdStripLogged)
            {
                _wisdomIdStripLogged = true;
                AiLog("WARN", "WISDOM", "a wisdom rule id reached user-visible prose and was stripped");
            }
            return _wisdomIdRx.Replace(v, "").Replace("  ", " ");
        }

        // SL 3: actions that FOLLOW from the category, so they do not vary run to run. Deliberately a
        // short list -- only where the category itself already decided the outcome.
        private static string DeterministicAction(string category)
        {
            if (string.IsNullOrEmpty(category)) { return null; }
            if (category.Equals("Transient - no action", StringComparison.OrdinalIgnoreCase))
            { return "No action for this alert. Monitor; raise a job only if it recurs."; }
            if (category.Equals("Derived artifact", StringComparison.OrdinalIgnoreCase))
            { return "No field action. The breach is a computation artefact, not a measured fault."; }
            if (category.Equals("Coverage gap", StringComparison.OrdinalIgnoreCase))
            { return "No conclusion possible from the available history. Re-run once coverage is restored."; }
            return null;
        }

        // Remove a clause that justifies work by the ML standing condition. That finding has its own
        // band and its own action; folding it in here turned "monitor" into "schedule".
        private static readonly Regex _standingClauseRx = new Regex(
            @"\s*(?:;|,|\.|--)?\s*(?:per|as per|due to|because of|given|citing|based on)\s+(?:the\s+)?ML[^.;]*",
            RegexOptions.IgnoreCase | RegexOptions.Compiled);

        private static string StripStandingConditionClause(string v)
        {
            if (string.IsNullOrEmpty(v)) { return v; }
            if (v.IndexOf("ML", StringComparison.Ordinal) < 0) { return v; }
            string o = _standingClauseRx.Replace(v, "").Trim();
            o = o.TrimEnd(';', ',', ' ');
            if (o.Length > 0 && !o.EndsWith(".")) { o += "."; }
            return o.Length >= 8 ? o : v;
        }

        // What a browser may see of the 7W audit. Static by necessity -- called with no instance.
        private static JObject RedactAuditForClient(JObject a7, bool privileged)
        {
            if (a7 == null) { return null; }
            try
            {
                JObject c = (JObject)a7.DeepClone();
                if (privileged) { return c; }
                JObject which = c["which"] as JObject;
                if (which != null)
                {
                    if (which["engine"] != null) { which["engine"] = OpaqueProviderId(which["engine"].ToString()); }
                    which.Remove("provider");
                    which.Remove("model");
                }
                JObject where = c["where"] as JObject;
                if (where != null) { where.Remove("providerUrl"); }
                // Field removal handles what is known. This catches what is not: a vendor string added
                // to the audit later, in a field nobody redacts, is stripped before it can leave.
                try
                {
                    string flat = c.ToString(Formatting.None);
                    string clean = ScrubEngineIdentity(flat);
                    if (!string.Equals(flat, clean, StringComparison.Ordinal))
                    {
                        AiLogStatic("WARN", "AUDIT", "a vendor identifier survived field redaction and was scrubbed from the client audit");
                        return JObject.Parse(clean);
                    }
                }
                catch { return null; }
                return c;
            }
            catch { return null; }
        }

