        // v1.0.160.91: INSTANCE, and prefers the captured value. Static + LoginUser cannot work here:
        // by the time the agentic loop filters tools, HttpContext.Current is long gone.
        private bool AiDebugAllowed()
        {
            if (_luSiteKeep) { return true; }                       // captured before the first await
            if (!string.IsNullOrEmpty(_luEmail)
                && IsSiteKeepOverrideEmail(_luEmail)) { return true; }
