        private static bool SafeIsSiteKeeping()
        {
            try
            {
                var u = E7FRSAdvance.Utility.ClsHttpContent.LoginUser;
                if (u == null) { return false; }
                if (u.IsSiteKeeping) { return true; }
                // v1.0.160.4: named test users get site-keeping too (mirrors the view's override).
                // NO AiLog here -- this method is STATIC and AiLog is an instance method (CS0120 in
                // 1.0.160.3). The grant is logged at the call site instead, which has the instance.
                return IsSiteKeepOverrideEmail(u.EmailAddress);
            }
            catch { return false; }   // no session/context -> treat as non-site-keeping (safe default)
        }

        // v1.0.160.2: ALIAS BRIDGE. Alert cards and derived formulas are written in ALIAS names
        // (VTC TFC O/P, ITC FEED END) while telemetry arrives under RDPMS TITLES (Charger OP V,
        // If mA). On 2026-08-08 alert 484640 this cost a verdict: the model reported "VTC TFC O/P
        // and VTC CH FEED END unavailable" and returned INCONCLUSIVE at 40% -- while Charger OP V
        // (7.223 vs the card's 7.22) and Choke V (1.007 vs 1.01) had BOTH been fetched with 12 and
        // 229 samples. The data was there; only the naming was missing. Source: RDPMS_Attributes
        // in the RDSO master workbook.
        private static readonly string[,] _aliasPairs = new string[,]
        {
            { "If mA",        "ITC FEED END" },
            { "Ir mA",        "ITC RELAY END" },
            { "Vf",           "VTC FEED END" },
            { "Vr",           "VTC RELAY END" },
            { "Choke V",      "VTC CH FEED END" },
            { "Charger mA",   "ITC TFC O/P" },
            { "Charger OP V", "VTC TFC O/P" },
            { "Charger V",    "VTC TFC I/P" },
            { "TPR V",        "VTC 24 DC TPR I/P" },
            { "TPR V (Loc)",  "VTC 24 DC LOC" }
        };
        // Only the aliases that actually appear in this alert's formula/description are injected,
        // so the block stays short and every line is relevant to the verdict being made.
        private static string BuildAliasBridge(string formulaAndCard)
        {
            if (string.IsNullOrEmpty(formulaAndCard)) { return ""; }
            string hay = formulaAndCard.ToUpperInvariant();
            StringBuilder b = new StringBuilder();
            for (int i = 0; i < _aliasPairs.GetLength(0); i++)
            {
                string title = _aliasPairs[i, 0], alias = _aliasPairs[i, 1];
                if (hay.IndexOf(alias.ToUpperInvariant(), StringComparison.Ordinal) < 0) { continue; }
                if (b.Length == 0)
                {
                    b.Append("[NAME BRIDGE - the alert card and the formula use ALIAS names; the telemetry above ")
                     .Append("is listed under RDPMS TITLES. These are THE SAME MEASUREMENT. Do NOT report a ")
                     .Append("component as missing because its alias name does not appear in the telemetry:]").Append("\n");
                }
                b.Append("  ").Append(alias).Append("  ==  ").Append(title).Append("\n");
            }
            if (b.Length > 0) { b.Append("\n"); }
            return b.ToString();
        }

        private static string GateNameForAttId(int attId)
        {
            string g;
            return _gateById.TryGetValue(attId, out g) ? g : null;
        }
        private static bool GateIsUngatedId(int attId) { return _gateUngatedIds.Contains(attId); }
        // Point detection only: the relay that must be proven DOWN while the gate is UP.
        private static string GateCounterpart(string gateName)
        {
            if (string.Equals(gateName, "NWKR", StringComparison.OrdinalIgnoreCase)) { return "RWKR"; }
            if (string.Equals(gateName, "RWKR", StringComparison.OrdinalIgnoreCase)) { return "NWKR"; }
            return null;
        }
        private static string GateCanon(string x)
        {
            if (string.IsNullOrEmpty(x)) { return ""; }
            StringBuilder b = new StringBuilder();
            for (int i = 0; i < x.Length; i++)
            {
                char ch = x[i];
                if (char.IsLetterOrDigit(ch)) { b.Append(char.ToUpperInvariant(ch)); }
                else if (ch == '_') { b.Append('_'); }
            }
            return b.ToString();
        }
        // Relay identity is by NAME among the asset's DataLogger relays -- NEVER by AssetAttributeId,
        // because relay ids are asset-specific and collide with analog ids (GatedAverage's own note).
        // Exact canon match wins; otherwise a UNIQUE "_<GATE>" suffix match ("Combined-NWKR");
        // none or ambiguous -> null, fail-closed.
        private static JObject GateRelayRow(string tagsJson, string gateName)
        {
            if (string.IsNullOrEmpty(tagsJson) || string.IsNullOrEmpty(gateName)) { return null; }
            try
            {
                string cg = GateCanon(gateName), suffix = "_" + cg;
                JObject exact = null; int exactN = 0;
                JObject token = null; int tokenN = 0;
                List<JToken> docs = ParseJsonDocuments(tagsJson);
                for (int d = 0; d < docs.Count; d++)
                {
                    foreach (JToken row in docs[d].SelectTokens("$..*"))
                    {
                        JObject o = row as JObject;
                        if (o == null) { continue; }
                        JToken nm = PropCI(o, "AssetAttributeName");
                        if (nm == null) { continue; }
                        JToken rt = PropCI(o, "RoleType");
                        if (rt != null && rt.ToString().IndexOf("DataLogger", StringComparison.OrdinalIgnoreCase) < 0) { continue; }
                        string cn = GateCanon(nm.ToString());
                        if (cn == cg) { exact = o; exactN++; }
                        else if (cn.EndsWith(suffix, StringComparison.Ordinal)) { token = o; tokenN++; }
                    }
                }
                if (exactN == 1) { return exact; }
                if (exactN == 0 && tokenN == 1) { return token; }
            }
            catch { }
            return null;
        }

        private static string AttIdForTag(string tagsJson, string tagId)
        {
            if (string.IsNullOrEmpty(tagsJson) || string.IsNullOrEmpty(tagId)) { return null; }
            try
            {
                List<JToken> docs = ParseJsonDocuments(tagsJson);
                for (int d = 0; d < docs.Count; d++)
                {
                    foreach (JToken row in docs[d].SelectTokens("$..*"))
                    {
                        JObject o = row as JObject;
                        if (o == null) { continue; }
                        JToken tid = PropCI(o, "TagID");
                        if (tid == null) { tid = PropCI(o, "TagId"); }
                        if (tid == null || !string.Equals(tid.ToString(), tagId, StringComparison.Ordinal)) { continue; }
                        JToken att = PropCI(o, "AssetAttributeId");
                        if (att == null) { att = PropCI(o, "AttributeId"); }
                        if (att != null && !string.IsNullOrEmpty(att.ToString())) { return att.ToString(); }
                    }
                }
            }
            catch { }
            return null;
        }

        private async Task<string> HistoryPageToEndAsync(string tool, JToken args, string page1, System.Threading.CancellationToken ct, int owner)
        {
            try
            {
                JObject a = args as JObject;
                if (a == null || a["limit"] == null) { return page1; }
                int lim;
                if (!int.TryParse(a["limit"].ToString(), out lim) || lim <= 0) { return page1; }

                int n = 0; long firstTs = 0, lastTs = 0, winTo = 0;
                if (!HistorySpan(page1, out n, out firstTs, out lastTs, out winTo)) { return page1; }
                if (n < 2 || winTo <= lastTs) { return page1; }

                double spanSec = (double)(lastTs - firstTs);
                if (spanSec <= 0) { return page1; }
                double ratePerSec = (double)(n - 1) / spanSec;
                double rowsToEnd = ratePerSec * (double)(winTo - lastTs);
                int guess = 1 + (int)Math.Ceiling(rowsToEnd / lim);
                if (guess < 2) { guess = 2; }

                string best = null; long bestLast = lastTs; int bestPage = 1;
                int probes = 0, pg = guess;
                while (probes < _histMaxPageProbes && pg >= 2)
                {
                    probes++;
                    JObject pArgs = (JObject)a.DeepClone();
                    pArgs["page"] = pg;
                    string pRes = await CallToolRoutedAsync(tool, pArgs, ct, owner).ConfigureAwait(false);
                    // Initialised at declaration: HistorySpan sits behind a short-circuiting &&, so
                    // the compiler cannot prove these are assigned on the path where pRes is empty.
                    int pn = 0; long pFirst = 0, pLast = 0, pTo = 0;
                    bool ok = !string.IsNullOrEmpty(pRes) && HistorySpan(pRes, out pn, out pFirst, out pLast, out pTo);
                    AiLog("INFO", "HIST", "page probe " + pg + " -> " + (ok ? ("n=" + pn) : "no rows"));
                    if (!ok || pn == 0)
                    {
                        pg--;                                   // overshot the data -- step back
                        if (pg < 2) { break; }
                        continue;
                    }
                    if (pLast > bestLast) { best = pRes; bestLast = pLast; bestPage = pg; }
                    if (pn < lim) { break; }                    // short page = last page
                    if (winTo - pLast <= 3600) { break; }       // reached the window end
                    pg++;                                       // still short -- go forward
                }

                if (best != null)
                {
                    AiLog("INFO", "HIST", "PAGED to page " + bestPage + " for " + tool
                        + " -- series now ends " + Math.Round((double)(winTo - bestLast) / 3600.0, 1)
                        + " h before the window end (page 1 ended "
                        + Math.Round((double)(winTo - lastTs) / 3600.0, 1) + " h before it)");
                    return best;
                }
                AiLog("WARN", "HIST", "paging found no later rows for " + tool + "; keeping page 1");
            }
            catch (Exception pex) { AiLog("WARN", "HIST", "paging failed: " + pex.Message); }
            return page1;
        }

        // n, first/last sample epoch and the requested window end, from a columnar history payload.
        private static bool HistorySpan(string res, out int n, out long firstTs, out long lastTs, out long winTo)
        {
            n = 0; firstTs = 0; lastTs = 0; winTo = 0;
            try
            {
                if (string.IsNullOrEmpty(res)) { return false; }
                System.Text.RegularExpressions.Match mn = _histNRx.Match(res);
                if (!mn.Success || !int.TryParse(mn.Groups[1].Value, out n)) { return false; }
                System.Text.RegularExpressions.Match mto = _histToRx.Match(res);
                if (mto.Success) { long.TryParse(mto.Groups[1].Value, out winTo); }
                System.Text.RegularExpressions.Match mts = _histTsRx.Match(res);
                if (!mts.Success) { return false; }
                string arr = mts.Groups[1].Value;
                if (string.IsNullOrEmpty(arr.Trim())) { return false; }
                // v1.0.160.65: MIN and MAX, not first and last. Taking position for order was only ever
                // safe while every series arrived ascending; 160.38 added sort=desc to the TPR fetch and
                // silently inverted the meaning of "last". min/max is correct under any ordering.
                string[] toks = arr.Split(new char[] { ',' });
                long lo = long.MaxValue, hi = long.MinValue; int parsed = 0;
                for (int i = 0; i < toks.Length; i++)
                {
                    long tv;
                    if (!long.TryParse(toks[i].Trim(), out tv) || tv <= 0) { continue; }
                    if (tv < lo) { lo = tv; }
                    if (tv > hi) { hi = tv; }
                    parsed++;
                }
                if (parsed == 0) { return false; }
                firstTs = lo; lastTs = hi;
                return lastTs > 0;
            }
            catch { }
            return false;
        }

        private bool NoteHistoryTruncation(string tool, JToken args, string res)
        {
            try
            {
                if (string.IsNullOrEmpty(res) || !IsHistoryFamily(tool)) { return false; }
                JObject a = args as JObject;
                if (a == null || a["limit"] == null) { return false; }
                int lim;
                if (!int.TryParse(a["limit"].ToString(), out lim) || lim <= 0) { return false; }
                System.Text.RegularExpressions.Match mn = _histNRx.Match(res);
                if (!mn.Success) { return false; }
                int n;
                if (!int.TryParse(mn.Groups[1].Value, out n)) { return false; }
                string tagId = "";
                System.Text.RegularExpressions.Match mt = _histTagRx.Match(res);
                if (mt.Success) { tagId = mt.Groups[1].Value; }
                string attr = "";
                lock (_trendLock)
                {
                    if (!string.IsNullOrEmpty(tagId) && _tagMeta.ContainsKey(tagId))
                    { attr = (string)_tagMeta[tagId]["attr"] ?? ""; }
                }
                string who = string.IsNullOrEmpty(attr) ? ("tag " + tagId) : attr;
                // v1.0.158.4: n >= requested limit was the WRONG test. The API enforces its own hard
                // cap (500) BELOW what we ask for, so a cut series returns n=500 against limit=5000
                // and the old check never fired. The real signature is the DATA ENDING EARLY: a
                // substantial series whose last sample sits well before the requested window end.
                long lastTs = 0, winTo = 0;
                System.Text.RegularExpressions.Match mto = _histToRx.Match(res);
                if (mto.Success) { long.TryParse(mto.Groups[1].Value, out winTo); }
                System.Text.RegularExpressions.Match mts = _histTsRx.Match(res);
                if (mts.Success)
                {
                    // v1.0.160.66: MIN/MAX, not the last token. This parser is SEPARATE from
                    // HistorySpan (fixed in 160.65) and prints the line operators actually read, so
                    // the sort=desc bug survived here: TPR reported a 50 h gap that did not exist.
                    string arr = mts.Groups[1].Value;
                    string[] tks = arr.Split(new char[] { ',' });
                    long hiTs = 0;
                    for (int ti = 0; ti < tks.Length; ti++)
                    {
                        long tv;
                        if (long.TryParse(tks[ti].Trim(), out tv) && tv > hiTs) { hiTs = tv; }
                    }
                    // The original took the LAST token, which is the OLDEST sample once sort=desc is
                    // used. Those lines are DELETED, not merely preceded -- in 160.66 they still ran
                    // after this and overwrote the value.
                    lastTs = hiTs;
                }
                double shortBySec = (winTo > 0 && lastTs > 0) ? (double)(winTo - lastTs) : 0;
                // A sparse digital tag (TPR: 164 change-records, quiet for hours overnight) also ends
                // "early" and must NOT be called truncated. What marks a CUT series is hitting the
                // API's own row cap: n at or near _histCapHint (measured 500) while data stops short.
                bool cut = (n >= lim) || (n >= (_histCapHint - (_histCapHint / 10)) && shortBySec > 3600);
                if (cut)
                {
                    if (!string.IsNullOrEmpty(attr)) { lock (_trendLock) { _truncatedAttrs.Add(attr); } }
                    AiLog("WARN", "HIST", "TRUNCATED " + who + ": n=" + n + " (asked " + lim
                        + "), last sample is " + Math.Round(shortBySec / 3600.0, 1)
                        + " h BEFORE the window end -- default asc returns the OLDEST rows up to the"
                        + " cap; re-query with sort=desc to reach the recent end.");
                }
                else
                {
                    AiLog("INFO", "HIST", who + ": n=" + n + " of limit " + lim + ", ends "
                        + Math.Round(shortBySec / 3600.0, 1) + " h before window end (not truncated)"
                        + " [span=min/max, order-agnostic since 1.0.160.65]");
                }
                return cut;
            }
            catch { }
            return false;
        }

        private void RegisterTagMeta(string tagId, string attr, bool isTpr, bool isTrigger)
        {
            if (string.IsNullOrEmpty(tagId)) { return; }
            JObject m = new JObject(); m["attr"] = attr ?? ""; m["isTpr"] = isTpr; m["isTrigger"] = isTrigger;
            lock (_trendLock) { _tagMeta[tagId] = m; }
        }

        // v1.0.152.6: a search_tags row belongs to the current asset (or carries no AssetId, in
        // which case it cannot be disqualified). search_tags can return rows for other similarly-
        // named assets, so TPR + derived components must be AssetId-grounded (mirrors PickAlertingTagId).
        private static bool RowAssetOk(JObject o, string assetId, bool allowMissing)
        {
            if (string.IsNullOrEmpty(assetId)) { return true; }
            JToken aid = PropCI(o, "AssetId");
            if (aid == null) { return allowMissing; }   // v1.0.152.7: fail-closed for name-scoped search (allowMissing=false)
            return string.Equals(aid.ToString().Trim(), assetId.Trim(), StringComparison.Ordinal);
        }

        // v1.0.152.6: resolve the DIGITAL TPR state tag grounded to AssetId, preferring EXACT
        // digital-state names over a broad Contains("TPR") (which can match the analog "TPR V").
        private static string ResolveTprTag(string tagsJson, string assetId, bool allowMissing)
        {
            if (string.IsNullOrEmpty(tagsJson)) { return null; }
            // v1.0.160.108: resolve the DIGITAL TPR STATE by the fixed rule AssetId+attid+datatype
            // (attid 6, datatype=DataLogger) -- immune to the attid-6 name collision with the analog
            // "TPR V" (RDPMS). Name chain kept only as a last-ditch fallback.
            return PickTagIdByAttrId(tagsJson, assetId, "6", true)
                ?? TagIdForAttributeNameExactForAsset(tagsJson, "TPR", assetId, allowMissing)
                ?? TagIdForAttributeNameExactForAsset(tagsJson, "TPR STATUS", assetId, allowMissing)
                ?? TagIdForAttributeNameExactForAsset(tagsJson, "TPR STATE", assetId, allowMissing)
                ?? TagIdForAttributeNameExactForAsset(tagsJson, "TPR (LOC)", assetId, allowMissing)
                ?? TagIdForAttributeNameForAsset(tagsJson, "TPR", assetId, allowMissing);
        }

        // v1.0.152.6: EXACT name match, grounded to AssetId.
        private static string TagIdForAttributeNameExactForAsset(string tagsJson, string canonical, string assetId, bool allowMissing)
        {
            if (string.IsNullOrEmpty(tagsJson) || string.IsNullOrEmpty(canonical)) { return null; }
            string want = canonical.ToUpperInvariant().Trim();
            try
            {
                List<JToken> docs = ParseJsonDocuments(tagsJson);
                for (int d = 0; d < docs.Count; d++)
                {
                    foreach (JToken row in docs[d].SelectTokens("$..*"))
                    {
                        JObject o = row as JObject; if (o == null) { continue; }
                        JToken nm = PropCI(o, "AssetAttributeName");
                        JToken tid = PropCI(o, "TagID") ?? PropCI(o, "TagId");
                        if (nm == null || tid == null) { continue; }
                        if (nm.ToString().ToUpperInvariant().Trim() != want) { continue; }
                        if (!RowAssetOk(o, assetId, allowMissing)) { continue; }
                        return tid.ToString();
                    }
                }
            }
            catch { }
            return null;
        }

        // v1.0.152.6: exact-then-Contains name match, grounded to AssetId. Used for the TPR
        // last-resort and every derived formula component (so a synthetic derived line never
        // combines telemetry from different assets).
        private static string TagIdForAttributeNameForAsset(string tagsJson, string canonical, string assetId, bool allowMissing)
        {
            if (string.IsNullOrEmpty(tagsJson) || string.IsNullOrEmpty(canonical)) { return null; }
            List<string> wants = new List<string> { canonical };
            if (canonical.StartsWith("TR V")) { wants.Add("VR"); wants.Add("TR V"); }
            try
            {
                List<JToken> docs = ParseJsonDocuments(tagsJson);
                for (int pass = 0; pass < 2; pass++)
                {
                    for (int d = 0; d < docs.Count; d++)
                    {
                        foreach (JToken row in docs[d].SelectTokens("$..*"))
                        {
                            JObject o = row as JObject; if (o == null) { continue; }
                            JToken nm = PropCI(o, "AssetAttributeName");
                            JToken tid = PropCI(o, "TagID") ?? PropCI(o, "TagId");
                            if (nm == null || tid == null) { continue; }
                            if (!RowAssetOk(o, assetId, allowMissing)) { continue; }
                            string upper = nm.ToString().ToUpperInvariant().Trim();
                            for (int w = 0; w < wants.Count; w++)
                            {
                                bool hit = pass == 0 ? upper == wants[w]
                                    : (upper.IndexOf(wants[w], StringComparison.Ordinal) >= 0 || wants[w].IndexOf(upper, StringComparison.Ordinal) >= 0);
                                if (hit) { return tid.ToString(); }
                            }
                        }
                    }
                }
            }
            catch { }
            return null;
        }

        private static readonly string[] _trendTools = { "history_get", "get_attribute_range_history", "get_hist_realtime" };
        private static readonly string[] _tsKeys = { "ts", "timestamp", "time", "t", "dt", "TimeStamp", "Time" };
        private static readonly string[] _valKeys = { "value", "val", "v", "Value", "Val" };

        // v1.0.149.0: deterministic per-day stats + sensor-health from the harvested
        // trigger-attribute series (checklist items 3/4/5 for TRACK, 2/3/6 for SIGNAL) --
        // computed here so the model reads facts instead of deriving them.
        // v1.0.152.0: assemble the multi-series trend frame the chart consumes. Includes
        // every captured attribute series, marks the trigger and any TPR series, and -- when a
        // TPR series is present -- computes a TRAIN-FREE reference value + threshold for the
        // trigger deterministically (so the chart never shows a train-polluted 0 threshold).
        private JObject BuildTrendFrame()
        {
            JObject tf = new JObject();
            tf["schema"] = 2;
            string trigAttr = _trendCandidate != null && _trendCandidate["attr"] != null ? _trendCandidate["attr"].ToString() : "";
            // v1.0.152.1: is the alert's triggered attribute DERIVED (RRAIL etc.)? Derived attrs
            // have NO telemetry series of their own -- so we plot the drivers, do not compute a
            // derived reference/threshold, and let the client default to all-drivers + normalized.
            string dP, dF; bool isDerived = DetectDerived(_prefetchCtx, out dP, out dF);
            tf["trigger"] = isDerived ? (dP ?? trigAttr) : trigAttr;
            tf["derived"] = isDerived;
            tf["alertTs"] = GetCtx(_prefetchCtx, "time");
            tf["resetTs"] = GetCtx(_prefetchCtx, "resetTime");

            // Resolve the DIGITAL TPR STATE series explicitly (not a broad "TPR" substring, which
            // would also match analog TPR V). Digital state = values are ~0/1 only.
            string tprKey = ResolveTprStateKey();
            List<object[]> tprRaw = null;
            if (tprKey != null) { _trendRawByAttr.TryGetValue(tprKey, out tprRaw); }

            // Build exclusion intervals from RAW TPR (epoch seconds).
            List<double[]> excl = null; string maskStatus = "unavailable";
            if (tprRaw != null && tprRaw.Count >= 2)
            {
                excl = BuildTrainExclusionRaw(tprRaw);
                // coverage: does TPR span the trigger window?
                maskStatus = TprCoversTrigger(tprRaw, trigAttr) ? "complete" : "partial";
            }

            // emit series array (chart uses ~240 downsampled points, + any gap sentinels)
            JArray sarr = new JArray();
            bool aggAnyDriver = false; bool aggAllComplete = true;   // v1.0.152.6: per-series coverage roll-up (for the derived top-level mask status)
            foreach (KeyValuePair<string, JObject> kv in _trendSeriesByAttr)
            {
                JObject so = new JObject();
                bool isTpr = string.Equals(kv.Key, tprKey, StringComparison.OrdinalIgnoreCase);
                bool isTrig = !isDerived && string.Equals(kv.Key, trigAttr, StringComparison.OrdinalIgnoreCase);
                so["attr"] = kv.Value["attr"];
                so["unit"] = GuessUnit(kv.Key);
                so["n"] = kv.Value["n"];
                so["points"] = kv.Value["points"];
                so["isTrigger"] = isTrig;
                so["isTpr"] = isTpr;
                // per-series train-free reference (median/trimmed-mean) on RAW masked data.
                // v1.0.152.5 (P0): coverage is checked PER SERIES -- a driver whose window extends
                // beyond the TPR series must not have out-of-coverage samples treated as train-free.
                if (excl != null && !isTpr)
                {
                    bool cov = tprRaw != null && TprCoversTrigger(tprRaw, kv.Key);
                    aggAnyDriver = true;
                    if (cov)
                    {
                        List<object[]> raw; JObject rf = null;
                        if (_trendRawByAttr.TryGetValue(kv.Key, out raw)) { rf = ComputeTrainFreeRef(raw, excl); }
                        if (rf != null) { so["reference"] = rf; so["maskStatus"] = "complete"; }
                        else { so["maskStatus"] = "insufficient_samples"; aggAllComplete = false; }   // v1.0.152.7: covered, but too few train-free samples for a reference
                    }
                    else { so["maskStatus"] = "partial"; aggAllComplete = false; }
                }
                sarr.Add(so);
            }
            // v1.0.152.3: for a derived alert, synthesize the DERIVED value series (the hero)
            // from the drivers via the card formula and put it FIRST so the chart leads with it.
            if (isDerived)
            {
                JArray dpts = SynthDerivedSeries(dF);
                if (dpts != null && dpts.Count >= 3)
                {
                    JObject dso = new JObject();
                    dso["attr"] = dP ?? "derived";
                    // v1.0.152.6: carry the derived quantity's unit from the alert card (e.g. RRAIL -> Ohm).
                    string dUnit = "";
                    try { JObject _cU = _prefetchCtx != null ? _prefetchCtx["alertCard"] as JObject : null; JArray _tcU = _cU != null ? _cU["triggeredConditions"] as JArray : null; if (_tcU != null && _tcU.Count > 0) { JObject _t0U = _tcU[0] as JObject; if (_t0U != null && _t0U["unit"] != null) { dUnit = _t0U["unit"].ToString(); } } } catch { }
                    dso["unit"] = dUnit;
                    dso["n"] = dpts.Count;
                    dso["points"] = dpts;
                    dso["isTrigger"] = true;    // the derived value IS the alerting quantity
                    dso["isTpr"] = false;
                    dso["isDerived"] = true;
                    sarr.Insert(0, dso);
                    if (_lastSynthMaxAgeSec > 0) { tf["synthMaxDriverAgeSec"] = Math.Round(_lastSynthMaxAgeSec); }
                    if (_lastSynthWorstRejAgeSec > 0) { tf["synthGapMaxAgeSec"] = Math.Round(_lastSynthWorstRejAgeSec); }   // v1.0.152.8: the age that caused the gap
                    if (_lastSynthGapped) { tf["synthGapped"] = true; }
                    lock (_trendLock)
                    {
                        if (_truncatedAttrs.Count > 0)
                        {
                            JArray ta = new JArray();
                            foreach (string tAttr in _truncatedAttrs) { ta.Add(tAttr); }
                            tf["truncatedAttrs"] = ta;   // v1.0.158.3: client says "cut at the row limit", not "no samples"
                        }
                    }
                    if (_lastSynthEvalGapped) { tf["synthEvalGapped"] = true; }   // v1.0.152.9: formula-undefined span broke the line
                    AiLog("INFO", "TREND", "synthesized derived series " + (dP ?? "?") + " n=" + dpts.Count + " from formula" + (_lastSynthGapped ? " (gapped: a driver exceeded the freshness bound)" : ""));
                }
                else { AiLog("INFO", "TREND", "derived series synth failed (drivers/formula unresolved) -- plotting drivers only"); }
            }
            tf["series"] = sarr;

            // mask block
            // v1.0.152.6 (P1): for a DERIVED alert the top-level status must reflect ALL drivers,
            // not just whichever became _trendCandidate -- complete only when every driver is covered.
            if (isDerived && tprRaw != null && aggAnyDriver) { maskStatus = aggAllComplete ? "complete" : "partial"; }
            JObject mask = new JObject();
            mask["status"] = maskStatus;
            mask["excludeSec"] = ClampCfg(ReadInt("AnalyzeTrmExcludeSec", 120), 10, 900);
            tf["mask"] = mask;

            // DIRECT alert: compute + expose the trigger train-free reference (+ carded threshold).
            // DERIVED alert: no derived series -> no top-level reference (drivers carry their own).
            if (!isDerived && excl != null && maskStatus == "complete")
            {
                List<object[]> trigRaw; JObject rf = null;
                if (_trendRawByAttr.TryGetValue(trigAttr, out trigRaw)) { rf = ComputeTrainFreeRef(trigRaw, excl); }
                if (rf != null)
                {
                    tf["refValue"] = rf["median"];
                    // threshold ONLY from a defined source (alert card); else omitted.
                    double cardThr; string thrSrc;
                    if (TryCardThreshold(out cardThr, out thrSrc)) { tf["refThreshold"] = Math.Round(cardThr, 3); tf["refThresholdSource"] = thrSrc; }
                    else { tf["refThresholdSource"] = "none"; }
                    tf["trainExcluded"] = rf["trainExcluded"];
                    tf["trainKept"] = rf["usedSamples"];
                    AiLog("INFO", "TREND", "train mask(raw) applied: kept=" + rf["usedSamples"] + " excluded=" + rf["trainExcluded"] + " status=" + maskStatus + " refMedian=" + rf["median"]);
                }
                else
                {
                    // v1.0.152.7 (P0): TPR covers the window but too few train-free samples remain
                    // -> coverage is complete yet there is NO authoritative reference. Say so.
                    tf["refNote"] = "train mask complete but fewer than the minimum train-free samples remain -- no authoritative reference";
                    tf["referenceStatus"] = "insufficient_samples";
                }
            }
            else if (!isDerived && excl != null)   // v1.0.152.4: exclusion exists but coverage partial
            {
                tf["refNote"] = "train mask partial: TPR does not span the trigger window -- no authoritative train-free reference";
            }
            else if (tprKey == null)
            {
                tf["trainMask"] = "unavailable (no digital TPR state series captured)";
            }

            // v1.0.152.1: legacy top-level attr/n/points (primary series) kept ONE release so the
            // SVG fallback still renders. Primary = trigger series (direct) else the first driver
            // (derived) -- so a derived alert's SVG fallback labels a real DRIVER, not the
            // nonexistent derived series.
            JObject primary = null;
            if (!isDerived && _trendSeriesByAttr.ContainsKey(trigAttr)) { primary = _trendSeriesByAttr[trigAttr]; }
            if (primary == null)
            {
                foreach (KeyValuePair<string, JObject> kv in _trendSeriesByAttr)
                {
                    if (string.Equals(kv.Key, tprKey, StringComparison.OrdinalIgnoreCase)) { continue; }
                    primary = kv.Value; break;
                }
            }
            if (primary != null)
            {
                tf["attr"] = primary["attr"];
                tf["n"] = primary["n"];
                tf["points"] = primary["points"];
            }
            return tf;
        }

        // v1.0.152.3: synthesize the DERIVED value series (e.g. RRAIL) from its driver series,
        // applying the alert card's own formula at each timestamp. The derived attribute has no
        // telemetry tag of its own, so without this the chart shows only the drivers and omits
        // the actual alerting value. Time-alignment: build the union of driver timestamps; at
        // each, bind every formula variable to that driver's value at-or-nearest that time
        // (within a tolerance), evaluate the formula. Returns a points JArray [[isoTs,val]..] or
        // null if the formula/drivers cannot be resolved.
        // v1.0.160.114 CUT E: cap and spike-preserving reduction. Decimation (every Nth point) can
        // drop a single-sample breach entirely; min/max per bucket cannot, because the extreme of
        // each bucket is always kept. Output is [epochSec, value] pairs -- timestamped, so the chart
        // cannot silently rescale time.
        private static readonly int _vizSeriesMaxPts = ClampCfg(ReadInt("VizSeriesMaxPoints", 120), 20, 400);

        private static JArray DownsampleMinMax(List<double[]> pts, int maxPts)
        {
            JArray outArr = new JArray();
            if (pts == null || pts.Count == 0) { return outArr; }
            pts.Sort(delegate (double[] a, double[] b) { return a[0].CompareTo(b[0]); });
            if (pts.Count <= maxPts)
            {
                for (int i = 0; i < pts.Count; i++)
                { JArray p = new JArray(); p.Add((long)pts[i][0]); p.Add(Math.Round(pts[i][1], 3)); outArr.Add(p); }
                return outArr;
            }
            int buckets = Math.Max(1, maxPts / 2);   // each bucket contributes a min AND a max
            double span = pts[pts.Count - 1][0] - pts[0][0];
            if (span <= 0) { span = 1; }
            double width = span / buckets;
            int idx = 0;
            for (int b = 0; b < buckets && idx < pts.Count; b++)
            {
                double lo = pts[0][0] + b * width, hi = lo + width;
                double[] mn = null, mx = null;
                while (idx < pts.Count && (pts[idx][0] < hi || b == buckets - 1))
                {
                    if (mn == null || pts[idx][1] < mn[1]) { mn = pts[idx]; }
                    if (mx == null || pts[idx][1] > mx[1]) { mx = pts[idx]; }
                    idx++;
                }
                if (mn == null) { continue; }
                double[] first = mn[0] <= mx[0] ? mn : mx;
                double[] second = mn[0] <= mx[0] ? mx : mn;
                JArray p1 = new JArray(); p1.Add((long)first[0]); p1.Add(Math.Round(first[1], 3)); outArr.Add(p1);
                if (second[0] != first[0])
                { JArray p2 = new JArray(); p2.Add((long)second[0]); p2.Add(Math.Round(second[1], 3)); outArr.Add(p2); }
            }
            return outArr;
        }

        // Returns the REAL series for the quantity the threshold applies to, or null.
        private JArray RealVizSeries(JObject v, out string source)
        {
            source = "unavailable";
            try
            {
                // Derived alert: the breached quantity IS the derived one, and SynthDerivedSeries
                // already computes it from the drivers via the card formula.
                // The formula is not a field -- DetectDerived yields it, the same call BuildTrendFrame
                // uses. (_derivedFormula does not exist; reading it would not have compiled.)
                string _dP, _dF;
                bool _isDer = DetectDerived(_prefetchCtx, out _dP, out _dF);
                if (_isDer && !string.IsNullOrEmpty(_dF))
                {
                    JArray d = SynthDerivedSeries(_dF);
                    if (d != null && d.Count > 0)
                    {
                        List<double[]> pts = new List<double[]>();
                        for (int i = 0; i < d.Count; i++)
                        {
                            JArray pr = d[i] as JArray;
                            if (pr != null && pr.Count >= 2)
                            { pts.Add(new double[] { (double)pr[0], (double)pr[1] }); }
                        }
                        if (pts.Count > 0) { source = "derived"; return DownsampleMinMax(pts, _vizSeriesMaxPts); }
                    }
                }
                // Otherwise: the trigger attribute's own captured raw series.
                JObject z = v != null ? v["viz"] as JObject : null;
                string metric = (z != null && z["metric"] != null) ? z["metric"].ToString() : "";
                if (metric.Length == 0) { return null; }
                List<object[]> raw = null;
                if (!_trendRawByAttr.TryGetValue(metric, out raw))
                {
                    foreach (KeyValuePair<string, List<object[]>> kv in _trendRawByAttr)
                    {
                        string k = kv.Key ?? "";
                        if (k.Equals(metric, StringComparison.OrdinalIgnoreCase)
                            || k.IndexOf(metric, StringComparison.OrdinalIgnoreCase) >= 0
                            || metric.IndexOf(k, StringComparison.OrdinalIgnoreCase) >= 0)
                        { raw = kv.Value; break; }
                    }
                }
                if (raw == null || raw.Count == 0) { return null; }
                List<double[]> rp = new List<double[]>();
                for (int i = 0; i < raw.Count; i++)
                {
                    object[] r = raw[i];
                    if (r == null || r.Length < 2) { continue; }
                    double ts, val;
                    if (!double.TryParse(Convert.ToString(r[0], System.Globalization.CultureInfo.InvariantCulture),
                            System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out ts)) { continue; }
                    if (!double.TryParse(Convert.ToString(r[1], System.Globalization.CultureInfo.InvariantCulture),
                            System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out val)) { continue; }
                    rp.Add(new double[] { ts, val });
                }
                if (rp.Count == 0) { return null; }
                source = "measured";
                return DownsampleMinMax(rp, _vizSeriesMaxPts);
            }
            catch { source = "unavailable"; return null; }
        }

        private JArray SynthDerivedSeries(string formula)
        {
            if (string.IsNullOrEmpty(formula)) { return null; }
            List<string> vars = ExtractFormulaComponents(formula);
            if (vars == null || vars.Count == 0) { return null; }
            // gather each variable's RAW series as sorted (epochSec,value); match by name against
            // captured attrs (case-insensitive, allow the captured key to contain the var or v/v).
            Dictionary<string, List<double[]>> byVar = new Dictionary<string, List<double[]>>(StringComparer.OrdinalIgnoreCase);
            foreach (string v in vars)
            {
                List<object[]> raw = null;
                if (!_trendRawByAttr.TryGetValue(v, out raw))
                {
                    foreach (KeyValuePair<string, List<object[]>> kv in _trendRawByAttr)
                    {
                        string k = kv.Key ?? "";
                        if (k.Equals(v, StringComparison.OrdinalIgnoreCase)
                            || k.IndexOf(v, StringComparison.OrdinalIgnoreCase) >= 0
                            || v.IndexOf(k, StringComparison.OrdinalIgnoreCase) >= 0)
                        { raw = kv.Value; break; }
                    }
                }
                if (raw == null) { return null; }   // a variable has no captured series -> cannot synth
                List<double[]> pr = new List<double[]>();
                foreach (object[] pt in raw)
                {
                    double ep = TrendTsToEpoch(new JValue(pt[0].ToString()));
                    double vv; if (!double.TryParse(pt[1].ToString(), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out vv)) { continue; }
                    if (!double.IsNaN(ep)) { pr.Add(new double[] { ep, vv }); }
                }
                if (pr.Count < 2) { return null; }
                pr.Sort(delegate(double[] a, double[] c) { return a[0].CompareTo(c[0]); });
                byVar[v] = pr;
            }
            // v1.0.152.8 (P0): build a UNION of every driver's timestamps + the incidence and bind
            // as-of at each. Do NOT clock off the largest series -- at its OWN timestamps its age is
            // ~0, so a STALE BASE DRIVER (the 16.5h IR MA case) evaded the 152.7 freshness bound and
            // the series merely ended early instead of gapping. The incidence timestamp forces an
            // as-of (and a freshness test on EVERY driver) at the alert time itself; the union also
            // makes the derived value update whenever ANY input changes.
            double synthMaxAge = ClampCfg(ReadInt("DerivedSynthMaxAgeSec", 21600), 600, 172800);   // 6h default; operator-tunable
            _lastSynthGapped = false; _lastSynthMaxAgeSec = 0; _lastSynthWorstRejAgeSec = 0; _lastSynthEvalGapped = false;
            SortedSet<double> tsSet = new SortedSet<double>();
            foreach (KeyValuePair<string, List<double[]>> kv in byVar) { for (int pi = 0; pi < kv.Value.Count; pi++) { tsSet.Add(kv.Value[pi][0]); } }
            if (_incidenceEpoch > 0) { tsSet.Add(_incidenceEpoch); }
            List<double> uni = new List<double>(tsSet);
            if (uni.Count < 2) { return null; }
            // full null-aware series on the union timeline (value = NaN marks a gap sentinel)
            List<double[]> full = new List<double[]>();
            bool lastValid = false;
            for (int ui = 0; ui < uni.Count; ui++)
            {
                double t = uni[ui];
                Dictionary<string, double> bind = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
                bool ok = true; double ptMaxAge = 0; bool staleGap = false; double rejAge = 0;
                foreach (string v in vars)
                {
                    double val, ageSec;
                    if (!AsOfValueAt(byVar[v], t, synthMaxAge, out val, out ageSec))
                    {
                        ok = false;
                        if (!double.IsNaN(ageSec)) { staleGap = true; if (ageSec > rejAge) { rejAge = ageSec; } }   // present but older than the bound
                        break;
                    }
                    if (ageSec > ptMaxAge) { ptMaxAge = ageSec; }
                    bind[v] = val;
                }
                if (!ok)
                {
                    if (staleGap)
                    {
                        _lastSynthGapped = true;
                        if (rejAge > _lastSynthWorstRejAgeSec) { _lastSynthWorstRejAgeSec = rejAge; }   // v1.0.152.8 (P1): the age that CAUSED the gap, not the max ACCEPTED age
                        if (lastValid) { full.Add(new double[] { t, double.NaN }); lastValid = false; }   // one null sentinel at the gap boundary
                    }
                    continue;   // no-sample-yet (before this driver starts) -> skip silently
                }
                double dv;
                if (TryEvalFormula(formula, bind, out dv) && !double.IsNaN(dv) && !double.IsInfinity(dv))
                {
                    if (ptMaxAge > _lastSynthMaxAgeSec) { _lastSynthMaxAgeSec = ptMaxAge; }
                    full.Add(new double[] { t, dv }); lastValid = true;
                }
                else
                {
                    // v1.0.152.9 (P1): a mathematically undefined point (formula eval failed / NaN /
                    // Infinity) after a valid segment must break the line exactly like a stale-driver
                    // rejection -- otherwise valid -> undefined -> valid reconnects across the span.
                    if (lastValid) { full.Add(new double[] { t, double.NaN }); lastValid = false; _lastSynthEvalGapped = true; }
                }
            }
            int validCount = 0; for (int fi = 0; fi < full.Count; fi++) { if (!double.IsNaN(full[fi][1])) { validCount++; } }
            if (validCount < 3) { return null; }
            // downsample: ~cap regular picks PLUS every null gap sentinel (output can slightly
            // exceed cap when gaps exist) so the client can break the line at each gap
            int cap = 240;
            List<int> pick = new List<int>();
            if (full.Count <= cap) { for (int fi = 0; fi < full.Count; fi++) { pick.Add(fi); } }
            else
            {
                HashSet<int> chosen = new HashSet<int>();
                for (int bi = 0; bi < cap; bi++) { int ix = (int)(((long)bi * (full.Count - 1) + (cap - 1) / 2) / (cap - 1)); if (ix > full.Count - 1) { ix = full.Count - 1; } chosen.Add(ix); }
                for (int fi = 0; fi < full.Count; fi++) { if (double.IsNaN(full[fi][1])) { chosen.Add(fi); } }   // always keep gap sentinels
                pick = new List<int>(chosen); pick.Sort();
            }
            JArray outPts = new JArray();
            for (int pk = 0; pk < pick.Count; pk++)
            {
                double[] p = full[pick[pk]];
                DateTimeOffset dto = DateTimeOffset.FromUnixTimeSeconds((long)p[0]);
                string iso = dto.ToLocalTime().ToString("yyyy-MM-ddTHH:mm:ss");
                if (double.IsNaN(p[1])) { outPts.Add(new JArray(iso, JValue.CreateNull())); }   // explicit null gap marker (client spanGaps:false)
                else { outPts.Add(new JArray(iso, Math.Round(p[1], 4))); }
            }
            return outPts;
        }

        // v1.0.152.6: AS-OF lookup -- the latest sample AT OR BEFORE t (causal; no future look-ahead,
        // which the old nearest-either-side search allowed). Under change-of-value (deadband)
        // telemetry the last change before t is the held value at t. series is sorted ascending;
        // false only when no sample exists at or before t.
        private static bool AsOfValueAt(List<double[]> series, double t, double maxAgeSec, out double val, out double ageSec)
        {
            val = double.NaN; ageSec = double.NaN; bool found = false; double at = 0;
            for (int i = 0; i < series.Count; i++)
            {
                if (series[i][0] <= t) { val = series[i][1]; at = series[i][0]; found = true; }
                else { break; }
            }
            if (!found) { return false; }
            ageSec = t - at;
            // v1.0.152.7: a driver older than the freshness bound is NOT carried across (a
            // stopped/dead feed would otherwise produce a valid-looking flat derived line). ageSec
            // is set even on this reject so the caller can distinguish stale-gap from no-sample.
            if (maxAgeSec > 0 && ageSec > maxAgeSec) { return false; }
            return true;
        }

        // Resolve which captured attribute is the DIGITAL TPR STATE (values ~0/1), as opposed to
        // analog TPR V. Prefers a raw series whose name contains TPR and whose values are all
        // within {0,1} (+/- tolerance). Returns the attr key or null.
        private string ResolveTprStateKey()
        {
            string best = null;
            foreach (KeyValuePair<string, List<object[]>> kv in _trendRawByAttr)
            {
                // v1.0.152.4: identify TPR by the registered role flag OR the name (registry is
                // authoritative; name is the fallback for model-issued fetches).
                bool metaFlag = false; JObject soT; if (_trendSeriesByAttr.TryGetValue(kv.Key, out soT) && soT["isTpr"] != null) { metaFlag = (bool)soT["isTpr"]; }
                bool nameTpr = kv.Key != null && kv.Key.ToUpperInvariant().IndexOf("TPR", StringComparison.Ordinal) >= 0;
                if (!metaFlag && !nameTpr) { continue; }
                // digital if every value is ~0 or ~1
                bool digital = true; int seen = 0;
                foreach (object[] pt in kv.Value)
                {
                    double vv; if (!double.TryParse(pt[1].ToString(), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out vv)) { continue; }
                    seen++;
                    // v1.0.152.5: accept ONLY values near 0 or near 1 -- the old "<=1.5" test let
                    // 0.7 / 1.4 / negatives pass as digital.
                    bool near0 = vv >= -0.2 && vv <= 0.2;
                    bool near1 = vv >= 0.8 && vv <= 1.2;
                    if (!near0 && !near1) { digital = false; break; }
                }
                if (digital && seen >= 2) { best = kv.Key; break; }
            }
            return best;
        }

        // train-free reference on a RAW series given exclusion intervals (epoch seconds).
        private JObject ComputeTrainFreeRef(List<object[]> raw, List<double[]> excl)
        {
            int minSamp = ClampCfg(ReadInt("AnalyzeTrmMinSamples", 8), 3, 200);
            List<double> keep = new List<double>(); int excluded = 0;
            foreach (object[] pt in raw)
            {
                double ep = TrendTsToEpoch(pt[0] is JToken ? (JToken)pt[0] : new JValue(pt[0].ToString()));
                double vv; if (!double.TryParse(pt[1].ToString(), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out vv)) { continue; }
                if (double.IsNaN(ep)) { continue; }   // v1.0.152.5: cannot prove a sample train-free without a usable timestamp
                bool masked = false;
                for (int i = 0; i < excl.Count; i++) { if (ep >= excl[i][0] && ep <= excl[i][1]) { masked = true; break; } }
                if (masked) { excluded++; } else { keep.Add(vv); }
            }
            if (keep.Count < minSamp) { return null; }
            keep.Sort();
            double med = (keep.Count % 2 == 1) ? keep[keep.Count / 2] : (keep[keep.Count / 2 - 1] + keep[keep.Count / 2]) / 2.0;
            int lo10 = (int)(keep.Count * 0.10), hi10 = (int)(keep.Count * 0.90);
            double tsum = 0; int tcnt = 0; for (int ti = lo10; ti < hi10 && ti < keep.Count; ti++) { tsum += keep[ti]; tcnt++; }
            double trimMean = tcnt > 0 ? tsum / tcnt : med;
            JObject rf = new JObject();
            rf["median"] = Math.Round(med, 3);
            rf["trimmedMean"] = Math.Round(trimMean, 3);
            rf["usedSamples"] = keep.Count;
            rf["trainExcluded"] = excluded;
            return rf;
        }

        // Threshold from the alert card's configured limit, if present. thresholdSource set.
        private bool TryCardThreshold(out double thr, out string src)
        {
            thr = double.NaN; src = null;
            try
            {
                JObject card = _prefetchCtx != null ? _prefetchCtx["alertCard"] as JObject : null;
                JArray tc = card != null ? card["triggeredConditions"] as JArray : null;
                JObject cond = (tc != null && tc.Count > 0) ? tc[0] as JObject : null;
                if (cond == null) { return false; }
                // v1.0.152.4: the real card stores configured limits at triggeredConditions[0]
                // .thresholds[] = [{label,value,unit,status,comparison}]. Prefer the FAIL entry;
                // else the first parseable value. (Scalar keys below kept as a fallback.)
                JArray thrs = cond["thresholds"] as JArray;
                if (thrs != null && thrs.Count > 0)
                {
                    JObject chosen = null;
                    foreach (JToken tk2 in thrs) { JObject to = tk2 as JObject; if (to == null) { continue; } string st = to["status"] != null ? to["status"].ToString().ToUpperInvariant() : ""; if (st == "FAIL") { chosen = to; break; } if (chosen == null) { chosen = to; } }
                    if (chosen != null && chosen["value"] != null)
                    {
                        double dv2; if (double.TryParse(chosen["value"].ToString(), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out dv2)) { thr = dv2; string lbl2 = chosen["label"] != null ? chosen["label"].ToString() : "threshold"; src = "alertCard:thresholds[" + lbl2 + "]"; return true; }
                    }
                }
                string[] keys = { "threshold", "limit", "thresholdValue", "setValue", "value" };
                foreach (string k in keys)
                {
                    JToken t = PropCI(cond, k);
                    if (t != null && t.Type != JTokenType.Null)
                    {
                        double d; if (double.TryParse(t.ToString(), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out d)) { thr = d; src = "alertCard:" + k; return true; }
                    }
                }
            }
            catch { }
            return false;
        }

        // does the raw TPR series cover the trigger series time window?
        private bool TprCoversTrigger(List<object[]> tprRaw, string trigAttr)
        {
            // v1.0.152.4: cannot confirm coverage without a trigger series -> NOT complete (was
            // returning true, wrongly claiming authority).
            List<object[]> trig; if (!_trendRawByAttr.TryGetValue(trigAttr ?? "", out trig) || trig.Count < 2) { return false; }
            // v1.0.152.4: use MIN/MAX epoch, not positional first/last -- a latest-first history
            // response would otherwise invert the window and mis-judge coverage.
            double tLo, tHi, pLo, pHi;
            if (!SpanEpoch(trig, out tLo, out tHi) || !SpanEpoch(tprRaw, out pLo, out pHi)) { return false; }
            return pLo <= tLo + 1 && pHi >= tHi - 1;
        }

        // v1.0.152.4: min/max parsed epoch over a raw series; false if fewer than 2 parse.
        private static bool SpanEpoch(List<object[]> raw, out double lo, out double hi)
        {
            lo = double.MaxValue; hi = double.MinValue; int seen = 0;
            for (int i = 0; i < raw.Count; i++)
            {
                double ep = TrendTsToEpoch(new JValue(raw[i][0].ToString()));
                if (double.IsNaN(ep)) { continue; }
                if (ep < lo) { lo = ep; } if (ep > hi) { hi = ep; } seen++;
            }
            return seen >= 2;
        }

        // best-effort unit from attribute name (mA / V), else "".
        private static string GuessUnit(string attr)
        {
            if (string.IsNullOrEmpty(attr)) { return ""; }
            string u = attr.ToUpperInvariant();
            if (u.Contains("MA")) { return "mA"; }
            if (u.EndsWith(" V") || u.Contains(" V ") || u.Contains("VOLT")) { return "V"; }
            return "";
        }

        // Build [startEpoch,endEpoch] exclusion intervals from a TPR series: any span while
        // TPR value <= 0.5 (dropped = occupied), padded by AnalyzeTrmExcludeSec on each side,
        // plus a +/-window around every 0<->1 transition. Epoch seconds.
        // v1.0.152.1: exclusion intervals from a RAW TPR series (epoch seconds). Sorts and
        // dedupes by time, builds occupied spans (down..next up) + a +/-window around each real
        // 0<->1 transition, then MERGES overlapping intervals. Two-pointer filtering in
        // ComputeTrainFreeRef consumes these.
        private List<double[]> BuildTrainExclusionRaw(List<object[]> tprRaw)
        {
            List<double[]> ex = new List<double[]>();
            if (tprRaw == null || tprRaw.Count < 2) { return ex; }
            int win = ClampCfg(ReadInt("AnalyzeTrmExcludeSec", 120), 10, 900);
            // parse to (epochSec, value), drop unparseable, sort by time, dedupe identical ts
            List<double[]> pts = new List<double[]>();
            foreach (object[] pt in tprRaw)
            {
                double ep = TrendTsToEpoch(new JValue(pt[0].ToString()));
                double vv; if (!double.TryParse(pt[1].ToString(), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out vv)) { continue; }
                if (double.IsNaN(ep)) { continue; }
                pts.Add(new double[] { ep, vv });
            }
            if (pts.Count < 2) { return ex; }
            pts.Sort(delegate(double[] a, double[] c) { return a[0].CompareTo(c[0]); });
            double prevV = double.NaN, prevT = double.NaN, dropStart = double.NaN;
            for (int i = 0; i < pts.Count; i++)
            {
                double ep = pts[i][0], vv = pts[i][1];
                if (!double.IsNaN(prevT) && ep == prevT) { continue; }   // dedupe same ts
                bool dropped = vv <= 0.5;
                if (!double.IsNaN(prevV) && ((prevV <= 0.5) != dropped)) { ex.Add(new double[] { ep - win, ep + win }); }
                if (dropped && double.IsNaN(dropStart)) { dropStart = ep; }
                if (!dropped && !double.IsNaN(dropStart)) { ex.Add(new double[] { dropStart - win, ep + win }); dropStart = double.NaN; }
                prevV = vv; prevT = ep;
            }
            if (!double.IsNaN(dropStart)) { ex.Add(new double[] { dropStart - win, prevT + win }); }
            // merge overlapping intervals
            if (ex.Count <= 1) { return ex; }
            ex.Sort(delegate(double[] a, double[] c) { return a[0].CompareTo(c[0]); });
            List<double[]> merged = new List<double[]>();
            double[] curi = ex[0];
            for (int i = 1; i < ex.Count; i++)
            {
                if (ex[i][0] <= curi[1]) { if (ex[i][1] > curi[1]) { curi[1] = ex[i][1]; } }
                else { merged.Add(curi); curi = ex[i]; }
            }
            merged.Add(curi);
            return merged;
        }

        // Parse a trend point timestamp (ISO local "yyyy-MM-ddTHH:mm:ss", E7 "HH:mm:ss/dd.MM.yyyy",
        // or epoch string) to epoch SECONDS. NaN on failure.
        private static double TrendTsToEpoch(JToken tsTok)
        {
            if (tsTok == null) { return double.NaN; }
            string str = tsTok.ToString();
            System.Text.RegularExpressions.Match m = System.Text.RegularExpressions.Regex.Match(str, "^(\\d{2}):(\\d{2}):(\\d{2})/(\\d{2})\\.(\\d{2})\\.(\\d{4})$");
            if (m.Success) { str = m.Groups[6].Value + "-" + m.Groups[5].Value + "-" + m.Groups[4].Value + "T" + m.Groups[1].Value + ":" + m.Groups[2].Value + ":" + m.Groups[3].Value; }
            DateTime dt;
            if (DateTime.TryParse(str, System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.AssumeLocal, out dt))
            {
                return (dt.ToUniversalTime() - new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc)).TotalSeconds;
            }
            long ep; if (long.TryParse(str, out ep)) { return ep < 100000000000L ? ep : ep / 1000.0; }
            return double.NaN;
        }

        // v1.0.151.0: SIGNAL ASPECT DETECTION -- ported from the tested Debouncer
        // (ProcessService AspectPattern / drive-proving logic). A signal aspect is ACTIVE
        // only when its ECR relay is PROVED: RG<-RECR, HG<-HR+HECR, DG<-DR+DECR, HHG<-HR+
        // HHR+HHECR, shunt OFF<-HR+OFFECR. Averaging a signal's V/mA is only meaningful
        // while the RESPECTIVE aspect is active -- so the analysis prompt is told to average
        // only aspect-active samples and which relay proves each aspect. (Point machine:
        // only the commanded-end operation samples, i.e. the CR/KR side that was driven.)
        private static readonly string[][] _aspectProof = new string[][] {
            new string[] { "RG",  "RECR" },
            new string[] { "HG",  "HR", "HECR" },
            new string[] { "DG",  "DR", "DECR" },
            new string[] { "HHG", "HR", "HHR", "HHECR" },
            new string[] { "SH_OFF", "HR", "OFFECR" }
        };

        // v1.0.151.1: POINT-MACHINE INDICATION -- the point equivalent of a signal's
        // active aspect. From the Debouncer CR/KR pair model (ProcessService PMPendingBatch):
        // NWKR = Normal indication relay (point proved sitting NORMAL), RWKR = Reverse
        // indication relay (proved REVERSE); NWCR/RWCR are the control (commanded) relays.
        // A point operation's electricals are only meaningful for the end whose INDICATION
        // relay is up -- averaging current/voltage when no indication is proved (mid-stroke,
        // or indication lost) is not the operation's signature.
        private static readonly string[][] _pointIndication = new string[][] {
            new string[] { "NORMAL",  "NWKR", "(commanded by NWCR)" },
            new string[] { "REVERSE", "RWKR", "(commanded by RWCR)" }
        };

        private static string BuildPointIndicationNote()
        {
            // v1.0.151.2: built FROM _pointIndication so there is one source of truth
            // (was hardcoded separately -- the two could drift).
            StringBuilder b = new StringBuilder();
            b.Append("Point INDICATION proves which end the point sits at: ");
            for (int i = 0; i < _pointIndication.Length; i++)
            {
                string[] row = _pointIndication[i];
                b.Append(row[0]).Append("<-").Append(row[1]).Append(" up ").Append(row[2]);
                b.Append(i == _pointIndication.Length - 1 ? ". " : ", ");
            }
            b.Append("If no indication is up the point is mid-stroke or indication is LOST -- ");
            b.Append("those samples are not a settled operation.");
            return b.ToString();
        }

        // Human-readable "which relay proves which aspect" block for the analysis prompt.
        private static string BuildAspectProofNote()
        {
            StringBuilder b = new StringBuilder();
            b.Append("Aspect is ACTIVE only when its ECR relay is proved: ");
            for (int i = 0; i < _aspectProof.Length; i++)
            {
                string[] row = _aspectProof[i];
                b.Append(row[0]).Append("<-");
                for (int j = 1; j < row.Length; j++) { if (j > 1) { b.Append("+"); } b.Append(row[j]); }
                b.Append(i == _aspectProof.Length - 1 ? "." : "; ");
            }
            return b.ToString();
        }

        private string BuildComputedTrendBlock()
        {
            try
            {
                JObject tc = _trendCandidate;
                JArray pts = tc != null ? tc["points"] as JArray : null;
                if (pts == null || pts.Count < 5) { return null; }
                List<KeyValuePair<DateTime, double>> series = new List<KeyValuePair<DateTime, double>>();
                foreach (JToken pt in pts)
                {
                    JArray pa = pt as JArray; if (pa == null || pa.Count < 2) { continue; }
                    DateTime dt; double dv;
                    string tsr = pa[0].ToString();
                    // E7 "HH:mm:ss/dd.MM.yyyy" -> ISO
                    System.Text.RegularExpressions.Match m = System.Text.RegularExpressions.Regex.Match(tsr, "^(\\d{2}):(\\d{2}):(\\d{2})/(\\d{2})\\.(\\d{2})\\.(\\d{4})$");
                    if (m.Success) { tsr = m.Groups[6].Value + "-" + m.Groups[5].Value + "-" + m.Groups[4].Value + "T" + m.Groups[1].Value + ":" + m.Groups[2].Value + ":" + m.Groups[3].Value; }
                    if (!DateTime.TryParse(tsr, System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.AssumeLocal, out dt)) { continue; }
                    if (!double.TryParse(pa[1].ToString(), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out dv)) { continue; }
                    series.Add(new KeyValuePair<DateTime, double>(dt, dv));
                }
                if (series.Count < 5) { return null; }
                series.Sort(delegate(KeyValuePair<DateTime, double> a, KeyValuePair<DateTime, double> b) { return a.Key.CompareTo(b.Key); });
                StringBuilder sbTrend = new StringBuilder();
                int _fetchedN = 0; try { if (tc["n"] != null) { int.TryParse(tc["n"].ToString(), out _fetchedN); } } catch { }
                if (_fetchedN > series.Count)
                {
                    sbTrend.Append("=== COMPUTED TREND & SENSOR HEALTH (deterministic; stats from ").Append(series.Count).Append(" sampled points out of ").Append(_fetchedN).Append(" fetched) ===").Append("\n");
                }
                else
                {
                    sbTrend.Append("=== COMPUTED TREND & SENSOR HEALTH (deterministic, from ").Append(series.Count).Append(" fetched samples").Append(") ===").Append("\n");
                }
                // v1.0.152.5 (P0): NAME which series this block describes. For a derived alert
                // _trendCandidate is an arbitrary DRIVER, not the derived quantity -- say so, so the
                // model does not read a component's stats as the derived trend.
                {
                    string dPh, dFh; bool isDerivedH = DetectDerived(_prefetchCtx, out dPh, out dFh);
                    string blkAttr = tc != null && tc["attr"] != null ? tc["attr"].ToString() : "";
                    if (isDerivedH)
                    {
                        sbTrend.Append("NOTE: the statistics below are for COMPONENT '").Append(string.IsNullOrEmpty(blkAttr) ? "a driver" : blkAttr).Append("' -- ONE DRIVER of the derived value, NOT the derived quantity's own trend. Judge the derived alert from the per-component as-of values and the computed derived value, not this single driver.\n");
                    }
                    else if (!string.IsNullOrEmpty(blkAttr))
                    {
                        sbTrend.Append("(series: ").Append(blkAttr).Append(")\n");
                    }
                }
                // per-day min/avg/max -- key by sortable yyyyMMdd so first/last day are
                // truly chronological (v1.0.151.2: was "dd.MM" in a Dictionary, enumerated
                // unsorted, so firstAvg/lastAvg could be out of order).
                Dictionary<string, List<double>> byDay = new Dictionary<string, List<double>>(StringComparer.Ordinal);
                Dictionary<string, string> dayLabel = new Dictionary<string, string>(StringComparer.Ordinal);
                foreach (KeyValuePair<DateTime, double> kv in series)
                {
                    string dayKey = kv.Key.ToString("yyyyMMdd");
                    List<double> l; if (!byDay.TryGetValue(dayKey, out l)) { l = new List<double>(); byDay[dayKey] = l; dayLabel[dayKey] = kv.Key.ToString("dd.MM"); }
                    l.Add(kv.Value);
                }
                List<string> dayKeys = new List<string>(byDay.Keys);
                dayKeys.Sort(StringComparer.Ordinal);
                double firstAvg = 0, lastAvg = 0; int di = 0;
                foreach (string day in dayKeys)
                {
                    List<double> l = byDay[day];
                    double mn = double.MaxValue, mx = double.MinValue, sum = 0;
                    foreach (double v in l) { if (v < mn) mn = v; if (v > mx) mx = v; sum += v; }
                    double avg = sum / l.Count;
                    if (di == 0) { firstAvg = avg; }
                    lastAvg = avg; di++;
                    sbTrend.Append("day ").Append(dayLabel[day]).Append(": min=").Append(mn.ToString("0.###")).Append(" avg=").Append(avg.ToString("0.###")).Append(" max=").Append(mx.ToString("0.###")).Append(" (n=").Append(l.Count).Append(")").Append("\n");
                }
                // v1.0.151.0: occupation-resistant resting reference. Train-movement spikes
                // are a minority of samples, so the MEDIAN (and the mean of the middle 80%,
                // trimming both tails) tracks the healthy resting value far better than the
                // raw mean, which the shunt/occupation excursions drag. Reported alongside
                // so the model has a train-resistant number even without the TPR mask.
                List<double> allv = new List<double>();
                foreach (KeyValuePair<DateTime, double> kv in series) { allv.Add(kv.Value); }
                allv.Sort();
                double median = (allv.Count % 2 == 1) ? allv[allv.Count / 2]
                    : (allv[allv.Count / 2 - 1] + allv[allv.Count / 2]) / 2.0;
                int lo10 = (int)(allv.Count * 0.10), hi10 = (int)(allv.Count * 0.90);
                double tsum = 0; int tcnt = 0;
                for (int ti = lo10; ti < hi10 && ti < allv.Count; ti++) { tsum += allv[ti]; tcnt++; }
                double trimMean = tcnt > 0 ? tsum / tcnt : median;
                sbTrend.Append("resting reference (occupation-resistant): median=").Append(median.ToString("0.###"))
                       .Append(", trimmed-mean(mid 80%)=").Append(trimMean.ToString("0.###"))
                       .Append(" -- prefer these over the raw mean for the healthy baseline; the raw mean is inflated by train-movement/shunt samples.").Append("\n");
                string dir = "stable";
                if (firstAvg != 0)
                {
                    double chg = (lastAvg - firstAvg) / Math.Abs(firstAvg);
                    if (chg > 0.05) { dir = "worsening (+" + (chg * 100).ToString("0.#") + "% avg)"; }
                    else if (chg < -0.05) { dir = "improving (" + (chg * 100).ToString("0.#") + "% avg)"; }
                }
                sbTrend.Append("trend direction (first-day avg vs last-day avg): ").Append(dir).Append("\n");
                // sensor health: stale age, flatline run, spikes vs 4-sigma
                double mean = 0; foreach (KeyValuePair<DateTime, double> kv in series) { mean += kv.Value; } mean /= series.Count;
                double var2 = 0; foreach (KeyValuePair<DateTime, double> kv in series) { var2 += (kv.Value - mean) * (kv.Value - mean); } 
                double sd = Math.Sqrt(var2 / series.Count);
                int flatRun = 1, maxFlat = 1, spikes = 0;
                for (int i = 1; i < series.Count; i++)
                {
                    if (series[i].Value == series[i - 1].Value) { flatRun++; if (flatRun > maxFlat) { maxFlat = flatRun; } }
                    else { flatRun = 1; }
                    if (sd > 0 && Math.Abs(series[i].Value - mean) > 4 * sd) { spikes++; }
                }
                TimeSpan staleAge = DateTime.Now - series[series.Count - 1].Key;
                sbTrend.Append("sensor health: last sample ").Append(staleAge.TotalMinutes < 1 ? "<1 min" : (staleAge.TotalHours >= 1 ? staleAge.TotalHours.ToString("0.#") + " h" : ((int)staleAge.TotalMinutes) + " min")).Append(" old");
                sbTrend.Append("; longest flatline run=").Append(maxFlat).Append(" samples");
                sbTrend.Append("; spikes beyond 4-sigma=").Append(spikes).Append("\n");
                // v1.0.152.1: MODEL-GROUNDING -- when a digital TPR series is present, state the
                // TRAIN-FREE reference computed on the RAW trigger series (samples during
                // occupation / near TPR transitions excluded). The model is told to prefer this
                // over the raw mean, since train dips are not the asset's resting state.
                try
                {
                    string dPg, dFg; bool isDerivedG = DetectDerived(_prefetchCtx, out dPg, out dFg);
                    string tprK = ResolveTprStateKey();
                    List<object[]> tprRawC = null; if (tprK != null) { _trendRawByAttr.TryGetValue(tprK, out tprRawC); }
                    string trigK = tc != null && tc["attr"] != null ? tc["attr"].ToString() : "";
                    List<object[]> trigRawC = null; _trendRawByAttr.TryGetValue(trigK ?? "", out trigRawC);
                    // v1.0.152.4: DERIVED alerts have no trigger telemetry -- _trendCandidate is
                    // just the largest DRIVER, so do NOT present its masked stat as "the trigger
                    // reference". Ground only a DIRECT alert, and only when TPR fully covers it.
                    if (isDerivedG)
                    {
                        sbTrend.Append("derived alert: the plotted drivers each carry their own train-free reference -- judge the derived value from the components, not any single driver's masked statistic.\n");
                    }
                    else if (tprRawC != null && tprRawC.Count >= 2 && trigRawC != null && trigRawC.Count >= 5 && TprCoversTrigger(tprRawC, trigK))
                    {
                        List<double[]> exC = BuildTrainExclusionRaw(tprRawC);
                        JObject rfC = ComputeTrainFreeRef(trigRawC, exC);
                        if (rfC != null)
                        {
                            sbTrend.Append("train-free reference (TPR-masked, prefer this over the raw mean): median=")
                                   .Append(rfC["median"]).Append(", trimmed-mean=").Append(rfC["trimmedMean"])
                                   .Append(" over ").Append(rfC["usedSamples"]).Append(" train-free samples (")
                                   .Append(rfC["trainExcluded"]).Append(" excluded as train movement via the digital TPR state). ")
                                   .Append("Train-occupation dips in the trigger are NOT fault readings -- do not treat them as the fault.\n");
                        }
                    }
                }
                catch { }
                return sbTrend.ToString();
            }
            catch { return null; }
        }

        private void TryHarvestTrend(string toolName, JToken args, string result)
        {
            try
            {
                if (string.IsNullOrEmpty(result) || result.Length < 40) { return; }
                bool care = false;
                for (int i = 0; i < _trendTools.Length; i++)
                {
                    if (string.Equals(toolName, _trendTools[i], StringComparison.OrdinalIgnoreCase)) { care = true; break; }
                }
                if (!care) { return; }
                JToken root; try { root = JToken.Parse(result); } catch { return; }
                List<object[]> best = null;
                Queue<JToken> q = new Queue<JToken>(); q.Enqueue(root); int visited = 0; int innerParses = 0;
                while (q.Count > 0 && visited < 400)
                {
                    JToken cur = q.Dequeue(); visited++;
                    // v1.0.148.0: MCP results often wrap the real payload as a STRING --
                    // {"result":{"content":[{"text":"<json>"}]}} -- so a plain walk never
                    // reaches the series. Parse embedded JSON strings too (bounded).
                    if (cur.Type == JTokenType.String && innerParses < 6)
                    {
                        string sv = cur.ToString();
                        if (sv.Length > 80)
                        {
                            string tv = sv.TrimStart();
                            if (tv.StartsWith("{") || tv.StartsWith("["))
                            {
                                try { q.Enqueue(JToken.Parse(sv)); innerParses++; } catch { }
                            }
                        }
                        continue;
                    }
                    // v1.0.150.0: E7 history_get returns PARALLEL ARRAYS -- {"n":38,
                    // "ts":[epochSec,...],"v":[val,...]} -- not object rows. Zip them.
                    JObject po = cur as JObject;
                    if (po != null)
                    {
                        JArray tsArr = po["ts"] as JArray;
                        JArray vArr = (po["v"] as JArray) ?? (po["values"] as JArray);
                        if (tsArr != null && vArr != null && tsArr.Count >= 5 && tsArr.Count == vArr.Count)
                        {
                            List<object[]> pts2 = new List<object[]>();
                            for (int i = 0; i < tsArr.Count; i++)
                            {
                                double dv2; long ep;
                                if (!double.TryParse(vArr[i].ToString(), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out dv2)) { continue; }
                                string tstr = tsArr[i].ToString();
                                if (long.TryParse(tstr, out ep))
                                {
                                    // epoch seconds (10 digits) vs ms (13): normalize to ISO local
                                    DateTimeOffset dto = ep < 100000000000L
                                        ? DateTimeOffset.FromUnixTimeSeconds(ep)
                                        : DateTimeOffset.FromUnixTimeMilliseconds(ep);
                                    tstr = dto.ToLocalTime().ToString("yyyy-MM-ddTHH:mm:ss");
                                }
                                pts2.Add(new object[] { tstr, dv2 });
                            }
                            if (pts2.Count >= 5 && (best == null || pts2.Count > best.Count)) { best = pts2; }
                        }
                    }
                    JArray arr = cur as JArray;
                    if (arr != null && arr.Count >= 5 && arr[0] is JObject)
                    {
                        List<object[]> pts = new List<object[]>();
                        foreach (JToken it in arr)
                        {
                            JObject io = it as JObject; if (io == null) { continue; }
                            string tsv = null; double dv = double.NaN;
                            foreach (string tk in _tsKeys) { JToken t = PropCI(io, tk); if (t != null && t.Type != JTokenType.Null) { tsv = t.ToString(); break; } }
                            foreach (string vk in _valKeys) { JToken t = PropCI(io, vk); if (t != null && t.Type != JTokenType.Null) { double dd; if (double.TryParse(t.ToString(), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out dd)) { dv = dd; break; } } }
                            if (tsv != null && !double.IsNaN(dv)) { pts.Add(new object[] { tsv, dv }); }
                        }
                        if (pts.Count >= 5 && (best == null || pts.Count > best.Count)) { best = pts; }
                    }
                    if (cur is JObject || cur is JArray)
                    {
                        foreach (JToken ch in cur.Children()) { q.Enqueue(ch is JProperty ? ((JProperty)ch).Value : ch); }
                    }
                }
                if (best == null) { return; }
                string attr = null;
                JObject ao = args as JObject;
                if (ao != null)
                {
                    string[] ak = { "AttributeName", "attributeName", "attribute", "TagName", "tagName", "attr" };
                    foreach (string k in ak) { JToken t = PropCI(ao, k); if (t != null && t.Type == JTokenType.String && t.ToString().Length > 0) { attr = t.ToString(); break; } }
                }
                // v1.0.152.4: prefetch calls carry a TagId, not an AttributeName -> recover the
                // real attribute + role from the registry populated at fetch time.
                bool metaTpr = false, metaTrig = false;
                if (ao != null)
                {
                    string tagId = null;
                    string[] tik = { "TagId", "tagId", "TagID", "tagid" };
                    foreach (string k in tik) { JToken t = PropCI(ao, k); if (t != null && t.Type != JTokenType.Null) { tagId = t.ToString(); break; } }
                    if (!string.IsNullOrEmpty(tagId)) { JObject mm; lock (_trendLock) { _tagMeta.TryGetValue(tagId, out mm); } if (mm != null) { if (string.IsNullOrEmpty(attr) && mm["attr"] != null) { attr = mm["attr"].ToString(); } metaTpr = mm["isTpr"] != null && (bool)mm["isTpr"]; metaTrig = mm["isTrigger"] != null && (bool)mm["isTrigger"]; } }
                }
                int score = best.Count;
                try
                {
                    JObject card = _prefetchCtx != null ? _prefetchCtx["alertCard"] as JObject : null;
                    JArray tc = card != null ? card["triggeredConditions"] as JArray : null;
                    string lbl = (tc != null && tc.Count > 0 && tc[0]["paramLabel"] != null) ? tc[0]["paramLabel"].ToString().Trim() : null;
                    if (!string.IsNullOrEmpty(lbl) && !string.IsNullOrEmpty(attr)
                        && (attr.IndexOf(lbl, StringComparison.OrdinalIgnoreCase) >= 0 || lbl.IndexOf(attr, StringComparison.OrdinalIgnoreCase) >= 0))
                    { score += 100000; }
                }
                catch { }
                int n = best.Count, cap = 240;
                JArray pj = new JArray();
                if (n <= cap) { foreach (object[] pt in best) { pj.Add(new JArray(pt[0], pt[1])); } }
                else { for (int i = 0; i < cap; i++) { int idx = (int)(((long)i * (n - 1) + (cap - 1) / 2) / (cap - 1)); if (idx > n - 1) { idx = n - 1; } object[] pt = best[idx]; pj.Add(new JArray(pt[0], pt[1])); } }   // v1.0.151.2: retain first AND last sample
                JObject tr = new JObject();
                tr["attr"] = attr ?? "";
                tr["n"] = n;
                tr["points"] = pj;
                tr["isTpr"] = metaTpr;                 // v1.0.152.4: role from the TagId registry
                if (metaTrig) { score += 100000; }     // a registered trigger tag counts as the trigger
                // v1.0.152.0: keep EVERY attribute's series for the multi-line chart (dedup by
                // attr name; a later, larger fetch for the same attr replaces the earlier one).
                // v1.0.152.4 (P1): guard the shared series maps against concurrent history harvests.
                lock (_trendLock)
                {
                    // v1.0.152.7 (P1): ONLY identified series (a real attribute name from args or the
                    // TagId registry) enter the multi-series chart + the derived mask aggregate. An
                    // anonymous range-history result would otherwise land as "seriesN", consume the
                    // 6-cap, and be counted as an uncovered driver -> a false "partial". It may still
                    // feed the legacy _trendCandidate (the registered trigger's +100000 score wins).
                    if (!string.IsNullOrEmpty(attr))
                    {
                        JObject prevS; bool hadPrev = _trendSeriesByAttr.TryGetValue(attr, out prevS);
                        if (!hadPrev || (prevS["n"] != null && n > (int)prevS["n"]))
                        {
                            if (_trendSeriesByAttr.Count < 6 || hadPrev) { _trendSeriesByAttr[attr] = tr; _trendRawByAttr[attr] = best; }   // v1.0.152.1: keep RAW too
                        }
                    }
                    // trigger/stats series = highest score (unchanged behaviour for computed stats)
                    if (_trendCandidate == null || score > _trendScore) { _trendCandidate = tr; _trendScore = score; }
                }
                AiLog("INFO", "TREND", "harvested tool=" + toolName + " attr=" + (attr ?? "?") + " n=" + n + " score=" + score + " seriesTotal=" + _trendSeriesByAttr.Count);
            }
            catch { }
        }

        private void TryHarvestGrounding(string toolName, string result)
        {
            try
            {
                if (_prefetchCtx == null || string.IsNullOrEmpty(result)) { return; }
                bool care = false;
                for (int i = 0; i < _groundingTools.Length; i++)
                {
                    if (string.Equals(toolName, _groundingTools[i], StringComparison.OrdinalIgnoreCase)) { care = true; break; }
                }
                if (!care) { return; }
                string alertId = GetCtx(_prefetchCtx, "alertId");
                if (string.IsNullOrEmpty(alertId)) { return; }
                string sid = HarvestIdToken(result, "SiteId");
                if (sid == null) { sid = HarvestIdToken(result, "site_id"); }
                string aid = HarvestIdToken(result, "AssetId");
                if (aid == null) { aid = HarvestIdToken(result, "asset_id"); }
                if (sid == null && aid == null) { return; }
                JObject g = _groundingByAlert.GetOrAdd(alertId, delegate(string k) { return new JObject(); });
                lock (g)
                {
                    if (sid != null && g["siteId"] == null) { g["siteId"] = sid; }
                    if (aid != null && g["assetId"] == null) { g["assetId"] = aid; }
                    g["ts"] = DateTime.UtcNow.ToString("o");
                }
                if (_groundingByAlert.Count > 300)
                {
                    foreach (string k in _groundingByAlert.Keys) { JObject drop; _groundingByAlert.TryRemove(k, out drop); if (_groundingByAlert.Count <= 200) { break; } }
                }
            }
            catch { }
        }

        // First positive integer following "<key>": in a JSON-ish blob (quotes optional).
        private static string HarvestIdToken(string text, string key)
        {
            try
            {
                System.Text.RegularExpressions.Match m = System.Text.RegularExpressions.Regex.Match(
                    text, "\"?" + key + "\"?\\s*[:=]\\s*\"?(\\d{1,10})\"?",
                    System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                if (m.Success)
                {
                    string v = m.Groups[1].Value;
                    long n; if (long.TryParse(v, out n) && n > 0) { return v; }
                }
            }
            catch { }
            return null;
        }

        // Merge cached grounding into a follow-up chat ctx (fills only MISSING ids).
        private static bool MergeGrounding(JObject ctx)
        {
            try
            {
                if (ctx == null) { return false; }
                string alertId = GetCtx(ctx, "alertId");
                if (string.IsNullOrEmpty(alertId)) { return false; }
                JObject g; if (!_groundingByAlert.TryGetValue(alertId, out g)) { return false; }
                bool merged = false;
                lock (g)
                {
                    if (string.IsNullOrEmpty(GetCtx(ctx, "siteId")) && g["siteId"] != null) { ctx["siteId"] = g["siteId"].ToString(); merged = true; }
                    if (string.IsNullOrEmpty(GetCtx(ctx, "assetId")) && g["assetId"] != null) { ctx["assetId"] = g["assetId"].ToString(); merged = true; }
                }
                return merged;
            }
            catch { return false; }
        }

        private JObject _prefetchCtx;   // set by the verdict endpoint before the loop runs
        private bool _synthesisMode;    // one call, no tools, compact prompt
        // Synthesis removes the model's ability to fetch anything, so it must only
        // engage when the evidence is genuinely COMPLETE. "History exists" is not
        // enough: a series that stops before the incidence still set _jsonGotHistory,
        // and the model was then unable to request a narrower window -- turning a
        // recoverable gap into an avoidable INCONCLUSIVE.
        private bool _prefetchComplete;
        private string _prefetchGap;

        // ---- user-facing engine names --------------------------------------
        // What the operator sees. "MCP1"/"MCP2" are internal plumbing names and
        // mean nothing to a maintainer. Rename from web.config without a rebuild:
        //   <add key="AiEngineName1" value="ENERGY7 ULTRA 1" />
        //   <add key="AiEngineName2" value="ENERGY7 ULTRA 2" />
        //   <add key="AiEngineBrand" value="ENERGY7 ULTRA" />
        // Logs and traces deliberately KEEP srv1/srv2 -- diagnosis needs the
        // plumbing names, the operator does not.
        private static string ReadStr(string key, string def)
        {
            string v = ConfigurationManager.AppSettings[key];
            return string.IsNullOrWhiteSpace(v) ? def : v.Trim();
        }
        private static readonly string _engineBrand = ReadStr("AiEngineBrand", "ENERGY7 ULTRA");
        private static readonly string _engineName1 = ReadStr("AiEngineName1", "ENERGY7 ULTRA 1");
        private static readonly string _engineName2 = ReadStr("AiEngineName2", "ENERGY7 ULTRA 2");
        private static string EngineName(int owner) { return owner == 2 ? _engineName2 : _engineName1; }

        private static readonly int _traceMaxMB = ReadInt("AnalyzeTraceMaxMB", 64);

        // ==================================================================
        // LEVELED LOG  ->  App_Data/AiToolLogs/ai-log-YYYYMMDD.txt
        //
        // Companion to the JSONL trace: the trace answers "what were the
        // numbers", this answers "what went wrong and where". One line per
        // event, fixed-width columns so grep and awk both work:
        //
        //   2026-08-01 14:23:05.123 [WARN ] [GROUND ] [dryrun-1b83a5] message
        //
        //   grep " \[ERROR\] " ai-log-20260801.txt
        //   grep " \[MCP    \] " ai-log-*.txt
        //   grep "dryrun-1b83a5" ai-log-*.txt      <- one whole analysis
        //
        // Files older than today are gzipped in the background on the first
        // write of a new day, then swept by AnalyzeTraceRetainDays.
        // ==================================================================
        private static readonly string _aiLogMinLevel =
            (ConfigurationManager.AppSettings["AiLogMinLevel"] ?? "INFO").Trim().ToUpperInvariant();
        private static int _aiLogDropped;          // non-zero is always actionable
        private static int _aiLogWritten;
        private static DateTime _aiLogLastDay = DateTime.MinValue;
        private static string _aiLogLastError;   // surfaced by Status
        private static readonly object _aiLogDayLock = new object();

        // Answers, in one call: where are the logs, can the app pool write
        // there, has it written anything, and if not -- why.
        private static object LogDiagnostics()
        {
            string probeError = null;
            bool canWrite = false;
            try
            {
                System.IO.Directory.CreateDirectory(_toolLogDir);
                string probe = System.IO.Path.Combine(_toolLogDir, "_write_probe.tmp");
                System.IO.File.WriteAllText(probe, "probe");
                System.IO.File.Delete(probe);
                canWrite = true;
            }
            catch (Exception ex)
            {
                probeError = ex.GetType().Name + ": " + ex.Message;
            }

            string[] files = new string[0];
            try
            {
                if (System.IO.Directory.Exists(_toolLogDir))
                {
                    files = System.IO.Directory.GetFiles(_toolLogDir, "ai-*");
                }
            }
            catch { }

            List<string> names = new List<string>();
            for (int i = 0; i < files.Length && i < 12; i++)
            {
                try
                {
                    System.IO.FileInfo fi = new System.IO.FileInfo(files[i]);
                    names.Add(fi.Name + " (" + fi.Length + "B, " + fi.LastWriteTime.ToString("yyyy-MM-dd HH:mm") + ")");
                }
                catch { }
            }

            return new
            {
                logDir = _toolLogDir,
                dirExists = System.IO.Directory.Exists(_toolLogDir),
                canWrite = canWrite,
                writeError = probeError,
                minLevel = _aiLogMinLevel,
                traceEnabled = _analyzeTraceEnabled,
                toolLoggingEnabled = _toolLoggingEnabled,
                writtenLines = _aiLogWritten,
                droppedLines = _aiLogDropped,
                lastError = _aiLogLastError,
                fileCount = files.Length,
                files = names
            };
        }

        private static int LevelRank(string lvl)
        {
            if (lvl == "DEBUG") { return 0; }
            if (lvl == "INFO") { return 1; }
            if (lvl == "WARN") { return 2; }
            if (lvl == "ERROR") { return 3; }
            return 1;
        }

        public static int AiLogDroppedLines { get { return _aiLogDropped; } }
        public static int AiLogWrittenLines { get { return _aiLogWritten; } }

        // v1.0.160.73: static twin of AiLog. The audit-DB helpers are static (breaker state is
        // process-wide) and AiLog is an instance method using _traceId -- calling it from static
        // context is CS0120, which has already cost this arc three compile breaks. Same file, same
        // lock, no traceId.
        private static void AiLogStatic(string level, string tag, string message)
        {
            try
            {
                if (LevelRank(level) < LevelRank(_aiLogMinLevel)) { return; }
                DateTime now = DateTime.Now;
                string line = now.ToString("yyyy-MM-dd HH:mm:ss.fff")
                    + " [" + level.PadRight(5) + "]"
                    + " [" + (tag ?? "").PadRight(7) + "]"
                    + " [-] "
                    + (message ?? "").Replace("\r", " ").Replace("\n", " ");
                System.IO.Directory.CreateDirectory(_toolLogDir);
                string path = System.IO.Path.Combine(
                    _toolLogDir, "ai-log-" + now.ToString("yyyyMMdd") + ".txt");
                lock (_toolLogLock)
                {
                    System.IO.File.AppendAllText(path, line + Environment.NewLine, Encoding.UTF8);
                }
            }
            catch { }
        }

        private void AiLog(string level, string tag, string message)
        {
            try
            {
                if (LevelRank(level) < LevelRank(_aiLogMinLevel)) { return; }
                DateTime now = DateTime.Now;
                string line = now.ToString("yyyy-MM-dd HH:mm:ss.fff")
                    + " [" + level.PadRight(5) + "]"
                    + " [" + (tag ?? "").PadRight(7) + "]"
                    + " [" + (_traceId ?? "-") + "] "
                    + (message ?? "").Replace("\r", " ").Replace("\n", " ");

                RollIfNewDay(now);
                System.IO.Directory.CreateDirectory(_toolLogDir);
                string path = System.IO.Path.Combine(
                    _toolLogDir, "ai-log-" + now.ToString("yyyyMMdd") + ".txt");
                lock (_toolLogLock)
                {
                    System.IO.File.AppendAllText(path, line + Environment.NewLine, Encoding.UTF8);
                }
                System.Threading.Interlocked.Increment(ref _aiLogWritten);
            }
            catch (Exception ex)
            {
                // Never let logging break an analysis -- but do not go silent
                // either. A swallowed failure here is why "no logs anywhere"
                // used to be undiagnosable; Status now reports this.
                System.Threading.Interlocked.Increment(ref _aiLogDropped);
                _aiLogLastError = ex.GetType().Name + ": " + ex.Message;
            }
        }

        private void AiLogEx(string tag, string message, Exception ex)
        {
            string detail = ex == null ? "" : " | " + ex.GetType().Name + ": " + ex.Message;
            AiLog("ERROR", tag, message + detail);
            if (ex != null)
            {
                System.Diagnostics.Trace.TraceError("[AiChat/" + tag + "] " + ex.ToString());
            }
        }

        // gzip yesterday's logs on the first write of a new day, off-thread
        private static void RollIfNewDay(DateTime now)
        {
            DateTime today = now.Date;
            lock (_aiLogDayLock)
            {
                if (_aiLogLastDay == today) { return; }
                _aiLogLastDay = today;
            }
            Task.Run(() => CompressOldLogs(today));
        }

        private static void CompressOldLogs(DateTime today)
        {
            try
            {
                if (!System.IO.Directory.Exists(_toolLogDir)) { return; }
                string[] pats = { "ai-log-*.txt", "ai-analyze-*.jsonl", "ai-tool-*.jsonl" };
                string stamp = today.ToString("yyyyMMdd");
                for (int p2 = 0; p2 < pats.Length; p2++)
                {
                    string[] files = System.IO.Directory.GetFiles(_toolLogDir, pats[p2]);
                    for (int i = 0; i < files.Length; i++)
                    {
                        string f = files[i];
                        if (f.IndexOf(stamp, StringComparison.Ordinal) >= 0) { continue; } // today's stays open
                        string gz = f + ".gz";
                        if (System.IO.File.Exists(gz)) { continue; }
                        try
                        {
                            using (System.IO.FileStream src = System.IO.File.OpenRead(f))
                            using (System.IO.FileStream dst = System.IO.File.Create(gz))
                            using (System.IO.Compression.GZipStream zip =
                                new System.IO.Compression.GZipStream(dst, System.IO.Compression.CompressionMode.Compress))
                            {
                                src.CopyTo(zip);
                            }
                            System.IO.File.Delete(f);
                        }
                        catch { /* file in use or unreadable: leave it, retry tomorrow */ }
                    }
                }
                // retention now covers the archives too
                DateTime cut = DateTime.UtcNow.AddDays(-_traceRetainDays);
                string[] old = System.IO.Directory.GetFiles(_toolLogDir, "ai-*.gz");
                for (int i = 0; i < old.Length; i++)
                {
                    if (System.IO.File.GetLastWriteTimeUtc(old[i]) < cut)
                    {
                        try { System.IO.File.Delete(old[i]); } catch { }
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.TraceWarning("[AiChat] log compression failed: " + ex.Message);
            }
        }

        private void TraceAnalyze(string step, JObject data)
        {
            // NOTE: _traceActive gates ACCUMULATION at call sites and stays on for
            // analyze endpoints regardless of the file switch, so envelope timing
            // meta is populated even when file tracing is disabled.
            if (!_analyzeTraceEnabled || !_traceActive) { return; }
            try
            {
                JObject e = new JObject();
                e["tsUtc"] = DateTime.UtcNow.ToString("o");
                e["traceId"] = _traceId ?? "";
                e["step"] = step;
                if (data != null) { e["data"] = data; }
                System.IO.Directory.CreateDirectory(_toolLogDir);
                string path = System.IO.Path.Combine(
                    _toolLogDir,
                    "ai-analyze-" + DateTime.UtcNow.ToString("yyyyMMdd") + ".jsonl");
                lock (_toolLogLock)
                {
                    System.IO.FileInfo fi = new System.IO.FileInfo(path);
                    if (!fi.Exists) { CleanupOldTraces(); } // retention on day roll, best-effort
                    if (fi.Exists && fi.Length > (long)_traceMaxMB * 1024 * 1024) { return; } // daily file size bound
                    System.IO.File.AppendAllText(path, e.ToString(Formatting.None) + Environment.NewLine, Encoding.UTF8);
                }
            }
            catch (Exception tex)
            {
                System.Diagnostics.Trace.TraceWarning("[AiChat] analyze trace failed: " + tex.Message);
            }
        }

        private static readonly int _traceRetainDays = ReadInt("AnalyzeTraceRetainDays", 14);
        private static void CleanupOldTraces()
        {
            try
            {
                string[] files = System.IO.Directory.GetFiles(_toolLogDir, "ai-analyze-*.jsonl");
                DateTime cut = DateTime.UtcNow.AddDays(-_traceRetainDays);
                for (int k = 0; k < files.Length; k++)
                {
                    if (System.IO.File.GetLastWriteTimeUtc(files[k]) < cut)
                    {
                        try { System.IO.File.Delete(files[k]); } catch { }
                    }
                }
            }
            catch { }
        }

        // free-text analogue of the tool log's CloneAndRedact: strip
        // key/token/password-like assignments before the prompt is persisted.
        private const string _credWords = "api[_-]?key|apikey|access[_-]?token|token|password|passwd|pwd|secret|authorization|auth|credential";
        // quoted JSON form: "token": "abc123"  /  'secret' = 'x y z'
        private static readonly System.Text.RegularExpressions.Regex _redactQuoted =
            new System.Text.RegularExpressions.Regex(
                "(?i)([\"']?(?:" + _credWords + ")[\"']?\\s*[:=]\\s*)([\"'])(?:\\\\.|[^\"'])*\\2",
                System.Text.RegularExpressions.RegexOptions.Compiled);
        // double-quoted value that may contain apostrophes: "token":"O'Brien"
        private static readonly System.Text.RegularExpressions.Regex _redactDq =
            new System.Text.RegularExpressions.Regex(
                "(?i)([\"]?(?:" + _credWords + ")[\"]?\\s*[:=]\\s*)\"(?:\\\\.|[^\"])*\"",
                System.Text.RegularExpressions.RegexOptions.Compiled);
        // CLI flag form: --token abcdefgh
        private static readonly System.Text.RegularExpressions.Regex _redactFlag =
            new System.Text.RegularExpressions.Regex(
                "(?i)(--?(?:" + _credWords + ")\\s+)\\S+",
                System.Text.RegularExpressions.RegexOptions.Compiled);
        // bare form: token=abc123 / secret: abc123
        // unquoted JSON scalar: "token": 123456789
        private static readonly System.Text.RegularExpressions.Regex _redactNumeric =
            new System.Text.RegularExpressions.Regex(
                "(?i)([\"']?(?:" + _credWords + ")[\"']?\\s*[:=]\\s*)(-?[0-9][0-9\\.]*(?:[eE][-+]?[0-9]+)?)",
                System.Text.RegularExpressions.RegexOptions.Compiled);
        private static readonly System.Text.RegularExpressions.Regex _redactBare =
            new System.Text.RegularExpressions.Regex(
                "(?i)((?:" + _credWords + ")\\s*[:=]\\s*)\\S+",
                System.Text.RegularExpressions.RegexOptions.Compiled);
        // scheme form: Bearer abc123 / Basic dGVzdA==
        private static readonly System.Text.RegularExpressions.Regex _redactScheme =
            new System.Text.RegularExpressions.Regex(
                "(?i)\\b(bearer|basic)\\s+[A-Za-z0-9\\-\\._~\\+/=]{3,}",
                System.Text.RegularExpressions.RegexOptions.Compiled);
        private static string RedactForTrace(string s0)
        {
            if (string.IsNullOrEmpty(s0)) { return s0; }
            try
            {
                string o = _redactDq.Replace(s0, "$1\"[REDACTED]\"");
                o = _redactQuoted.Replace(o, "$1\"[REDACTED]\"");
                o = _redactFlag.Replace(o, "$1[REDACTED]");
                o = _redactNumeric.Replace(o, "$1[REDACTED]");
                o = _redactScheme.Replace(o, "$1 [REDACTED]");
                o = _redactBare.Replace(o, "$1[REDACTED]");
                return o;
            }
            catch { return s0; }
        }

        // Anthropic returns usage on every reply; the OpenAI adapter passes it
        // through. Real counts beat the chars/4 estimate, and cache_read shows
        // whether prompt caching is actually working.
        private static JObject ReadUsage(string raw)
        {
            if (string.IsNullOrEmpty(raw)) { return null; }
            try
            {
                JObject o = JObject.Parse(raw);
                return o["usage"] as JObject;
            }
            catch { return null; }
        }

        private static long ReadLong(JObject o, string key)
        {
            if (o == null) { return 0; }
            JToken t = o[key];
            long v;
            if (t == null || t.Type == JTokenType.Null) { return 0; }
            return long.TryParse(t.ToString(), out v) ? v : 0;
        }

        private static string TraceTrunc(string s0, int max)
        {
            if (s0 == null) { return ""; }
            return s0.Length <= max ? s0 : s0.Substring(0, max) + "...[+" + (s0.Length - max) + " chars]";
        }

        private async Task<T> AwaitWithCancel<T>(Task<T> t, System.Threading.CancellationToken ct, int bgWeight = 1)
        {
            if (!ct.CanBeCanceled) { return await t.ConfigureAwait(false); }
            Task done = await Task.WhenAny(t, Task.Delay(System.Threading.Timeout.Infinite, ct)).ConfigureAwait(false);
            if (done != t)
            {
                RegisterAbandoned(t, bgWeight);
                ct.ThrowIfCancellationRequested();
            }
            return await t.ConfigureAwait(false);
        }

        // runs BEFORE the OCE unwinds the loop, so the wrapper-loop completion
        // continuation (which settles the reservation) always sees the final
        // abandoned weight. The real task releases its own weight on completion.
        private void RegisterAbandoned(Task t, int weight)
        {
            if (weight < 1) { weight = 1; }
            System.Threading.Interlocked.Add(ref _jsonAbandonedW, weight);
            int w = weight;
            t.ContinueWith(x =>
            {
                var _ = x.Exception; // observe
                System.Threading.Interlocked.Add(ref _jsonBgReserved, -w);
            });
        }

        private static void ObserveAbandoned(Task t)
        {
            t.ContinueWith(x => { var _ = x.Exception; },
                System.Threading.Tasks.TaskContinuationOptions.OnlyOnFaulted);
        }

        private static bool FixedTimeEquals(string a, string b)
        {
            if (a == null || b == null) { return false; }
            byte[] ba = Encoding.UTF8.GetBytes(a);
            byte[] bb = Encoding.UTF8.GetBytes(b);
            int diff = ba.Length ^ bb.Length;
            int n = Math.Max(ba.Length, bb.Length);
            for (int i = 0; i < n; i++)
            {
                byte x = i < ba.Length ? ba[i] : (byte)0;
                byte y = i < bb.Length ? bb[i] : (byte)0;
                diff |= x ^ y;
            }
            return diff == 0;
        }

        // Only messages we generate ourselves may leave the endpoint; everything
        // else is logged server-side and replaced. Exact/prefix whitelist -- no
        // substring matching.
        private static readonly string[] _jsonErrExact =
        {
            "Rate limit. Wait ~60s.", "AI auth failed.", "Auth failed. Check web.config.",
            "API overloaded. Try again.", "AI request timed out",
            "verdict not valid JSON",
            "no verdict text produced (empty response or step limit)", "client busy",
            "no successful telemetry tool call; verdict ungrounded",
            "no usable history/baseline/alert evidence; verdict ungrounded"
        };
        // failure text fed back to the MODEL is fixed-code only; the raw
        // exception goes to the server-side tool log / Trace, never to the model.
        private static string ShortHash(string s0)
        {
            if (s0 == null) { return ""; }
            try
            {
                using (System.Security.Cryptography.SHA256 sha = System.Security.Cryptography.SHA256.Create())
                {
                    byte[] h = sha.ComputeHash(Encoding.UTF8.GetBytes(s0));
                    StringBuilder sb2 = new StringBuilder();
                    for (int k = 0; k < 16; k++) { sb2.Append(h[k].ToString("x2")); } // 128-bit prefix
                    return sb2.ToString();
                }
            }
            catch { return ""; }
        }

        private static string SanitizeToolFailure(Exception ex)
        {
            if (ex == null) { return "internal error"; }
            if (ex is OperationCanceledException) { return "timeout"; }
            if (ex is System.Net.Http.HttpRequestException) { return "connection error"; }
            if (ex is System.Net.WebException) { return "connection error"; }
            System.Diagnostics.Trace.TraceError("[AiChat] tool failure: " + ex.ToString());
            return "internal error";
        }

        private static string SanitizeJsonError(string msg)
        {
            if (string.IsNullOrEmpty(msg)) { return "internal error"; }
            for (int i = 0; i < _jsonErrExact.Length; i++)
            {
                if (string.Equals(msg, _jsonErrExact[i], StringComparison.Ordinal)) { return msg; }
            }
            if (msg.StartsWith("verdict schema invalid: ", StringComparison.Ordinal)) { return msg; }
            if (msg.StartsWith("ctx.", StringComparison.Ordinal)) { return msg; } // our shape reasons
            System.Diagnostics.Trace.TraceError("[AnalyzeAlertJson] " + msg);
            return "internal error";
        }

        // mechanical cost bounds, overflow-safe: limit-like keys of ANY incoming
        // type normalized to an integer in [1,10] via decimal-range checks BEFORE
        // any cast; skip/page/offset capped; ID arrays truncated to 20; Limit
        // INJECTED for the history family when absent ("Limit" -- the only
        // consuming code in hand reads args["Limit"]; the packaged registry
        // schema shows lowercase "limit", unresolvable without the missing
        // handler partial -- recorded residual); start/end date pairs clamped to
        // a 15-day span PRESERVING the incoming format (ddMMyyyy_HHmmss or
        // ISO-like); unknown formats are left untouched (recorded residual).
        private static readonly string[] _limitKeys =
            { "limit", "max_results", "maxresults", "count", "pagesize", "page_size", "top", "n" };
        private static readonly string[] _skipKeys = { "skip", "page", "offset" };
        private static readonly string[] _startKeys =
            { "startdate", "start", "from", "fromdate", "start_time", "starttime" };
        private static readonly string[] _endKeys =
            { "enddate", "end", "to", "todate", "end_time", "endtime" };
        private const string _ddFmt = "ddMMyyyy_HHmmss";

        private static int ClampDecimalToInt(JToken t, int lo, int hi, int def)
        {
            decimal dv;
            if (t == null || !decimal.TryParse(t.ToString(), out dv)) { return def; }
            if (dv > hi) { return hi; }
            if (dv < lo) { return lo; }
            return (int)Math.Floor(dv);
        }

        private static bool TryParseFlexibleDate(string raw, out DateTime dt, out bool wasDdFmt)
        {
            wasDdFmt = false;
            if (DateTime.TryParseExact(raw, _ddFmt, System.Globalization.CultureInfo.InvariantCulture,
                System.Globalization.DateTimeStyles.None, out dt))
            {
                wasDdFmt = true; return true;
            }
            return DateTime.TryParse(raw, out dt);
        }

        // The history API returns the OLDEST rows up to `limit` (MCPHelper.Compact:
        // limit = Math.Min(lim, 500), page defaults to 1). So `limit` is not a size
        // guard -- it decides HOW FAR FORWARD IN TIME the series reaches, and a limit
        // smaller than the window's sample count silently ends the data before the
        // alert.
        //
        // Measured at ~1 sample / 13 min on a track tag:
        //     limit=200, window=3d  -> covers 1.8d, ends ~29h SHORT   <- the bug
        //     limit=500, window=3d  -> covers 3.0d, REACHES the alert, ~7 KB
        //     limit=500, window=7d  -> covers 4.5d, ends ~60h short
        //
        // I cut this to 200 in 1.0.15.0 believing oversized payloads were the cause
        // of the parse failures. They were not -- that was the transport splicing a
        // truncation marker mid-JSON (fixed in 1.0.20.0).
        // v1.0.158.3 (owner instruction "make it 5000"): the ceiling is raised 500 -> 5000 and the
        // default with it. IMPORTANT: a request is not a guarantee -- the history API was measured
        // in 1.0.152.5 to CAP AT 500 rows regardless of the value asked for. If that cap is still
        // in force, asking for 5000 changes nothing on the wire; NoteHistoryTruncation() below now
        // logs the actual returned n against the requested limit on every history call, so one run
        // tells us whether the cap still exists (look for "HIST" WARN lines in ai-log-*.txt).
        // Even at 5000, a busy tag over a 3-day window can still be cut: If mA runs ~308 samples/day
        // (~950 over the window), so the WINDOW, not just the limit, decides whether the series
        // reaches the incidence. See History_Truncation_Finding_MD.md.
        private static readonly int _limitCapEvidence = ClampCfg(ReadInt("AnalyzeEvidenceLimit", 5000), 50, 5000);
        private const int _limitCapOther = 10;

        // The history API returns the OLDEST rows in the window, capped at `limit`.
        // Measured on a track tag: ~1 sample / 13 min, so limit=500 spans only ~4.4
        // days. A 7-day window therefore NEVER reached the alert -- the series ended
        // 58 h short of it and the breach was invisible in history, exactly as the
        // verdict caveats reported. 3 days at ~1/13min is ~330 samples: inside the
        // cap, and still enough baseline to judge a sustained deviation.
        private static readonly int _evidenceWindowDays = ClampCfg(ReadInt("AnalyzeWindowDays", 3), 1, 15);
        // v1.0.158.4: PROVEN on 2026-08-07 -- we requested limit=5000 and the API returned EXACTLY
        // 500 twice (If mA, Vf). The 500 cap is real and unchanged, so the limit is NOT the lever.
        // When a series is cut, re-fetch just the tail of the window (which contains the incidence)
        // so the analysis sees the event even though it cannot see the whole span.
        private static readonly int _histTailHours = ClampCfg(ReadInt("AnalyzeHistoryTailHours", 8), 2, 72);
        // v1.0.159.0 (C1): reading the EdgeX source settled it -- history_get ALREADY pages, and
        // page 1 is the OLDEST rows (DbHelper: ORDER BY "TimestampDevice" ... LIMIT/OFFSET with
        // offset=(page-1)*limit). The newest rows were always reachable; we never sent `page`.
        // A cut series is therefore fixed by PAGING to the end of the window, not by narrowing it.
        private static readonly bool _histPagingEnabled = ReadBool("AnalyzeHistoryPaging", true);
        private static readonly int _histMaxPageProbes = ClampCfg(ReadInt("AnalyzeHistoryMaxPageProbes", 4), 1, 12);
        // C2/C3: gated_get and summary_get already exist on the MCP server and do in SQL what this
        // controller has been doing in C#. Additive for now -- the deterministic mask STAYS.
        private static readonly bool _gatedRefEnabled = ReadBool("AnalyzeGatedRef", true);
        private static readonly bool _summaryBaselineEnabled = ReadBool("AnalyzeSummaryBaseline", true);
        // v1.0.160.24 (Item 9): doctrinal signalling wisdom -- retrieval-injected advisory rules
        // (RDSO SPN/257/2025, IRSEM 2021, Glued Joint Manual). Subordinate to CauseLogicMaps/RdpmsMaps.
        private static readonly bool _doctrinalWisdomEnabled = ReadBool("AnalyzeDoctrinalWisdom", true);
        // v1.0.160.50: circuit topology + upstream causality. Default OFF for canary -- flip on after
        // validating against the flip-prone leakage/resistance causes.
        private static readonly bool _circuitWisdomEnabled = ReadBool("AnalyzeCircuitWisdom", false);
        // v1.0.160.57: 7W audit record. Default ON -- it is one log line and coverage is the point.
        private static readonly bool _audit7W = ReadBool("AnalyzeAudit7W", true);
        // v1.0.160.59: bash during analysis. Default OFF -- turn on only after ApiToken is set.
        private static readonly bool _bashInVerdict = ReadBool("AnalyzeBashInVerdict", false);
        private static readonly int _bashMaxCalls = ClampCfg(ReadInt("AnalyzeBashMaxCalls", 2), 1, 6);
        private static readonly int _circuitWisdomMaxRules = ClampCfg(ReadInt("AnalyzeCircuitWisdomMaxRules", 8), 1, 20);
        private static readonly int _doctrinalWisdomMaxRules = ClampCfg(ReadInt("AnalyzeDoctrinalWisdomMaxRules", 6), 1, 20);
        // v1.0.160.25 (Item 8): field-expert wisdom v2 -- adds the Failure-vs-Predictive verdict logic
