        private static readonly bool _gatedDerivedEnabled = ReadBool("AnalyzeGatedDerived", false);
        private static readonly int _gateGuardSec = ClampCfg(ReadInt("GateGuardSec", 10), 0, 120);
        private static readonly int _tprGateAttributeId = ClampCfg(ReadInt("AnalyzeTprAttributeId", 6), 1, 100000);
        // v1.0.160.103: movement panel compares each derived input against its PREVIOUS IN-ENVELOPE
        // reading (configured MinFail..MaxSafe), not a window statistic. Max age is measured from the
        // AT-ALERT sample, not the stamped incidence (incidence can post-date the trigger by minutes).
        private static readonly int _prevCompMaxAgeMin = ClampCfg(ReadInt("PrevComparableMaxAgeMin", 60), 1, 360);
        // v1.0.160.109 CUT A (SL 1): how old the AT-ALERT sample itself may be, measured from the
        // anchor. PrevComparableMaxAgeMin bounds reference->at-sample (15 s in the 543194 case, so it
        // passed); NOTHING bounded at-sample->anchor, which was 32.2 h. Evidence for the default:
        // Charger mA clear-track p99.9 gap is 9.2 min, so 30 min fires only on genuine outages
        // (3 gaps in 4 days across 7,628 samples).
        private static readonly int _atSampleMaxAgeMin = ClampCfg(ReadInt("AtSampleMaxAgeMin", 30), 1, 1440);
        private string _triggerAttId;          // v1.0.159.0: AssetAttributeId of the alerting tag
        private string _gatedRefSummary;       // v1.0.159.0: gated stats straight from TimescaleDB
        private string _gateNameUsed;          // v1.0.160.0: which relay proved the reading
        // The API's own hard row cap, measured at 500 on 2026-08-07 (asked 5000, got exactly 500).
        // Used to tell a CUT series from a merely sparse one; raise if the server cap is lifted.
        private static readonly int _histCapHint = ClampCfg(ReadInt("AnalyzeHistoryCapHint", 500), 50, 5000);

        private static JToken ClampToolArgs(string toolName, JToken args, HashSet<string> declared)
        {
            // declared == null means "schema unknown": inject nothing, only clamp
            // values already present. Never send an argument a tool did not declare.
            // Limit policy: the HISTORY family carries the evidence the verdict
            // rests on (sustained vs transient), so it gets full scale up to the
            // API max. In columnar output ~500 samples is about 10 KB, whereas the
            // old cap of 10 gave roughly one sample per 17 hours over a 7-day
            // window -- far too sparse to judge persistence. Discovery/search
            // tools stay capped small.
            bool histFamily = string.Equals(toolName, "history_get", StringComparison.OrdinalIgnoreCase)
                           || string.Equals(toolName, "trend_get", StringComparison.OrdinalIgnoreCase);
            // search_tags is a DISCOVERY tool: its rows are ~120 bytes and the caller
            // needs to see ALL of an asset's attributes to find the alerting one. The
            // server default is 3 (observed: a track asset returned only Charger tags,
            // no Ir/If, so the alerting attribute could never be matched) and the
            // generic cap of 10 was not enough either -- a track circuit has ~11 tags.
            bool breadthTool = string.Equals(toolName, "search_tags", StringComparison.OrdinalIgnoreCase)
                            || string.Equals(toolName, "search_assets", StringComparison.OrdinalIgnoreCase);
            int limitCap = histFamily ? _limitCapEvidence : (breadthTool ? 60 : _limitCapOther);
            JObject o = args as JObject;
            if (o == null) { o = new JObject(); }
            bool sawLimit = false;
            List<string> names = new List<string>();
            foreach (var prop in o.Properties()) { names.Add(prop.Name); }
            for (int i2 = 0; i2 < names.Count; i2++)
            {
                string lower = names[i2].ToLowerInvariant();
                for (int k = 0; k < _limitKeys.Length; k++)
                {
                    if (lower == _limitKeys[k])
                    {
                        sawLimit = true;
                        o[names[i2]] = ClampDecimalToInt(o[names[i2]], 1, limitCap, limitCap);
                        break;
                    }
                }
                for (int k = 0; k < _skipKeys.Length; k++)
                {
                    if (lower == _skipKeys[k])
                    {
                        o[names[i2]] = ClampDecimalToInt(o[names[i2]], 0, 90, 0);
                        break;
                    }
                }
                JToken val = o[names[i2]];
                if (val != null && val.Type == JTokenType.Array && ((JArray)val).Count > 20)
                {
                    JArray src = (JArray)val;
                    JArray cut = new JArray();
                    for (int k = 0; k < 20; k++) { cut.Add(src[k]); }
                    o[names[i2]] = cut; // ID lists bounded
                }
            }
            if (histFamily && !sawLimit && declared != null && declared.Contains("limit"))
            {
                o["limit"] = _limitCapEvidence; // full scale (history_get: MCPHelper.cs:397)
            }
            // outputMode: pin to "columnar" where the tool DECLARES it.
            // Per the DataAPI README, columnar IS the token-efficient AI format
            // (cols/rows positional arrays, epoch timestamps) and it is still
            // JSON -- so it satisfies the evidence JSON requirement while being
            // far cheaper than "json" named-key output. It is also the MCP
            // default, so this only prevents the model from asking for "csv"
            // (which is NOT JSON and would fail grounding).
            // Undeclared tools get nothing injected (rev 9 regression fix).
            if (IsEvidenceTool(toolName) && declared != null && declared.Contains("outputMode"))
            {
                string omName = null;
                for (int i2 = 0; i2 < names.Count; i2++)
                {
                    if (string.Equals(names[i2], "outputMode", StringComparison.OrdinalIgnoreCase)) { omName = names[i2]; break; }
                }
                o[omName ?? "outputMode"] = "columnar";
            }
            // drop model-invented arguments the tool never declared
            if (declared != null) // present-but-empty strips everything
            {
                List<string> strip = new List<string>();
                foreach (var prop in o.Properties())
                {
                    if (!declared.Contains(prop.Name)) { strip.Add(prop.Name); }
                }
                for (int k = 0; k < strip.Count; k++) { o.Remove(strip[k]); }
            }
            string startName = null, endName = null;
            for (int i2 = 0; i2 < names.Count; i2++)
            {
                string lower = names[i2].ToLowerInvariant();
                if (startName == null) { for (int k = 0; k < _startKeys.Length; k++) { if (lower == _startKeys[k]) { startName = names[i2]; break; } } }
                if (endName == null) { for (int k = 0; k < _endKeys.Length; k++) { if (lower == _endKeys[k]) { endName = names[i2]; break; } } }
            }
            // only rewrite date formats we can reproduce EXACTLY: ddMMyyyy_HHmmss
            // or plain "yyyy-MM-dd HH:mm:ss". Any other format (ISO with T/offset/
            // fractions, etc.) is left untouched -- never corrupted (residual:
            // those windows stay unclamped pending per-tool schemas).
            DateTime sd, ed; bool sdDd, edDd;
            string sRaw = startName != null ? (o[startName] ?? "").ToString() : null;
            string eRaw = endName != null ? (o[endName] ?? "").ToString() : null;
            bool sPlain = sRaw != null && System.Text.RegularExpressions.Regex.IsMatch(sRaw, "^\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}$");
            if (startName != null && endName != null
                && TryParseFlexibleDate(sRaw, out sd, out sdDd)
                && TryParseFlexibleDate(eRaw, out ed, out edDd)
                && (ed - sd).TotalDays > 15
                && (sdDd || sPlain))
            {
                DateTime ns = ed.AddDays(-15);
                o[startName] = sdDd ? ns.ToString(_ddFmt) : ns.ToString("yyyy-MM-dd HH:mm:ss");
            }
            else if (startName != null && endName == null
                && TryParseFlexibleDate(sRaw, out sd, out sdDd)
                && (DateTime.Now - sd).TotalDays > 15
                && (sdDd || sPlain))
            {
                DateTime ns = DateTime.Now.AddDays(-15);
                o[startName] = sdDd ? ns.ToString(_ddFmt) : ns.ToString("yyyy-MM-dd HH:mm:ss");
            }
            return o;
        }

        // usable = a result the model can genuinely ground on. Rejects: our own
        // failure text, HTML pages, malformed JSON, MCP isError envelopes,
        // error-marker objects, empty-data shells ({"data":[],"count":0}), and
        // common "no records" prose. RESIDUAL (stated): relevance to the alert's
        // asset/time window is NOT verified -- that needs per-tool result schemas.
        private static readonly string[] _noDataPhrases =
            { "no record", "no data", "not found", "no rows", "no results", "empty result",
              "unauthorized", "forbidden", "internal server error", "bad request",
              "service unavailable", "exception", "stack trace", "execution failed",
              "n/a", "null", "--" };

        private static readonly string[] _dataKeys =
            { "rows", "data", "items", "values", "results", "records", "list", "alerts", "history", "points" };

        private static JToken PropCI(JObject jo, string name)
        {
            foreach (var prop in jo.Properties())
            {
                if (string.Equals(prop.Name, name, StringComparison.OrdinalIgnoreCase)) { return prop.Value; }
            }
            return null;
        }

        private static bool Truthy(JToken t)
        {
            if (t == null || t.Type == JTokenType.Null) { return false; }
            if (t.Type == JTokenType.Boolean) { return (bool)t; }
            if (t.Type == JTokenType.Integer || t.Type == JTokenType.Float)
            {
                decimal dv2; return decimal.TryParse(t.ToString(), out dv2) && dv2 != 0m; // isError:1
            }
            string sv3 = t.ToString();
            return string.Equals(sv3, "true", StringComparison.OrdinalIgnoreCase)
                || string.Equals(sv3, "1", StringComparison.Ordinal)
                || string.Equals(sv3, "yes", StringComparison.OrdinalIgnoreCase);
        }

        // keys that identify or annotate a row but are not themselves a
        // measurement: a row of only these is metadata, not evidence
        private static readonly string[] _metaKeys =
            { "message", "status", "success", "ok", "type", "info", "note",
              "ts", "timestamp", "time", "date", "datetime", "epoch", "t0",
              "dt", "delta", "deltats", "offset",
              "id", "rowid", "tagid", "assetid", "siteid", "attributeid",
              "name", "unit", "units", "index", "seq", "page", "count", "total" };
        private static bool IsMetadataKey(string name)
        {
            string ln = (name ?? "").ToLowerInvariant();
            for (int k = 0; k < _metaKeys.Length; k++) { if (ln == _metaKeys[k]) { return true; } }
            return false;
        }

        private static readonly string[] _statusFailWords = { "error", "failed", "fail", "failure", "denied", "unauthorized" };

        private static bool IsErrorObject(JObject jo)
        {
            if (Truthy(PropCI(jo, "isError")) || Truthy(PropCI(jo, "is_error"))) { return true; }
            JToken succ = PropCI(jo, "success");
            if (succ != null && succ.Type != JTokenType.Null
                && succ.Type != JTokenType.Object && succ.Type != JTokenType.Array
                && !Truthy(succ)) { return true; } // covers success:0 and success:"0"
            if (PropCI(jo, "error") != null && PropCI(jo, "error").Type != JTokenType.Null) { return true; }
            JToken st = PropCI(jo, "status");
            if (st != null && st.Type == JTokenType.String)
            {
                string sv = st.ToString();
                for (int k = 0; k < _statusFailWords.Length; k++)
                {
                    if (string.Equals(sv, _statusFailWords[k], StringComparison.OrdinalIgnoreCase)) { return true; }
                }
            }
            string[] scKeys = { "statusCode", "status_code", "httpStatus", "http_status", "code" };
            for (int k = 0; k < scKeys.Length; k++)
            {
                JToken sc = PropCI(jo, scKeys[k]);
                if (sc != null && sc.Type != JTokenType.Null && sc.Type != JTokenType.Object && sc.Type != JTokenType.Array)
                {
                    decimal cv; // string "500" counts as well as numeric 500
                    if (decimal.TryParse(sc.ToString(), System.Globalization.NumberStyles.Any,
                            System.Globalization.CultureInfo.InvariantCulture, out cv) && cv >= 400m) { return true; }
                }
            }
            JToken msg = PropCI(jo, "message");
            if (msg != null && msg.Type == JTokenType.String)
            {
                string ml = msg.ToString().ToLowerInvariant();
                for (int k = 0; k < _noDataPhrases.Length; k++)
                {
                    if (ml.Contains(_noDataPhrases[k])) { return true; }
                }
            }
            JToken ok = PropCI(jo, "ok");
            if (ok != null && (ok.Type == JTokenType.Boolean || ok.Type == JTokenType.String)
                && !Truthy(ok) && ok.Type != JTokenType.Null
                && (ok.Type == JTokenType.Boolean || string.Equals(ok.ToString(), "false", StringComparison.OrdinalIgnoreCase)))
            { return true; }
            return false;
        }

        // element substance is RECURSIVE (depth-capped): [[null]] has none
        private static bool ElementHasSubstance(JToken e, int depth)
        {
            if (depth < 0) { return false; }
            if (e == null || e.Type == JTokenType.Null || e.Type == JTokenType.Boolean) { return false; }
            if (e.Type == JTokenType.Object)
            {
                JObject o = (JObject)e;
                if (o.Count == 0 || IsErrorObject(o)) { return false; }
                // a row must carry at least one non-null, non-metadata value:
                // {"x":null} and {"message":"..."} are not measurements
                foreach (var prop in o.Properties())
                {
                    JToken v = prop.Value;
                    if (v == null || v.Type == JTokenType.Null) { continue; }
                    if (v.Type == JTokenType.Boolean) { continue; }
                    if (IsMetadataKey(prop.Name)) { continue; } // ids/timestamps/status are not measurements
                    if (v.Type == JTokenType.Array) { if (ArrayHasSubstance((JArray)v, depth - 1)) { return true; } continue; }
                    if (v.Type == JTokenType.Object) { if (ElementHasSubstance(v, depth - 1)) { return true; } continue; }
                    string sv2 = v.ToString().Trim();
                    if (sv2.Length == 0) { continue; }
                    if (v.Type == JTokenType.String)
                    {
                        string lv = sv2.ToLowerInvariant();
                        bool nodata = false;
                        for (int k2 = 0; k2 < _noDataPhrases.Length; k2++)
                        {
                            if (lv.Contains(_noDataPhrases[k2])) { nodata = true; break; }
                        }
                        if (nodata) { continue; }
                    }
                    return true;
                }
                return false;
            }
            if (e.Type == JTokenType.Array) { return ArrayHasSubstance((JArray)e, depth - 1); }
            return e.ToString().Trim().Length > 0;
        }

        private static bool ArrayHasSubstance(JArray a, int depth)
        {
            // POSITIONAL ROW heuristic: an array of only scalars is a columnar
            // row whose first element is conventionally the timestamp/offset, so
            // it alone is not a measurement -- require a non-null value at index
            // >= 1. (Result schemas would replace this heuristic with real
            // column semantics; it fails SAFE toward ungrounded.)
            bool allScalar = a.Count > 0; bool anyComposite = false;
            for (int k = 0; k < a.Count; k++)
            {
                JTokenType tt = a[k] == null ? JTokenType.Null : a[k].Type;
                if (tt == JTokenType.Object || tt == JTokenType.Array) { allScalar = false; anyComposite = true; }
            }
            if (anyComposite)
            {
                // MIXED row (e.g. [ts, {"value":null}]): scalars in a composite row
                // are positional identifiers, so only composite members can supply
                // substance.
                for (int k = 0; k < a.Count; k++)
                {
                    JTokenType tt2 = a[k] == null ? JTokenType.Null : a[k].Type;
                    if (tt2 != JTokenType.Object && tt2 != JTokenType.Array) { continue; }
                    if (ElementHasSubstance(a[k], depth)) { return true; }
                }
                return false;
            }
            if (allScalar)
            {
                for (int k = 1; k < a.Count; k++)
                {
                    JToken e = a[k];
                    if (e == null || e.Type == JTokenType.Null || e.Type == JTokenType.Boolean) { continue; }
                    string sv = e.ToString().Trim();
                    if (sv.Length == 0) { continue; }
                    // a measurement is numeric: also rejects header rows like
                    // ["ts","value"] and placeholders like "N/A"
                    decimal nv;
                    if (!decimal.TryParse(sv, System.Globalization.NumberStyles.Any,
                            System.Globalization.CultureInfo.InvariantCulture, out nv)) { continue; }
                    return true;
                }
                return false;
            }
            for (int k = 0; k < a.Count; k++)
            {
                if (ElementHasSubstance(a[k], depth)) { return true; }
            }
            return false;
        }

        private static void ScanDataKeys(JObject jo, int depth, ref bool saw, ref bool good)
        {
            if (depth < 0) { return; }
            foreach (var prop in jo.Properties())
            {
                string ln = prop.Name.ToLowerInvariant();
                JToken v = prop.Value;
                bool isDataKey = false;
                for (int k = 0; k < _dataKeys.Length; k++) { if (ln == _dataKeys[k]) { isDataKey = true; break; } }
                if (isDataKey && v != null && v.Type == JTokenType.Array)
                {
                    saw = true;
                    if (ArrayHasSubstance((JArray)v, 2)) { good = true; }
                }
                else if (v != null && v.Type == JTokenType.Object)
                {
                    // an error-marked wrapper cannot supply evidence, whatever it contains
                    if (IsErrorObject((JObject)v)) { saw = true; continue; }
                    ScanDataKeys((JObject)v, depth - 1, ref saw, ref good);
                }
            }
        }

        // The in-hand server wraps every tool outcome as
        //   McpToolResult { "content":[{"text":...}], "isError": true|absent }
        // inside a JSON-RPC SUCCESS result (MCPHelper.cs:59-68, :925;
        // MCPServerProject.HandleToolCallAsync). Unwrap that shape wherever it
        // appears (root, or under "result"), reject on isError at ANY level,
        // and re-judge extracted content text recursively -- so
        // "Tool execution failed: <raw>" dies whether the client hands us the
        // raw envelope, the result object, or the unwrapped text.
        private static bool JudgeMcpShape(JObject jo, bool requireJson, int depth, out bool handled)
        {
            handled = false;
            if (depth < 0) { return false; }
            // ROOT error marker decides FIRST: a failure envelope cannot be
            // rescued by well-formed content nested under "result".
            if (IsErrorObject(jo)) { handled = true; return false; }
            JToken res = PropCI(jo, "result");
            if (res != null && res.Type == JTokenType.Object)
            {
                bool h2;
                bool ok = JudgeMcpShape((JObject)res, requireJson, depth - 1, out h2);
                if (h2) { handled = true; return ok; }
            }
            JToken content = PropCI(jo, "content");
            if (content != null && content.Type == JTokenType.Array)
            {
                handled = true;
                JArray ca = (JArray)content;
                StringBuilder sb = new StringBuilder();
                for (int k = 0; k < ca.Count; k++)
                {
                    if (ca[k] == null || ca[k].Type != JTokenType.Object) { continue; }
                    JToken tx = PropCI((JObject)ca[k], "text");
                    if (tx != null && tx.Type == JTokenType.String) { sb.Append(tx.ToString()); }
                }
                string inner = sb.ToString().Trim();
                if (inner.Length == 0) { return false; }
                return LooksUsableInner(inner, requireJson, depth - 1);
            }
            return false;
        }

        // The MCP transport can hand back SEVERAL concatenated JSON documents in
        // one string -- one per content block. JToken.Parse rejects that outright
        // ("additional text after finished reading"), which looked exactly like
        // truncation even though head and tail were both well formed. Parse
        // permissively so every document is judged on its own.
        private static List<JToken> ParseJsonDocuments(string r)
        {
            List<JToken> parts = new List<JToken>();
            try { parts.Add(JToken.Parse(r)); return parts; }
            catch { parts.Clear(); }
            try
            {
                using (System.IO.StringReader sr = new System.IO.StringReader(r))
                using (JsonTextReader jr = new JsonTextReader(sr))
                {
                    jr.SupportMultipleContent = true;
                    while (jr.Read())
                    {
                        JToken t = JToken.ReadFrom(jr);
                        if (t != null) { parts.Add(t); }
                        if (parts.Count >= 25) { break; }
                    }
                }
            }
            catch { /* keep whatever parsed cleanly before the fault */ }
            if (parts.Count > 0) { return parts; }

            // TRANSPORT TRUNCATION. The MCP client splices a human-readable marker
            //   [...234311 chars truncated - narrow the query]
            // into the MIDDLE of the JSON, keeping a head and a tail. Head and tail
            // both look well formed, so this presented as mysterious corruption.
            // Salvage the HEAD: cut back to the last completed element and close the
            // open containers, which yields valid JSON holding the earliest samples
            // -- the oldest part of the window, which is what a trend needs.
            JToken repaired = RepairTruncatedJson(r);
            if (repaired != null) { parts.Add(repaired); return parts; }

            // Last resort: LINE-DELIMITED documents. Observed in the wild -- a tool
            // result arrives as a TRUNCATED document followed on a later line by a
            // COMPLETE one. A sequential reader aborts on the broken first document
            // and never reaches the intact copy, so the whole payload looked
            // corrupt. Judge each line independently and keep the ones that parse.
            try
            {
                string[] lines = r.Split('\n');
                for (int i = 0; i < lines.Length; i++)
                {
                    string ln = lines[i].Trim();
                    if (ln.Length < 3) { continue; }
                    if (ln[0] != '[' && ln[0] != '{') { continue; }
                    try { parts.Add(JToken.Parse(ln)); }
                    catch { /* truncated fragment: skip it */ }
                    if (parts.Count >= 25) { break; }
                }
            }
            catch { }
            return parts;
        }

        private static readonly System.Text.RegularExpressions.Regex _truncMarker =
            new System.Text.RegularExpressions.Regex(
                @"\[\s*\.\.\.\s*[0-9][0-9,]*\s*chars\s+truncated[^\]]*\]",
                System.Text.RegularExpressions.RegexOptions.Compiled);

        private static JToken RepairTruncatedJson(string r)
        {
            if (string.IsNullOrEmpty(r)) { return null; }
            System.Text.RegularExpressions.Match m = _truncMarker.Match(r);
            if (!m.Success) { return null; }
            string head = r.Substring(0, m.Index);
            if (head.Length < 8) { return null; }

            // walk the head, remembering the last index at which a NESTED element
            // finished -- that is the last point we can cut without splitting a value
            List<char> stack = new List<char>();
            bool inStr = false, esc = false;
            int lastSafe = -1;
            for (int i = 0; i < head.Length; i++)
            {
                char c = head[i];
                if (esc) { esc = false; continue; }
                if (inStr && c == '\\') { esc = true; continue; }
                if (c == '"') { inStr = !inStr; continue; }
                if (inStr) { continue; }
                if (c == '{' || c == '[') { stack.Add(c); }
                else if (c == '}' || c == ']')
                {
                    if (stack.Count > 0) { stack.RemoveAt(stack.Count - 1); }
                    if (stack.Count > 0) { lastSafe = i; }
                }
            }
            if (lastSafe < 0) { return null; }

            string cut = head.Substring(0, lastSafe + 1);
            stack.Clear(); inStr = false; esc = false;
            for (int i = 0; i < cut.Length; i++)
            {
                char c = cut[i];
                if (esc) { esc = false; continue; }
                if (inStr && c == '\\') { esc = true; continue; }
                if (c == '"') { inStr = !inStr; continue; }
                if (inStr) { continue; }
                if (c == '{' || c == '[') { stack.Add(c); }
                else if (c == '}' || c == ']') { if (stack.Count > 0) { stack.RemoveAt(stack.Count - 1); } }
            }
            StringBuilder sb = new StringBuilder(cut);
            for (int i = stack.Count - 1; i >= 0; i--) { sb.Append(stack[i] == '{' ? '}' : ']'); }
            try { return JToken.Parse(sb.ToString()); }
            catch { return null; }
        }

        private static bool JudgeJsonToken(JToken t, bool requireJson, int depth)
        {
            if (t == null) { return false; }
            return LooksUsableInner(t.ToString(Formatting.None), requireJson, depth);
        }

        // v1.0.160.153: the MCP server returns E7 API failures (403 session-expired etc.) as
        // PLAIN-TEXT tool RESULTS, not tool errors. Detect them by their fixed prefixes.
        private static bool IsE7ApiFailureText(string s)
        {
            if (s == null)
            {
                return false;
            }
            string t = s.TrimStart();
            return t.StartsWith("E7 API returned ", StringComparison.Ordinal)
                || t.StartsWith("E7 API call failed", StringComparison.Ordinal);
        }

        // v1.0.160.153: name the failure in the log, mark the run degraded, and hand the caller
        // null so every consumer takes its existing missing-input path.
        private string DropE7ApiFailure(string result, string toolName)
        {
            if (!IsE7ApiFailureText(result))
            {
                return result;
            }
            string one = result.Trim();
            if (one.Length > 140)
            {
                one = one.Substring(0, 140);
            }
            _e7ApiInputFailed = true;
            AiLog("WARN", "PREFETCH", toolName + " returned an E7 API failure -- treated as MISSING input: " + one);
            return null;
        }

        private static bool LooksUsableToolResult(string result, bool requireJson)
        {
            return LooksUsableInner(result, requireJson, 2);
        }

        private static bool LooksUsableInner(string result, bool requireJson, int depth)
        {
            if (result == null || depth < 0) { return false; }
            string r = result.Trim();
            if (r.Length < 3) { return false; }
            if (r.StartsWith("Tool '", StringComparison.Ordinal)) { return false; }
            if (r.StartsWith("<", StringComparison.Ordinal)) { return false; } // HTML
            if (r.StartsWith("[") || r.StartsWith("{"))
            {
                List<JToken> _docs = ParseJsonDocuments(r);
                if (_docs.Count == 0) { return false; } // genuinely malformed
                if (_docs.Count > 1)
                {
                    // several concatenated documents: usable if ANY carries evidence
                    for (int _di = 0; _di < _docs.Count; _di++)
                    {
                        if (JudgeJsonToken(_docs[_di], requireJson, depth)) { return true; }
                    }
                    return false;
                }
                JToken t = _docs[0];
                if (t.Type == JTokenType.Array)
                {
                    JArray a = (JArray)t;
                    if (a.Count == 0) { return false; }
                    // client may project ONLY the MCP content[] array, dropping the
                    // parent isError flag: detect that shape and re-judge its text
                    // MCP content projection = EVERY element is an object carrying
                    // "text". Requiring "text" on all elements keeps legitimate data
                    // rows with a "type" column (e.g. [{"type":"analog","value":12.3}])
                    // out of this branch; a mixed array like [{"text":...},0] is not a
                    // projection either and falls through to substance rules.
                    // ANY element carrying "text" marks an MCP content projection
                    // (a mixed array like [{"text":...},0] is one too). Legitimate
                    // data rows have no "text" column, so [{"type":"analog",
                    // "value":12.3}] is unaffected. A data row that DID carry "text"
                    // would be re-judged and, if non-JSON, fail SAFE to ungrounded.
                    bool contentShape = false;
                    for (int k = 0; k < a.Count; k++)
                    {
                        if (a[k].Type == JTokenType.Object && PropCI((JObject)a[k], "text") != null)
                        {
                            contentShape = true; break;
                        }
                    }
                    if (contentShape)
                    {
                        StringBuilder cb = new StringBuilder();
                        for (int k = 0; k < a.Count; k++)
                        {
                            if (a[k] == null || a[k].Type != JTokenType.Object) { continue; } // scalars in a mixed array must not be cast
                            JToken tx = PropCI((JObject)a[k], "text");
                            if (tx != null && tx.Type == JTokenType.String) { cb.Append(tx.ToString()); }
                        }
                        string inner = cb.ToString().Trim();
                        if (inner.Length == 0) { return false; }
                        return LooksUsableInner(inner, requireJson, depth - 1);
                    }
                    return ArrayHasSubstance(a, 2);
                }
                if (t.Type == JTokenType.Object)
                {
                    JObject jo = (JObject)t;
                    if (jo.Count == 0) { return false; }
                    bool handled;
                    bool mcpOk = JudgeMcpShape(jo, requireJson, depth, out handled);
                    if (handled) { return mcpOk; } // MCP envelope/result decided
                    if (IsErrorObject(jo)) { return false; }
                    bool saw = false, good = false;
                    ScanDataKeys(jo, 2, ref saw, ref good);
                    if (saw) { return good; }
                    if (requireJson)
                    {
                        // EVIDENCE mode. A recognised data container is the norm, but the
                        // FRS tools return NESTED shapes with no top-level data key and no
                        // top-level numerics -- e.g. get_hist_realtime {"report":{...},
                        // "relay":[...]} and analyse_alert {cause_code_def, instant, reda,
                        // formula_check}. The earlier rule counted only top-level numbers
                        // and so rejected real telemetry as ungrounded. Accept a payload
                        // that carries substantive nested content; error shells, no-data
                        // prose and empty containers have already been rejected above, and
                        // an explicit data key still decides on its own.
                        if (ElementHasSubstance(jo, 3)) { return true; }
                        // scalar-METRIC response (trend_get: direction/slope/pct_change)
                        int metrics = 0;
                        foreach (var prop in jo.Properties())
                        {
                            JToken v = prop.Value;
                            if (v == null || v.Type == JTokenType.Null) { continue; }
                            if (IsMetadataKey(prop.Name)) { continue; }
                            if (v.Type == JTokenType.Integer || v.Type == JTokenType.Float) { metrics++; }
                        }
                        return metrics >= 2;
                    }
                    foreach (var prop in jo.Properties())
                    {
                        string ln = prop.Name.ToLowerInvariant();
                        if ((ln == "count" || ln == "total" || ln == "rows")
                            && (prop.Value.Type == JTokenType.Integer || prop.Value.Type == JTokenType.Float)
                            && prop.Value.ToString() == "0") { return false; }
                    }
                    if (HasNonEmptyArray(jo, 2)) { return true; }
                    int informative = 0;
                    foreach (var prop in jo.Properties())
                    {
                        JToken v = prop.Value;
                        if (v == null || v.Type == JTokenType.Null) { continue; }
                        if (v.Type == JTokenType.Array) { continue; }
                        if (v.Type == JTokenType.Boolean) { continue; }
                        string lname = prop.Name.ToLowerInvariant();
                        if (lname == "message" || lname == "status" || lname == "success") { continue; }
                        informative++;
                    }
                    return informative >= 3;
                }
                return false;
            }
            if (requireJson) { return false; } // evidence must be JSON from this server
            string lower = r.ToLowerInvariant();
            for (int k = 0; k < _noDataPhrases.Length; k++)
            {
                if (lower.Contains(_noDataPhrases[k])) { return false; }
            }
            return r.Length > 10;
        }

        private static bool HasNonEmptyArray(JToken t, int depth)
        {
            if (depth < 0 || t == null) { return false; }
            if (t.Type == JTokenType.Array) { return ArrayHasSubstance((JArray)t, depth); } // substance, not count
            if (t.Type == JTokenType.Object)
            {
                foreach (var prop in ((JObject)t).Properties())
                {
                    if (HasNonEmptyArray(prop.Value, depth - 1)) { return true; }
                }
            }
            return false;
        }

        private static readonly string[] _evidenceTools =
            { "history_get", "get_attribute_range", "get_attribute_range_history", "get_frs_alerts",
              "analyse_alert", "get_hist_realtime", "fetch_alert_details_frs",
              "predict_track_health", "predict_pm_operation", "predict_pm_cluster" };
        // Why a payload was rejected. PARSE_FAIL almost always means the result
        // was truncated in transit -- compare the tail in the preview.
        private static string RejectReason(string result, bool requireJson)
        {
            if (string.IsNullOrEmpty(result)) { return "EMPTY"; }
            string r = result.Trim();
            if (r.StartsWith("Tool '", StringComparison.Ordinal)) { return "TOOL_FAILED"; }
            if (r.StartsWith("<", StringComparison.Ordinal)) { return "HTML"; }
            if (r.StartsWith("[") || r.StartsWith("{"))
            {
                Exception pex = null;
                try { JToken.Parse(r); return "NO_SUBSTANCE"; }
                catch (Exception e1) { pex = e1; }
                List<JToken> docs = ParseJsonDocuments(r);
                if (docs.Count > 1) { return "MULTI_DOC(" + docs.Count + ")_NO_SUBSTANCE"; }
                if (docs.Count == 1) { return _truncMarker.IsMatch(r) ? "TRUNCATED_REPAIRED_NO_SUBSTANCE" : "NO_SUBSTANCE"; }
                // Newtonsoft names the offending character AND its position; quote
                // both plus the surrounding text so the defect is identified rather
                // than inferred.
                string pm = pex == null ? "" : pex.Message.Replace("\r", " ").Replace("\n", " ");
                if (pm.Length > 180) { pm = pm.Substring(0, 180); }
                return "PARSE_FAIL: " + pm + ContextAtPosition(r, pex);
            }
            return requireJson ? "NOT_JSON" : "PROSE";
        }

        // Head AND tail of a rejected payload: a tail that does not close the
        // JSON is proof of truncation. Redacted and newline-flattened.
        // Pull "position NNNN" out of the parser message and quote the text
        // around it, so a corrupt byte in the middle of a payload is visible.
        private static string ContextAtPosition(string r, Exception pex)
        {
            if (pex == null || string.IsNullOrEmpty(r)) { return ""; }
            try
            {
                // Newtonsoft reports line AND position-within-that-line, not an
                // absolute offset. Resolve the line first, or the quoted context
                // points at the start of the payload and misleads.
                System.Text.RegularExpressions.Match ml =
                    System.Text.RegularExpressions.Regex.Match(pex.Message, @"line (\d+)");
                System.Text.RegularExpressions.Match m =
                    System.Text.RegularExpressions.Regex.Match(pex.Message, @"position (\d+)");
                if (!m.Success) { return ""; }
                int pos = int.Parse(m.Groups[1].Value);
                if (ml.Success)
                {
                    int lineNo = int.Parse(ml.Groups[1].Value);
                    int off = 0;
                    for (int L = 1; L < lineNo && off >= 0; L++)
                    {
                        int nx = r.IndexOf('\n', off);
                        if (nx < 0) { off = -1; break; }
                        off = nx + 1;
                    }
                    if (off >= 0) { pos += off; }
                }
                int from = Math.Max(0, pos - 45);
                int len = Math.Min(90, r.Length - from);
                if (len <= 0) { return ""; }
                string around = r.Substring(from, len).Replace("\r", " ").Replace("\n", " ");
                StringBuilder esc = new StringBuilder();
                for (int i = 0; i < around.Length; i++)
                {
                    char c = around[i];
                    if (c < 32 || c == 127) { esc.Append("<0x").Append(((int)c).ToString("x2")).Append(">"); }
                    else { esc.Append(c); }
                }
                return " @pos" + pos + " >>[" + esc.ToString() + "]";
            }
            catch { return ""; }
        }

        private static string TracePreview(string result)
        {
            if (string.IsNullOrEmpty(result)) { return "(empty)"; }
            string t = RedactSecretText(result).Replace("\r", " ").Replace("\n", " ").Trim();
            if (t.Length <= 200) { return t; }
            return t.Substring(0, 140) + " ...TAIL: " + t.Substring(t.Length - 60);
        }

        private void CollectAssetHints(JToken toolArgs)
        {
            JObject o = toolArgs as JObject;
            if (o == null || _jsonAssetHints == null) { return; }
            foreach (var prop in o.Properties())
            {
                string ln = prop.Name.ToLowerInvariant();
                if (ln != "assetid" && ln != "assetids" && ln != "aid" && ln != "asset_id") { continue; }
                JToken v = prop.Value;
                if (v == null) { continue; }
                if (v.Type == JTokenType.Array)
                {
                    foreach (JToken e in (JArray)v)
                    {
                        if (e != null && e.Type != JTokenType.Null) { _jsonAssetHints.Add(e.ToString()); }
                    }
                }
                else if (v.Type != JTokenType.Null) { _jsonAssetHints.Add(v.ToString()); }
            }
        }

        // get_attribute_range is SITE-scoped by design: the server calls
        // FRSAttributeRange/SiteId/{id} and there is no AssetId filter, so it
        // returns the baseline row for EVERY attribute of EVERY asset at the
        // station -- measured at ~266 KB, which then gets truncated in transit and
        // discarded. The analysis only ever concerns one asset, so keep the rows
        // for the AssetIds this request has actually used and drop the rest.
        // Falls through untouched if nothing matches, so a mismatch can never
        // remove evidence.
        private string NarrowAttributeRange(string toolName, string result)
        {
            if (!string.Equals(toolName, "get_attribute_range", StringComparison.OrdinalIgnoreCase)) { return result; }
            if (_jsonAssetHints == null || _jsonAssetHints.Count == 0) { return result; }
            if (string.IsNullOrEmpty(result)) { return result; }
            try
            {
                List<JToken> docs = ParseJsonDocuments(result);
                for (int d = 0; d < docs.Count; d++)
                {
                    // v1.0.104.0: the FRSAttributeRangeHistory response is a JOBJECT with an
                    // AssetAttributes[] array PLUS top-level site context (Latitude, Longitude,
                    // FamilyTrack, SignalTrackMapping, SiteName, StationCode). Emit ONE VALID
                    // JSON OBJECT {siteContext, legend, rows} - NOT text+JSON. get_attribute_range
                    // is an evidence tool (requireJson=true); a "[SITE CONTEXT] ..." or "legend:"
                    // prefix is not valid JSON and the evidence validator rejects the whole
                    // result, dropping the baseline (the 1.0.102 defect). A single object passes
                    // validation on prefetch AND both agentic paths while keeping geo + topology.
                    JObject obj = docs[d] as JObject;
                    if (obj != null)
                    {
                        JArray attrs = PropCI(obj, "AssetAttributes") as JArray;
                        if (attrs != null)
                        {
                            JArray keptO = new JArray();
                            for (int i = 0; i < attrs.Count; i++)
                            {
                                JObject row = attrs[i] as JObject;
                                if (row == null) { continue; }
                                JToken aid = PropCI(row, "AssetId") ?? PropCI(row, "Id");
                                if (aid == null || _jsonAssetHints.Contains(aid.ToString())) { keptO.Add(row); }
                            }
                            if (keptO.Count == 0) { keptO = attrs; }
                            AddDiag("ATTR_RANGE_NARROWED");
                            return BuildRangeJson(obj, keptO);
                        }
                    }
                    JArray arr = docs[d] as JArray;
                    if (arr == null) { continue; }
                    JArray kept = new JArray();
                    for (int i = 0; i < arr.Count; i++)
                    {
                        JObject row = arr[i] as JObject;
                        if (row == null) { continue; }
                        JToken aid = PropCI(row, "AssetId");
                        if (aid != null && _jsonAssetHints.Contains(aid.ToString())) { kept.Add(row); }
                    }
                    if (kept.Count > 0)
                    {
                        AddDiag("ATTR_RANGE_NARROWED");
                        // bare-array form (no site context available) - still emit valid JSON
                        return BuildRangeJson(null, kept);
                    }
                }
            }
            catch { }
            return result;
        }

        // v1.0.104.0: assemble the compact attribute-range evidence as ONE valid JSON object.
        // Shape: { "siteContext": {...}, "legend": {...}, "rows": [ {a,t,n,avg,max,min,fail}, ... ] }
        // siteContext is omitted when no geo/topology is present (bare-array form). This is the
        // single thing get_attribute_range returns to the model, and it must be valid JSON.
        private static string BuildRangeJson(JObject src, JArray keptRows)
        {
            JObject outObj = new JObject();
            if (src != null)
            {
                JObject sc = SiteContextObject(src);
                if (sc != null) { outObj["siteContext"] = sc; }
            }
            outObj["legend"] = new JObject
            {
                ["a"] = "AssetId", ["t"] = "AssetAttributeId", ["n"] = "AttributeName",
                ["avg"] = "AverageValue", ["max"] = "MaxSafeValue", ["min"] = "MinSafeValue",
                ["fail"] = "MinFailValue"
            };
            JArray rows = new JArray();
            for (int i = 0; i < keptRows.Count; i++)
            {
                JObject r = keptRows[i] as JObject;
                if (r == null) { continue; }
                JObject c = new JObject();
                CopyIf(r, c, "AssetId", "a");
                CopyIf(r, c, "AssetAttributeId", "t");
                CopyIf(r, c, "AttributeName", "n");
                CopyIf(r, c, "AverageValue", "avg");
                CopyIf(r, c, "MaxSafeValue", "max");
                CopyIf(r, c, "MinSafeValue", "min");
                CopyIf(r, c, "MinFailValue", "fail");
                // Raw FRS rows use Id/Title rather than AssetAttributeId/AttributeName - fall
                // back to those so the attribute id/name survive whichever shape the tool emits.
                if (c["t"] == null) { CopyIf(r, c, "Id", "t"); }
                if (c["n"] == null) { CopyIf(r, c, "Title", "n"); }
                if (c.Count > 0) { rows.Add(c); }
            }
            outObj["rows"] = rows;
            return outObj.ToString(Formatting.None);
        }

        // v1.0.104.0: site context (geo + topology) as a JSON OBJECT, or null if nothing present.
        // These are top-level fields on the FRSAttributeRangeHistory object, dropped by the per-row
        // compactor, so they are surfaced here. Topology values are numeric asset IDs; the model is
        // told to cite the ID (not invent a name) unless site-alert evidence maps the ID to a name.
        private static JObject SiteContextObject(JObject obj)
        {
            if (obj == null) { return null; }
            JToken lat = PropCI(obj, "Latitude");
            JToken lon = PropCI(obj, "Longitude");
            JToken site = PropCI(obj, "SiteName");
            JToken code = PropCI(obj, "StationCode");
            JToken fam = PropCI(obj, "FamilyTrack");
            JToken sigMap = PropCI(obj, "SignalTrackMapping") ?? PropCI(obj, "SignalTrackMappings");
            JToken ptMap = PropCI(obj, "PointTrackMapping") ?? PropCI(obj, "PointTrackMappings");
            bool any = site != null || code != null || lat != null || lon != null
                       || fam != null || sigMap != null || ptMap != null;
            if (!any) { return null; }
            JObject sc = new JObject();
            if (site != null) { sc["site"] = site.ToString(); }
            if (code != null) { sc["code"] = code.ToString(); }
            if (lat != null) { sc["latitude"] = lat; }
            if (lon != null) { sc["longitude"] = lon; }
            if (fam != null) { sc["familyTracks"] = IdArray(fam, "TrackFamilyId"); }
            if (sigMap != null) { sc["signalTrack"] = IdArray(sigMap, "SignalAssetId"); }
            if (ptMap != null) { sc["pointTrack"] = IdArray(ptMap, "PointAssetId"); }
            return sc;
        }

        // Render a mapping array like [{"TrackFamilyId":41516},...] as a compact JSON id array.
        private static JArray IdArray(JToken t, string idField)
        {
            JArray outA = new JArray();
            JArray a = t as JArray;
            if (a == null) { return outA; }
            for (int i = 0; i < a.Count; i++)
            {
                JObject o = a[i] as JObject;
                if (o != null) { JToken v = PropCI(o, idField); if (v != null) { outA.Add(v); } }
                else { outA.Add(a[i]); }
            }
            return outA;
        }

        private static void CopyIf(JObject src, JObject dst, string from, string to)
        {
            JToken v = PropCI(src, from);
            if (v != null && v.Type != JTokenType.Null) { dst[to] = v; }
        }

        // v1.0.117.0: pull latitude/longitude out of a get_attribute_range_history response.
        // The handoff delivers them as top-level "latitude"/"longitude" STRINGS (e.g. "26.7046");
        // accept string or number, case-insensitively. Returns false if either is absent/unparseable.
        // v1.0.160.46: the station code can arrive in four places depending on which page opened the
        // analysis. Ordered most-specific-first; all are CODES (never the station NAME).
        private static string ResolveStationCode(JObject ctx, string rangeHistoryJson)
        {
            // v1.0.160.203: hardcoded override -- site 71 (Bhilai G Cabin) uses DBEC for the timetable.
            string sid = GetCtx(ctx, "siteId");
            if (!string.IsNullOrEmpty(sid) && sid.Trim() == "71")
            {
                AiLogStatic("INFO", "TRAIN", "station code hardcoded: siteId 71 -> DBEC");
                return "DBEC";
            }
            // v1.0.160.136: CODE first. ctx["station"] carries the station NAME since 1.0.160.110,
            // and a name is not a valid timetable key.
            string stn = GetCtx(ctx, "stationCode");
            if (!string.IsNullOrEmpty(stn)) { return stn.Trim(); }
            try
            {
                JObject card = ctx != null ? ctx["alertCard"] as JObject : null;
                if (card != null)
                {
                    string cs = GetCtx(card, "stationCode");
                    if (!string.IsNullOrEmpty(cs)) { return cs.Trim(); }
                }
            }
            catch { }
            // v1.0.160.136: ctx["station"] LAST, and only if it looks like a code rather than a
            // name -- SAKHUN is a name, SK is a code. A wrong key fetches nothing and, on a
            // best-effort path, fails silently.
            string nm = GetCtx(ctx, "station");
            if (!string.IsNullOrEmpty(nm))
            {
                string t = nm.Trim();
                if (t.Length <= 5 && t.IndexOf(' ') < 0) { return t; }
            }
            // Last resort: the E7 API returns stationCode alongside lat/lon in the range-history
            // payload, so a client that sends no code at all still resolves.
            try
            {
                if (!string.IsNullOrEmpty(rangeHistoryJson))
                {
                    // v1.0.160.81: tolerant parse. JObject.Parse throws when the server truncates this
                    // payload mid-array, and the station code was being lost even though it sits in the
                    // first ~120 chars and survives every cut. TryExtractLatLon below already parses
                    // this defensively -- that asymmetry is why weather kept working and trains did not.
                    List<JToken> rhDocs = ParseJsonDocuments(rangeHistoryJson);
                    for (int i = 0; i < rhDocs.Count; i++)
                    {
                        JObject rho = rhDocs[i] as JObject;
                        if (rho == null) { continue; }
                        string rs2 = GetCtx(rho, "stationCode");
                        if (!string.IsNullOrEmpty(rs2)) { return rs2.Trim(); }
                    }
                    // Last resort: read it straight out of the head. A cut payload is not valid JSON,
                    // but the field is still sitting there in plain text.
                    Match sm = Regex.Match(rangeHistoryJson,
                        "\"stationCode\"\\s*:\\s*\"([A-Za-z0-9_-]{1,12})\"");
                    if (sm.Success)
                    {
                        AiLogStatic("INFO", "TRAIN", "station code recovered by scan from a truncated range-history payload");
                        return sm.Groups[1].Value.Trim();
                    }
                }
            }
            catch { }
            return "";
        }

        private static bool TryExtractLatLon(string rangeHistoryJson, out double lat, out double lon)
        {
            lat = 0; lon = 0;
            if (string.IsNullOrEmpty(rangeHistoryJson)) { return false; }
            try
            {
                List<JToken> docs = ParseJsonDocuments(rangeHistoryJson);
                for (int d = 0; d < docs.Count; d++)
                {
                    JObject o = docs[d] as JObject;
                    if (o == null) { continue; }
                    JToken latT = PropCI(o, "latitude");
                    JToken lonT = PropCI(o, "longitude");
                    if (latT == null || lonT == null) { continue; }
                    if (double.TryParse(latT.ToString(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out lat)
                        && double.TryParse(lonT.ToString(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out lon)
                        && (Math.Abs(lat) > 1e-6 || Math.Abs(lon) > 1e-6))
                    { return true; }
                }
            }
            catch { }
            return false;
        }

        // ═════════════════════════════════════════════════════════
        //  WEATHER (Option A) - controller-side external enrichment, NOT an MCP tool.
        //  Rain/lightning are top external causes and hit multiple assets; if it rained/
        //  thundered at the site around incidence, that supports a site-wide/environmental
        //  read. The controller fetches this itself (Open-Meteo, no API key), gated on
        //  weather-relevant cause codes, and injects it as evidence - so the EdgeX MCP
        //  server never carries a third-party API. Best-effort: any failure/timeout ->
        //  no weather block (the model then never mentions weather).
        // ═════════════════════════════════════════════════════════
        private static readonly bool _weatherEnabled = ReadBool("WeatherEnrichment", true);
        private static readonly int _weatherTimeoutSec = ReadInt("WeatherTimeoutSec", 6);
        private static readonly System.Net.Http.HttpClient _weatherHttp = new System.Net.Http.HttpClient();

        // v1.0.160.33: TRAIN-CONTEXT config. Scheduled trains through the alert's STATION around the
        // alert time, fetched by direct HTTP from a public timetable (totaltraininfo) and parsed
        // controller-side -- best-effort, zero model tokens, mirrors the weather card. SCHEDULED, not
        // confirmed passage. OFF by default; set TrainContextEnabled=true to enable per site.
        private static readonly bool _trainCtxEnabled = ReadBool("TrainContextEnabled", false);
        private static readonly int _trainCtxWindowMin = ClampCfg(ReadInt("TrainContextWindowMin", 5), 1, 60);
        private static readonly int _trainCtxTimeoutMs = ClampCfg(ReadInt("TrainContextTimeoutMs", 4000), 1000, 15000);
        private static readonly string _trainCtxBaseUrl = ReadStr("TrainContextBaseUrl", "https://www.totaltraininfo.com/station/");
        // v1.0.160.41 (Guard B): a real station page lists tens of trains; the generic fallback page
        // served for an UNKNOWN code lists ~1454. Anything above this ceiling is not a station page.
        private static readonly int _trainCtxMaxTrains = ClampCfg(ReadInt("TrainContextMaxTrains", 400), 20, 5000);
        private static readonly int _trainCtxCacheMin = ClampCfg(ReadInt("TrainContextCacheMinutes", 10), 0, 1440);
        private static readonly int _trainCtxMaxBytes = ClampCfg(ReadInt("TrainContextMaxKB", 2048), 64, 16384) * 1024;
        private static readonly System.Net.Http.HttpClient _trainCtxHttp = MakeTrainCtxHttp();
        // v1.0.160.35: per-station short-TTL cache so repeated alerts at the same station do not re-hit the
        // public site every time. Key = lowercased station code -> (fetchedUtc, html).
        private static readonly System.Collections.Concurrent.ConcurrentDictionary<string, Tuple<DateTime, string>> _trainCtxCache
            = new System.Collections.Concurrent.ConcurrentDictionary<string, Tuple<DateTime, string>>();
        private static System.Net.Http.HttpClient MakeTrainCtxHttp()
        {
            System.Net.Http.HttpClient h = new System.Net.Http.HttpClient();
            h.MaxResponseContentBufferSize = _trainCtxMaxBytes;   // cap the buffered body (P1: was unbounded)
            return h;
        }

        // Weather matters for track/rail-resistance/leakage/ballast (rain) and for surge/
        // multi-asset events (lightning). It is NOT relevant to point-machine mechanical or
        // pure config alerts, so those skip the fetch (deterministic, cheaper than a model turn).
        private static bool IsWeatherRelevantCause(string causeCode)
        {
            if (string.IsNullOrEmpty(causeCode)) { return false; }
            string c = causeCode.ToUpperInvariant();
            return c.Contains("RAIL RES") || c.Contains("TRACK") || c.Contains("TC ")
                || c.Contains("BALLAST") || c.Contains("LEAK") || c.Contains("RRAIL")
                || c.Contains("IPS") || c.Contains("POWER") || c.Contains("VOLT")
                || c.Contains("EARTH") || c.Contains("SURGE");
        }

        // Fetch a compact weather summary for the site around the incidence. Uses Open-Meteo's
        // historical archive (past incidence) by lat/long. Returns null on any problem.
        private async Task<string> FetchWeatherAsync(double lat, double lon, DateTime incidenceIst, System.Threading.CancellationToken ct)
        {
            try
            {
                // Archive API wants a date window; take the incidence day and the day before
                // (covers a pre-incidence rain build-up). Dates are the site-local date.
                string end = incidenceIst.ToString("yyyy-MM-dd", System.Globalization.CultureInfo.InvariantCulture);
                string start = incidenceIst.AddDays(-1).ToString("yyyy-MM-dd", System.Globalization.CultureInfo.InvariantCulture);
                string url = "https://archive-api.open-meteo.com/v1/archive"
                    + "?latitude=" + lat.ToString(System.Globalization.CultureInfo.InvariantCulture)
                    + "&longitude=" + lon.ToString(System.Globalization.CultureInfo.InvariantCulture)
                    + "&start_date=" + start + "&end_date=" + end
                    + "&hourly=precipitation,rain,weather_code,temperature_2m,wind_speed_10m"
                    + "&timezone=auto";

                using (System.Threading.CancellationTokenSource wc = System.Threading.CancellationTokenSource.CreateLinkedTokenSource(ct))
                {
                    wc.CancelAfter(TimeSpan.FromSeconds(_weatherTimeoutSec));
                    System.Net.Http.HttpResponseMessage resp = await _weatherHttp.GetAsync(url, wc.Token).ConfigureAwait(false);
                    if (!resp.IsSuccessStatusCode) { return null; }
                    string raw = await resp.Content.ReadAsStringAsync().ConfigureAwait(false);
                    return SummariseWeather(raw, incidenceIst);
                }
            }
            catch { return null; }   // egress blocked, timeout, parse fault -> no weather
        }

        // v1.0.119.0: reshape the internal weather JSON (rain/precip/thunderstorm/temp_c_range)
        // into the card's contract {condition, tempC, summary} so the verdict WEATHER tile renders
        // the real data. Attached to the verdict server-side (weather is a server-only key). Returns
        // null if the input is unusable.
        // v1.0.160.49: WMO weather-code -> condition word. Codes per the Open-Meteo/WMO table the
        // hourly weather_code field already returns. Falls back to the pre-160.49 rain/thunder
        // booleans when no code is present, so a missing code degrades to old behaviour.
        private static string WmoCondition(int wc, bool thunder, bool rain)
        {
            if (wc < 0)
            {
                return thunder ? "Thunderstorm" : (rain ? "Rain" : "Clear");
            }
            if (wc >= 95) { return "Thunderstorm"; }
            if (wc == 0) { return "Clear"; }
            if (wc == 1) { return "Mainly clear"; }
            if (wc == 2) { return "Partly cloudy"; }
            if (wc == 3) { return "Overcast"; }
            if (wc == 45 || wc == 48) { return "Fog"; }
            if (wc >= 51 && wc <= 57) { return "Drizzle"; }
            if (wc >= 61 && wc <= 67) { return "Rain"; }
            if (wc >= 71 && wc <= 77) { return "Snow"; }
            if (wc >= 80 && wc <= 82) { return "Rain showers"; }
            if (wc == 85 || wc == 86) { return "Snow showers"; }
            // unknown code: fall back to the measured booleans rather than inventing a sky.
            return thunder ? "Thunderstorm" : (rain ? "Rain" : "Clear");
        }

        private static JObject BuildWeatherCard(string weatherJson)
        {
            if (string.IsNullOrEmpty(weatherJson)) { return null; }
            try
            {
                JObject w = JObject.Parse(weatherJson);
                bool rain = w["rain"] != null && w["rain"].Type == JTokenType.Boolean && (bool)w["rain"];
                bool thunder = w["thunderstorm"] != null && w["thunderstorm"].Type == JTokenType.Boolean && (bool)w["thunderstorm"];
                double precip = 0; if (w["precip_mm_total"] != null) { double.TryParse(w["precip_mm_total"].ToString(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out precip); }

                // v1.0.160.49: map the WMO weather_code to a REAL sky state. The old three-way
                // ternary could only say Thunderstorm/Rain/"Dry", and "Dry" matches none of the
                // view's rvwxKind() patterns, so every dry alert drew the generic cloud. Every word
                // emitted below already matches an existing pattern (clear|cloud|overcast|fog|
                // drizzle|rain|shower|snow|thunder), so NO view change is needed.
                int wc = -1;
                if (w["weather_code"] != null) { int.TryParse(w["weather_code"].ToString(), out wc); }
                string condition = WmoCondition(wc, thunder, rain);
                JObject card = new JObject();
                card["condition"] = condition;
                // mid of the temp range, if present
                JArray tr = w["temp_c_range"] as JArray;
                if (tr != null && tr.Count == 2)
                {
                    double a, b;
                    if (double.TryParse(tr[0].ToString(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out a)
                        && double.TryParse(tr[1].ToString(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out b))
                    { card["tempC"] = Math.Round((a + b) / 2.0, 1); }
                }
                // summary: rainfall amount if any, else the plain condition
                if (rain || precip > 0.1) { card["summary"] = precip.ToString("0.#", System.Globalization.CultureInfo.InvariantCulture) + " mm around alert"; }
                // v1.0.160.49: the view classifies on condition+summary COMBINED, so the summary must
                // not contain a trigger word. The old text "no rain at alert time" matched /rain/ and
                // drew the RAIN icon on a dry day -- a pre-existing bug. "no precipitation" is neutral.
                else if (!thunder) { card["summary"] = "no precipitation around alert"; }
                return card;
            }
            catch { return null; }
        }

        // v1.0.160.33: fetch a public station timetable page (totaltraininfo) by station code. Direct
        // HTTP GET, short timeout, best-effort -- returns the raw HTML, or null on any problem.
        private static async Task<string> FetchStationTrainsAsync(string stationCode, System.Threading.CancellationToken ct)
        {
            try
            {
                string code = (stationCode ?? "").Trim().ToLowerInvariant();
                if (code.Length == 0) { return null; }
                // v1.0.160.35: serve from the short-TTL per-station cache when fresh (avoid re-hitting the site).
                Tuple<DateTime, string> hit;
                if (_trainCtxCacheMin > 0 && _trainCtxCache.TryGetValue(code, out hit) && hit != null
                    && (DateTime.UtcNow - hit.Item1).TotalMinutes < _trainCtxCacheMin)
                {
                    return hit.Item2;
                }
                string url = _trainCtxBaseUrl + Uri.EscapeDataString(code) + "/";
                using (System.Threading.CancellationTokenSource cts = System.Threading.CancellationTokenSource.CreateLinkedTokenSource(ct))
                {
                    cts.CancelAfter(_trainCtxTimeoutMs);
                    using (System.Net.Http.HttpRequestMessage req = new System.Net.Http.HttpRequestMessage(System.Net.Http.HttpMethod.Get, url))
                    {
                        req.Headers.TryAddWithoutValidation("User-Agent", "Mozilla/5.0 (compatible; E7MRIWeb/1.0)");
                        // v1.0.160.35: ResponseContentRead so the linked-CTS timeout covers the FULL body
                        // download (headers-only completion let a stalled body run past the timeout).
                        using (System.Net.Http.HttpResponseMessage resp = await _trainCtxHttp.SendAsync(req, System.Net.Http.HttpCompletionOption.ResponseContentRead, cts.Token).ConfigureAwait(false))
                        {
                            if (!resp.IsSuccessStatusCode) { return null; }
                            string body = await resp.Content.ReadAsStringAsync().ConfigureAwait(false);
                            // v1.0.160.36: cache ONLY a VALIDATED page (marker + >=1 parsed train), so a
                            // challenge / changed-format page can never suppress the station for the whole
                            // TTL; sweep expired entries first, and keep a hard ceiling to bound memory.
                            if (_trainCtxCacheMin > 0 && !string.IsNullOrEmpty(body) && ParseStationTrains(body, code).Count > 0)
                            {
                                SweepTrainCtxCache();
                                if (_trainCtxCache.Count < 512) { _trainCtxCache[code] = Tuple.Create(DateTime.UtcNow, body); }
                            }
                            return body;
                        }
                    }
                }
            }
            catch { return null; }
        }

        // v1.0.160.36: drop expired cache entries (TTL controls reuse but never removed them before, so the
        // dictionary could grow for the process lifetime). Snapshots the keys so removal is enumerator-safe.
        private static void SweepTrainCtxCache()
        {
            try
            {
                DateTime now = DateTime.UtcNow;
                foreach (string k in new System.Collections.Generic.List<string>(_trainCtxCache.Keys))
                {
                    Tuple<DateTime, string> v;
                    if (_trainCtxCache.TryGetValue(k, out v) && (v == null || (now - v.Item1).TotalMinutes >= _trainCtxCacheMin))
                    {
                        Tuple<DateTime, string> rm;
                        _trainCtxCache.TryRemove(k, out rm);
                    }
                }
            }
            catch { }
        }

        // Parse the station timetable HTML into rows of {train_no, name, arr, dep}. Tolerant: isolate
        // the trains table, split on <tr>, and per row take the first 4-5 digit train number + the
        // first two HH:MM times; skip rows that do not match. Best-effort -- a page-format change just
        // yields fewer/zero rows (no train_context), never an exception.
        private static List<string[]> ParseStationTrains(string html, string stationCode)
        {
            List<string[]> outp = new List<string[]>();
            if (string.IsNullOrEmpty(html)) { return outp; }
            try
            {
                // v1.0.160.41 GUARD A (page identity): an unknown station code is NOT a 404 -- the site
                // returns a generic page whose <title> has a BLANK station ("/  Railway Station | ..."),
                // while a real page reads "PPTA / Patliputra Junction Railway Station | ...". Requiring
                // the title to start with the requested code rejects the generic page outright, which
                // restores the fail-safe the pre-160.38 </table> bound provided by accident.
                if (!string.IsNullOrEmpty(stationCode))
                {
                    System.Text.RegularExpressions.Match ttl = System.Text.RegularExpressions.Regex.Match(
                        html, "<title[^>]*>(.*?)</title>",
                        System.Text.RegularExpressions.RegexOptions.IgnoreCase | System.Text.RegularExpressions.RegexOptions.Singleline);
                    if (!ttl.Success) { return outp; }
                    string tt = System.Net.WebUtility.HtmlDecode(ttl.Groups[1].Value);
                    tt = System.Text.RegularExpressions.Regex.Replace(tt, "\\s+", " ").Trim();
                    string want = stationCode.Trim();
                    bool idOk = tt.StartsWith(want + " ", StringComparison.OrdinalIgnoreCase)
                                || tt.StartsWith(want + "/", StringComparison.OrdinalIgnoreCase)
                                || string.Equals(tt, want, StringComparison.OrdinalIgnoreCase);
                    if (!idOk) { return outp; }   // generic/changed page -> no rows -> block omitted
                }
                // marker gate (unchanged): no "List of all trains" marker => not a valid timetable page
                // (bot-challenge / changed / invalid station) => return no rows, so BuildTrainContext
                // omits train_context rather than asserting a false "no train".
                int ti = html.IndexOf("List of all trains", StringComparison.OrdinalIgnoreCase);
                if (ti < 0) { return outp; }
                string region = html.Substring(ti);

                // v1.0.160.38 PATH A (current site layout): totaltraininfo migrated the timetable from
                // <table>/<tr> to <div class="sch-Table/sch-Row/sch-Cell">. The old </table> bound now
                // hits an unrelated table right after the marker and truncates to ~1 row. Split the
                // post-marker region on the schedule-exclusive "sch-Row" token; a genuine train row
                // carries a /train/<no>/schedule anchor (this also skips the header row and any
                // non-train segment). Arr/Dep = the HH:MM cells (1st=Arr, 2nd=Dep; a single time is an
                // originating/terminating train => Arr=Dep). Name from the row's title="..." attribute
                // (the anchor text is ellipsis-truncated); cosmetic.
                string[] divRows = System.Text.RegularExpressions.Regex.Split(region, "sch-Row", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                for (int r = 0; r < divRows.Length; r++)
                {
                    System.Text.RegularExpressions.Match dno = System.Text.RegularExpressions.Regex.Match(divRows[r], "/train/(\\d{4,6})/schedule", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                    if (!dno.Success) { continue; }

                    // v1.0.160.40 (D2 fix): read the row's CELLS, not the flattened row. Taking the first
                    // two HH:MM out of the whole row meant any stray time before the Arr cell became the
                    // arrival (e.g. an "Updated 23:59" cell -> arr=23:59). A time cell is a sch-Cell whose
                    // ENTIRE text is a bare HH:MM, so labelled cells ("Halt 10m", "Updated ...") cannot win.
                    System.Text.RegularExpressions.MatchCollection dcells = System.Text.RegularExpressions.Regex.Matches(
                        divRows[r], "sch-Cell[^>]*>(.*?)</div>",
                        System.Text.RegularExpressions.RegexOptions.IgnoreCase | System.Text.RegularExpressions.RegexOptions.Singleline);
                    List<string> dtimes = new List<string>();
                    string dname = "";
                    for (int ci = 0; ci < dcells.Count; ci++)
                    {
                        string cin = dcells[ci].Groups[1].Value;
                        string ctx = System.Text.RegularExpressions.Regex.Replace(cin, "<[^>]+>", " ");
                        ctx = System.Net.WebUtility.HtmlDecode(ctx);
                        ctx = System.Text.RegularExpressions.Regex.Replace(ctx, "\\s+", " ").Trim();
                        if (System.Text.RegularExpressions.Regex.IsMatch(ctx, "^\\d{1,2}:\\d{2}$")) { dtimes.Add(ctx); }
                        // v1.0.160.40 (D3 fix): the train name is the title= on the cell that ALSO carries
                        // the /train/<no>/schedule anchor -- not merely the first title= in the row (a
                        // leading UI title such as "Sort ascending" would otherwise win).
                        if (dname.Length == 0
                            && System.Text.RegularExpressions.Regex.IsMatch(cin, "/train/\\d{4,6}/schedule", System.Text.RegularExpressions.RegexOptions.IgnoreCase))
                        {
                            System.Text.RegularExpressions.Match cti = System.Text.RegularExpressions.Regex.Match(cin, "title=\"([^\"]+)\"", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                            if (cti.Success)
                            {
                                dname = System.Net.WebUtility.HtmlDecode(cti.Groups[1].Value);
                                dname = System.Text.RegularExpressions.Regex.Replace(dname, "\\s+", " ").Trim();
                            }
                        }
                    }
                    // Fallback ONLY if the cell structure is unrecognisable (markup changed again): scan
                    // the flattened row as 160.38 did, so a layout tweak degrades instead of dropping rows.
                    if (dtimes.Count < 1)
                    {
                        string dtext = System.Text.RegularExpressions.Regex.Replace(divRows[r], "<[^>]+>", " ");
                        dtext = System.Net.WebUtility.HtmlDecode(dtext);
                        dtext = System.Text.RegularExpressions.Regex.Replace(dtext, "\\s+", " ").Trim();
                        System.Text.RegularExpressions.MatchCollection dtmc = System.Text.RegularExpressions.Regex.Matches(dtext, "\\b(\\d{1,2}:\\d{2})\\b");
                        for (int ti2 = 0; ti2 < dtmc.Count; ti2++) { dtimes.Add(dtmc[ti2].Groups[1].Value); }
                    }
                    if (dtimes.Count < 1) { continue; }
                    string darr = dtimes[0];
                    string ddep = dtimes.Count > 1 ? dtimes[1] : darr;
                    if (dname.Length == 0)
                    {
                        System.Text.RegularExpressions.MatchCollection danchors = System.Text.RegularExpressions.Regex.Matches(
                            divRows[r], "<a\\b[^>]*>(.*?)</a>",
                            System.Text.RegularExpressions.RegexOptions.IgnoreCase | System.Text.RegularExpressions.RegexOptions.Singleline);
                        for (int ai = 0; ai < danchors.Count; ai++)
                        {
                            string at = System.Text.RegularExpressions.Regex.Replace(danchors[ai].Groups[1].Value, "<[^>]+>", " ");
                            at = System.Net.WebUtility.HtmlDecode(at);
                            at = System.Text.RegularExpressions.Regex.Replace(at, "\\s+", " ").Trim();
                            if (at.Length >= 3 && System.Text.RegularExpressions.Regex.IsMatch(at, "[A-Za-z]")
                                && !System.Text.RegularExpressions.Regex.IsMatch(at, "^\\d{1,2}:\\d{2}$"))
                            { dname = at; break; }
                        }
                    }
                    if (dname.Length > 60) { dname = dname.Substring(0, 60).Trim(); }
                    outp.Add(new string[] { dno.Groups[1].Value, dname, darr, ddep });
                }
                if (outp.Count > 0) { return outp; }   // div layout parsed -> done

                // v1.0.160.38 PATH B (fallback, VERBATIM 160.36 logic): the div layout parsed nothing,
                // so the page may still be the legacy <table>/<tr> format. Bound marker -> next </table>
                // and split on <tr>. No closing </table> => malformed => no rows.
                int te = region.IndexOf("</table>", StringComparison.OrdinalIgnoreCase);
                if (te < 0) { return outp; }
                string tregion = region.Substring(0, te);
                string[] rows = System.Text.RegularExpressions.Regex.Split(tregion, "<tr", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                for (int r = 0; r < rows.Length; r++)
                {
                    string text = System.Text.RegularExpressions.Regex.Replace(rows[r], "<[^>]+>", " ");
                    text = System.Net.WebUtility.HtmlDecode(text);
                    text = System.Text.RegularExpressions.Regex.Replace(text, "\\s+", " ").Trim();
                    System.Text.RegularExpressions.Match no = System.Text.RegularExpressions.Regex.Match(text, "\\b(\\d{4,5})\\b");
                    if (!no.Success) { continue; }
                    System.Text.RegularExpressions.MatchCollection tmc = System.Text.RegularExpressions.Regex.Matches(text, "\\b(\\d{1,2}:\\d{2})\\b");
                    if (tmc.Count < 1) { continue; }
                    string arr = tmc[0].Groups[1].Value;
                    string dep = tmc.Count > 1 ? tmc[1].Groups[1].Value : arr;
                    string name = "";
                    System.Text.RegularExpressions.MatchCollection anchors = System.Text.RegularExpressions.Regex.Matches(
                        rows[r], "<a\\b[^>]*>(.*?)</a>",
                        System.Text.RegularExpressions.RegexOptions.IgnoreCase | System.Text.RegularExpressions.RegexOptions.Singleline);
                    for (int ai = 0; ai < anchors.Count; ai++)
                    {
                        string at = System.Text.RegularExpressions.Regex.Replace(anchors[ai].Groups[1].Value, "<[^>]+>", " ");
                        at = System.Net.WebUtility.HtmlDecode(at);
                        at = System.Text.RegularExpressions.Regex.Replace(at, "\\s+", " ").Trim();
                        if (at.Length >= 3 && System.Text.RegularExpressions.Regex.IsMatch(at, "[A-Za-z]")
                            && !System.Text.RegularExpressions.Regex.IsMatch(at, "^\\d{1,2}:\\d{2}$"))
                        { name = at; break; }
                    }
                    if (name.Length > 60) { name = name.Substring(0, 60).Trim(); }
                    outp.Add(new string[] { no.Groups[1].Value, name, arr, dep });
                }

                // v1.0.160.41 GUARD B (row-count sanity): belt-and-braces behind Guard A. A single
                // station lists tens of trains; the generic all-services page lists ~1454. Over the
                // ceiling we cannot trust the page identity, so return NOTHING rather than assert a
                // false "train at_station" on every alert.
                if (outp.Count > _trainCtxMaxTrains) { outp.Clear(); }
            }
            catch { }
            return outp;
        }

        private static bool TryHHMM(string s, out int minutes)
        {
            minutes = -1;
            if (string.IsNullOrEmpty(s)) { return false; }
            string[] parts = s.Split(':');
            int h, m;
            if (parts.Length == 2 && int.TryParse(parts[0], out h) && int.TryParse(parts[1], out m)
                && h >= 0 && h < 24 && m >= 0 && m < 60) { minutes = h * 60 + m; return true; }
            return false;
        }

        // v1.0.160.33 (hardened 160.35): assemble the train_context block -- trains scheduled through the
        // station within +/- windowMin of the arrival..departure interval. Returns NULL when nothing parsed
        // (so a blocked/changed/invalid page is omitted, never a false "no train"). Running day is NOT
        // verified. SCHEDULED only; the note always states it is not confirmed passage.
        private static JObject BuildTrainContext(string html, string stationCode, DateTime alertIst)
        {
            List<string[]> trains = ParseStationTrains(html, stationCode);
            // P1: if NOTHING parsed we cannot tell an empty/blocked/changed page from a station with
            // genuinely no trains -> return null so NO train_context is attached. A page that DID parse
            // trains but none in the window still yields a real scheduled=false below.
            if (trains.Count == 0) { return null; }
            JObject tc = new JObject();
            tc["station"] = stationCode;
            tc["alert_time"] = alertIst.ToString("HH:mm");
            tc["window_min"] = _trainCtxWindowMin;
            tc["running_day_checked"] = false;   // P1: booked timetable; the running day is NOT verified
            int alertMin = alertIst.Hour * 60 + alertIst.Minute;
            JArray matches = new JArray();
            string[] nearest = null; int nearestAbs = int.MaxValue; int nearestDelta = 0; string nearestPhase = null;
            for (int i = 0; i < trains.Count; i++)
            {
                int aMin, dMin;
                if (!TryHHMM(trains[i][2], out aMin)) { continue; }
                if (trains[i].Length < 4 || !TryHHMM(trains[i][3], out dMin)) { dMin = aMin; }
                int delta = SignedDeltaToInterval(alertMin, aMin, dMin);   // 0 = standing at the station
                if (Math.Abs(delta) <= _trainCtxWindowMin)
                {
                    string ph = TrainPhase(alertMin, aMin, dMin);   // v1.0.160.39: arriving | at_station | passed
                    JObject m = new JObject();
                    m["train_no"] = trains[i][0];
                    m["train_name"] = trains[i][1];
                    m["sched_time"] = trains[i][2];
                    m["dep_time"] = trains[i][3];
                    m["delta_min"] = delta;
                    m["phase"] = ph;   // v1.0.160.39
                    matches.Add(m);
                    if (Math.Abs(delta) < nearestAbs) { nearestAbs = Math.Abs(delta); nearestDelta = delta; nearest = trains[i]; nearestPhase = ph; }
                }
            }
            bool scheduled = matches.Count > 0;
            tc["scheduled"] = scheduled;
            if (nearest != null)
            {
                JObject n = new JObject();
                n["train_no"] = nearest[0]; n["train_name"] = nearest[1]; n["sched_time"] = nearest[2]; n["dep_time"] = nearest[3]; n["delta_min"] = nearestDelta; n["phase"] = nearestPhase;   // v1.0.160.39
                tc["nearest"] = n;
            }
            else { tc["nearest"] = null; }
            tc["matches"] = matches;

            // v1.0.160.47: last/next train REGARDLESS of the window. Full 24h wrap, so at 23:50 the
            // "next" train is the first of the following morning rather than nothing.
            string[] prevT = null; int prevGap = int.MaxValue;
            string[] nextT = null; int nextGap = int.MaxValue;
            for (int i = 0; i < trains.Count; i++)
            {
                int aMin2, dMin2;
                if (!TryHHMM(trains[i][2], out aMin2)) { continue; }
                if (trains[i].Length < 4 || !TryHHMM(trains[i][3], out dMin2)) { dMin2 = aMin2; }
                int since = ModFwd(alertMin - dMin2);   // minutes since it departed
                int until = ModFwd(aMin2 - alertMin);   // minutes until it arrives
                if (since > 0 && since < prevGap) { prevGap = since; prevT = trains[i]; }
                if (until > 0 && until < nextGap) { nextGap = until; nextT = trains[i]; }
            }
            if (prevT != null)
            {
                JObject p = new JObject();
                p["train_no"] = prevT[0]; p["train_name"] = prevT[1];
                p["sched_time"] = prevT[2]; p["dep_time"] = prevT[3];
                p["mins_since"] = prevGap; p["phase"] = "passed";
                tc["previous"] = p;
            }
            else { tc["previous"] = null; }
            if (nextT != null)
            {
                JObject nx = new JObject();
                nx["train_no"] = nextT[0]; nx["train_name"] = nextT[1];
                nx["sched_time"] = nextT[2]; nx["dep_time"] = nextT[3];
                nx["mins_until"] = nextGap; nx["phase"] = "arriving";
                tc["next"] = nx;
            }
            else { tc["next"] = null; }
            tc["trains_today"] = trains.Count;
            tc["note"] = scheduled
                ? "scheduled (booked timetable; running day NOT verified) through the station, NOT confirmed passage -- verify the running day and live status with section control; not authority to occupy the track"
                : "no train in the booked timetable within the window (running day NOT verified; scheduled data only) -- verify live with section control";
            // v1.0.160.47: previous/next are ORIENTATION ONLY. Only a WINDOW match (scheduled=true)
            // indicates a train could plausibly have been on the track at the alert minute; a train
            // hours away must NEVER be offered as the cause of a breach.
            tc["prev_next_note"] = "previous/next are the nearest scheduled trains OUTSIDE the match window -- traffic orientation only, NOT evidence that a train influenced this alert. Only scheduled=true (a train within the window) supports a shunt/occupation explanation.";
            return tc;
        }

        // v1.0.160.35: signed minutes from the alert to a train's arrival..departure interval, nearest-
        // midnight wrap. 0 = the alert falls inside the interval (train standing at the station); negative
        // = the train was at the station before the alert; positive = after. Covers a train already
        // standing when the alert fired, which arrival-only matching would miss.
        private static int SignedDeltaToInterval(int alertMin, int aMin, int dMin)
        {
            int da = WrapDelta(aMin - alertMin);   // arrival vs alert (negative if arrival before alert)
            int dd = WrapDelta(dMin - alertMin);   // departure vs alert
            if (da <= 0 && dd >= 0) { return 0; }  // arrival <= alert <= departure -> standing
            return (Math.Abs(da) <= Math.Abs(dd)) ? da : dd;   // otherwise the nearer edge
        }

        // v1.0.160.47: forward distance in minutes over a full 24h clock (0..1439). WrapDelta clamps
        // to +/-720, which cannot express a gap over 12h -- at a quiet station the next train can be
        // further away than that (SAKHUN 20:01 -> 07:03 = 662 min, and sparser lines exceed 720).
        private static int ModFwd(int d)
        {
            int m = d % 1440;
            if (m < 0) { m += 1440; }
            return m;
        }

        private static int WrapDelta(int d)
        {
            if (d > 720) { d -= 1440; } else if (d < -720) { d += 1440; }
            return d;
        }

        // v1.0.160.39: label the alert position relative to a train's arrival..departure interval,
        // so the verdict reads "arriving"/"at_station"/"passed" without interpreting delta_min.
        //   arriving   = arrival is still ahead of the alert (train approaching)
        //   at_station = alert falls inside [arrival, departure] (dwelling, or passing through now)
        //   passed     = departure is behind the alert (train has gone through)
        private static string TrainPhase(int alertMin, int aMin, int dMin)
        {
            int da = WrapDelta(aMin - alertMin);
            int dd = WrapDelta(dMin - alertMin);
            if (da <= 0 && dd >= 0) { return "at_station"; }
            if (da > 0) { return "arriving"; }
            return "passed";
        }

        // Reduce the hourly Open-Meteo payload to the hours around incidence and a compact,
        // model-readable summary. Returns null if nothing usable.
        private static string SummariseWeather(string raw, DateTime incidenceIst)
        {
            try
            {
                JObject o = JObject.Parse(raw);
                JObject hourly = o["hourly"] as JObject;
                if (hourly == null) { return null; }
                JArray times = hourly["time"] as JArray;
                JArray precip = hourly["precipitation"] as JArray;
                JArray codes = hourly["weather_code"] as JArray;
                JArray temp = hourly["temperature_2m"] as JArray;
                if (times == null) { return null; }

                // window: incidence hour +/- 3h
                DateTime lo = incidenceIst.AddHours(-3), hi = incidenceIst.AddHours(3);
                double precipTotal = 0, peak = 0, tMin = double.MaxValue, tMax = double.MinValue;
                bool thunder = false; bool anyHour = false;
                // v1.0.160.49: keep the WMO code AT the incidence hour (what the sky actually was)
                // and the WORST code in the window (so a shower an hour either side is not lost).
                int wcAt = -1, wcWorst = -1; double bestGapH = double.MaxValue;
                for (int i = 0; i < times.Count; i++)
                {
                    DateTime ht;
                    if (!DateTime.TryParse(times[i] != null ? times[i].ToString() : "", System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.None, out ht)) { continue; }
                    if (ht < lo || ht > hi) { continue; }
                    anyHour = true;
                    if (precip != null && i < precip.Count) { double p; if (double.TryParse(precip[i].ToString(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out p)) { precipTotal += p; if (p > peak) { peak = p; } } }
                    if (codes != null && i < codes.Count)
                    {
                        int wc;
                        if (int.TryParse(codes[i].ToString(), out wc))
                        {
                            if (wc == 95 || wc == 96 || wc == 99) { thunder = true; }
                            if (wc > wcWorst) { wcWorst = wc; }
                            double gapH = Math.Abs((ht - incidenceIst).TotalHours);
                            if (gapH < bestGapH) { bestGapH = gapH; wcAt = wc; }
                        }
                    }
                    if (temp != null && i < temp.Count) { double t; if (double.TryParse(temp[i].ToString(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out t)) { if (t < tMin) { tMin = t; } if (t > tMax) { tMax = t; } } }
                }
                if (!anyHour) { return null; }

                JObject w = new JObject();
                w["window"] = "incidence +/- 3h (site-local)";
                w["rain"] = precipTotal > 0.1;
                w["precip_mm_total"] = Math.Round(precipTotal, 2);
                w["peak_precip_mm_h"] = Math.Round(peak, 2);
                w["thunderstorm"] = thunder;
                if (wcAt >= 0) { w["weather_code"] = wcAt; }          // v1.0.160.49: sky at the incidence hour
                if (wcWorst >= 0) { w["weather_code_worst"] = wcWorst; }
                if (tMin <= tMax) { w["temp_c_range"] = new JArray(Math.Round(tMin, 1), Math.Round(tMax, 1)); }
                return w.ToString(Formatting.None);
            }
            catch { return null; }
        }

        // Supplementary analyses. When one is unavailable the verdict still stands
        // on the sample series, so its absence must not surface as a caveat -- doing
        // so made sound verdicts look under-evidenced.
        private static readonly string[] _optionalTools =
            { "predict_track_health", "predict_pm_operation", "predict_pm_cluster" };
        private static bool IsOptionalEnrichment(string toolName)
        {
            for (int i = 0; i < _optionalTools.Length; i++)
            {
                if (string.Equals(toolName, _optionalTools[i], StringComparison.OrdinalIgnoreCase)) { return true; }
            }
            return false;
        }

        // A call with asset_id=0 or site_id=0 identifies NOTHING, but the backend
        // answers it anyway with a zero-filled shell -- observed: get_hist_realtime
        // with asset_id=0 returned 3,217 chars of {"Id":0,"Name":null,
        // "CreatedDate":"0001-01-01T00:00:00"...}. That shell is large and
        // well-formed enough to pass the usability check, and get_hist_realtime is
        // history-class, so it would have SATISFIED THE GROUNDING GATE and allowed a
        // verdict of "ok" resting on no telemetry at all. Refuse the call instead.
        private static readonly string[] _idArgKeys =
            { "site_id", "siteid", "asset_id", "assetid", "tag_id", "tagid",
              "attribute_id", "attributeid", "assetattributeid" };

        private static string ZeroIdentifier(JToken args)
        {
            JObject o = args as JObject;
            if (o == null) { return null; }
            foreach (var prop in o.Properties())
            {
                string ln = prop.Name.ToLowerInvariant();
                bool isId = false;
                for (int i = 0; i < _idArgKeys.Length; i++) { if (ln == _idArgKeys[i]) { isId = true; break; } }
                if (!isId) { continue; }
                JToken v = prop.Value;
                if (v == null || v.Type == JTokenType.Null) { return prop.Name; }
                if (v.Type == JTokenType.Array) { continue; } // TrackIds etc. handled by the tool
                decimal dv;
                if (decimal.TryParse(v.ToString(), System.Globalization.NumberStyles.Any,
                        System.Globalization.CultureInfo.InvariantCulture, out dv) && dv == 0m)
                {
                    return prop.Name;
                }
                if (v.Type == JTokenType.String && v.ToString().Trim().Length == 0) { return prop.Name; }
            }
            return null;
        }

        // The API caps rows and returns the OLDEST ones, so a wide window silently
        // stops short of the alert. Say so IN the tool result: the model cannot see
        // that the last sample predates the incidence unless it is told.
        // Alert timestamps are IST wall-clock with no DateTimeKind, so
        // ToUniversalTime() silently used the SERVER's timezone -- on a UTC host the
        // comparison was 5h30m out, which is exactly the size of error that would let
        // a short history look complete. Convert with an explicit offset instead.
        private static readonly TimeSpan _istOffset = TimeSpan.FromMinutes(330);
        private static long ToEpochIst(DateTime wallClockIst)
        {
            DateTime utc = DateTime.SpecifyKind(wallClockIst, DateTimeKind.Unspecified) - _istOffset;
            return (long)(utc - new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc)).TotalSeconds;
        }

        // -- v1.0.75.0 -- REMOVED LastHistoryEpoch: read only {"ts":[...]} property
        // arrays on the OUTER document, so (a) the columnar cols/rows format this
        // controller itself forces returned 0, and (b) the same JSON wrapped in an
        // MCP content[].text envelope was invisible; the trailing `to` branch was a
        // no-op. Replaced by ParseCoverageDocuments + ComputeHistoryCoverage below.
        // private static long LastHistoryEpoch(string result)
        // {
        //     try
        //     {
        //         List<JToken> docs = ParseJsonDocuments(result);
        //         long best = 0;
        //         for (int d = 0; d < docs.Count; d++)
        //         {
        //             foreach (JToken tsArr in docs[d].SelectTokens("$..ts"))
        //             {
        //                 JArray a = tsArr as JArray;
        //                 if (a == null || a.Count == 0) { continue; }
        //                 long v;
        //                 if (long.TryParse(a[a.Count - 1].ToString(), out v) && v > best) { best = v; }
        //             }
        //             JToken to = docs[d].SelectToken("$..to");
        //             long t2;
        //             if (to != null && long.TryParse(to.ToString(), out t2) && t2 > best && best == 0) { best = 0; }
        //         }
        //         return best;
        //     }
        //     catch { return 0; }
        // }

        // Machine-readable coverage categories: the recovery advice DIFFERS by
        // reason (narrower window cannot add samples or lengthen a span), so the
        // caller must know WHICH check failed, not merely that one did.
        private enum CoverageStateKind
        {
            Unverifiable = 0,
            ShortAtEnd = 1,
            InsufficientSamples = 2,
            InsufficientSpan = 3,
            Covered = 4
        }

        // Everything the coverage/adequacy gate needs, computed from UNIQUE
        // pre-alert samples only: duplicated documents, repeated encodings of the
        // same series, and post-alert rows must not inflate adequacy.
        private sealed class HistoryCoverage
        {
            public long LastBefore;                 // last unique sample at/before incidence (+15 s grace)
            public long FirstAfter;                 // first unique sample after the bound, 0 if none
            public int PreAlertSampleCount;         // unique samples at/before the bound
            public long EarliestBefore;             // earliest unique pre-alert sample
            public long MedianPreAlertIntervalSec;  // median spacing of pre-alert samples, 0 when < 3
        }

        // Coverage must read the SAME payloads LooksUsableToolResult accepts: the
        // MCP client may deliver {"result":{"content":[{"text":"<json>"}]}} or the
        // bare projected [{"text":"<json>"}] array. Text members of ONE content
        // array are concatenated before parsing (parity with LooksUsableInner), so
        // a JSON document split across blocks is reconstructed. Depth-bounded.
        private static List<JToken> ParseCoverageDocuments(string result, int depth)
        {
            List<JToken> docs = ParseJsonDocuments(result);
            if (depth <= 0)
            {
                return docs;
            }
            List<JToken> all = new List<JToken>(docs);
            for (int d = 0; d < docs.Count; d++)
            {
                foreach (JToken contentTok in docs[d].SelectTokens("$..content"))
                {
                    AddConcatenatedContent(contentTok as JArray, all, depth);
                }
                // bare projection: the content array itself IS the document
                AddConcatenatedContent(docs[d] as JArray, all, depth);
            }
            return all;
        }

        private static void AddConcatenatedContent(JArray content, List<JToken> all, int depth)
        {
            if (content == null || content.Count == 0)
            {
                return;
            }
            StringBuilder cb = new StringBuilder();
            for (int k = 0; k < content.Count; k++)
            {
                JObject o = content[k] as JObject;
                if (o == null)
                {
                    continue;
                }
                JToken tx = PropCI(o, "text");
                if (tx != null && tx.Type == JTokenType.String)
                {
                    cb.Append(tx.ToString());
                }
            }
            string inner = cb.ToString().Trim();
            if (inner.Length < 3 || !(inner.StartsWith("{") || inner.StartsWith("[")))
            {
                return;
            }
            List<JToken> innerDocs = ParseCoverageDocuments(inner, depth - 1);
            for (int k = 0; k < innerDocs.Count; k++)
            {
                all.Add(innerDocs[k]);
            }
        }

        // One pass over every readable shape: {"ts":[...]} parallel arrays and the
        // columnar {"cols":[...],"rows":[[ts,v],...]} format this controller forces
        // via outputMode=columnar. All stamps land in one SET; statistics come from
        // the unique pre-alert subset.
        private HistoryCoverage ComputeHistoryCoverage(string result)
        {
            try
            {
                long bound = _incidenceEpoch + 15;
                HashSet<long> uniq = new HashSet<long>();
                List<JToken> docs = ParseCoverageDocuments(result, 2);
                for (int d = 0; d < docs.Count; d++)
                {
                    foreach (JToken tsArr in docs[d].SelectTokens("$..ts"))
                    {
                        JArray a = tsArr as JArray;
                        if (a == null)
                        {
                            continue;
                        }
                        for (int k = 0; k < a.Count; k++)
                        {
                            long v = NormalizeEpoch(a[k]);
                            if (v > 0)
                            {
                                uniq.Add(v);
                            }
                        }
                    }
                    foreach (JToken rowsTok in docs[d].SelectTokens("$..rows"))
                    {
                        JArray rows = rowsTok as JArray;
                        if (rows == null || rows.Count == 0)
                        {
                            continue;
                        }
                        int tsIdx = 0;
                        JProperty prop = rowsTok.Parent as JProperty;
                        JObject holder = prop != null ? prop.Parent as JObject : null;
                        JArray cols = holder != null ? holder["cols"] as JArray : null;
                        if (cols != null)
                        {
                            for (int c = 0; c < cols.Count; c++)
                            {
                                string cn = cols[c] == null ? "" : cols[c].ToString().Trim().ToLowerInvariant();
                                if (cn == "ts" || cn == "time" || cn == "timestamp")
                                {
                                    tsIdx = c;
                                    break;
                                }
                            }
                        }
                        for (int r = 0; r < rows.Count; r++)
                        {
                            JArray row = rows[r] as JArray;
                            if (row == null || tsIdx >= row.Count)
                            {
                                continue;
                            }
                            long v = NormalizeEpoch(row[tsIdx]);
                            if (v > 0)
                            {
                                uniq.Add(v);
                            }
                        }
                    }
                }
                if (uniq.Count == 0)
                {
                    return null;
                }
                List<long> sorted = new List<long>(uniq);
                sorted.Sort();
                List<long> before = new List<long>();
                long firstAfter = 0;
                for (int i = 0; i < sorted.Count; i++)
                {
                    if (sorted[i] <= bound)
                    {
                        before.Add(sorted[i]);
                    }
                    else
                    {
                        firstAfter = sorted[i];
                        break;
                    }
                }
                if (before.Count == 0)
                {
                    return null;
                }
                HistoryCoverage cov = new HistoryCoverage();
                cov.PreAlertSampleCount = before.Count;
                cov.EarliestBefore = before[0];
                cov.LastBefore = before[before.Count - 1];
                cov.FirstAfter = firstAfter;
                if (before.Count >= 3)
                {
                    List<long> gaps = new List<long>();
                    for (int i = 1; i < before.Count; i++)
                    {
                        long g = before[i] - before[i - 1];
                        if (g > 0)
                        {
                            gaps.Add(g);
                        }
                    }
                    if (gaps.Count > 0)
                    {
                        gaps.Sort();
                        cov.MedianPreAlertIntervalSec = gaps[gaps.Count / 2];
                    }
                }
                return cov;
            }
            catch
            {
                return null;
            }
        }

        // Epoch values may arrive in seconds or milliseconds; coverage math is in
        // seconds. Non-numeric and implausible (< 2001) values return 0 and are
        // ignored, so counters in unrelated "rows" cannot poison the result.
        private static long NormalizeEpoch(JToken t)
        {
            if (t == null)
            {
                return 0;
            }
            long v;
            if (!long.TryParse(t.ToString(), out v))
            {
                return 0;
            }
            if (v > 100000000000L)
            {
                v = v / 1000;
            }
            if (v < 1000000000L)
            {
                return 0;
            }
            return v;
        }

        // -- v1.0.75.0 -- covered now requires ADEQUACY of the UNIQUE PRE-ALERT
        // set: recency alone let a single row 10 s before the alert stand in for
        // a trend, and the flat 300 s gap rejected healthy periodic series
        // sampled every ~13 min (line 1966).
        private CoverageStateKind HistoryCoverageState(string result, out long shortBySec, out string why)
        {
            shortBySec = 0;
            why = null;
            if (_incidenceEpoch <= 0 || string.IsNullOrEmpty(result))
            {
                return CoverageStateKind.Unverifiable;
            }
            HistoryCoverage cov = ComputeHistoryCoverage(result);
            if (cov == null || cov.LastBefore <= 0)
            {
                why = "no readable sample at or before the incidence";
                return CoverageStateKind.Unverifiable;
            }
            shortBySec = _incidenceEpoch - cov.LastBefore;
            if (shortBySec < 0)
            {
                shortBySec = 0;
            }
            long adaptive = cov.MedianPreAlertIntervalSec > 0 ? cov.MedianPreAlertIntervalSec * 2 : 0;
            if (adaptive > _historyAdaptiveCapSec)
            {
                adaptive = _historyAdaptiveCapSec;
            }
            long effectiveTol = _historyCoverToleranceSec;
            if (adaptive > effectiveTol)
            {
                effectiveTol = adaptive;
            }
            long spanSec = _incidenceEpoch - cov.EarliestBefore;
            AiLog("INFO", "COVERAGE", "last-before gap=" + shortBySec + "s preSamples=" + cov.PreAlertSampleCount
                + " span=" + spanSec + "s median=" + cov.MedianPreAlertIntervalSec + "s effTol=" + effectiveTol
                + "s after=" + (cov.FirstAfter > 0 ? "yes" : "no"));
            // v1.0.160.5: NO temporal-tolerance gate. Owner rule: whatever sample exists at or before
            // the incidence IS the incidence value, however long before it was recorded (change-of-value
            // feeds legitimately HOLD a value for many minutes/hours between changes -- a reading
            // unchanged since 10:00 is still that value at a 13:13 alert, not a coverage gap). The old
            // "shortBySec > effectiveTol -> ShortAtEnd" gate is removed so a value-present alert is
            // never downgraded to coverage-gap merely because the last change predates the incidence by
            // more than N seconds. effectiveTol is still computed above for the log line only.
            // (Genuine no-data -- no row at all at/before incidence -- is still caught by the
            // cov.LastBefore <= 0 check earlier, which returns Unverifiable.)
            if (cov.PreAlertSampleCount < _historyMinSamples)
            {
                why = "has only " + cov.PreAlertSampleCount + " pre-alert sample(s) - cannot show sustained vs transient";
                return CoverageStateKind.InsufficientSamples;
            }
            if (spanSec < _historyMinSpanSec)
            {
                why = "spans only " + (spanSec / 60) + " min before the alert";
                return CoverageStateKind.InsufficientSpan;
            }
            return CoverageStateKind.Covered;
        }

        private static readonly int _historyCoverToleranceSec =
            ClampCfg(ReadInt("AnalyzeHistoryCoverToleranceSec", 300), 30, 3600);
        // v1.0.75.0 adequacy policy (Review rev D decisions D1-D3, canary defaults)
        private static readonly int _historyAdaptiveCapSec =
            ClampCfg(ReadInt("AnalyzeHistoryAdaptiveCapSec", 1800), 300, 7200);
        private static readonly int _historyMinSamples =
            ClampCfg(ReadInt("AnalyzeHistoryMinSamples", 6), 1, 100);
        private static readonly int _historyMinSpanSec =
            ClampCfg(ReadInt("AnalyzeHistoryMinSpanSec", 14400), 600, 259200);

        // The correct recovery DIFFERS by failure: only a series cut off by the
        // row cap is fixed by narrowing. Advice text is generated in ONE place so
        // status, prefetch note and agentic note can never disagree.
        private static string CoverageRecoveryAdvice(CoverageStateKind kind)
        {
            if (kind == CoverageStateKind.ShortAtEnd)
            {
                return "call history_get again with sort=desc (newest-first) to return the MOST-RECENT "
                     + "rows in the range -- the incidence sits near the window end, so desc reaches it "
                     + "without narrowing; only narrow further if desc still stops short";
            }
            if (kind == CoverageStateKind.InsufficientSamples)
            {
                return "call history_get again with a WIDER window (or a different tag of the same "
                     + "asset for CORROBORATION - it cannot itself satisfy alerting-tag coverage) - "
                     + "narrowing cannot add samples";
            }
            if (kind == CoverageStateKind.InsufficientSpan)
            {
                return "call history_get again with an EARLIER start so the pre-alert span is "
                     + "longer - narrowing cannot lengthen it";
            }
            return "do not claim incidence coverage; if its samples do not reach the incidence "
                 + "time, one retry with a narrower window MAY help, otherwise treat coverage as unverified";
        }

        // v1.0.75.0: coverage is tracked PER TAG and enforced for the ALERTING
        // tag only -- a different tag's good series provides corroboration, never
        // coverage. gotUsableHistoryGet is deliberately NOT _jsonGotHistory: that
        // flag is raised by the whole history family including analyse_alert and
        // get_hist_realtime, which carry no series to verify.
        private enum HistoryCoverageLevel
        {
            Unknown = 0,
            Unverified = 1,
            Inadequate = 2,
            VerifiedAdequate = 3
        }

        private void SetTagCoverage(string tagId, HistoryCoverageLevel level)
        {
            if (coverageByTag == null)
            {
                coverageByTag = new Dictionary<string, HistoryCoverageLevel>(StringComparer.OrdinalIgnoreCase);
            }
            string key = tagId ?? "";
            HistoryCoverageLevel cur;
            if (!coverageByTag.TryGetValue(key, out cur) || level > cur)
            {
                coverageByTag[key] = level;   // monotonic upward PER TAG
            }
        }

        private string AlertingTagId()
        {
            return requiredAlertingTagId ?? presumedAlertingTagId;
        }

        private HistoryCoverageLevel AlertingCoverageLevel()
        {
            string tag = AlertingTagId();
            HistoryCoverageLevel lvl;
            if (tag == null || coverageByTag == null || !coverageByTag.TryGetValue(tag, out lvl))
            {
                return HistoryCoverageLevel.Unknown;
            }
            return lvl;
        }

        private static string HistoryTagFromArgs(JObject args)
        {
            if (args == null)
            {
                return null;
            }
            JToken t = PropCI(args, "TagId");
            if (t == null || t.Type == JTokenType.Null)
            {
                return null;
            }
            string s = t.ToString().Trim();
            return s.Length == 0 ? null : s;
        }

        // -- v1.0.75.0 -- REMOVED: own regex scan with a one-hour allowance, so the
        // agentic path accepted series the prefetch gate rejected (300 s vs 3600 s),
        // and an unverifiable series produced NO warning at all.
