        // One rule for BOTH paths. Takes the fetched TagId so coverage is tracked
        // PER TAG (a different tag's good series must never satisfy the ALERTING
        // tag's coverage requirement). The presumed alerting tag is resolved
        // MECHANICALLY (see TryResolveAlertingTagFromSearch below), never from
        // trusting whichever tag the model happened to fetch first.
        private string HistoryCoverageNote(string result, string tagId)
        {
            // -- v1.0.76.0 -- moved before the incidence check: an unparseable
            // incidence with a usable payload must still register that a
            // history_get ran, or scoped enforcement silently skips the alert.
            gotUsableHistoryGet = true;
            if (_incidenceEpoch <= 0 || string.IsNullOrEmpty(result))
            {
                _lastCoverageKind = CoverageStateKind.Unverifiable;
                SetTagCoverage(tagId, HistoryCoverageLevel.Unverified);
                return "NOTE: incidence timestamp could not be parsed; history coverage "
                     + "cannot be verified.";
            }
            // -- v1.0.76.0 -- REMOVED: promoting the FIRST model-issued history_get to
            // "the alerting tag" trusted an unverified guess (the model may fetch TPR,
            // a coupled voltage, or any corroborating attribute first). Resolution is
            // now mechanical only, via TryResolveAlertingTagFromSearch (below) on a
            // successful search_tags result. If it still cannot resolve, AlertingTagId()
            // stays null and no tag is "presumed" -- a good series for a different tag
            // remains corroboration, never coverage.
            // if (requiredAlertingTagId == null && presumedAlertingTagId == null && tagId != null)
            // {
            //     presumedAlertingTagId = tagId;
            //     coverageTagPresumed = true;
            // }
            long shortBy;
            string why;
            CoverageStateKind state = HistoryCoverageState(result, out shortBy, out why);
            _lastCoverageKind = state;
            if (state == CoverageStateKind.Covered)
            {
                SetTagCoverage(tagId, HistoryCoverageLevel.VerifiedAdequate);
                return null;
            }
            if (state == CoverageStateKind.Unverifiable)
            {
                SetTagCoverage(tagId, HistoryCoverageLevel.Unverified);
                return "NOTE: incidence coverage of this series could NOT be verified - it " + why
                    + ". " + CoverageRecoveryAdvice(state) + ".";
            }
            SetTagCoverage(tagId, HistoryCoverageLevel.Inadequate);
            return "NOTE: this series is NOT sufficient evidence - it " + why + ". "
                + CoverageRecoveryAdvice(state) + ".";
        }

        // v1.0.76.0: the ONLY mechanical route to presumedAlertingTagId. Runs the
        // SAME matcher prefetch uses (PickAlertingTagId) against a model-issued
        // search_tags result, so a substitute tag is never trusted on faith.
        private void TryResolveAlertingTagFromSearch(string searchResult)
        {
            if (requiredAlertingTagId != null || presumedAlertingTagId != null)
            {
                return;   // identity already known -- never overwritten
            }
            if (_prefetchCtx == null || string.IsNullOrEmpty(searchResult))
            {
                return;
            }
            string assetId = GetCtx(_prefetchCtx, "assetId");
            string resolved = PickAlertingTagId(searchResult, _prefetchCtx, assetId);
            if (resolved != null)
            {
                presumedAlertingTagId = resolved;
                coverageTagPresumed = true;
            }
        }

        private static bool IsHistoryFamily(string toolName)
        {
            for (int i = 0; i < _jsonHistoryFamily.Length; i++)
            {
                if (string.Equals(toolName, _jsonHistoryFamily[i], StringComparison.OrdinalIgnoreCase)) { return true; }
            }
            return false;
        }

        // Coverage stamps are only readable for the true series tool. analyse_alert
        // and get_hist_realtime stay in _jsonHistoryFamily for grounding and caps,
        // but their report shapes carry no cols/rows series to verify.
        private static bool IsCoverageCheckedTool(string toolName)
        {
            return string.Equals(toolName, "history_get", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsEvidenceTool(string toolName)
        {
            for (int i = 0; i < _evidenceTools.Length; i++)
            {
                if (string.Equals(toolName, _evidenceTools[i], StringComparison.OrdinalIgnoreCase)) { return true; }
            }
            return false;
        }

        // bounded byte read: returns null when the stream exceeds maxBytes
        private static async Task<string> ReadBodyBoundedAsync(System.IO.Stream input, int maxBytes, System.Threading.CancellationToken ct)
        {
            byte[] buf = new byte[8192];
            using (System.IO.MemoryStream ms = new System.IO.MemoryStream())
            {
                int read;
                while ((read = await input.ReadAsync(buf, 0, buf.Length, ct).ConfigureAwait(false)) > 0)
                {
                    ms.Write(buf, 0, read);
                    if (ms.Length > maxBytes) { return null; }
                }
                return Encoding.UTF8.GetString(ms.ToArray());
            }
        }

        // scalar keys must be scalars (bounded), cards must be objects
        private static readonly string[] _ctxScalarKeys =
            { "alertId", "causeCode", "assetName", "station", "time", "resetTime",
              "alertType", "description", "rawMessage", "requestId",
              "siteId", "assetId", "provider" };
        private static bool ValidateCtxShape(JObject ctx, out string reason)
        {
            reason = null;
            for (int i = 0; i < _ctxScalarKeys.Length; i++)
            {
                JToken t = ctx[_ctxScalarKeys[i]];
                if (t == null || t.Type == JTokenType.Null) { continue; }
                if (t.Type == JTokenType.Object || t.Type == JTokenType.Array)
                {
                    reason = "ctx." + _ctxScalarKeys[i] + " must be a scalar"; return false;
                }
                string v = t.ToString();
                if (v.Length > 2000)
                {
                    reason = "ctx." + _ctxScalarKeys[i] + " too long (max 2000)"; return false;
                }
            }
            string[] cardKeys = { "alertCard", "resetCard" };
            for (int i = 0; i < cardKeys.Length; i++)
            {
                JToken t = ctx[cardKeys[i]];
                if (t == null || t.Type == JTokenType.Null) { continue; }
                if (t.Type != JTokenType.Object)
                {
                    reason = "ctx." + cardKeys[i] + " must be an object"; return false;
                }
            }
            return true;
        }

        // ---- enforced read-only tool policy for verdict mode ----
        private Dictionary<string, int> _jsonToolUsed;
        private int _jsonToolTotal;
        private static readonly Dictionary<string, int> _jsonToolCaps =
            new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase)
            {
                { "search_sites", 2 }, { "search_assets", 2 }, { "search_tags", 2 },
                { "get_asset_tags", 2 }, { "get_timestamps", 1 },
                { "get_attribute_range", 2 }, { "get_frs_alerts", 2 },
                { "history_get", 2 },
                // trend_get REMOVED. Measured across every trace we have: 11 calls,
                // every one returning 45-50 bytes (a valid but degenerate single-bucket
                // summary). It never once produced usable evidence, yet the model
                // reached for it ~4 times per run -- and each attempt costs a turn,
                // which re-sends the entire accumulated conversation. Demoting it was
                // not enough; it had to go. If a slope figure is ever wanted, re-add
                // here and to _evidenceTools.
                // MCP2 (FRS server) -- the tools actually built for alert analysis.
                // They were absent from this allowlist, so verdict mode filtered
                // them out of the tool list and the model never saw them:
                // analyse_alert in particular runs the cause-code formula check
                // that this endpoint exists to perform.
                { "analyse_alert", 2 }, { "get_hist_realtime", 2 },
                { "fetch_alert_details_frs", 2 },
                // ML analyses. Capped at ONE call each -- they are the slowest tools
                // and a second call adds nothing. Evidence-class, but NOT
                // history-class: they return a derived assessment, and the verdict
                // must still rest on the sample series.
                { "predict_track_health", 1 }, { "predict_pm_operation", 1 },
                { "predict_pm_cluster", 1 },
                // v1.0.117.0: get_attribute_range_history - asset-scoped historical AVG trend +
                // site geo/topology. Cap 2. Prefetched (controller reads lat/long from it for the
                // weather enrichment), but also allowed if the model wants the trend directly.
                { "get_attribute_range_history", 2 },
                // v1.0.117.0: get_weather REMOVED as an MCP tool. Weather is now fetched
                // controller-side (Open-Meteo) during prefetch and injected as evidence (Option A) -
                // so no third-party API sits in the MCP server. See FetchWeatherAsync + the WEATHER
                // block in the prefetch flow. The model receives weather as evidence, not a tool.
                // Live-value lookups. Needed by the FOLLOW-UP chat ("what is it now?").
                // 1.0.27.0 applied this allowlist to the streaming path as well, which
                // silently removed the ability to answer that -- the follow-up would
                // have been denied the very tool the prompt tells it to use. Verdict
                // mode is separately instructed not to call these, and the caps bound
                // them either way.
                { "get_tag_current", 4 }, { "live_get", 2 }
            };
        // Tools returning VALUE TELEMETRY, which satisfy the grounding gate.
        // get_hist_realtime returns historian readings around the alert and
        // analyse_alert returns HIST data plus the evaluated formula, so both are
        // genuine value evidence -- not merely lookups.
        // trend_get is DEMOTED: observed returning 46 bytes (an empty summary) and
        // grounding a verdict on a slope figure is not acceptable -- the model must
        // see the samples to tell a sustained breach from a transient. It stays
        // callable as a supplementary figure, but no longer satisfies the gate.
        private static readonly string[] _jsonHistoryFamily =
            { "history_get", "get_hist_realtime", "analyse_alert" };
        private const int _jsonHistoryFamilyCap = 3; // one retry if the first window misses
        private const int _jsonToolTotalCap = 12;

        private bool JsonToolPermitted(string toolName, out string denyReason)
        {
            denyReason = null;
            string n = toolName ?? "";
            if (!_jsonToolCaps.ContainsKey(n))
            {
                denyReason = "Tool '" + n + "' is not permitted in verdict mode (read-only allowlist). Use only: " + string.Join(", ", _jsonToolCaps.Keys) + ".";
                return false;
            }
            if (_jsonToolTotal >= _jsonToolTotalCap)
            {
                denyReason = "Tool budget exhausted (" + _jsonToolTotalCap + " calls). Produce the verdict JSON now from the evidence already gathered.";
                return false;
            }
            int used;
            _jsonToolUsed.TryGetValue(n, out used);
            if (used >= _jsonToolCaps[n])
            {
                denyReason = "Call limit for '" + n + "' reached (" + _jsonToolCaps[n] + "). Produce the verdict from data already gathered.";
                return false;
            }
            bool isHist = false;
            for (int i = 0; i < _jsonHistoryFamily.Length; i++) { if (string.Equals(_jsonHistoryFamily[i], n, StringComparison.OrdinalIgnoreCase)) { isHist = true; break; } }
            if (isHist)
            {
                int fam = 0;
                for (int i = 0; i < _jsonHistoryFamily.Length; i++)
                {
                    int u; _jsonToolUsed.TryGetValue(_jsonHistoryFamily[i], out u); fam += u;
                }
                if (fam >= _jsonHistoryFamilyCap)
                {
                    denyReason = "History-call budget reached (" + _jsonHistoryFamilyCap + " total). Produce the verdict from data already gathered.";
                    return false;
                }
            }
            _jsonToolUsed[n] = used + 1;
            _jsonToolTotal++;
            return true;
        }

        // ---- strict verdict schema validation + operational-action filtering ----
        private static readonly string[] _verdictCategories =
            { "Field HW", "Config", "Calibration/Threshold", "Platform",
              "A10 transition", "Datalogger", "Genuine failure",
              "Coverage gap",     // v1.0.75.0: mechanical downgrade category (D6)
              // v1.0.160.87: separate "the alert was RIGHT and it passed" from "the alert was WRONG".
              "Transient - no action",   // breach real, recovered inside the sustain window
              "Derived artifact" };      // breach not real -- divisor moved / component held

        // v1.0.110.0: map an unknown/misspelled/descriptive category to the nearest valid
        // bucket, so a good verdict is never discarded over a label. Case-insensitive exact
        // match first; then keyword heuristics; then a verdict-appropriate default. Returns a
        // value guaranteed to be in _verdictCategories.
        private static string CoerceCategory(string raw, string verdict)
        {
            string c = (raw ?? "").Trim();
            // exact match ignoring case
            for (int i = 0; i < _verdictCategories.Length; i++)
            {
                if (string.Equals(c, _verdictCategories[i], StringComparison.OrdinalIgnoreCase))
                { return _verdictCategories[i]; }
            }
            string l = c.ToLowerInvariant();
            // keyword heuristics -> valid bucket. ORDER MATTERS: check the more-specific/physical
            // buckets before the generic ones so "point wiring failure" -> Field HW (not Config)
            // and "network data gap" -> Coverage gap (not Platform).
            // v1.0.160.87: a computation artifact is NOT a field fault -- test it FIRST, or phrases
            // like "spike drove the derived value" fall through to Genuine failure.
            if (l.Contains("artifact") || l.Contains("artefact") || l.Contains("divisor")
                || l.Contains("computation") || l.Contains("computed value") || l.Contains("formula"))
            { return "Derived artifact"; }
            if (l.Contains("transient") || l.Contains("momentary") || l.Contains("self-clear")
                || l.Contains("self clear") || l.Contains("recovered") || l.Contains("settled")
                || l.Contains("brief") || l.Contains("spike"))
            { return "Transient - no action"; }
            if (l.Contains("obstruct") || l.Contains("mechanic") || l.Contains("jam")
                || l.Contains("point machine") || l.Contains("motor") || l.Contains("physical")
                || l.Contains("genuine") || l.Contains("real fail") || l.Contains("field fail"))
            { return "Genuine failure"; }
            // coverage / no-data BEFORE platform (a "network data gap" is a coverage gap)
            if (l.Contains("coverage") || l.Contains("no data") || l.Contains("no-data")
                || l.Contains("data gap") || l.Contains("missing") || l.Contains("insufficient"))
            { return "Coverage gap"; }
            // field hardware (incl. wiring/cable/relay/sensor) BEFORE config
            if (l.Contains("hardware") || l.Contains("wiring") || l.Contains("cable")
                || l.Contains("relay") || l.Contains("sensor") || l.Contains("field")
                || l.Equals("hw") || l.Contains(" hw"))
            { return "Field HW"; }
            if (l.Contains("calib") || l.Contains("thresh") || l.Contains("tuning") || l.Contains("limit"))
            { return "Calibration/Threshold"; }
            if (l.Contains("datalog") || l.Contains("logger") || l.Contains("dl "))
            { return "Datalogger"; }
            if (l.Contains("a10") || l.Contains("transition") || l.Contains("migrat"))
            { return "A10 transition"; }
            if (l.Contains("config") || l.Contains("mapping") || l.Contains("setting") || l.Contains("parameter"))
            { return "Config"; }
            if (l.Contains("platform") || l.Contains("server") || l.Contains("comm")
                || l.Contains("network") || l.Contains("connectivity"))
            { return "Platform"; }
            // default by verdict: a confirmed condition is a genuine field issue; an
            // inconclusive one is most often a coverage/data gap; otherwise Field HW.
            if (string.Equals(verdict, "CONFIRMED", StringComparison.OrdinalIgnoreCase)) { return "Field HW"; }
            if (string.Equals(verdict, "INCONCLUSIVE", StringComparison.OrdinalIgnoreCase)) { return "Coverage gap"; }
            return "Field HW";
        }
        // v1.0.111.0: derived_inputs, triage, hi and weather are SERVER-CONTROLLED - they are
        // NOT accepted from the model. They are attached ONLY by trusted post-validation code
        // (derived_inputs + triage computed server-side; hi from the sanitize-then-translate
        // step). They are deliberately absent here so StripUnknown removes any model-emitted
        // version (a model-invented Hindi block would otherwise bypass the English filter).
        private static readonly string[] _verdictTopKeys =
            { "verdict", "confidence", "headline", "likely_cause", "category",
              "evidence", "recommended_action", "caveats", "viz" };
        // fields the server may attach AFTER validation (never accepted from the model)
        private static readonly string[] _serverOnlyVerdictKeys =
            { "derived_inputs", "triage", "hi", "weather" };
        private static readonly string[] _vizKeys =
            { "metric", "unit", "value", "threshold", "baseline", "direction",
              "pct_change", "series", "secondary", "trigger_pct", "recovery_pct", "phase_note" };
        private static readonly string[] _vizSecondaryKeys = { "label", "value", "unit", "x_threshold" };

        // v1.0.160.27 (Item 6): tally the per-line provenance tags the model put on evidence bullets
        // ([fetched]/[record]/[computed]) into a small summary for meta. Static, best-effort, no side effects.
        private static JObject ComputeEvidenceProvenance(JObject v)
        {
            if (v == null) { return null; }
            JArray ev = v["evidence"] as JArray;
            if (ev == null || ev.Count == 0) { return null; }
            int fetched = 0, record = 0, computed = 0, tagged = 0;
            for (int i = 0; i < ev.Count; i++)
            {
                JToken t = ev[i];
                if (t == null || t.Type != JTokenType.String) { continue; }
                string low = t.ToString().TrimStart().ToLowerInvariant();
                if (low.StartsWith("[fetched]")) { fetched++; tagged++; }
                else if (low.StartsWith("[record]")) { record++; tagged++; }
                else if (low.StartsWith("[computed]")) { computed++; tagged++; }
            }
            JObject o = new JObject();
            o["fetched"] = fetched;
            o["record"] = record;
            o["computed"] = computed;
            o["tagged"] = tagged;
            o["total"] = ev.Count;
            o["verified"] = (fetched + computed) > 0;   // any independently-obtained evidence at all?
            return o;
        }

        // v1.0.160.182: ENFORCE evidence provenance (not merely tally it). Item 6/7 only COUNTED the
        // model's [fetched] labels and PROMPTED it to cross-check -- neither verified that a [fetched]
        // line was actually fetched. Result (alert 611604): a 9 h-stale DPR feed produced
        // "[fetched] DPR history shows 0 V at incidence" and a DG line for a tag never pulled, both
        // labelled [fetched]. This is the deterministic backstop: when the alerting tag's history does
        // NOT cover the incidence (_lastCoverageKind != Covered), the model cannot have fetched an
        // at-incidence sample, so every [fetched] evidence line is demoted to [unverified] and an honest
        // caveat is added. Confidence is capped ONLY when the verdict is NOT a genuine FAILURE
        // relay-trigger -- for a FAILURE the [record] relay evidence stands (doctrine FLD-001: a real
        // relay trigger is not cleared by thin analog coverage), so we correct provenance but keep the
        // confidence. Applies to EVERY cause code; gated by AnalyzeProvenanceEnforce (default true).
        // Runs BEFORE ComputeEvidenceProvenance so the meta tally reflects the corrected tags.
        private static readonly bool _provEnforceEnabled = ReadBool("AnalyzeProvenanceEnforce", true);
        private static readonly int  _provEnforceCap = ClampCfg(ReadInt("AnalyzeDowngradeConfidenceCap", 40), 0, 100);

        private void EnforceEvidenceProvenance(JObject v, CoverageStateKind cov)
        {
            if (v == null) { return; }
            if (cov == CoverageStateKind.Covered) { return; }   // history genuinely covers incidence -> [fetched] is legitimate
            int demoted = DemoteFetchedTags(v["evidence"] as JArray);
            JObject hi = v["hi"] as JObject;
            if (hi != null) { demoted += DemoteFetchedTags(hi["evidence"] as JArray); }
            if (demoted == 0) { return; }
            v["caveats"] = AppendCaveat(PushStr(v["caveats"]),
                "incidence coverage not established from history; fetched-telemetry claims marked unverified");
            if (hi != null)
            {
                hi["caveats"] = AppendCaveat(PushStr(hi["caveats"]),
                    "incidence coverage history se establish nahi hua; fetched-telemetry claims unverified");
            }
            bool capped = false;
            if (!_isFailureAlert)
            {
                JToken ct = v["confidence"];
                if (ct != null && (ct.Type == JTokenType.Integer || ct.Type == JTokenType.Float))
                {
                    double c = (double)ct;
                    if (c > _provEnforceCap) { v["confidence"] = _provEnforceCap; capped = true; }
                }
            }
            AiLog("INFO", "PROV", "provenance enforce: coverage=" + cov + " demoted " + demoted
                + " [fetched] line(s)" + (_isFailureAlert ? " (failure verdict; confidence kept)"
                    : (capped ? " (confidence capped " + _provEnforceCap + ")" : "")));
        }

        private static int DemoteFetchedTags(JArray ev)
        {
            if (ev == null) { return 0; }
            int n = 0;
            for (int i = 0; i < ev.Count; i++)
            {
                JToken t = ev[i];
                if (t == null || t.Type != JTokenType.String) { continue; }
                string s = t.ToString();
                if (s.StartsWith("[fetched]", StringComparison.OrdinalIgnoreCase))
                {
                    ev[i] = "[unverified]" + s.Substring("[fetched]".Length);
                    n++;
                }
            }
            return n;
        }

        private static string AppendCaveat(string existing, string add)
        {
            if (string.IsNullOrWhiteSpace(existing)) { return add; }
            string e = existing.TrimEnd();
            if (!e.EndsWith(";") && !e.EndsWith(".")) { e += ";"; }
            return e + " " + add;
        }

        // v1.0.160.186 (#1/#4/#7): viz.threshold must be the one that FIRED (card triggering
        // condition), not a value re-derived from get_attribute_range (which was showing MinSafe).
        // For a LOWER OR-rule (value<avg*LD% OR value<MinSafe) the effective trigger is the HIGHER
        // threshold -> max of the card FAIL thresholds; for a HIGHER rule -> min. Direction from the
        // card comparison, else the cause's CauseToLogic rule (< / >). LD% is baked into the card's
        // avg threshold already. Gated AnalyzeVizCardThreshold (default true).
        private static readonly bool _vizCardThresholdEnabled = ReadBool("AnalyzeVizCardThreshold", true);

        private void OverrideVizThresholdFromCard(JObject v, JObject ctx)
        {
            if (v == null || ctx == null) { return; }
            JObject viz = v["viz"] as JObject;
            if (viz == null) { return; }
            JObject card = ctx["alertCard"] as JObject;
            JArray tc = card != null ? card["triggeredConditions"] as JArray : null;
            JObject cond = (tc != null && tc.Count > 0) ? tc[0] as JObject : null;
            if (cond == null) { return; }
            JArray thrs = cond["thresholds"] as JArray;

            bool haveMax = false, haveMin = false; double maxFail = 0, minFail = 0;
            bool lower = true, haveDir = false;
            if (thrs != null)
            {
                foreach (JToken tk in thrs)
                {
                    JObject to = tk as JObject; if (to == null) { continue; }
                    string cmp = to["comparison"] != null ? to["comparison"].ToString() : "";
                    if (cmp.IndexOf('<') >= 0) { lower = true; haveDir = true; }
                    else if (cmp.IndexOf('>') >= 0) { lower = false; haveDir = true; }
                    string st = to["status"] != null ? to["status"].ToString().ToUpperInvariant() : "";
                    if (st != "FAIL") { continue; }
                    JToken val = to["value"]; double dv;
                    if (val == null || !double.TryParse(val.ToString(),
                            System.Globalization.NumberStyles.Float,
                            System.Globalization.CultureInfo.InvariantCulture, out dv)) { continue; }
                    if (!haveMax || dv > maxFail) { maxFail = dv; haveMax = true; }
                    if (!haveMin || dv < minFail) { minFail = dv; haveMin = true; }
                }
            }
            if (!haveDir)
            {
                string rule;
                if (CauseLogicMaps.CauseToLogic.TryGetValue((GetCtx(ctx, "causeCode") ?? "").Trim(), out rule)
                    && !string.IsNullOrEmpty(rule) && rule.IndexOf('>') >= 0 && rule.IndexOf('<') < 0)
                { lower = false; }
            }
            if (!haveMax) { return; }
            double thr = lower ? maxFail : minFail;

            viz["threshold"] = Math.Round(thr, 3);
            if (cond["paramLabel"] != null) { viz["metric"] = cond["paramLabel"].ToString().Trim(); }
            JToken meas = cond["measured"] ?? cond["value"]; double mv;
            if (meas != null && double.TryParse(meas.ToString(),
                    System.Globalization.NumberStyles.Float,
                    System.Globalization.CultureInfo.InvariantCulture, out mv))
            { viz["value"] = Math.Round(mv, 3); }
            if (cond["unit"] != null) { string u = cond["unit"].ToString().Trim(); if (u.Length > 0) { viz["unit"] = u; } }
            AiLog("INFO", "VIZ", "viz threshold from card = " + Math.Round(thr, 3)
                + (lower ? " (max, lower-rule)" : " (min, higher-rule)")
                + " metric=" + (cond["paramLabel"] != null ? cond["paramLabel"].ToString().Trim() : "?"));
        }

        // v1.0.160.186 (#2): IPS drivers (VIPS.../IIPS...) live on the site's IPS asset
        // (AssetTypeId 39). ResolveIpsAssetIdAsync finds it via search_assets{SiteId}, cached per
        // site; CardMentionsDriver gates the cross-asset fetch to terms the card carries.
        private static readonly bool _ipsCrossAssetEnabled = ReadBool("AnalyzeIpsCrossAsset", true);
        private readonly System.Collections.Concurrent.ConcurrentDictionary<string, string> _ipsAssetBySite
            = new System.Collections.Concurrent.ConcurrentDictionary<string, string>(StringComparer.Ordinal);

        private async Task<string> ResolveIpsAssetIdAsync(string siteId, System.Threading.CancellationToken ct)
        {
            if (string.IsNullOrEmpty(siteId)) { return null; }
            string cached;
            if (_ipsAssetBySite.TryGetValue(siteId, out cached)) { return cached; }
            string found = null;
            try
            {
                string res = await CallToolRoutedAsync("search_assets", NewArgs("SiteId", siteId), ct).ConfigureAwait(false);
                if (!string.IsNullOrEmpty(res))
                {
                    JArray arr = JArray.Parse(res);
                    for (int i = 0; i < arr.Count; i++)
                    {
                        JObject a = arr[i] as JObject; if (a == null) { continue; }
                        JToken ty = a["AssetTypeId"];
                        int tid;
                        if (ty != null && int.TryParse(ty.ToString(), out tid) && tid == 39)
                        {
                            if (a["AssetId"] != null) { found = a["AssetId"].ToString(); break; }
                        }
                    }
                }
            }
            catch { found = null; }
            _ipsAssetBySite[siteId] = found;
            return found;
        }

        private static bool CardMentionsDriver(JObject ctx, string dn)
        {
            if (ctx == null || string.IsNullOrWhiteSpace(dn)) { return false; }
            JObject card = ctx["alertCard"] as JObject;
            if (card == null) { return false; }
            try { return card.ToString(Newtonsoft.Json.Formatting.None)
                    .IndexOf(dn.Trim(), StringComparison.OrdinalIgnoreCase) >= 0; }
            catch { return false; }
        }

        // v1.0.160.188: SQL-Server side link (dbo.FRSAlert_AIAnalysis in E7MRIV2DB). One row per
        // analysis SUBJECT, which is EITHER an FRS alert (FRSAlertId) OR a PendingAlertApproval
        // (PendingAlertApprovalId) -- exactly one id set, the other NULL. FirstAnalysisId = write-once
        // anchor, AnalysisId = latest (overwritten on re-run). The MERGE matches on whichever id is
        // > 0, so an FRS row and a pending row never collide, and re-runs update the right one.
        // Gated AnalyzeSqlAnalysisLink (default true); best-effort. E7MRIV2DB_SQL connection.
        private static readonly bool _analysisLinkEnabled = ReadBool("AnalyzeSqlAnalysisLink", true);
        private const string _analysisLinkSql =
            "MERGE dbo.FRSAlert_AIAnalysis AS t " +
            "USING (SELECT @FRSAlertId AS FRSAlertId, @PendingId AS PendingAlertApprovalId) AS s " +
            "ON ((@FRSAlertId > 0 AND t.FRSAlertId = @FRSAlertId) " +
            "    OR (@PendingId > 0 AND t.PendingAlertApprovalId = @PendingId)) " +
            "WHEN MATCHED THEN UPDATE SET AnalysisId = @NewId, ModifiedDate = GETDATE() " +
            "WHEN NOT MATCHED THEN INSERT (FRSAlertId, PendingAlertApprovalId, FirstAnalysisId, AnalysisId, CreatedDate, ModifiedDate) " +
            "VALUES (NULLIF(@FRSAlertId,0), NULLIF(@PendingId,0), @NewId, @NewId, GETDATE(), GETDATE());";

        private static void WriteAnalysisLink(int frsAlertId, long pendingId, long newId)
        {
            var cs = System.Configuration.ConfigurationManager.ConnectionStrings["E7MRIV2DB_SQL"];
            if (cs == null || string.IsNullOrEmpty(cs.ConnectionString)) { return; }
            using (var cn = new System.Data.SqlClient.SqlConnection(cs.ConnectionString))
            using (var cmd = new System.Data.SqlClient.SqlCommand(_analysisLinkSql, cn))
            {
                cmd.CommandTimeout = 5;
                cmd.Parameters.Add("@FRSAlertId", System.Data.SqlDbType.Int).Value = frsAlertId;   // 0 => NULLIF -> NULL
                cmd.Parameters.Add("@PendingId", System.Data.SqlDbType.BigInt).Value = pendingId;   // 0 => NULLIF -> NULL
                cmd.Parameters.Add("@NewId", System.Data.SqlDbType.BigInt).Value = newId;
                cn.Open();
                cmd.ExecuteNonQuery();
            }
        }

        // v1.0.160.190: recover a thin analysis context from the FRS alert record. If causeCode /
        // siteId / assetId are blank but station+assetName are present, resolve them deterministically
        // (search_sites by station name -> search_assets by asset name -> get_frs_alerts around the
        // incidence -> the row matching this alertId/time) and fill ONLY the blank ctx fields. Then the
        // normal pipeline (CauseToLogic / CauseToAttributes / _gateById) has a real cause to work from.
        // Best-effort: any miss leaves ctx as-is (today's behaviour). Gated AnalyzeBackfillContext.
        private static readonly bool _backfillCtxEnabled = ReadBool("AnalyzeBackfillContext", true);

        private async Task BackfillContextAsync(JObject ctx, System.Threading.CancellationToken ct)
        {
            if (ctx == null) { return; }
            string cause = GetCtx(ctx, "causeCode");
            string siteId = GetCtx(ctx, "siteId");
            string assetId = GetCtx(ctx, "assetId");
            // nothing to do if the cause is already known and both ids present
            if (!string.IsNullOrEmpty(cause) && !string.IsNullOrEmpty(siteId) && !string.IsNullOrEmpty(assetId)) { return; }

            string station = GetCtx(ctx, "station");
            string assetName = GetCtx(ctx, "assetName");
            string alertId = GetCtx(ctx, "alertId");

            // 0) alertId-only path: fetch_alert_details_frs returns the alert row directly, so even a
            //    near-empty context (only alertId) can be recovered in ONE call. Try this first.
            if (!string.IsNullOrEmpty(alertId) && (string.IsNullOrEmpty(cause) || string.IsNullOrEmpty(siteId) || string.IsNullOrEmpty(assetId)))
            {
                try
                {
                    JObject dargs = NewArgs("AlertId", alertId);
                    string dres = await CallToolRoutedAsync("fetch_alert_details_frs", dargs, ct).ConfigureAwait(false);
                    JObject row = FirstAlertRow(dres);
                    if (row != null)
                    {
                        ApplyAlertRow(ctx, row);
                        cause = GetCtx(ctx, "causeCode"); siteId = GetCtx(ctx, "siteId"); assetId = GetCtx(ctx, "assetId");
                        station = GetCtx(ctx, "station"); assetName = GetCtx(ctx, "assetName");
                    }
                }
                catch { }
            }
            // if the by-id path already filled the cause and ids, we're done
            if (!string.IsNullOrEmpty(cause) && !string.IsNullOrEmpty(siteId) && !string.IsNullOrEmpty(assetId))
            {
                AiLog("INFO", "BACKFILL", "context backfill (by alertId): cause='" + cause + "' site=" + siteId + " asset=" + assetId);
                return;
            }
            if (string.IsNullOrEmpty(assetName) && string.IsNullOrEmpty(station) && string.IsNullOrEmpty(siteId)) { return; }  // nothing left to resolve from

            // 1) siteId from station name
            if (string.IsNullOrEmpty(siteId) && !string.IsNullOrEmpty(station))
            {
                try
                {
                    string sres = await CallToolRoutedAsync("search_sites", NewArgs("SiteName", station), ct).ConfigureAwait(false);
                    string sid = HarvestIdToken(sres, "SiteId") ?? HarvestIdToken(sres, "site_id");
                    if (!string.IsNullOrEmpty(sid)) { siteId = sid; ctx["siteId"] = sid; }
                }
                catch { }
            }
            // 2) assetId from asset name (+site)
            if (string.IsNullOrEmpty(assetId) && !string.IsNullOrEmpty(assetName))
            {
                try
                {
                    JObject aargs = NewArgs("AssetName", assetName);
                    if (!string.IsNullOrEmpty(siteId)) { aargs["SiteId"] = siteId; }
                    string ares = await CallToolRoutedAsync("search_assets", aargs, ct).ConfigureAwait(false);
                    string aid = HarvestIdToken(ares, "AssetId") ?? HarvestIdToken(ares, "asset_id");
                    if (!string.IsNullOrEmpty(aid)) { assetId = aid; ctx["assetId"] = aid; }
                    if (string.IsNullOrEmpty(siteId))
                    {
                        string sid2 = HarvestIdToken(ares, "SiteId") ?? HarvestIdToken(ares, "site_id");
                        if (!string.IsNullOrEmpty(sid2)) { siteId = sid2; ctx["siteId"] = sid2; }
                    }
                }
                catch { }
            }
            // 3) the FRS alert row around the incidence -> causeCode / alertType / description
            if (string.IsNullOrEmpty(cause) && !string.IsNullOrEmpty(siteId))
            {
                try
                {
                    DateTime incT;
                    if (!TryParseAlertTime(GetCtx(ctx, "time"), out incT)) { incT = DateTime.UtcNow; }
                    string fres = await CallToolRoutedAsync("get_frs_alerts", NewSiteAlertArgs(siteId, incT), ct).ConfigureAwait(false);
                    JObject fo = null;
                    try { fo = JObject.Parse(fres); } catch { }
                    JArray rows = fo != null ? fo["mFRSAlerts"] as JArray : null;
                    JObject pick = null;
                    if (rows != null)
                    {
                        long aidWant; long.TryParse(alertId, out aidWant);
                        foreach (JToken tk in rows)
                        {
                            JObject ro = tk as JObject; if (ro == null) { continue; }
                            long rid; long.TryParse(FirstStr(ro, "Id", "AlertId", "id"), out rid);
                            string raid = FirstStr(ro, "AssetId", "assetId");
                            if (aidWant > 0 && rid == aidWant) { pick = ro; break; }
                            if (pick == null && !string.IsNullOrEmpty(assetId) && raid == assetId) { pick = ro; }
                        }
                        if (pick == null && rows.Count > 0) { pick = rows[0] as JObject; }
                    }
                    if (pick != null) { ApplyAlertRow(ctx, pick); }
                }
                catch { }
            }
            AiLog("INFO", "BACKFILL", "context backfill: cause='" + GetCtx(ctx, "causeCode") + "' site=" + GetCtx(ctx, "siteId")
                + " asset=" + GetCtx(ctx, "assetId") + " (from station='" + station + "' assetName='" + assetName + "')");
        }

        // v1.0.160.190: pull the first alert row out of a tool result (fetch_alert_details_frs returns
        // either a bare array or { mFRSAlerts:[...] } / { data:[...] }).
        private static JObject FirstAlertRow(string res)
        {
            if (string.IsNullOrEmpty(res)) { return null; }
            try
            {
                JToken t = JToken.Parse(res);
                JArray arr = t as JArray;
                if (arr == null && t is JObject)
                {
                    JObject o = (JObject)t;
                    arr = (o["mFRSAlerts"] as JArray) ?? (o["data"] as JArray) ?? (o["rows"] as JArray);
                    if (arr == null && (o["CauseCode"] != null || o["PossibleCause"] != null)) { return o; }
                }
                if (arr != null && arr.Count > 0) { return arr[0] as JObject; }
            }
            catch { }
            return null;
        }

        // v1.0.160.190: copy blank ctx fields from an FRS alert row (fills only what's missing).
        private static void ApplyAlertRow(JObject ctx, JObject row)
        {
            if (ctx == null || row == null) { return; }
            if (GetCtx(ctx, "causeCode") == "") { string cc = FirstStr(row, "CauseCode", "PossibleCause", "causeCode", "cause_code"); if (!string.IsNullOrEmpty(cc)) ctx["causeCode"] = cc; }
            if (GetCtx(ctx, "siteId") == "") { string sid = FirstStr(row, "SiteId", "siteId", "site_id"); if (!string.IsNullOrEmpty(sid)) ctx["siteId"] = sid; }
            if (GetCtx(ctx, "assetId") == "") { string aid = FirstStr(row, "AssetId", "assetId", "asset_id"); if (!string.IsNullOrEmpty(aid)) ctx["assetId"] = aid; }
            if (GetCtx(ctx, "assetName") == "") { string an = FirstStr(row, "AssetName", "assetName"); if (!string.IsNullOrEmpty(an)) ctx["assetName"] = an; }
            if (GetCtx(ctx, "station") == "") { string sn = FirstStr(row, "SiteName", "siteName", "station"); if (!string.IsNullOrEmpty(sn)) ctx["station"] = sn; }
            if (GetCtx(ctx, "description") == "") { string ds = FirstStr(row, "Description", "description"); if (!string.IsNullOrEmpty(ds)) ctx["description"] = ds; }
            if (GetCtx(ctx, "time") == "" || GetCtx(ctx, "time") == "-") { string tm = FirstStr(row, "SetTimeStamp", "setTimeStamp", "time"); if (!string.IsNullOrEmpty(tm)) ctx["time"] = tm; }
            if (string.IsNullOrEmpty(GetCtx(ctx, "alertType")))
            {
                string cat = FirstStr(row, "AlertCategoryId", "alertCategoryId");
                if (cat == "1") ctx["alertType"] = "PREDICTIVE";
                else if (cat == "2") ctx["alertType"] = "FAILURE";
            }
        }

        // v1.0.160.191: assemble the follow-up-chat grounding from the alert card the web already sent
        // to analyze, PLUS the cause's FRS logic. Returns null when there's no card (then the loop runs
        // as before). Passed as systemPromptOverride so the model starts fully grounded -- no rediscovery.
        // v1.0.160.197: fetch the point-machine operation AVERAGES (EdgeX "-Avg" attids) and format
        // them for the chat grounding, so chat returns the last-operation voltage/current DETERMINISTICALLY.
        // Guidance alone (.196) was not enough: live_get returns a positional payload the model cannot map,
        // and predict_pm_operation can be down -- so the model fell back to the 0-at-rest RDPMS tags.
        // Binding the parsed values removes that dependency. PT* cause + assetId only; "" on any miss
        // (then the .196 guidance still applies). Short timeout so a PM chat never stalls on this.
        private static string BuildPmOperationValues(JObject payload)
        {
            try
            {
                if (payload == null) { return ""; }
                string cause = payload["causeCode"] != null ? payload["causeCode"].ToString() : "";
                if (string.IsNullOrEmpty(cause) && payload["alertCard"] is JObject)
                { cause = FirstStr((JObject)payload["alertCard"], "alertCode", "causeCode", "CauseCode"); }
                if (string.IsNullOrEmpty(cause) || !cause.TrimStart().ToUpperInvariant().StartsWith("PT ")) { return ""; }
                string assetId = payload["assetId"] != null ? payload["assetId"].ToString()
                                : (payload["AssetId"] != null ? payload["AssetId"].ToString() : "");
                int aid;
                if (string.IsNullOrEmpty(assetId) || !int.TryParse(assetId, out aid) || aid <= 0) { return ""; }

                Dictionary<int, double> v = FetchLiveValueMap(aid);
                if (v.Count == 0) { return ""; }
                // EdgeX PointMachine "-Avg" attid -> label + unit (V for voltage, A for operation current)
                string[][] defs = new string[][] {
                    new []{"2002","A End NW-V","V"}, new []{"4002","B End NW-V","V"},
                    new []{"1002","A End NW-C","A"}, new []{"3002","B End NW-C","A"},
                    new []{"7002","A End RW-V","V"}, new []{"9002","B End RW-V","V"},
                    new []{"6002","A End RW-C","A"}, new []{"8002","B End RW-C","A"},
                };
                System.Text.StringBuilder sb = new System.Text.StringBuilder();
                for (int i = 0; i < defs.Length; i++)
                {
                    int at = int.Parse(defs[i][0]); double val;
                    if (v.TryGetValue(at, out val))
                    {
                        if (sb.Length == 0)
                        {
                            sb.Append("POINT-MACHINE OPERATION VALUES (live, last-operation average -- AUTHORITATIVE. ")
                              .Append("Use these for operation voltage/current; do NOT read the 0-at-rest RDPMS ")
                              .Append("'A/B End - NW-V/NW-C/RW-V/RW-C' tags or a raw history sample):\n");
                        }
                        sb.Append("  ").Append(defs[i][1]).Append(": ")
                          .Append(Math.Round(val, 2)).Append(" ").Append(defs[i][2]).Append("\n");
                    }
                }
                return sb.ToString();
            }
            catch { return ""; }
        }

        // v1.0.160.195 (memory-loss B): does the chat POST already carry an alert card? Mirrors the
        // card detection in BuildChatGrounding so the self-heal only runs when the card is genuinely absent.
        private static bool ChatPayloadHasCard(JObject payload)
        {
            if (payload == null) { return false; }
            JObject card = (payload["alertCard"] as JObject) ?? (payload["card"] as JObject) ?? (payload["context"] as JObject);
            if (card != null && card["alertCard"] is JObject) { card = (JObject)card["alertCard"]; }
            return card != null;
        }

        // v1.0.160.195 (memory-loss B): rebuild the analyze input context from what was persisted at
        // analysis start (AlertInputJson holds the full input incl. the alert card). Read-only; reuses
        // the breaker-safe CacheGet (404 = miss, breaker untouched) and returns null on any miss so the
        // caller falls back to today's behaviour. IncludeJson=1 is required or the heavy JSON is stripped.
        private static JObject LoadStoredAlertContext(JObject payload)
        {
            try
            {
                if (payload == null) { return null; }
                string alertId = payload["alertId"] != null ? payload["alertId"].ToString()
                                : (payload["AlertId"] != null ? payload["AlertId"].ToString() : "");
                long aid;
                if (string.IsNullOrEmpty(alertId) || !long.TryParse(alertId, out aid) || aid <= 0) { return null; }
                JArray rows = CacheGet("/api/AIAnalysis/Get?AlertId=" + aid + "&IncludeJson=1");
                if (rows == null || rows.Count == 0) { return null; }
                // rows are newest-first; take the newest that actually carries the stored input context.
                for (int i = 0; i < rows.Count; i++)
                {
                    JObject row = rows[i] as JObject;
                    if (row == null) { continue; }
                    JToken inTok = row["AlertInputJson"];
                    if (inTok == null || inTok.Type == JTokenType.Null) { continue; }
                    string inStr = inTok.ToString();
                    if (string.IsNullOrWhiteSpace(inStr) || inStr == "{}") { continue; }
                    try
                    {
                        JObject stored = JObject.Parse(inStr);
                        if (stored["alertCard"] is JObject || stored["causeCode"] != null) { return stored; }
                    }
                    catch { }
                }
                return null;
            }
            catch { return null; }
        }

        private static string BuildChatGrounding(JObject payload)
        {
            if (payload == null) { return null; }
            // accept several field names the web might use
            JObject card = (payload["alertCard"] as JObject) ?? (payload["card"] as JObject) ?? (payload["context"] as JObject);
            // context wrapper: {context:{alertCard:{...}}}
            if (card != null && card["alertCard"] is JObject) { card = (JObject)card["alertCard"]; }
            string alertId = payload["alertId"] != null ? payload["alertId"].ToString()
                            : (payload["AlertId"] != null ? payload["AlertId"].ToString() : "");
            string analysisId = payload["analysisId"] != null ? payload["analysisId"].ToString()
                            : (payload["AnalysisId"] != null ? payload["AnalysisId"].ToString() : "");
            string cause = "";
            if (card != null)
            {
                cause = FirstStr(card, "alertCode", "causeCode", "CauseCode");
                if (string.IsNullOrEmpty(cause) && card["meta"] is JObject) { cause = FirstStr((JObject)card["meta"], "causeCode", "CauseCode"); }
            }
            if (string.IsNullOrEmpty(cause)) { cause = payload["causeCode"] != null ? payload["causeCode"].ToString() : ""; }
            if (card == null && string.IsNullOrEmpty(cause)) { return null; }   // nothing to ground with

            System.Text.StringBuilder sb = new System.Text.StringBuilder();
            sb.Append("ALERT CONTEXT (authoritative -- already gathered; DO NOT re-investigate from scratch. ");
            sb.Append("Answer the user's question from THIS context; only call a tool if the user explicitly asks for data not present here).\n");
            if (!string.IsNullOrEmpty(alertId)) { sb.Append("AlertId: ").Append(alertId).Append("\n"); }
            if (!string.IsNullOrEmpty(analysisId)) { sb.Append("AnalysisId: ").Append(analysisId).Append("\n"); }
            if (!string.IsNullOrEmpty(cause)) { sb.Append("Cause: ").Append(cause).Append("\n"); }
            if (card != null)
            {
                // the full card as-is (triggeredConditions, enablingConditions, thresholds, relayStatus, resetCard)
                sb.Append("Alert card (measured values, thresholds, relay states, reset):\n");
                sb.Append(card.ToString(Newtonsoft.Json.Formatting.None)).Append("\n");
            }
            // cause FRS logic from CauseToLogic + parsed LD%/sustain -- the exact rule this alert follows
            if (!string.IsNullOrEmpty(cause))
            {
                string rule;
                if (CauseLogicMaps.CauseToLogic.TryGetValue(cause.Trim(), out rule) && !string.IsNullOrEmpty(rule))
                {
                    sb.Append("FRS logic for ").Append(cause).Append(": ").Append(rule).Append("\n");
                    try
                    {
                        var _ldm = System.Text.RegularExpressions.Regex.Match(rule, @"(\d+)\s*%\s*avg", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                        if (_ldm.Success) { sb.Append("LD% (from rule): ").Append(_ldm.Groups[1].Value).Append("%avg\n"); }
                        int sus = FrsSustainSeconds(rule);
                        if (sus > 0) { sb.Append("Sustain window: ").Append(sus).Append("s\n"); }
                    }
                    catch { }
                }
            }
            // v1.0.160.196: point-machine operation voltage/current guidance. A PM's operation V/C
            // (the value seen DURING a throw) lives on the EdgeX PointMachine "-Avg" attributes, which
            // hold the LAST-operation average. The RDPMS display tags "A/B End - NW-V/NW-C/RW-V/RW-C"
            // (attid 212-219) read 0 between throws, so they must NOT be reported as the operation value,
            // and a raw history sample is a single instant (often a transient peak), not the operation
            // voltage. Steer the model to the -Avg attids so chat matches the Live Data panel.
            if (!string.IsNullOrEmpty(cause) && cause.TrimStart().ToUpperInvariant().StartsWith("PT "))
            {
                sb.Append("POINT-MACHINE OPERATION VOLTAGE/CURRENT: when asked for this point machine's ")
                  .Append("operation voltage or current (the value during a throw), report the EdgeX ")
                  .Append("PointMachine per-operation AVERAGE, which is the last-operation average:\n")
                  .Append("  Normal throw voltage (NW-V): A end AssetAttributeId 2002, B end 4002\n")
                  .Append("  Normal throw current (NW-C): A end 1002, B end 3002\n")
                  .Append("  Reverse throw voltage (RW-V): A end 7002, B end 9002\n")
                  .Append("  Reverse throw current (RW-C): A end 6002, B end 8002\n")
                  .Append("These tags are named '<AssetId>-PM-0XXXX-Avg' (also -Min/-Max/-OperationTime/")
                  .Append("-Count/-Array). Resolve the -Avg AssetAttributeId via search_tags then live_get/")
                  .Append("history_get it. Do NOT report the 'A/B End - NW-V/NW-C/RW-V/RW-C' tags (they read ")
                  .Append("0 between throws) and do NOT report a raw history spike as the operation value ")
                  .Append("-- the -Avg value is the representative operation voltage/current.\n");
            }
            return sb.ToString();
        }

        private static void StripUnknown(JObject o, string[] allowed)
        {
            List<string> drop = new List<string>();
            foreach (var prop in o.Properties())
            {
                bool ok = false;
                for (int i = 0; i < allowed.Length; i++)
                {
                    if (string.Equals(prop.Name, allowed[i], StringComparison.Ordinal)) { ok = true; break; }
                }
                if (!ok) { drop.Add(prop.Name); }
            }
            for (int i = 0; i < drop.Count; i++) { o.Remove(drop[i]); }
        }

        // The prompt states hard word budgets; the validator never checked them, so
        // "MAX 15 WORDS" was advice the system did not keep. Trim rather than reject:
        // a sound verdict should not be discarded for being wordy, and the operator
        // reads a fixed-width card either way. Truncation does NOT save generation
        // time -- the model has already paid to write the words -- so this is about
        // consistency and payload, while max_tokens on the synthesis client is what
        // actually bounds the time.
        private static string TrimWords(string text, int maxWords)
        {
            if (string.IsNullOrEmpty(text)) { return text; }
            string[] w = text.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
            if (w.Length <= maxWords) { return text; }
            return string.Join(" ", w, 0, maxWords).TrimEnd(',', ';', '-') + "...";
        }

        private static bool NumOrNull(JObject o, string key, out string reason)
        {
            reason = null;
            JToken t = o[key];
            if (t == null || t.Type == JTokenType.Null) { return true; }
            if (t.Type == JTokenType.Integer || t.Type == JTokenType.Float) { return true; }
            reason = "viz." + key + " must be a number or null";
            return false;
        }

        private bool ValidateAndSanitizeVerdict(JObject v, out string reason)
        {
            reason = null;
            // v1.0.111.0: SAFETY - remove any model-emitted server-only field FIRST, before
            // anything else. derived_inputs / triage / hi / weather are attached only by trusted
            // post-validation code; a model-supplied version (e.g. an invented Hindi block that
            // would bypass the English operational-action filter) must never survive.
            for (int i = 0; i < _serverOnlyVerdictKeys.Length; i++) { v.Remove(_serverOnlyVerdictKeys[i]); }
            StripUnknown(v, _verdictTopKeys); // unknown extras never pass through
            string verdict = v["verdict"] != null ? v["verdict"].ToString() : "";
            if (verdict != "CONFIRMED" && verdict != "NOT_CONFIRMED" && verdict != "INCONCLUSIVE")
            {
                reason = "verdict must be CONFIRMED | NOT_CONFIRMED | INCONCLUSIVE"; return false;
            }
            JToken conf = v["confidence"];
            int confVal;
            if (conf == null || !int.TryParse(conf.ToString(), out confVal))
            {
                // v1.0.136.0: coerce numeric confidence. Some models (DeepSeek flash) emit
                // 72.0 or "72.5" where the schema says integer; rejecting the whole verdict
                // for that is too strict -- round and clamp instead. Non-numeric still fails.
                double confD;
                if (conf != null && double.TryParse(conf.ToString(), System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out confD)
                    && !double.IsNaN(confD) && !double.IsInfinity(confD))
                {
                    // v1.0.138.0: DeepSeek emits confidence on a 0-1 scale ("0.85" = 85%).
                    // 1.0.136.0's plain rounding collapsed every such value to 0 or 1,
                    // making all its verdicts display as ~1% confidence. A DECIMAL value
                    // <= 1.0 is a fraction -> scale to percent before rounding. A plain
                    // integer "1" (no decimal point) still means 1%.
                    if (confD > 0 && confD <= 1.0 && conf.ToString().IndexOf('.') >= 0)
                    {
                        confD = confD * 100.0;
                    }
                    confVal = (int)Math.Round(confD);
                }
                else
                {
                    reason = "confidence must be an integer 0-100"; return false;
                }
            }
            if (confVal < 0 || confVal > 100)
            {
                reason = "confidence must be an integer 0-100"; return false;
            }
            v["confidence"] = confVal;
            string cat = v["category"] != null ? v["category"].ToString() : "";
            bool catOk = false;
            for (int i = 0; i < _verdictCategories.Length; i++)
            {
                if (string.Equals(cat, _verdictCategories[i], StringComparison.Ordinal)) { catOk = true; break; }
            }
            if (!catOk)
            {
                // v1.0.110/111: category is a CLASSIFICATION LABEL, the least safety-critical
                // field - coerce an unknown/misspelled category to the nearest valid bucket rather
                // than discarding an otherwise-valid verdict. Log the coercion for auditability.
                string coerced = CoerceCategory(cat, verdict);
                AiLog("INFO", "CATEGORY", "coerced category '" + (cat ?? "") + "' -> '" + coerced + "'");
                v["category"] = coerced;
            }
            string[] reqStr = { "headline", "likely_cause", "recommended_action" };
            for (int i = 0; i < reqStr.Length; i++)
            {
                JToken t = v[reqStr[i]];
                if (t == null || t.Type != JTokenType.String || t.ToString().Trim().Length == 0)
                {
                    reason = reqStr[i] + " must be a non-empty string"; return false;
                }
                string cleaned = (reqStr[i] == "recommended_action")
                    ? ScrubPlatformInternals(FilterRecommendedAction(t.ToString()), "recommended_action")
                    : ScrubPlatformInternals(FilterOperationalActions(t.ToString()), "verdict");
                if (reqStr[i] == "headline") { cleaned = TrimWords(cleaned, 15); }
                else if (reqStr[i] == "likely_cause") { cleaned = TrimWords(cleaned, 25); }
                else if (reqStr[i] == "recommended_action") { cleaned = TrimWords(cleaned, 35); }
                v[reqStr[i]] = cleaned;
            }
            JToken ev = v["evidence"];
            if (ev == null || ev.Type != JTokenType.Array || ((JArray)ev).Count < 1 || ((JArray)ev).Count > 10)
            {
                reason = "evidence must be an array of 1-10 strings"; return false;
            }
            JArray evArr = (JArray)ev;
            for (int i = 0; i < evArr.Count; i++)
            {
                if (evArr[i].Type != JTokenType.String || evArr[i].ToString().Trim().Length == 0)
                {
                    reason = "evidence[" + i + "] must be a non-empty string"; return false;
                }
                evArr[i] = TrimWords(ScrubPlatformInternals(FilterOperationalActions(evArr[i].ToString()), "evidence"), 20);
            }
            // The prompt asks for EXACTLY 4 bullets, but validation deliberately
            // ACCEPTS 1-10 and trims to 4: a 3-bullet verdict is still a verdict,
            // and rejecting it over formatting would burn the whole analysis.
            // Extra lines are almost always the 5th and 6th restating earlier
            // ones, so keep the first four -- the prompt orders them
            // most-important-first.
            while (evArr.Count > 4) { evArr.RemoveAt(evArr.Count - 1); }
            if (v["caveats"] == null || v["caveats"].Type != JTokenType.String)
            {
                v["caveats"] = "";
            }
            else
            {
                v["caveats"] = TrimWords(ScrubPlatformInternals(FilterOperationalActions(v["caveats"].ToString()), "caveats"), 20);
            }
            // v1.0.111.0: derived_inputs and triage are NO LONGER accepted from the model - they
            // were stripped at the top of this method and are attached only by trusted server-side
            // code after validation. (The former model-emitted validation blocks were removed.)
            JToken viz = v["viz"];
            if (viz != null && viz.Type != JTokenType.Null)
            {
                if (viz.Type != JTokenType.Object) { reason = "viz must be an object or null"; return false; }
                JObject z = (JObject)viz;
                StripUnknown(z, _vizKeys);
                string[] vizStrings = { "metric", "unit" };
                for (int i = 0; i < vizStrings.Length; i++)
                {
                    JToken t = z[vizStrings[i]];
                    if (t != null && t.Type != JTokenType.Null)
                    {
                        if (t.Type != JTokenType.String) { reason = "viz." + vizStrings[i] + " must be a string"; return false; }
                        z[vizStrings[i]] = ScrubPlatformInternals(FilterOperationalActions(t.ToString()), "viz");
                    }
                }
                if (!NumOrNull(z, "value", out reason)) { return false; }
                if (!NumOrNull(z, "threshold", out reason)) { return false; }
                if (!NumOrNull(z, "baseline", out reason)) { return false; }
                if (!NumOrNull(z, "pct_change", out reason)) { return false; }
                if (!NumOrNull(z, "trigger_pct", out reason)) { return false; }
                if (!NumOrNull(z, "recovery_pct", out reason)) { return false; }
                JToken pn = z["phase_note"];
                if (pn != null && pn.Type != JTokenType.Null)
                {
                    if (pn.Type != JTokenType.String) { reason = "viz.phase_note must be a string"; return false; }
                    z["phase_note"] = ScrubPlatformInternals(FilterOperationalActions(pn.ToString()), "phase_note");
                }
                JToken dir = z["direction"];
                if (dir != null && dir.Type != JTokenType.Null)
                {
                    string d = dir.ToString();
                    if (d != "declining" && d != "rising" && d != "flat")
                    {
                        reason = "viz.direction must be declining | rising | flat | null"; return false;
                    }
                }
                // v1.0.160.120 SL1: if K2 could not run on a track asset, SAY SO. Appended to caveats
                // rather than logged only -- the reader must be able to tell "checked and clean" from
                // "not checked", which is exactly the distinction 122 silent skips destroyed.
                if (!string.IsNullOrEmpty(_circuitSkipReason))
                {
                    try
                    {
                        string cv = v["caveats"] != null ? v["caveats"].ToString() : "";
                        if (cv.IndexOf("coherence not checked", StringComparison.OrdinalIgnoreCase) < 0)
                        {
                            v["caveats"] = (cv.Length > 0 ? cv.TrimEnd('.', ' ') + "; " : "") + _circuitSkipReason;
                        }
                    }
                    catch { }
                }

                // v1.0.160.122 SL3 (relocated in .124): pin the action where it is a CONSEQUENCE of
                // the category, not a judgement. This belongs in the VERDICT sanitiser -- .122 put it
                // in BuildPushBlock, which builds the push NOTIFICATION, so the verdict itself still
                // drifted while the push text was pinned. The anchor string existed in both methods.
                try
                {
                    string catNow = v["category"] != null ? v["category"].ToString().Trim() : "";
                    string fixedAct = DeterministicAction(catNow);
                    if (fixedAct != null) { v["recommended_action"] = fixedAct; }
                    else
                    {
                        // Not pinned: keep the model's text, but remove any clause that justifies work
                        // by the STANDING CONDITION -- that finding has its own band and its own action
                        // (Cut F); letting it leak in here is what turned "monitor" into "schedule".
                        string a0 = v["recommended_action"] != null ? v["recommended_action"].ToString() : "";
                        string a1 = StripStandingConditionClause(a0);
                        if (!string.Equals(a0, a1, StringComparison.Ordinal))
                        {
                            v["recommended_action"] = a1;
                            AiLog("INFO", "ACTION", "standing-condition clause removed from recommended_action");
                        }
                    }
                }
                catch { }

                // v1.0.160.117 CUT C: take the citation, record it, then REMOVE the field. It is
                // internal attribution -- a non-privileged browser must never receive rule ids, which
                // would disclose the doctrine taxonomy (same class F2/F7 exist to prevent).
                try
                {
                    JToken wu = v["wisdom_used"];
                    if (wu != null)
                    {
                        if (wu.Type == JTokenType.Array)
                        {
                            JArray keep = new JArray();
                            JArray src = (JArray)wu;
                            for (int i = 0; i < src.Count && i < 20; i++)
                            {
                                string id = src[i] != null ? src[i].ToString().Trim().Trim('[', ']') : "";
                                if (id.Length > 0 && _wisdomIdRx.IsMatch(id)) { keep.Add(id.ToUpperInvariant()); }
                            }
                            if (keep.Count > 0) { _wisdomUsed = keep; }
                        }
                        v.Remove("wisdom_used");   // never reaches the browser
                    }
                }
                catch { try { v.Remove("wisdom_used"); } catch { } }

                // v1.0.160.114 CUT E: the MODEL's series is a restatement, not a measurement -- on
                // 543194 it was reset->breach->reset drawn as a V. Override with the real one the
                // controller already has; if there is none, emit an EMPTY series and say so rather
                // than letting an invented shape stand.
                {
                    string _srcKind;
                    JArray _real = RealVizSeries(v, out _srcKind);
                    if (_real != null && _real.Count > 0)
                    {
                        z["series"] = _real;
                        z["seriesSource"] = _srcKind;
                    }
                    else
                    {
                        z["series"] = new JArray();
                        z["seriesSource"] = "unavailable";
                    }
                }
                JToken series = z["series"];
                if (series != null && series.Type != JTokenType.Null)
                {
                    if (series.Type != JTokenType.Array) { reason = "viz.series must be an array"; return false; }
                    JArray sa = (JArray)series;
                    // 50 points is more chart resolution than a 500px SVG can show,
                    // and OUTPUT tokens dominate the final turn (measured: 1,569 out =
                    // 33 s, vs 10,540 in on the same turn). Trim rather than reject.
                    // NOTE: trimming here saves BYTES to the browser but NOT generation
                    // time -- the model has already paid to write them. The real control
                    // is the 12-point instruction in the prompt; this is the backstop.
                    while (sa.Count > 12) { sa.RemoveAt(1); }
                    // v1.0.87.0: COERCE rather than reject. The model sometimes emits a
                    // numeric value as a STRING ("8.53") or slips a null into the series
                    // -- rejecting the entire (otherwise grounded) verdict over that is a
                    // brittle output gate that turns a good analysis into a failure. Parse
                    // string numbers in place; drop nulls; only reject on a value that is
                    // genuinely not a number (e.g. an object or non-numeric text).
                    for (int i = sa.Count - 1; i >= 0; i--)
                    {
                        JToken el = sa[i];
                        if (el.Type == JTokenType.Integer || el.Type == JTokenType.Float) { continue; }
                        if (el.Type == JTokenType.Null) { sa.RemoveAt(i); continue; }
                        if (el.Type == JTokenType.String)
                        {
                            double dv;
                            string sv = el.ToString().Trim();
                            if (double.TryParse(sv, System.Globalization.NumberStyles.Any,
                                    System.Globalization.CultureInfo.InvariantCulture, out dv))
                            {
                                sa[i] = dv; continue;
                            }
                            // empty string -> drop; anything else non-numeric -> reject
                            if (sv.Length == 0) { sa.RemoveAt(i); continue; }
                        }
                        reason = "viz.series[" + i + "] must be numeric"; return false;
                    }
                }
                JToken sec = z["secondary"];
                if (sec != null && sec.Type != JTokenType.Null)
                {
                    if (sec.Type != JTokenType.Object) { reason = "viz.secondary must be an object"; return false; }
                    JObject so = (JObject)sec;
                    // v1.0.160.186 (#6): viz.secondary is OPTIONAL (like viz.series). If value is
                    // missing/non-numeric, DROP the whole secondary object instead of REJECTING the
                    // verdict (was: "Verdict failed validation: viz.secondary.value must be numeric" on
                    // causes with no natural secondary, e.g. ROSIG HPR VOLT LOW). label/unit/x_threshold
                    // already tolerate null; value was the only field that didn't.
                    JToken svPre = so["value"];
                    if (svPre == null || (svPre.Type != JTokenType.Integer && svPre.Type != JTokenType.Float))
                    {
                        z["secondary"] = null;
                    }
                    else
                    {
                        StripUnknown(so, _vizSecondaryKeys);
                        string[] secStr = { "label", "unit" };
                        for (int i = 0; i < secStr.Length; i++)
                        {
                            JToken sst = so[secStr[i]];
                            if (sst != null && sst.Type != JTokenType.Null)
                            {
                                if (sst.Type != JTokenType.String) { reason = "viz.secondary." + secStr[i] + " must be a string"; return false; }
                                so[secStr[i]] = ScrubPlatformInternals(FilterOperationalActions(sst.ToString()), "viz.secondary");
                            }
                        }
                        JToken xt = so["x_threshold"];
                        if (xt != null && xt.Type != JTokenType.Null
                            && xt.Type != JTokenType.Integer && xt.Type != JTokenType.Float)
                        {
                            reason = "viz.secondary.x_threshold must be numeric or null"; return false;
                        }
                    }
                }
            }

            // v1.0.75.0: mechanical final gate. Reads ONLY the ALERTING tag's
            // coverage level -- a different tag's good series is corroboration,
            // never coverage. AnalyzeStrictCoverage (D4) picks the policy:
            //   scoped (default) - downgrade only when a usable history_get ran
            //                       for SOME tag but the alerting tag never
            //                       reached VerifiedAdequate
            //   strict            - binary verdicts always require the alerting
            //                       tag at VerifiedAdequate, including alerts
            //                       grounded only by analyse_alert/ML
            // This is the single choke point both final paths pass through: the
            // JSON envelope and the SSE popup verdict frame each call this method.
            string vFinal = v["verdict"] != null ? v["verdict"].ToString() : "";
            if (vFinal == "CONFIRMED" || vFinal == "NOT_CONFIRMED")
            {
                // v1.0.82.0 rev J: a DERIVED alerting attribute has no tag of its own,
                // so the alerting-tag level is unsatisfiable by construction. For
                // derived alerts adequacy = component coverage (>=2 covered incl. one
                // voltage and one current when the formula uses both). Direct alerts:
                // unchanged strictness.
                bool adequate = _derivedAlert
                    ? _derivedComponentsAdequate
                    : AlertingCoverageLevel() == HistoryCoverageLevel.VerifiedAdequate;
                // v1.0.160.111 (BUG-5): card-authoritative bypass. If the card already carries the failing
                // value (a MinSafe/MaxSafe FAIL) or this is a FAILURE-type alert (a self-proving discrete
                // relay-state / blank / op-fail event), the incidence is established and sparse/absent
                // history must NOT force "Coverage gap" INCONCLUSIVE.
                if (_cardHasFail || _isFailureAlert || _rawHasBreach) { adequate = true; }
                bool enforce = _strictCoverage ? !adequate : (!adequate && gotUsableHistoryGet);
                if (enforce)
                {
                    coverageDowngrade = "verdict " + vFinal + " downgraded: "
                        + (_derivedAlert
                            ? "derived-attribute component coverage not established"
                            : "alerting-tag coverage "
                              + (AlertingCoverageLevel() == HistoryCoverageLevel.Unverified ? "unverified" : "not established")
                              + " (tag=" + (AlertingTagId() ?? "unresolved") + ")");
                    AiLog("WARN", "VERDICT", coverageDowngrade);
                    v["verdict"] = "INCONCLUSIVE";
                    v["headline"] = "Incidence coverage is insufficient for confirmation";
                    v["likely_cause"] = "Telemetry mechanism cannot be established from the available series";
                    v["recommended_action"] = "Retrieve incidence-covering history for the alerting attribute; "
                                            + "inspect only if independently corroborated";
                    v["category"] = "Coverage gap";
                    int confCap;
                    if (!int.TryParse(v["confidence"] == null ? "" : v["confidence"].ToString(), out confCap))
                    {
                        confCap = 0;
                    }
                    if (confCap > _downgradeConfidenceCap)
                    {
                        v["confidence"] = _downgradeConfidenceCap;
                    }
                    // P1: the downgrade reason comes FIRST so TrimWords can never hide it
                    string cav = v["caveats"] == null ? "" : v["caveats"].ToString();
                    v["caveats"] = TrimWords("Incidence coverage not established"
                        + (cav.Length > 0 ? "; " + cav : ""), 20);
                    // -- v1.0.76.0 -- REMOVED: word-matching a few assertive phrases
                    // ("confirmed", "proved", "genuine failure") let lines like "Active
                    // feed-side leakage diverted current from the relay end" survive
                    // unfiltered next to an INCONCLUSIVE verdict. A downgrade now
                    // REPLACES the evidence array outright with controlled factual
                    // lines rather than trying to detect every assertive phrasing.
                    // JArray evA = v["evidence"] as JArray;
                    // if (evA != null)
                    // {
                    //     for (int i = evA.Count - 1; i >= 0; i--)
                    //     {
                    //         string low = evA[i].ToString().ToLowerInvariant();
                    //         if (low.Contains("confirmed") || low.Contains("proved")
                    //             || low.Contains("proven") || low.Contains("genuine failure"))
                    //         {
                    //             evA.RemoveAt(i);   // factual/numeric lines stay; assertions go
                    //         }
                    //     }
                    //     if (evA.Count == 0)
                    //     {
                    //         evA.Add("Series does not reach the incidence with adequate unique samples");
                    //     }
                    // }
                    JArray controlledEv = new JArray();
                    controlledEv.Add("Alerting-attribute history did not provide adequate incidence coverage");
                    controlledEv.Add("Available alert facts remain visible; incidence-covering trend is not verified");
                    controlledEv.Add("Fault mechanism cannot be confirmed from the available trend");
                    controlledEv.Add("Additional incidence-covering history is required");
                    v["evidence"] = controlledEv;
                    // v1.0.76.0: neutralize the TREND-TELLING viz fields on a coverage
                    // downgrade -- a rejected series must not still narrate "confirmed
                    // mechanism" or "recovered" through the chart. value/threshold/
                    // baseline are directly-sourced scalars, not a trend claim, and stay.
                    JObject vizObj = v["viz"] as JObject;
                    if (vizObj != null)
                    {
                        vizObj["series"] = new JArray();
                        vizObj["trigger_pct"] = null;
                        vizObj["recovery_pct"] = null;
                        vizObj["phase_note"] = "Incidence-covering trend is unavailable; "
                                              + "development cannot be established";
                        vizObj["secondary"] = null;
                    }
                }
            }
            // v1.0.160.37: COMPUTED-VERDICT WINS (owner rule). This is the single choke point both final
            // paths pass through. When a PREDICTIVE/ANALOG sustain decision was computed AND coverage did
            // NOT downgrade the verdict, the computed class SETS the verdict deterministically (kills the
            // run-to-run flipping); the model's narration stays, only class + confidence + provenance change.
            // Failure/relay-state alerts never stash a decision, so they are untouched. Coverage-inadequate
            // (coverageDowngrade != null -> already INCONCLUSIVE) is left alone: no sustain trust on a bad series.
            if (_computedVerdictEnabled && _computedVerdict != null && coverageDowngrade == null)
            {
                string _cvCls = _computedVerdict["class"] != null ? _computedVerdict["class"].ToString() : "";
                if (_cvCls == "CONFIRMED" || _cvCls == "NOT_CONFIRMED")
                {
                    string _vNow = v["verdict"] != null ? v["verdict"].ToString() : "";
                    string _cvR = _computedVerdict["reason"] != null ? _computedVerdict["reason"].ToString() : "computed from the FRS sustain window";
                    if (_vNow != _cvCls)
                    {
                        // v1.0.160.77: this branch is the ONLY place that knows the computed class
                        // actually replaced the model's. Comparing strings after the fact would
                        // read "won" whenever the model happened to agree, which is not the same.
                        _computedWonLast = true;
                        AiLog("INFO", "VERDICT", "computed-verdict override " + _vNow + " -> " + _cvCls + " (" + _cvR + ")");
                        v["verdict"] = _cvCls;
                        JToken _cvConf = _computedVerdict["confidence"];
                        if (_cvConf != null) { v["confidence"] = _cvConf; }
                        v["category"] = "Computed verdict";
                        string _cav0 = v["caveats"] == null ? "" : v["caveats"].ToString();
                        v["caveats"] = TrimWords(_cvR + (_cav0.Length > 0 ? "; " + _cav0 : ""), 24);
                    }
                    JArray _cvEvi = v["evidence"] as JArray;
                    if (_cvEvi == null) { _cvEvi = new JArray(); v["evidence"] = _cvEvi; }
                    _cvEvi.Insert(0, "[computed] " + _cvR);
                }
            }

            // v1.0.160.170/.171: a FAILURE alert cannot end INCONCLUSIVE. It fired because a card
            // condition FAILED, and the card is authoritative for the incidence -- so the only valid
            // outcomes are CONFIRMED (genuine) or NOT_CONFIRMED (normal throw / train movement, decided
            // by the DataLogger relay / adjacent-track check). If the verdict still came out INCONCLUSIVE
            // for a FAILURE alert with a card FAIL (track, point OR signal), resolve it to CONFIRMED and
            // say in the UI remark that INCONCLUSIVE is not a valid outcome for a failure. .171 broadened
            // this from the 10 TC track codes to ALL failure alerts.
            if (_cardHasFail && (_isTrackFailureCause || _isFailureAlert))
            {
                string _fv = v["verdict"] != null ? v["verdict"].ToString() : "";
                if (_fv == "INCONCLUSIVE")
                {
                    AiLog("INFO", "VERDICT", "failure INCONCLUSIVE forbidden -> CONFIRMED (card FAIL authoritative)");
                    string _remark = "A FAILURE alert cannot be INCONCLUSIVE: the card condition FAILED and the card is authoritative for the incidence. Resolved to CONFIRMED (a normal throw / train movement would read NOT_CONFIRMED via the DataLogger relay / adjacent-track check).";
                    v["verdict"] = "CONFIRMED";
                    v["category"] = _isTrackFailureCause ? "Track failure" : "Field HW";
                    v["headline"] = "Failure confirmed (card condition failed at the incidence)";
                    v["remark"] = _remark;
                    int _fc;
                    if (!int.TryParse(v["confidence"] == null ? "" : v["confidence"].ToString(), out _fc) || _fc < 70)
                    { v["confidence"] = 70; }
                    string _fcav = v["caveats"] == null ? "" : v["caveats"].ToString();
                    v["caveats"] = TrimWords(_remark + (_fcav.Length > 0 ? "; " + _fcav : ""), 34);
                    JArray _fev = new JArray();
                    _fev.Add("Card condition FAILED at the incidence -> the failure is established (card authoritative)");
                    _fev.Add("INCONCLUSIVE is not a valid outcome for a FAILURE alert");
                    _fev.Add("A normal throw / train movement would show as NOT_CONFIRMED via DataLogger relay / adjacent-track");
                    v["evidence"] = _fev;
                }
            }

            return true;
        }

        // v1.0.75.0 enforcement policy (D4/D5 -- Review rev D)
        private static readonly bool _strictCoverage =
            ReadInt("AnalyzeStrictCoverage", 0) != 0;   // 0=scoped (default), 1=strict
        private static readonly int _downgradeConfidenceCap =
            ClampCfg(ReadInt("AnalyzeDowngradeConfidenceCap", 40), 0, 100);

        private string _jsonRequestId;

        // Outermost balanced { ... } in a string, quote-aware and escape-aware.
        // v1.0.137.0: when a verdict is rejected (parse or validation), preserve WHAT the
        // model actually said -- single line, secret-redacted, clamped -- so provider
        // A/B failures are diagnosable from ai-log instead of being discarded.
        private void LogRejectedReply(string fullText)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(fullText)) { AiLog("WARN", "VERDICT", "rejected reply: <empty>"); return; }
                string oneLine = fullText.Replace("\r", " ").Replace("\n", " ");
                AiLog("WARN", "VERDICT", "rejected reply (first 1500 chars): " + ClampLen(RedactSecretText(oneLine), 1500));
            }
            catch { }
        }

        private static JObject ExtractFirstJsonObject(string text)
        {
            if (string.IsNullOrEmpty(text)) { return null; }
            int start = text.IndexOf('{');
            if (start < 0) { return null; }
            int depth = 0; bool inStr = false; bool esc = false;
            for (int i = start; i < text.Length; i++)
            {
                char c = text[i];
                if (esc) { esc = false; continue; }
                if (c == '\\' && inStr) { esc = true; continue; }
                if (c == '"') { inStr = !inStr; continue; }
                if (inStr) { continue; }
                if (c == '{') { depth++; }
                else if (c == '}')
                {
                    depth--;
                    if (depth == 0)
                    {
                        try { return JObject.Parse(text.Substring(start, i - start + 1)); }
                        catch { return null; }
                    }
                }
            }
            return null;
        }

        private static string GetCtx(JObject o, string key)
        {
            JToken t = o[key];
            if (t == null || t.Type == JTokenType.Null)
            {
                return "";
            }
            return t.ToString();
        }

        // Alert time arrives as "HH:mm:ss/dd.MM.yyyy" (alert card) or
        // "dd/MM/yyyy HH:mm:ss" (board row); the MCP history tools expect
        // ddMMyyyy_HHmmss. That conversion is a step the model gets wrong --
        // and a wrong window returns an empty series, which the grounding gate
        // then correctly rejects as ungrounded. So compute it here and hand the
        // exact strings over.
        private static bool TryParseAlertTime(string s, out DateTime dt)
        {
            dt = DateTime.MinValue;
            if (string.IsNullOrWhiteSpace(s)) { return false; }
            string t = s.Trim();
            string[] fmts = {
                "HH:mm:ss/dd.MM.yyyy", "H:m:s/d.M.yyyy",
                "dd/MM/yyyy HH:mm:ss", "d/M/yyyy H:m:s",
                "dd.MM.yyyy HH:mm:ss", "yyyy-MM-ddTHH:mm:ss", "yyyy-MM-dd HH:mm:ss"
            };
            if (DateTime.TryParseExact(t, fmts,
                    System.Globalization.CultureInfo.InvariantCulture,
                    System.Globalization.DateTimeStyles.None, out dt)) { return true; }
            return DateTime.TryParse(t,
                    System.Globalization.CultureInfo.InvariantCulture,
                    System.Globalization.DateTimeStyles.None, out dt);
        }

        // The alert record carries the numeric ids; the board could not have rendered
        // the row otherwise. Presenting them removes the resolution chain entirely.
        // It cannot succeed anyway: the station is a site CODE ("SK") and search_sites
        // matches the site NAME ("SAKHUN"), and without a SiteId an asset-name search
        // is ambiguous because names repeat across stations.
        // ==================================================================
        // PRE-FETCH ENGINE
        // Phase 1 runs the independent lookups together; phase 2 needs a TagId
        // from phase 1, so it follows. Anything that fails is simply omitted --
        // pre-fetch NEVER blocks the analysis, it only saves turns.
        // ==================================================================
        private async Task<string> PrefetchEvidenceAsync(JObject ctx, ToolLoadResult loaded, System.Threading.CancellationToken ct)
        {
            // v1.0.160.110 SL5: WALL-CLOCK for the whole prefetch phase. Distinct from
            // toolCallMsSum, which sums concurrent calls and can legitimately exceed this.
            var _swPrefetchPhase = System.Diagnostics.Stopwatch.StartNew();
            try
            {
            // v1.0.160.110 SL7: fill station/assetType from the alert card before anything reads
            // them. They were empty in the payload while alertCard carried stationName/stationCode
            // and the alert row carried AssetType -- and the FOLLOW-UP chat reuses this same ctx,
            // where there is no card to fall back on.
            EnrichContextGrounding(ctx);
            string assetId = GetCtx(ctx, "assetId");
            string siteId = GetCtx(ctx, "siteId");
            if (assetId.Length == 0) { AiLog("INFO", "PREFETCH", "no assetId in context -- skipped"); return null; }

            // narrowing needs the AssetId BEFORE any tool arg has supplied it
            if (_jsonAssetHints == null) { _jsonAssetHints = new HashSet<string>(StringComparer.OrdinalIgnoreCase); }
            if (_prefetchDone == null) { _prefetchDone = new HashSet<string>(StringComparer.OrdinalIgnoreCase); }
            _jsonAssetHints.Add(assetId);
            _prefetchAssetId = assetId;   // v1.0.160.166: the scope of every one-shot denial

            System.Diagnostics.Stopwatch sw = System.Diagnostics.Stopwatch.StartNew();
            bool gotTags = false, gotRange = false, gotTagIds = false, gotPred = false;

            bool gotAudit = false, gotAlerts = false;
            string histWhy = null;
            StringBuilder ev = new StringBuilder();
            ev.Append("=== PRE-FETCHED EVIDENCE ===").Append("\n");
            ev.Append("These steps are ALREADY DONE. The results are below. Do NOT repeat them - ");
            ev.Append("re-running a lookup whose answer is already here wastes a full turn and ");
            // -- v1.0.75.0 -- was: "Where a section says MISSING, that is the only
            // thing worth a tool call." -- contradicted the RETRY REQUIRED status.
            ev.Append("returns the same bytes. Where a section says MISSING or RETRY REQUIRED, ");
            ev.Append("those are the only things worth a tool call.").Append("\n\n");

            // v1.0.160.169 (BUG-3a/4 + 3b): pin the incidence-value verdict anchor at the TOP of the
            // evidence so the model judges the moment the value BREACHED, not the moment it recovered.
            ev.Append(BuildVerdictAnchor(ctx));
            ev.Append(BuildPmVerdictAnchor(ctx));   // v1.0.160.171: PM common-condition (4 steps)
            ev.Append(BuildRawMessageAnchor(ctx));   // v1.0.160.173: cardless / rawMessage alerts

            // v1.0.95.0: for a cause code that maps to MULTIPLE attributes, list the FULL
            // related set so the model checks coherence across all of them, not just the
            // anchor. Owner-confirmed: all mapped attributes matter (e.g. TC RAIL RES OPEN ->
            // Ir mA + If mA + RRAIL must be read together; TC BALST/SLPR RES LOW -> Ir + IBALST).
            // The anchor tag (attrs[0]) still drives the primary history fetch; this note tells
            // the model the coherence set to weigh alongside it.
            {
                string cc2 = GetCtx(ctx, "causeCode");
                if (!string.IsNullOrEmpty(cc2))
                {
                    string[] relAttrs;
                    if (RdpmsMaps.CauseToAttributes.TryGetValue(cc2.Trim(), out relAttrs)
                        && relAttrs != null && relAttrs.Length > 1)
                    {
                        ev.Append("RELATED ATTRIBUTES for this cause code (check coherence across those that have ");
                        ev.Append("timestamp-aligned values): ").Append(string.Join(", ", relAttrs));
                        ev.Append(". Evaluate coherence ONLY for related attributes that have incidence-aligned values ");
                        ev.Append("in the alert card, fault audit, or history evidence below. Missing related history is a ");
                        ev.Append("LIMITATION, not evidence that those attributes failed to move - do NOT use current or ");
                        ev.Append("untimestamped values to contradict an incidence-time trend on the alerting attribute. If the ");
                        ev.Append("anchor's aligned history settles the condition AND the alert's conditionLogic permits it, ");
                        ev.Append("a binary verdict is allowed - for AND logic every required branch must support CONFIRMED, ");
                        ev.Append("for OR logic one breached branch may support CONFIRMED; lower confidence and note in caveats ");
                        ev.Append("each required related condition left uncorroborated.").Append("\n\n");
                    }
                }
            }

            // ---- phase 1: independent lookups, in parallel ----
            Task<string> tagsT = PrefetchCallAsync("get_asset_tags",
                NewArgs("AssetId", assetId), loaded, ct);
            // v1.0.160.6: AssetId-scope get_attribute_range (see note at the plan builder) so the
            // baseline arrives complete (~3KB) instead of site-scoped-and-truncated (~266KB->12KB).
            JObject arArgs2 = NewArgs("SiteId", siteId);
            if (!string.IsNullOrWhiteSpace(assetId)) { arArgs2["AssetId"] = assetId; }
            Task<string> rangeT = siteId.Length > 0
                ? PrefetchCallAsync("get_attribute_range", arArgs2, loaded, ct)
                : null;
            // get_asset_tags returns AssetAttributeId and CURRENT VALUES but NO TagID.
            // history_get requires a TagId, and search_tags is the only tool that
            // returns one. So this call is not optional -- without it there is no
            // series, which is why the model kept calling search_tags no matter what
            // the prompt said.
            string assetName = GetCtx(ctx, "assetName");
            Task<string> stagsT = assetName.Length > 0
                ? PrefetchCallAsync("search_tags", LogDriverSet(NewSearchArgs(assetName, siteId, ctx, IsDerivedCard(ctx)), ctx), loaded, ct)
                : null;
            // IMPORTANT DISTINCTION: the prediction APIs are keyed by ASSET
            // (SiteId + AssetId), while EdgeX history is keyed by TAG. So the ML
            // analyses need nothing we do not already have from the alert record --
            // no tag resolution, no matching, no dependency on search_tags. Fetch
            // them here, in parallel, and they cost the model zero turns.
            string predTool = PredictToolFor(GetCtx(ctx, "causeCode"));
            Task<string> predT = (predTool != null && siteId.Length > 0)
                ? PrefetchCallAsync(predTool, NewPredictArgs(predTool, siteId, assetId), loaded, ct)
                : null;

            // These two cost the model a full turn each and need nothing it has to
            // discover: analyse_alert takes the station CODE and the alert facts
            // verbatim, get_frs_alerts takes the SiteId. Measured: fetching them
            // late cost 13.2s of model time across three extra turns.
            DateTime incT;
            bool haveInc = TryParseAlertTime(GetCtx(ctx, "time"), out incT);
            // v1.0.160.13: analyse_alert (srv2 FRS tool) DROPPED as an evidence source. Its only
            // unique output was cause_code_def (the FRS pass/fail rule); that rule is now embedded
            // locally in CauseLogicMaps.CauseToLogic and injected below - no srv2 round-trip, and the
            // cause-name-mismatch class that made analyse_alert miss 9 of 11 PM causes cannot occur.
            // (get_frs_alerts + get_hist_realtime remain on srv2 and are unaffected.)
            Task<string> alertsT = (siteId.Length > 0 && haveInc)
                ? PrefetchCallAsync("get_frs_alerts", NewSiteAlertArgs(siteId, incT), loaded, ct)
                : null;
            // v1.0.160.154 Layer A: the asset's OWN alert history, fetched in parallel. The +/-2h
            // call above answers "what else fired around this asset"; this answers "is this asset
            // a repeat offender". OFF by default (AssetAlertHistoryEnabled).
            Task<string> ahistT = (_assetHistEnabled && siteId.Length > 0 && assetId.Length > 0 && haveInc)
                ? PrefetchCallAsync("get_frs_alerts", NewAssetHistoryArgs(siteId, assetId, incT, _assetHistDays), loaded, ct)
                : null;
            // v1.0.117.0: get_attribute_range_history - asset-scoped historical AVG trend over the
            // evidence window PLUS the site geo/topology (lat/long/familyTracks/signalTrack). This
            // is the source of the site lat/long the controller-side weather fetch needs, and gives
            // the model a historical trend to complement get_attribute_range (LIVE/current normal)
            // and history_get (precise timestamped samples). Asset + ddMMyyyy_HHmmss window.
            Task<string> rangeHistT = (assetId.Length > 0 && haveInc)
                ? PrefetchCallAsync("get_attribute_range_history", NewRangeHistoryArgs(assetId, incT), loaded, ct)
                : null;

            string tags = await SafeAwait(tagsT).ConfigureAwait(false);
            // v1.0.160.112 SL17: the snapshot describes NOW, not the alert. Stamp it so nothing
            // downstream can read it as an at-incidence reading.
            if (!string.IsNullOrEmpty(tags))
            {
                _snapshotRetrievedAt = DateTime.Now;
                _snapshotValues = ParseSnapshotValues(tags);
            }
            string range = DropE7ApiFailure(rangeT != null ? await SafeAwait(rangeT).ConfigureAwait(false) : null, "get_attribute_range");
            // v1.0.160.135: fold AverageValue / MinFailValue into the snapshot now that the range
            // result exists. Kept as a separate pass rather than reordering the awaits -- the
            // prefetch is concurrent and moving an await to suit a display field would serialise it.
            MergeRangeIntoSnapshot(range);
            // v1.0.160.198: op V/C tags read 0 in get_asset_tags (the snapshot source); overwrite them
            // with the last-operation average from the live tag table so the FIRST render matches Refresh.
            // No-op for non-point assets (PmOpChannelForName returns 0 for every row) and on any fetch miss.
            {
                int _pmAid;
                if (!string.IsNullOrEmpty(assetId) && int.TryParse(assetId, out _pmAid)) { MergePmAvgIntoSnapshot(_pmAid); }
            }
            string stags = stagsT != null ? await SafeAwait(stagsT).ConfigureAwait(false) : null;
            string pred = DropE7ApiFailure(predT != null ? await SafeAwait(predT).ConfigureAwait(false) : null, predTool != null ? predTool : "predict");
            // v1.0.160.112 SL12: keep the RAW ML result for controller-side promotion. The model is
            // never asked to elevate it -- that is what left a Critical finding at the bottom of
            // caveats on 543194.
            _predictRaw = pred;
            string alerts = DropE7ApiFailure(alertsT != null ? await SafeAwait(alertsT).ConfigureAwait(false) : null, "get_frs_alerts");
            // v1.0.160.150: state what the prefetch actually GOT. A run where get_attribute_range
            // and get_frs_alerts return nothing looks, downstream, exactly like a code regression:
            // no envelopes ("configured envelope unavailable"), no average markers, no assetType and
            // no resetTime -- so the panel says "Still active" on a cleared alert. Those are four
            // visible symptoms of one upstream fact, and nothing logged the fact.
            AiLog((string.IsNullOrEmpty(range) || string.IsNullOrEmpty(alerts)) ? "WARN" : "INFO", "PREFETCH",
                "inputs: tags=" + (tags == null ? 0 : tags.Length)
                + "B range=" + (range == null ? 0 : range.Length)
                + "B alerts=" + (alerts == null ? 0 : alerts.Length) + "B"
                + ((string.IsNullOrEmpty(range) || string.IsNullOrEmpty(alerts))
                   ? " -- MISSING INPUT: envelopes, averages, assetType and resetTime all depend on these"
                   : ""));
            // v1.0.160.123 SL5: alertCard has no assetType; the FRS row does. Fill it here, still
            // fill-only-when-empty, and only from the row whose Id matches THIS alert -- a
            // neighbouring alert on another asset would otherwise supply the wrong type.
            if (!string.IsNullOrEmpty(alerts) && GetCtx(ctx, "assetType").Length == 0)
            {
                try
                {
                    string wantId = GetCtx(ctx, "alertId");
                    JObject ao = JObject.Parse(alerts);
                    JArray rows = ao["mFRSAlerts"] as JArray;
                    if (rows != null && wantId.Length > 0)
                    {
                        for (int ri = 0; ri < rows.Count; ri++)
                        {
                            JObject r = rows[ri] as JObject;
                            if (r == null || r["Id"] == null) { continue; }
                            if (!string.Equals(r["Id"].ToString(), wantId, StringComparison.Ordinal)) { continue; }
                            JToken at = r["AssetType"];
                            if (at != null && at.ToString().Trim().Length > 0)
                            {
                                ctx["assetType"] = at.ToString().Trim();
                                AiLog("INFO", "CTX", "assetType filled from the FRS alert row: " + ctx["assetType"]);
                            }
                            // v1.0.160.130: and the RESET. The client had two optional sources for
                            // this and could end up with neither, announcing "Still active" on an
                            // alert the same page showed as cleared. This row is authoritative.
                            JToken rt = r["ResetTimeStamp"];
                            if (rt != null && rt.Type != JTokenType.Null && GetCtx(ctx, "resetTime").Length == 0)
                            {
                                DateTime rtd;
                                if (DateTime.TryParse(rt.ToString(), System.Globalization.CultureInfo.InvariantCulture,
                                        System.Globalization.DateTimeStyles.None, out rtd))
                                {
                                    ctx["resetTime"] = rtd.ToString("dd/MM/yyyy HH:mm:ss");
                                    AiLog("INFO", "CTX", "resetTime filled from the FRS alert row: " + ctx["resetTime"]);
                                }
                            }
                            break;
                        }
                    }
                }
                catch { }
            }
            string rangeHist = DropE7ApiFailure(rangeHistT != null ? await SafeAwait(rangeHistT).ConfigureAwait(false) : null, "get_attribute_range_history");
            // v1.0.160.154 Layer A: reduce the asset history to a compact summary -- never the raw
            // rows -- and speak it as ground truth. Failure (incl. an E7-API 403 via
            // DropE7ApiFailure) just leaves the chapter absent; this is context, not a required
            // input, so it never degrades the verdict on its own.
            string ahist = DropE7ApiFailure(ahistT != null ? await SafeAwait(ahistT).ConfigureAwait(false) : null, "get_frs_alerts(asset-history)");
            // v1.0.160.155: when the flag is ON, this block always speaks -- summary on success,
            // WARN with the head of the result otherwise. .154's silent null is how a schema
            // rejection ("SiteIds (int array) is required.") hid for a whole deploy cycle.
            if (_assetHistEnabled)
            {
                if (!string.IsNullOrEmpty(ahist) && LooksUsableToolResult(ahist, false))
                {
                    _assetHistory = BuildAssetHistory(ahist, GetCtx(ctx, "alertId"), GetCtx(ctx, "causeCode"), _assetHistDays);
                }
                if (_assetHistory != null)
                {
                    ev.Append(FormatAssetHistoryEvidence(_assetHistory)).Append("\n\n");
                    AiLog("INFO", "PREFETCH", "asset-history: total=" + _assetHistory["total"]
                        + " sameCause=" + _assetHistory["sameCause"]
                        + " causes=" + (((JObject)_assetHistory["byCause"]) != null ? ((JObject)_assetHistory["byCause"]).Count : 0)
                        + " over " + _assetHistDays + "d");
                    // v1.0.160.162: now that Layer A has landed, refresh the greeting WITH the
                    // synopsis line. The client replaces the header text in place.
                    if (_greetingEnabled)
                    {
                        try
                        {
                            string g2 = BuildGreeting(ctx, true);
                            if (!string.IsNullOrEmpty(g2)) { WriteSse("greeting", new { text = g2 }); }
                        }
                        catch { }
                    }
                }
                else
                {
                    string ahHead = ahist == null ? "(no result -- task not started or E7-API failure already warned)" : ahist.Trim();
                    if (ahHead.Length > 120)
                    {
                        ahHead = ahHead.Substring(0, 120);
                    }
                    AiLog("WARN", "PREFETCH", "asset-history: enabled but nothing usable -- " + ahHead);
                }
            }

            if (!string.IsNullOrEmpty(tags) && LooksUsableToolResult(tags, false))
            {
                gotTags = true; MarkPrefetched("get_asset_tags");
                // v1.0.160.72: no longer points at history_get(AssetId) -- see the note above.
                ev.Append("[ASSET TAGS - attribute names, AssetAttributeId and current values (NO TagID; get TagIDs from search_tags, then one history_get per TagId -- never history_get(AssetId))]").Append("\n");
                // v1.0.160.110: strip the bulky -Array waveform CurrentValues (attid 1001/2001/... on a
                // point machine) from the MODEL PROMPT only, so the relay-state row is not pushed off the
                // 4000-char budget. StripTagWaveforms returns a COPY -- `tags` is untouched, so the raw
                // waveform stays available to the chart and predict_pm_operation. search_tags already
                // gets this treatment.
                ev.Append(TrimForPrompt(StripTagWaveforms(tags), 4000)).Append("\n\n");
            }

            // v1.0.152.5 (P0): FORCE-FETCH the digital TPR STATE history for TRACK assets so the
            // deterministic train mask has data. Moved OUTSIDE the get_asset_tags-usable block --
            // the TPR TagID comes from search_tags, so this must run even if get_asset_tags failed.
            // Best-effort: failure just leaves the mask "unavailable", never blocks the verdict.
            try
            {
                string atc = (GetCtx(ctx, "assetType") ?? "").ToUpperInvariant();
                string ccc = (GetCtx(ctx, "causeCode") ?? "").ToUpperInvariant();
                bool trackAsset = atc.Contains("TRACK") || ccc.StartsWith("TC ") || ccc.Contains("RAIL RES");
                if (trackAsset && haveInc)
                {
                    // get_asset_tags carries NO TagID -- resolve TPR from search_tags. Try EXACT
                    // digital-state names first (v1.0.152.5): a broad Contains("TPR") can otherwise
                    // grab the analog "TPR V". stags is already unfiltered for derived/track cards;
                    // fall back to a fresh unfiltered AssetId search_tags for a narrowed direct case.
                    string tprSrc = stags;
                    string tprTag = ResolveTprTag(tprSrc, assetId, false);   // v1.0.152.7: stags is name-scoped -> fail-closed
                    if (tprTag == null && assetId.Length > 0)
                    {
                        JObject tprSearchArgs = NewArgs("AssetId", assetId); tprSearchArgs["Limit"] = 50;   // v1.0.152.6: search_tags defaults to 3 rows -- ask for the asset's full set (server cap 50)
                        string tprAll = await SafeAwait(PrefetchCallAsync("search_tags", tprSearchArgs, loaded, ct)).ConfigureAwait(false);
                        tprTag = ResolveTprTag(tprAll, assetId, true);   // v1.0.152.7: AssetId-scoped fallback -> a row missing AssetId is acceptable
                    }
                    if (tprTag != null)
                    {
                        RegisterTagMeta(tprTag, "TPR", true, false);   // the mask needs this identity
                        // v1.0.152.5: history API caps at 500 regardless; digital state records only
                        // CHANGES, so 500 changes span a long window.
                        JObject tprArgs = HistWindowArgs("TagId", tprTag,
                            incT.AddDays(-_evidenceWindowDays), incT.AddHours(2),
                            _limitCapEvidence, "columnar");
                        string tprHist = await HistFetchAsync(tprArgs, loaded, ct).ConfigureAwait(false);
                        // v1.0.160.120 SL1: force-fetch BOTH currents on a track asset. K2 needs feed
                        // AND relay; before this it got whatever the alert's own formula happened to
                        // pull, so IR MA reached the harvest ONCE in 135 runs and K2 skipped 90% of
                        // the time. HistFetchAsync dedupes, so a series the formula already fetched
                        // costs nothing here.
                        string[] k2Names = new string[] { "If mA", "Ir mA" };
                        for (int ki = 0; ki < k2Names.Length; ki++)
                        {
                            string k2Tag = TagIdForAttributeNameExactForAsset(tprSrc, k2Names[ki], assetId, true);
                            if (string.IsNullOrEmpty(k2Tag)) { continue; }
                            RegisterTagMeta(k2Tag, k2Names[ki], false, false);
                            JObject k2Args = HistWindowArgs("TagId", k2Tag,
                                incT.AddDays(-_evidenceWindowDays), incT.AddHours(2),
                                _limitCapEvidence, "columnar");
                            string k2Hist = await HistFetchAsync(k2Args, loaded, ct).ConfigureAwait(false);
                            AiLog("INFO", "CIRCUIT", "K2 input " + k2Names[ki] + " tag=" + k2Tag
                                + " (bytes=" + (k2Hist != null ? k2Hist.Length : 0) + ")");
                        }
                        AiLog("INFO", "TREND", "force-fetched TPR state tag=" + tprTag + " for track mask (bytes=" + (tprHist != null ? tprHist.Length : 0) + ")");
                        // v1.0.160.108: surface the force-fetched digital TPR STATE series into the model
                        // evidence (previously it fed only the train mask, so the model reported "No
                        // fetched TPR datalogger" and softened a card-confirmed relay-state FAILURE to
                        // INCONCLUSIVE). Labelled + authoritative for relay-state FAILUREs.
                        if (!string.IsNullOrEmpty(tprHist) && LooksUsableToolResult(tprHist, IsEvidenceTool("history_get")))
                        {
                            MarkPrefetched("history_get");
                            ev.Append("[DIGITAL TPR STATE (DataLogger, attid 6) history around incidence - 0=DROP/occupied, 1=PICK/clear. AUTHORITATIVE relay-state series for the event; a validly-fired relay-state FAILURE is CONFIRMED even when the analog partners (Ir/If/TPR V) look healthy.]").Append("\n");
                            ev.Append(TrimForPrompt(tprHist, 2000)).Append("\n\n");
                        }
                    }
                    else { AiLog("INFO", "TREND", "track asset but no TPR digital tag resolved -> mask may be unavailable"); }

                    // v1.0.160.69: fetch history for EVERY resolved DRIVER, not just the alerting tag.
                    // 160.55 stopped NewSearchArgs narrowing the TAG SEARCH, but the history plan was
                    // never extended -- the live trace showed exactly two history_get calls (TPR and
                    // ITC RELAY END) while driverSet already read "IR MA, IF MA". Resolving a driver
                    // set and then not fetching it is why every K2 fix so far changed nothing: the
                    // residual needs If AND Ir series, and If was never requested.
                    try
                    {
                        List<string> drv = DriverSetForCause(ctx);
                        // v1.0.160.80: the canonical name of the FAILING condition -- the attribute the
                        // alerting path will fetch. Derived from the card here because no variable in
                        // this scope holds it (checked; inventing one was the first attempt and it did
                        // not compile).
                        string _alertAttrCanon = FirstFailingParamCanon(ctx);
                        for (int di = 0; di < drv.Count; di++)
                        {
                            string dn = drv[di];
                            if (string.IsNullOrEmpty(dn)) { continue; }
                            // v1.0.160.80: skip the ALERTING attribute -- the alerting-tag fetch below
                            // pulls it anyway, WITH the coverage and truncation checks this loop does
                            // not run. Fetching it here too produced two identical calls per analysis.
                            if (!string.IsNullOrEmpty(_alertAttrCanon)
                                && NormAttrKey(dn) == NormAttrKey(_alertAttrCanon))
                            {
                                AiLog("INFO", "TREND", "driver " + dn + " is the alerting attribute -- left to the alerting path, not duplicated here");
                                continue;
                            }
                            bool have = false;
                            foreach (KeyValuePair<string, List<object[]>> hk in _trendRawByAttr)
                            { if (NormAttrKey(hk.Key) == NormAttrKey(dn)) { have = true; break; } }
                            if (have) { continue; }   // already harvested (unit-suffix aware)
                            string dTag = TagIdForAttributeNameExactForAsset(tprSrc, dn, assetId, true);
                            if (string.IsNullOrEmpty(dTag))
                            {
                                // v1.0.160.186 (#2): IPS drivers (VIPS.../IIPS...) live on the site's
                                // IPS asset (AssetTypeId 39), not the alerting asset, so they resolved
                                // empty and were dropped -- e.g. VIPS DC R EXT on TC TR CONTACT RES HIGH.
                                // Resolve cross-asset when the card carries the term. Card-gated + IPS
                                // asset cached per site => no fan-out. Only this dropped branch changes.
                                if (_ipsCrossAssetEnabled)
                                {
                                    string _du = (dn ?? "").TrimStart().ToUpperInvariant();
                                    if ((_du.StartsWith("VIPS") || _du.StartsWith("IIPS")) && CardMentionsDriver(ctx, dn))
                                    {
                                        try
                                        {
                                            string ipsAssetId = await ResolveIpsAssetIdAsync(GetCtx(ctx, "siteId"), ct).ConfigureAwait(false);
                                            if (!string.IsNullOrEmpty(ipsAssetId))
                                            {
                                                JObject ipsArgs = NewArgs("AssetId", ipsAssetId); ipsArgs["Limit"] = 50;
                                                string ipsTags = await CallToolRoutedAsync("search_tags", ipsArgs, ct).ConfigureAwait(false);
                                                string ipsTag = TagIdForAttributeNameExactForAsset(ipsTags, dn, ipsAssetId, true);
                                                if (!string.IsNullOrEmpty(ipsTag))
                                                {
                                                    RegisterTagMeta(ipsTag, dn, false, false);
                                                    JObject ipsHistArgs = HistWindowArgs("TagId", ipsTag,
                                                        incT.AddDays(-_evidenceWindowDays), incT.AddHours(2),
                                                        _limitCapEvidence, "columnar");
                                                    string ipsHist = await HistFetchAsync(ipsHistArgs, loaded, ct).ConfigureAwait(false);
                                                    AiLog("INFO", "TREND", "IPS cross-asset driver " + dn + " ips=" + ipsAssetId
                                                        + " tag=" + ipsTag + " (bytes=" + (ipsHist != null ? ipsHist.Length : 0) + ")");
                                                }
                                                else { AiLog("INFO", "TREND", "IPS cross-asset driver " + dn + " not found on IPS asset " + ipsAssetId); }
                                            }
                                            else { AiLog("INFO", "TREND", "IPS cross-asset driver " + dn + " -- no IPS asset (type 39) at site"); }
                                        }
                                        catch (Exception ipx) { AiLog("WARN", "TREND", "IPS cross-asset fetch skipped: " + SanitizeJsonError(ipx.Message)); }
                                    }
                                }
                                continue;        // derived names / unresolved non-IPS have no tag
                            }
                            RegisterTagMeta(dTag, dn, false, false);
                            JObject dArgs = HistWindowArgs("TagId", dTag,
                                incT.AddDays(-_evidenceWindowDays), incT.AddHours(2),
                                _limitCapEvidence, "columnar");
                            string dHist = await HistFetchAsync(dArgs, loaded, ct).ConfigureAwait(false);
                            AiLog("INFO", "TREND", "driver history " + dn + " tag=" + dTag
                                + " (bytes=" + (dHist != null ? dHist.Length : 0) + ")");
                        }
                    }
                    catch (Exception dex) { AiLog("WARN", "TREND", "driver history fetch skipped: " + SanitizeJsonError(dex.Message)); }
                }
            }
            catch (Exception exTpr) { AiLog("WARN", "TREND", "TPR force-fetch failed (mask falls back): " + SanitizeJsonError(exTpr.Message)); }

            string panelAssetRange = null;   // v1.0.160.104: retained ASSET-narrowed range (compact rows a/t/min/max/fail) for the envelope lookup
            if (!string.IsNullOrEmpty(range))
            {
                string narrowed = NarrowAttributeRange("get_attribute_range", range);
                panelAssetRange = narrowed;   // v1.0.160.104: use the asset-narrowed range for RangeBoundsForAsset
                if (LooksUsableToolResult(narrowed, IsEvidenceTool("get_attribute_range")))
                {
                    gotRange = true; MarkPrefetched("get_attribute_range");
                    ev.Append("[BASELINE - safe/average/fail limits for this asset]").Append("\n");
                    ev.Append(TrimForPrompt(narrowed, 3000)).Append("\n\n");
                }
            }
            // v1.0.117.0: historical AVG trend + geo for THIS asset (get_attribute_range_history).
            // Complements the LIVE baseline above with a trend over the evidence window; also the
            // source of the site lat/long used for weather (extracted below).
            if (!string.IsNullOrEmpty(rangeHist) && LooksUsableToolResult(rangeHist, IsEvidenceTool("get_attribute_range_history")))
            {
                MarkPrefetched("get_attribute_range_history");
                ev.Append("[HISTORICAL AVG TREND for this asset over the window + site geo/topology - ")
                  .Append("bucketed averages (NOT timestamped samples; use history evidence for exact-time values)]").Append("\n");
                ev.Append(TrimForPrompt(rangeHist, 3500)).Append("\n\n");
            }
            // -- v1.0.80.0 -- DEGRADED baseline fallback. When get_attribute_range
            // returns nothing usable (currently: the MCP server calls the E7 API
            // without Basic auth, so FRSAttributeRange returns a non-JSON auth page),
            // surface the alerting attribute's thresholds that the alert CARD already
            // carries, instead of leaving the model with no baseline and forcing it to
            // waste a turn re-calling the broken tool. Partial by nature (the card has
            // only the triggered attribute's MinSafe + percent-Avg, not MaxSafe/MinFail/
            // true-Average, and only for the one triggered attribute), so it is clearly
            // labelled DEGRADED. Fires ONLY when the tool yielded nothing, so it is
            // inert once the server auth fix lands and get_attribute_range returns JSON.
            if (!gotRange)
            {
                string cardBaseline = BuildCardBaseline(ctx);
                if (!string.IsNullOrEmpty(cardBaseline))
                {
                    gotRange = true;   // baseline now satisfied from the card
                    ev.Append("[BASELINE (DEGRADED - from alert card; get_attribute_range unavailable) - thresholds for the ALERTING attribute only]").Append("\n");
                    ev.Append(cardBaseline).Append("\n\n");
                    AiLog("INFO", "PREFETCH", "baseline from alert card (get_attribute_range unavailable)");
                }
            }

            // v1.0.123.0: POINT OPERATION prefetch. For a TIME cause the owner spec is exactly
            // three tags: the operation-TIME of the alerting END (A/B from the description) + the
            // two proving relays WCR & WKR (they prove the operation happened and completed). For
            // the other operation causes (VOLT/CURR/OBS) the map-based op attids are used. All
            // resolved op attid/relay attid -> TagId via the already-fetched search_tags, then
            // history_get. Detection-relay/indication point causes stay on the DB path. Best-effort.
            if (haveInc && !string.IsNullOrEmpty(stags))
            {
                string causeCode = GetCtx(ctx, "causeCode");
                // v1.0.124.0: unified per-cause tag spec - each entry [attid, alt, label]. Covers
                // ALL point causes (op tags + relays + per-END indication), end resolved from the
                // description. VPT-110/IPT/VIPS-110 params resolve via the existing mapping.
                List<string[]> want = PmTagsForCause(causeCode, PmEndFromAlert(ctx));
                if (want.Count > 0)
                {
                    DateTime pmSdT = incT.AddDays(-_evidenceWindowDays);
                    DateTime pmEdT = incT.AddHours(2);
                    List<Task<string>> opTasks = new List<Task<string>>();
                    List<string> opLabels = new List<string>();
                    for (int i = 0; i < want.Count; i++)
                    {
                        string attid = want[i][0]; string alt = want[i][1]; string label = want[i][2];
                        // resolve by AssetAttributeId; fall back to the alternate attid (e.g. NWCR 282->284)
                        string opTagId = PickTagIdByAttrId(stags, assetId, attid);
                        if (string.IsNullOrEmpty(opTagId) && !string.IsNullOrEmpty(alt))
                        { opTagId = PickTagIdByAttrId(stags, assetId, alt); }
                        if (string.IsNullOrEmpty(opTagId)) { continue; }
                        opTasks.Add(HistFetchAsync(HistWindowArgs("TagId", opTagId, pmSdT, pmEdT, _limitCapEvidence, "columnar"), loaded, ct));
                        // v1.0.160.6: point-machine ranges live under a DIFFERENT (RDPMS) attid than
                        // the operation VALUE attid -- surface the range-attid so the model reads the
                        // Min/MaxSafe from the correct row (value 2002 -> range 216 "A End - NW-V").
                        string rngAttid = PmRangeAttidFor(attid);
                        string rngHint = (!string.Equals(rngAttid, attid, StringComparison.Ordinal))
                            ? (", range attid " + rngAttid) : "";
                        opLabels.Add(label + " [attid " + attid + rngHint + ", TagId " + opTagId + "]");
                    }
                    if (opTasks.Count > 0)
                    {
                        ev.Append("[POINT OPERATION / RELAY / INDICATION history around incidence - the tags this ")
                          .Append("cause needs. For OPERATION-TIME: op-time vs 150% avg - HIGH with the WCR/WKR relays ")
                          .Append("showing a proper operation = mechanical binding/friction; HIGH with abnormal WCR/WKR ")
                          .Append("= operation did not complete cleanly; >6000ms = possible obstruction (WCR proves the ")
                          .Append("throw ran op<=12s, WKR proves it completed <=2s). For CURRENT/VOLTAGE: judge vs the ")
                          .Append("baseline band. For INDICATION/RELAY-DEFECT: check the relay transitions + indication ")
                          .Append("voltage vs Min-Safe. Per-operation data; compare A vs B end to localize. ")
                          .Append("NOTE: a point-machine operation value's Min/MaxSafe RANGE is stored in the FRS range ")
                          .Append("DB under the 'range attid' shown in each tag label (a different RDPMS attid than the ")
                          .Append("value attid) -- read the threshold from that range row, and also use the alert card's ")
                          .Append("configured limit which is authoritative for the specific alert.]").Append("\n");
                        for (int i = 0; i < opTasks.Count; i++)
                        {
                            string series = await SafeAwait(opTasks[i]).ConfigureAwait(false);
                            if (!string.IsNullOrEmpty(series) && LooksUsableToolResult(series, IsEvidenceTool("history_get")))
                            {
                                MarkPrefetched("history_get");
                                ev.Append("[").Append(opLabels[i]).Append("]").Append("\n");
                                ev.Append(TrimForPrompt(series, 2000)).Append("\n\n");
                            }
                        }
                        AiLog("INFO", "PREFETCH", "point operation history prefetched (" + opTasks.Count + " tags: op-time + relays as applicable)");

                        // v1.0.160.133: THE STROKE ITSELF. The block above spans two days so the
                        // model can see the operating band; it cannot show the shape of one throw.
                        // Re-fetch the same tags across the seconds around incidence -- that series
                        // IS the current signature, and no summary contains it.
                        try
                        {
                            DateTime sigSd = incT.AddSeconds(-90);
                            DateTime sigEd = incT.AddSeconds(150);
                            List<Task<string>> sigTasks = new List<Task<string>>();
                            List<string> sigLabels = new List<string>();
                            for (int i = 0; i < want.Count; i++)
                            {
                                string sAttid = want[i][0]; string sAlt = want[i][1]; string sLabel = want[i][2];
                                string sTag = PickTagIdByAttrId(stags, assetId, sAttid);
                                if (string.IsNullOrEmpty(sTag) && !string.IsNullOrEmpty(sAlt))
                                { sTag = PickTagIdByAttrId(stags, assetId, sAlt); }
                                if (string.IsNullOrEmpty(sTag)) { continue; }
                                sigTasks.Add(HistFetchAsync(HistWindowArgs("TagId", sTag, sigSd, sigEd, 500, "columnar"), loaded, ct));
                                sigLabels.Add(sLabel + " [stroke, TagId " + sTag + "]");
                            }
                            if (sigTasks.Count > 0)
                            {
                                StringBuilder sigSb = new StringBuilder();
                                int sigWith = 0;
                                for (int i = 0; i < sigTasks.Count; i++)
                                {
                                    string sSeries = await SafeAwait(sigTasks[i]).ConfigureAwait(false);
                                    if (string.IsNullOrEmpty(sSeries) || !LooksUsableToolResult(sSeries, IsEvidenceTool("history_get"))) { continue; }
                                    MarkPrefetched("history_get");
                                    sigSb.Append("[").Append(sigLabels[i]).Append("]").Append("\n");
                                    sigSb.Append(TrimForPrompt(sSeries, 1500)).Append("\n\n");
                                    sigWith++;
                                }
                                if (sigWith > 0)
                                {
                                    ev.Append("[CURRENT SIGNATURE - the same tags across the SECONDS around the incidence ")
                                      .Append("(-90s to +150s), which is the stroke itself. This is the only block that ")
                                      .Append("contains the SHAPE of the throw: where in the stroke the current peaks, how ")
                                      .Append("long it stays there, and whether it falls away cleanly at cut-off. Read it ")
                                      .Append("as MEASURED evidence and cite it as [fetched]. A high flat plateau through ")
                                      .Append("the stroke is obstruction; a slow rise with a late peak is friction or ")
                                      .Append("creeping; a normal peak that does not drop at the end is a cut-off problem. ")
                                      .Append("Any label from predict_pm_* is a CLASSIFICATION, not a measurement -- if it ")
                                      .Append("disagrees with this series, say so and prefer what was measured. If this ")
                                      .Append("block is absent or empty, say the signature was not captured; do not infer ")
                                      .Append("a stroke shape from averages.]").Append("\n");
                                    ev.Append(sigSb.ToString());
                                    AiLog("INFO", "PREFETCH", "stroke signature prefetched (" + sigWith + " of " + sigTasks.Count + " tags, -90s..+150s)");
                                }
                                else
                                {
                                    AiLog("WARN", "PREFETCH", "stroke signature EMPTY for all " + sigTasks.Count + " tags around incidence");
                                }
                            }
                        }
                        catch (Exception exSig)
                        {
                            AiLog("WARN", "PREFETCH", "stroke signature fetch failed: " + exSig.GetType().Name);
                        }
                        // v1.0.160.22: for a FAIL UNKNOWN cause, the alert generator could not pin a
                        // specific cause -- so the operation values above (110V, current, op-time) are
                        // provided precisely so the model can RECLASSIFY. Tell it to try.
                        if (causeCode != null && causeCode.ToUpperInvariant().Contains("UNKNOWN"))
                        {
                            ev.Append("[UNKNOWN-CAUSE RECLASSIFICATION: this alert is tagged FAIL UNKNOWN -- the generator ")
                              .Append("could not identify the specific cause. Examine the operation values above against the ")
                              .Append("FRS criteria and, if one clearly breaches, NAME the real cause: 110V loc below Min-safe ")
                              .Append("-> PT VOLT/CURR LOW (or FAIL); current abnormal -> PT VOLT/CURR LOW/FAIL; op-time > 150% ")
                              .Append("avg or > 6000ms with proper WCR/WKR -> PT OBS. If none breaches and the relays show a ")
                              .Append("clean operation, UNKNOWN stands. State which cause the evidence actually supports.]").Append("\n\n");
                        }
                        // v1.0.160.8: for point machines the tags above are already resolved by
                        // AssetId+AssetAttributeId (attid) and their history is fetched. Tell the model
                        // NOT to call search_tags by AttributeName -- PM tags are named by NUMBER
                        // ("NNNNN-PM-02002-Avg"), so a human-name search ("RTC VAR RES", "A TPT N",
                        // "ITC RELAY END") returns "No tags found" and wastes a call. Everything it
                        // needs is in the resolved tags + history already provided.
                        ev.Append("[RESOLUTION NOTE: the point-machine tags above are already resolved by ")
                          .Append("AssetId + attid and their history is included. Do NOT call search_tags by ")
                          .Append("AttributeName for this asset -- these tags are named by number, so a name ")
                          .Append("search returns no rows. Use the TagIds already listed; if you need another ")
                          .Append("attribute, request it by its attid, not its human name.]").Append("\n\n");
                    }
                }
            }

            // v1.0.117.0: WEATHER (Option A) - controller fetches it, not the MCP server. The site
            // lat/long comes from the get_attribute_range_history response (top-level latitude/
            // longitude); fetch only for weather-relevant causes and only when we have coordinates
            // + incidence. Best-effort: any failure leaves no weather block, model never mentions it.
            if (_weatherEnabled && haveInc && !string.IsNullOrEmpty(rangeHist)
                && IsWeatherRelevantCause(GetCtx(ctx, "causeCode")))
            {
                double wLat, wLon;
                if (TryExtractLatLon(rangeHist, out wLat, out wLon))
                {
                    string weather = await SafeAwait(FetchWeatherAsync(wLat, wLon, incT, ct)).ConfigureAwait(false);
                    if (!string.IsNullOrEmpty(weather))
                    {
                        ev.Append("[WEATHER at the site around incidence - CORROBORATIVE. rain=true supports ")
                          .Append("ballast/leakage/drainage; thunderstorm=true supports surge/multi-asset. Absence ")
                          .Append("of rain does NOT clear a fault.]").Append("\n");
                        ev.Append(weather).Append("\n\n");
                        // v1.0.119.0: also keep a card-shaped weather object so the verdict's WEATHER
                        // tile renders the real data (the card reads v.weather {condition,tempC,summary}).
                        // Attached to the verdict server-side (weather is a server-only key).
                        _weatherCard = BuildWeatherCard(weather);
                        AiLog("INFO", "PREFETCH", "weather injected (controller-side, Option A)");
                    }
                }
            }

            // v1.0.160.33: TRAIN-CONTEXT -- scheduled trains through the alert STATION around the alert
            // time. Direct HTTP to a public timetable, parsed controller-side. Best-effort: any failure
            // (egress/timeout/parse) leaves no train_context and never touches the verdict. SCHEDULED,
            // not confirmed passage. Gated OFF by default (TrainContextEnabled).
            // v1.0.160.134: say which exit was taken, always.
            if (!_trainCtxEnabled)
            {
                AiLog("INFO", "PREFETCH", "train-context OFF (TrainContextEnabled is false)");
            }
            else if (!haveInc)
            {
                AiLog("INFO", "PREFETCH", "train-context skipped: incidence time unresolved");
            }
            if (_trainCtxEnabled && haveInc)
            {
                string stn = ResolveStationCode(ctx, rangeHist);   // v1.0.160.46
                if (string.IsNullOrEmpty(stn)) { AiLog("INFO", "PREFETCH", "train-context skipped: no station code in ctx or range-history"); }
                if (!string.IsNullOrEmpty(stn))
                {
                    string trHtml = await SafeAwait(FetchStationTrainsAsync(stn, ct)).ConfigureAwait(false);
                    if (string.IsNullOrEmpty(trHtml))
                    {
                        // The most likely cause in production is egress: this is a direct call to a
                        // public timetable from the app server. Name it so nobody has to guess.
                        AiLog("WARN", "PREFETCH", "train-context: no page returned for station " + stn
                            + " (timeout, egress blocked, or site unreachable) -- base "
                            + Trunc(_trainCtxBaseUrl, 60));
                    }
                    if (!string.IsNullOrEmpty(trHtml))
                    {
                        JObject tcx = BuildTrainContext(trHtml, stn.Trim().ToUpperInvariant(), incT);
                        if (tcx != null) { _trainContext = tcx; AiLog("INFO", "PREFETCH", "train-context injected (controller-side, totaltraininfo)"); }
                        else { AiLog("WARN", "PREFETCH", "train-context: station " + stn + " page fetched (" + trHtml.Length + " chars) but no trains parsed"); }
                    }
                }
            }

            // v1.0.160.13: FRS cause rule from the embedded RDPMS master (CauseLogicMaps.CauseToLogic),
            // replacing the srv2 analyse_alert fault audit. Keyed by the exact master cause name, so a
            // direct lookup hits for every authored cause. Thresholds (Min-safe/Min-fail/%avg) are
            // resolved by the model from the range evidence already gathered above.
            // v1.0.160.50 PHASE 2: the K2 discriminator, as one [circuit] evidence line.
            string _circRes = BuildCircuitResidualLine();
            if (!string.IsNullOrEmpty(_circRes))
            {
                ev.Append("[CIRCUIT INVARIANT - which side of the circuit actually moved. Corroboration only: it never overturns a card-confirmed breach]").Append("\n");
                ev.Append(_circRes).Append("\n\n");
                AiLog("INFO", "PREFETCH", "circuit residual injected: " + Trunc(_circRes, 160));
            }

            string frsRule;
            if (CauseLogicMaps.CauseToLogic.TryGetValue((GetCtx(ctx, "causeCode") ?? "").Trim(), out frsRule)
                && !string.IsNullOrEmpty(frsRule))
            {
                ev.Append("[FRS CAUSE RULE - authoritative pass/fail logic for this cause (RDSO/SPN/257/2025, RDPMS master)]").Append("\n");
                ev.Append(frsRule).Append("\n");
                ev.Append("Threshold resolution: use avg x LD% when an average is present in the range; otherwise fall back to MinSafe (predictive) / MinFail (failure).").Append("\n\n");
                gotAudit = true; MarkPrefetched("analyse_alert");
            }

            // v1.0.160.14: for a cause whose FRS rule tests a DERIVED attribute (a resistance or
            // difference), inject how that value is computed from the base TPR-gated sensors. The
            // derived attribute has no sensor of its own; its components are already on srv1, so the
            // value can be computed from the component readings gathered above (deterministic math,
            // no telemetry tag needed). Covers the 15 TRACK derived causes (RRAIL, RTC VAR RES, etc.).
            int derivedAttid;
            if (CauseLogicMaps.CauseToDerived.TryGetValue((GetCtx(ctx, "causeCode") ?? "").Trim(), out derivedAttid))
            {
                string dFormula;
                if (CauseLogicMaps.DerivedFormula.TryGetValue(derivedAttid, out dFormula) && !string.IsNullOrEmpty(dFormula))
                {
                    ev.Append("[DERIVED VALUE - this cause tests a COMPUTED attribute; compute it from the component sensor averages, then compare to the FRS range]").Append("\n");
                    ev.Append(dFormula).Append("\n");
                    ev.Append("Base sensors: If = If mA, Ir = Ir mA, Vf, Vr, Choke = Choke V, ChgMa = Charger mA, ChgOpV = Charger OP V (all TPR-gated averages).").Append("\n\n");
                }
            }

            if (!string.IsNullOrEmpty(alerts) && LooksUsableToolResult(alerts, IsEvidenceTool("get_frs_alerts")))
            {
                ev.Append("[SITE ALERTS around the incidence - use for multi-asset correlation]").Append("\n");
                ev.Append(TrimForPrompt(alerts, 5000)).Append("\n\n");
                gotAlerts = true; MarkPrefetched("get_frs_alerts");
                // v1.0.111.0: keep the raw alert history + this alert's identity so triage can be
                // computed SERVER-SIDE (same AssetId + same cause code, count, direction) rather
                // than trusting the model to decide maintenance priority.
                _triageAlertsRaw = alerts;
                _triageAssetId = GetCtx(ctx, "assetId");
                _triageCauseCode = GetCtx(ctx, "causeCode");
                _triageCurrentAlertId = GetCtx(ctx, "alertId");
            }

            if (!string.IsNullOrEmpty(pred) && LooksUsableToolResult(pred, false))
            {
                ev.Append("[ASSET-LEVEL ML ANALYSIS - ").Append(predTool).Append("]").Append("\n");
                ev.Append(TrimForPrompt(pred, 4000)).Append("\n\n");
                gotPred = true; MarkPrefetched(predTool);
            }

            // ---- phase 2: the value series, which needs a TagId from phase 1 ----
            // -- v1.0.78.0 -- match FIRST, then decide whether the search_tags payload
            // is even about this asset. search_tags can return OTHER assets' tags
            // (point machines etc.); appending that misleads the model even when the
            // AssetId fallback later grounds the right history. Gate the append on
            // (matcher resolved) OR (result has rows for this AssetId).
            // -- v1.0.82.0 rev J -- detect a DERIVED alerting attribute up front.
            {
                string dP; string dF;
                _derivedAlert = DetectDerived(ctx, out dP, out dF);
                _derivedParam = dP;
                // v1.0.160.111 (BUG-5): capture the two coverage-gate bypass signals while ctx is live.
                _cardHasFail = CardHasFailCondition(ctx);
                _isFailureAlert = (GetCtx(ctx, "alertType") ?? "").Trim().ToUpperInvariant().StartsWith("F");
                _isTrackFailureCause = IsTrackFailureCauseCode(GetCtx(ctx, "causeCode"));   // v1.0.160.170
                string _rmA, _rmV, _rmD; bool _rmU;   // v1.0.160.173
                _rawHasBreach = RawMessageBreach(ctx, out _rmA, out _rmV, out _rmD, out _rmU);
                if (_derivedAlert)
                {
                    AiLog("INFO", "PREFETCH", "alerting attribute is DERIVED ('" + (dP ?? "?")
                        + "'); grounding via formula components");
                }
            }
            string tagId = _derivedAlert ? null : PickAlertingTagId(stags, ctx, assetId);
            // v1.0.152.5 (P0): register the DIRECT alerting tag as the trigger BEFORE its history is
            // fetched -- prefetch history_get carries only a TagId, so without this the trigger series
            // stays anonymous and TprCoversTrigger can never find it (mask stuck partial).
            if (!_derivedAlert && !string.IsNullOrEmpty(tagId))
            {
                string trigAttrName = null;
                try { JToken _c = ctx["alertCard"]; JToken _tcx = _c != null ? _c["triggeredConditions"] : null; if (_tcx is JArray && ((JArray)_tcx).Count > 0) { JObject _t0 = ((JArray)_tcx)[0] as JObject; if (_t0 != null && _t0["paramLabel"] != null) { trigAttrName = _t0["paramLabel"].ToString().Trim(); } } } catch { }
                RegisterTagMeta(tagId, string.IsNullOrEmpty(trigAttrName) ? "trigger" : trigAttrName, false, true);
                _triggerAttId = AttIdForTag(stags, tagId);   // v1.0.159.0: needed by gated_get/summary_get
            }
            // v1.0.159.0 (C2/C3): ask the DB for what it can compute better than we can.
            // gated_get -> train-free stats (gate = TPR, value = 1) in SQL, which is what the
            // deterministic mask does row-by-row in C#. summary_get -> the multi-day baseline
            // WITHOUT spending raw rows, which matters because C1 now pages the raw rows to the
            // event end of the window. Both are best-effort: a failure changes nothing.
            if ((_gatedRefEnabled || _summaryBaselineEnabled)
                && !_derivedAlert && !string.IsNullOrEmpty(_triggerAttId)
                && !string.IsNullOrEmpty(siteId) && !string.IsNullOrEmpty(assetId) && haveInc)
            {
                string gsSd = incT.AddDays(-_evidenceWindowDays).ToString(_ddFmt);
                string gsEd = incT.AddHours(2).ToString(_ddFmt);
                if (_gatedRefEnabled)
                {
                    try
                    {
                        // v1.0.160.0: the gate is chosen PER ATTRIBUTE from the GatedAverage map, not
                        // hardcoded to TPR as 1.0.159.0 did. Gating a signal aspect on TPR is
                        // meaningless -- an aspect is proved by its OWN ECR. The relay is then
                        // resolved BY NAME among the asset's DataLogger rows (its AssetAttributeId is
                        // asset-specific and collides with analog ids), and THAT row's id is what
                        // gated_get needs. Unresolvable gate -> skip, fail-closed, and say so.
                        int trigAttNum;
                        string gateNm = int.TryParse(_triggerAttId, out trigAttNum) ? GateNameForAttId(trigAttNum) : null;
                        bool ungated = (gateNm == null) && int.TryParse(_triggerAttId, out trigAttNum) && GateIsUngatedId(trigAttNum);
                        // get_asset_tags carries the DataLogger relay rows (RoleType + names);
                        // search_tags is the fallback when the asset-tags call came back thin.
                        JObject gateRow = null;
                        if (gateNm != null)
                        {
                            gateRow = GateRelayRow(tags, gateNm);
                            if (gateRow == null) { gateRow = GateRelayRow(stags, gateNm); }
                        }
                        string gateAttId = null;
                        if (gateRow != null)
                        {
                            JToken gid = PropCI(gateRow, "AssetAttributeId");
                            if (gid != null) { gateAttId = gid.ToString(); }
                        }
                        if (ungated)
                        {
                            AiLog("INFO", "GATE", "attid " + _triggerAttId + " is UNGATED (charger / point-operation) -- no gated reference is meaningful");
                        }
                        else if (gateNm == null)
                        {
                            AiLog("INFO", "GATE", "attid " + _triggerAttId + " is not in the gate map -- gated reference skipped");
                        }
                        else if (string.IsNullOrEmpty(gateAttId))
                        {
                            AiLog("WARN", "GATE", "gate relay '" + gateNm + "' not found (or ambiguous) among this asset's DataLogger relays -- gated reference skipped (fail-closed)");
                        }
                        else
                        {
                            JObject gArgs = new JObject();
                            gArgs["SiteId"] = siteId; gArgs["AssetId"] = assetId;
                            gArgs["AttributeId"] = _triggerAttId; gArgs["Type"] = "a";
                            gArgs["StartDate"] = gsSd; gArgs["EndDate"] = gsEd;
                            gArgs["GateAttributeId"] = gateAttId; gArgs["GateValue"] = 1;
                            gArgs["SummaryType"] = "AVG"; gArgs["Interval"] = "15m";
                            string gres = await PrefetchCallAsync("gated_get", gArgs, loaded, ct).ConfigureAwait(false);
                            if (LooksUsableToolResult(gres, false))
                            {
                                _gatedRefSummary = gres;
                                _gateNameUsed = gateNm;
                                ev.Append("[GATED REFERENCE (gated_get) - the alerting attribute aggregated ONLY while its")
                                  .Append(" governing relay ").Append(gateNm).Append(" is UP. ")
                                  .Append(string.Equals(gateNm, "TPR", StringComparison.OrdinalIgnoreCase)
                                      ? "TPR UP means the track is CLEAR, so train-occupancy samples are excluded."
                                      : ("This is the relay that proves the reading is meaningful; TPR would NOT prove it."))
                                  .Append("]").Append("\n");
                                ev.Append(TrimForPrompt(gres, 2500)).Append("\n\n");
                                MarkPrefetched("gated_get");
                                AiLog("INFO", "GATE", "gated reference for attid " + _triggerAttId
                                    + " gated on " + gateNm + " (attid " + gateAttId + ")==1");
                            }
                        }
                    }
                    catch (Exception gex) { AiLog("WARN", "GATE", "gated_get failed: " + gex.Message); }
                }
                if (_summaryBaselineEnabled)
                {
                    try
                    {
                        JObject sArgs = new JObject();
                        sArgs["SiteId"] = siteId; sArgs["AssetId"] = assetId;
                        sArgs["AttributeId"] = _triggerAttId; sArgs["Type"] = "a";
                        sArgs["StartDate"] = gsSd; sArgs["EndDate"] = gsEd;
                        sArgs["SummaryType"] = "AVG"; sArgs["Interval"] = "1h";
                        string sres = await PrefetchCallAsync("summary_get", sArgs, loaded, ct).ConfigureAwait(false);
                        if (LooksUsableToolResult(sres, false))
                        {
                            ev.Append("[BASELINE (summary_get) - hourly average of the alerting attribute across the ")
                              .Append("whole evidence window; use this for 'what is normal', not the raw sample list, ")
                              .Append("which is paged to the event]").Append("\n");
                            ev.Append(TrimForPrompt(sres, 2500)).Append("\n\n");
                            MarkPrefetched("summary_get");
                        }
                    }
                    catch (Exception sex) { AiLog("WARN", "SUMMARY", "summary_get failed: " + sex.Message); }
                }
            }
            bool stagsPertains = (tagId != null) || TagsContainAsset(stags, assetId);
            // -- v1.0.79.0 -- prove the search_tags parameter fix is working (reviewer
            // RI-2): record what filter was sent implicitly (AssetName+optional
            // AttributeName), the row count, the unique AssetIds returned, whether the
            // requested AssetId is among them, and the resolved TagId.
            {
                int rowCount; int uniqueAssets; bool hasRequested;
                SearchTagsStats(stags, assetId, out rowCount, out uniqueAssets, out hasRequested);
                AiLog("INFO", "PREFETCH", "search_tags result assetName='" + assetName
                    + "' rows=" + rowCount + " uniqueAssets=" + uniqueAssets
                    + " requestedAssetPresent=" + (hasRequested ? "yes" : "no")
                    + " resolvedTag=" + (tagId ?? "none"));
            }
            if (!string.IsNullOrEmpty(stags) && LooksUsableToolResult(stags, false) && stagsPertains)
            {
                ev.Append("[TAG IDS - TagID per attribute, needed by history_get]").Append("\n");
                // v1.0.160.6: strip the bulky -Array waveform CurrentValues before the prompt. For a
                // point machine, search_tags returns the operation waveform arrays (attid 1001/2001/
                // 9001 "..-Array") whose CurrentValue is a 130-point comma string (~600+ chars each) ->
                // the payload balloons to ~22KB and the server truncates it mid-list (10535 chars
                // dropped on PT-117/118), which can cut the very TagID rows the resolver needs. The
                // model resolves tags on TagID + AssetAttributeId + AssetAttributeName + RoleType, NOT
                // on the waveform values, so dropping those long CurrentValue arrays keeps every tag
                // record intact and lets the useful list fit without blunt truncation.
                ev.Append(TrimForPrompt(StripTagWaveforms(stags), 4000)).Append("\n\n");
                gotTagIds = true; MarkPrefetched("search_tags");
            }
            else if (!string.IsNullOrEmpty(stags))
            {
                // suppress the wrong payload; do not let it reach the model
                MarkPrefetched("search_tags");   // still count it as attempted (don't re-call)
                AiLog("INFO", "PREFETCH", "search_tags returned no rows for AssetId "
                    + (string.IsNullOrEmpty(assetId) ? "?" : assetId)
                    + "; payload ignored, resolving via history_get(AssetId)");
            }

            // -- v1.0.82.0 rev J -- DERIVED alerting attribute (e.g. RRAIL): it has NO
            // telemetry tag; hunting one (and the AssetId fallback) can never succeed
            // and previously guaranteed a Coverage-gap INCONCLUSIVE. Ground on the
            // formula's COMPONENT tags instead: resolve each component from the
            // search_tags rows (TagID + AssetAttributeName), pull their series in
            // parallel, and satisfy coverage via components (J3 policy below).
            if (_derivedAlert)
            {
                string dFormula; string dParamTmp;
                DetectDerived(ctx, out dParamTmp, out dFormula);
                // v1.0.160.2: emit the alias->title bridge for THIS formula, before any component
                // discussion, so the model cannot call a fetched component "unavailable" merely
                // because the formula names it by its alias.
                try
                {
                    string _bridge = BuildAliasBridge((dFormula ?? "") + " " + (GetCtx(ctx, "description") ?? ""));
                    if (!string.IsNullOrEmpty(_bridge))
                    {
                        ev.Append(_bridge);
                        AiLog("INFO", "ALIAS", "name bridge emitted for the derived formula");
                    }
                }
                catch { }
                // v1.0.84.0: the authoritative derived value from the card (for the
                // "use THIS, don't recompute" guard note below).
                string dMeasured = null;
                {
                    JToken _c = ctx["alertCard"];
                    JToken _tc = _c != null ? _c["triggeredConditions"] : null;
                    if (_tc != null && _tc.Type == JTokenType.Array && ((JArray)_tc).Count > 0)
                    {
                        JObject _t0 = ((JArray)_tc)[0] as JObject;
                        if (_t0 != null && _t0["measured"] != null)
                        {
                            dMeasured = _t0["measured"].ToString();
                            if (_t0["unit"] != null) { dMeasured += " " + _t0["unit"].ToString(); }
                        }
                    }
                }
                List<string> comps = ExtractFormulaComponents(dFormula);
                // v1.0.160.30 (Item 4c): for a KNOWN derived attid, fetch its base sensors by the
                // pinned canonical list (which resolves against search_tags) instead of the prose
                // formula's short forms (ChgOpV/Vf/If) that DomainAttributeName drops -- otherwise
                // the inputs are never fetched and the derived value cannot be computed.
                if (_derivedComputeV2)
                {
                    int _dAttInp;
                    if (CauseLogicMaps.CauseToDerived.TryGetValue((GetCtx(ctx, "causeCode") ?? "").Trim(), out _dAttInp))
                    {
                        List<string> _pinned = DerivedBaseInputs(_dAttInp);
                        if (_pinned != null && _pinned.Count > 0) { comps = _pinned; }
                    }
                }
                DateTime dInc;
                bool dHaveInc = TryParseAlertTime(GetCtx(ctx, "time"), out dInc);
                // v1.0.160.104: the movement panel anchors on the MAIN triggered-condition time when
                // present (the stamped incidence can post-date the real trigger sample by minutes),
                // else the stamped incidence. The verdict/coverage path (dInc/compAsOf/dComputed) is
                // unchanged; this anchor drives ONLY the previous-in-envelope comparator. Fix 6: never
                // call ToUnixSeconds on a missing/malformed incidence -- if we have no valid anchor the
                // comparator is skipped (as before, this fails safe).
                bool cmpHaveAnchor = dHaveInc;
                DateTime cmpAnchorDt = dHaveInc ? dInc : DateTime.MinValue;
                {
                    string mainTrigTime = MainTriggeredTime(ctx);
                    DateTime parsedTrig;
                    if (mainTrigTime != null && TryParseAlertTime(mainTrigTime, out parsedTrig))
                    {
                        cmpAnchorDt = parsedTrig;
                        cmpHaveAnchor = true;
                    }
                }
                long cmpAnchorEpoch = cmpHaveAnchor ? ToUnixSeconds(cmpAnchorDt) : 0L;
                long cmpIncidenceEpoch = dHaveInc ? ToUnixSeconds(dInc) : cmpAnchorEpoch;   // referenceAgeSec is incidence-relative (design schema)
                bool cmpTrackAsset = (GetCtx(ctx, "assetType") ?? "").ToUpperInvariant().Contains("TRACK")
                                  || (GetCtx(ctx, "causeCode") ?? "").ToUpperInvariant().StartsWith("TC ")
                                  || (GetCtx(ctx, "causeCode") ?? "").ToUpperInvariant().Contains("RAIL RES");
                int covered = 0; bool covI = false; bool covV = false;
