                            DerivedCompare dc = PrevInEnvelopeSample(cHist, cmpAnchorEpoch, cmpIncidenceEpoch, cmpTrackAsset, haveBounds, envMinSafe, envMaxSafe, envMinFail, (long)_prevCompMaxAgeMin * 60L);
                            if (dc != null) { compCompare[comps[ci]] = dc; }
