                if (!string.IsNullOrEmpty(hist) && LooksUsableToolResult(hist, true))
                {
                    long shortBy;
                    string covWhy;
                    CoverageStateKind covState = HistoryCoverageState(hist, out shortBy, out covWhy);
                    _lastCoverageKind = covState;
                    // requiredAlertingTagId = tagId;   -- v1.0.76.0: moved above, before the fetch (Item 1)
                    gotUsableHistoryGet = true;
                    string covNote = null;
                    if (covState == CoverageStateKind.Covered)
                    {
                        SetTagCoverage(tagId, HistoryCoverageLevel.VerifiedAdequate);
                    }
                    else if (covState == CoverageStateKind.Unverifiable)
                    {
                        covNote = "NOTE: incidence coverage of this series could NOT be verified - it "
                                + covWhy + ". " + CoverageRecoveryAdvice(covState) + ".";
                        _prefetchGap = "history coverage could not be verified";
                        SetTagCoverage(tagId, HistoryCoverageLevel.Unverified);
                    }
                    else
                    {
                        covNote = "NOTE: this series is NOT sufficient evidence - it " + covWhy + ". "
                                + CoverageRecoveryAdvice(covState) + ".";
                        _prefetchGap = "history " + covWhy;
                        SetTagCoverage(tagId, HistoryCoverageLevel.Inadequate);
                    }
                    ev.Append("[VALUE HISTORY - the alerting attribute, oldest first]").Append("\n");
                    ev.Append(TrimForPrompt(hist, 12000)).Append("\n");
                    if (covNote != null) { ev.Append(covNote).Append("\n"); }
                    ev.Append("\n");
                    // pre-fetched telemetry grounds the verdict exactly as a tool call
                    // would: the gate exists to require REAL data, not a tool call.
                    _jsonGotHistory = true;
                    _jsonGotEvidence = true;
                }
                else
                {
                    histWhy = "TagId " + tagId + " returned no usable series - fetch it yourself";
                    _prefetchGap = "history unusable";
                    AiLog("WARN", "PREFETCH", histWhy);
                }
            }
            else
            {
                // -- v1.0.78.0 -- AssetId fallback. search_tags could not resolve the
                // alerting TagId (wrong/other assets). history_get accepts AssetId
                // directly (unique, no site/tag lookup); its JSON response carries
                // TagID + AssetAttributeName per block, the exact fields the matcher
                // reads. Probe MUST be outputMode=json (preserveJson=true): columnar
                // cols/rows have no field names.
                string fbTagId = null;
                DateTime fbInc;
                bool fbHaveInc = TryParseAlertTime(GetCtx(ctx, "time"), out fbInc);
                // v1.0.160.177: for a POINT MACHINE, the history_get(AssetId) fallback probe returns the
                // last row for EVERY attribute -- including the ~48 -PM- operation ARRAY tags (each a
                // 120-250 point waveform string). That single call cost ~21s in the wire trace (>90% of
                // prefetch), and those array tags are NOT used for the verdict. The alerting tag resolves
                // from search_tags (already fetched) + the attid maps, so skip this wide probe for points.
                string _fbType = (GetCtx(ctx, "assetType") ?? "").ToUpperInvariant();
                bool _fbIsPoint = _fbType.IndexOf("POINT") >= 0;
                if (!string.IsNullOrEmpty(assetId) && !_fbIsPoint)
                {
                    // v1.0.160.109 CUT A: outputMode is deliberately JSON here and the limit is 1
                    // (rows PER TAG, not attribute count -- see RF-5). The block below scans the
                    // response for the literal field name "TagID"; emitting columnar would return
                    // positional arrays and break PickAlertingTagId SILENTLY.
                    JObject probeArgs = fbHaveInc
                        ? HistWindowArgs("AssetId", assetId, fbInc.AddDays(-_evidenceWindowDays), fbInc.AddHours(2), 1, "json")
                        : HistWindowArgs("AssetId", assetId, DateTime.Now.AddDays(-_evidenceWindowDays), DateTime.Now, 1, "json");
                    string probe = await HistFetchAsync(probeArgs, loaded, ct, true).ConfigureAwait(false);
                    int blocks = -1;
                    bool truncated = false;
                    if (!string.IsNullOrEmpty(probe))
                    {
                        truncated = _truncMarker.IsMatch(probe);
                        int c = 0; int idx = 0;
                        while ((idx = probe.IndexOf("TagID", idx, StringComparison.OrdinalIgnoreCase)) >= 0) { c++; idx += 5; }
                        blocks = c;
                        fbTagId = PickAlertingTagId(probe, ctx, assetId);
                    }
                    AiLog("INFO", "PREFETCH", "AssetId probe assetId=" + assetId
                        + " chars=" + (probe == null ? 0 : probe.Length)
                        + " truncated=" + truncated
                        + " tagBlocks=" + blocks
                        + " resolved=" + (fbTagId ?? "none"));
                }
                if (fbTagId != null)
                {
                    requiredAlertingTagId = fbTagId;
                    JObject fbArgs = fbHaveInc
                        ? HistWindowArgs("TagId", fbTagId, fbInc.AddDays(-_evidenceWindowDays), fbInc.AddHours(2), 500, "columnar")
                        : HistWindowArgs("TagId", fbTagId, DateTime.Now.AddDays(-_evidenceWindowDays), DateTime.Now, 500, "columnar");
                    string fbHist = await HistFetchAsync(fbArgs, loaded, ct).ConfigureAwait(false);
                    if (!string.IsNullOrEmpty(fbHist) && LooksUsableToolResult(fbHist, true))
                    {
                        long fbShortBy;
                        string fbWhy;
                        CoverageStateKind fbState = HistoryCoverageState(fbHist, out fbShortBy, out fbWhy);
                        _lastCoverageKind = fbState;
                        gotUsableHistoryGet = true;
                        string fbNote = null;
                        if (fbState == CoverageStateKind.Covered)
                        {
                            SetTagCoverage(fbTagId, HistoryCoverageLevel.VerifiedAdequate);
                        }
                        else if (fbState == CoverageStateKind.Unverifiable)
                        {
                            fbNote = "NOTE: incidence coverage of this series could NOT be verified - it "
                                   + fbWhy + ". " + CoverageRecoveryAdvice(fbState) + ".";
                            _prefetchGap = "history coverage could not be verified";
                            SetTagCoverage(fbTagId, HistoryCoverageLevel.Unverified);
                        }
                        else
                        {
                            fbNote = "NOTE: this series is NOT sufficient evidence - it " + fbWhy + ". "
                                   + CoverageRecoveryAdvice(fbState) + ".";
                            _prefetchGap = "history " + fbWhy;
                            SetTagCoverage(fbTagId, HistoryCoverageLevel.Inadequate);
                        }
                        ev.Append("[VALUE HISTORY - the alerting attribute, oldest first]").Append("\n");
                        ev.Append(TrimForPrompt(fbHist, 12000)).Append("\n");
                        if (fbNote != null) { ev.Append(fbNote).Append("\n"); }
                        ev.Append("\n");
                        _jsonGotHistory = true;
                        _jsonGotEvidence = true;
                        AiLog("INFO", "PREFETCH", "search_tags miss -> grounded via AssetId fallback, TagId " + fbTagId);
                    }
                    else
                    {
                        histWhy = "AssetId fallback: TagId " + fbTagId + " returned no usable series";
                        _prefetchGap = "history unusable";
                        AiLog("WARN", "PREFETCH", histWhy);
                    }
                }
                else
                {
                    histWhy = "could not match the alerting attribute to a TagId (search_tags AND AssetId fallback) - pick it from the ASSET TAGS above and call history_get";
                    _prefetchGap = "alerting attribute could not be matched to a TagId";
                    AiLog("INFO", "PREFETCH", histWhy);
                }
            }

            // Every condition the one-turn path depends on. Any miss keeps the tools.
            if (!gotTags) { _prefetchGap = _prefetchGap ?? "asset tags missing"; }
            if (!gotRange) { _prefetchGap = _prefetchGap ?? "baseline thresholds missing"; }
            if (!_jsonGotHistory) { _prefetchGap = _prefetchGap ?? "no value history"; }
            // Cause-specific depth. The verdicts that proved most useful leaned on the
            // fault audit and the ML leakage events -- mechanism and corroboration, not
            // just the threshold crossing. For a track or point-machine alert, entering
            // one-turn synthesis without EITHER of those would silently produce a
            // thinner analysis than the agentic path would have.
            if (predTool != null && !gotPred && !gotAudit)
            {
                _prefetchGap = _prefetchGap ?? "neither fault audit nor ML analysis available for this asset type";
            }
            _prefetchComplete = gotTags && gotRange && _jsonGotHistory && _prefetchGap == null;

            ev.Append("[STATUS]").Append("\n");
            ev.Append("  asset tags .... ").Append(gotTags ? "DONE - do not call get_asset_tags" : "MISSING").Append("\n");
            ev.Append("  baseline ...... ").Append(gotRange ? "DONE - do not call get_attribute_range" : "MISSING").Append("\n");
            ev.Append("  tag ids ....... ").Append(gotTagIds ? "DONE - do not call search_tags" : "MISSING").Append("\n");
            ev.Append("  fault audit ... ").Append(gotAudit ? "DONE - do not call analyse_alert" : "unavailable").Append("\n");
            ev.Append("  site alerts ... ").Append(gotAlerts ? "DONE - do not call get_frs_alerts" : "unavailable").Append("\n");
            if (predTool != null)
            {
                ev.Append("  ML analysis ... ").Append(gotPred ? ("DONE - do not call " + predTool) : "unavailable this cycle").Append("\n");
            }
            // -- v1.0.75.0 -- REMOVED: keyed on _jsonGotHistory alone, so SHORT
            // history read as "DONE - do not call history_get".
            // ev.Append("  value history . ").Append(_jsonGotHistory ? "DONE - do not call history_get" : ("MISSING (" + (histWhy ?? "not attempted") + ")")).Append("\n");
            string histStatus;
            if (_jsonGotHistory && AlertingCoverageLevel() == HistoryCoverageLevel.VerifiedAdequate)
            {
                histStatus = "DONE - do not call history_get";
            }
            else if (_jsonGotHistory)
            {
                histStatus = "RETRY REQUIRED - " + CoverageRecoveryAdvice(_lastCoverageKind);
            }
            else
            {
                histStatus = "MISSING (" + (histWhy ?? "not attempted") + ")";
            }
            ev.Append("  value history . ").Append(histStatus).Append("\n");

            // v1.0.92.0 STAGE 4 (PM branch): for a POINT-MACHINE alert, add a detection-
            // coherence note. Point detection has a structure track/signal alerts lack:
            // per end NWKR xor RWKR (Normal vs Reverse), and A-END must AGREE with B-END.
            // We surface the eight detection Titles (room + location, both ends) + the PM ML
            // tools so the model checks agreement. ADDITIVE and POINT-ONLY -- never touches track/signal paths.
            // NOTE: this guides the model using the detection attributes; it does not yet
            // fetch each detection tag's live state in prefetch (that is the next refinement
            // once we have a real PM alert to validate the fetch against). Kept honest.
            if (IsPointCard(ctx))
            {
                ev.Append("=== POINT-MACHINE DETECTION COHERENCE ===").Append("\n");
                ev.Append("Current Point cause class: ")
                  .Append(IsPointDetectionRelayCause(GetCtx(ctx, "causeCode")) ? "DETECTION-RELAY" : "OPERATION/CURRENT/VOLTAGE")
                  .Append(".").Append("\n");
                ev.Append("This is a point-machine alert. Point detection has structure track/signal lack: a point end ");
                ev.Append("is normally Normal (NWKR up) XOR Reverse (RWKR up), and A-END normally agrees with B-END. ");
                ev.Append("Detection relays: ").Append(string.Join(", ", _pmDetectionAttrs)).Append(". ");
                ev.Append("ROOM vs LOC: the room-side relays (A/B End - NWKR/RWKR) are AUTHORITATIVE - what the interlocking ");
                ev.Append("acts on; the (Loc) relays are what the field/point reports before the cable run back to the room. ");
                ev.Append("If the (Loc) side shows a lie the room side does not, that SUPPORTS localization to the cable ");
                ev.Append("path between the point and the relay room (telemetry alone does not establish the failed ");
                ev.Append("component). Room and Loc agreeing means no room-versus-location transmission mismatch; ");
                ev.Append("it does NOT establish the correct commanded lie - still verify NWKR/RWKR exclusivity, A/B-end ");
                ev.Append("agreement, and that the detected lie matches the command outcome. ");
                ev.Append("GUARD: use a detection value for incidence coherence ONLY when its timestamp is within the alert ");
                ev.Append("window - current or untimestamped values (e.g. from get_asset_tags) describe present state, ");
                ev.Append("possibly a later throw or the reset, and cannot prove the state at the alert. ");
                ev.Append("CAUSE-AWARE: for a current/voltage/operation alert, detection disagreement WEAKENS the mechanical ");
                ev.Append("assessment and normally warrants INCONCLUSIVE unless independently resolved; for a detection-relay ");
                ev.Append("alert (NWKR/RWKR RELAY DEFECT), the same disagreement MAY CONFIRM the reported condition when ");
                ev.Append("timestamp-aligned. Operation values (IPT/VPT/TPT) exist only during a throw: absence = idle ONLY ");
                ev.Append("if no throw/control event (NWCR/RWCR) is in the window; a commanded throw with absent operation ");
                ev.Append("telemetry is a DATA GAP -> INCONCLUSIVE. A throw with current but no detection is an operation/");
                ev.Append("detection coherence failure; telemetry cannot name the cause. Operation TIME is on the CURRENT ");
                ev.Append("channel (A/B end) in milliseconds; a normal throw is ~5 s, and an operation over ~6000 ms (6 s) ");
                ev.Append("is EXTENDED - flag as a possible obstruction/high-load concern for the engineer, do not name the ");
                ev.Append("cause. The predict_pm_operation / predict_pm_cluster ML tools cover point health if needed.").Append("\n");
            }

            // v1.0.149.0: per-section STATUS truth table (checked responses, not hope) +
            // deterministic computed blocks the model reads instead of deriving.
            ev.Append("=== SECTION STATUS (checked) ===").Append("\n");
            ev.Append("tags=").Append(gotTags ? "ok" : "MISSING")
              .Append("  range=").Append(gotRange ? "ok" : "MISSING")
              .Append("  searchTags=").Append(gotTagIds ? "ok" : "MISSING")
              .Append("  history=").Append(histWhy == null ? "ok" : ("MISSING(" + histWhy + ")"))
              .Append("  mlAudit=").Append(gotAudit ? "ok" : "MISSING")
              .Append("  alerts=").Append(gotAlerts ? "ok" : "MISSING")
              .Append("  predictions=").Append(gotPred ? "ok" : "n/a").Append("\n");
            string computed = BuildComputedTrendBlock();
            if (!string.IsNullOrEmpty(computed)) { ev.Append(computed); }
            ev.Append("=== END PRE-FETCHED EVIDENCE ===").Append("\n");

            sw.Stop();
            AiLog("INFO", "PREFETCH", "gathered " + ev.Length + " chars in " + sw.ElapsedMilliseconds + "ms"
                + " (history=" + (_jsonGotHistory ? "yes" : "no") + ")");
            JObject tr = new JObject();
            tr["ms"] = sw.ElapsedMilliseconds; tr["chars"] = ev.Length; tr["grounded"] = _jsonGotHistory;
            TraceAnalyze("prefetch", tr);
            // ok reflects whether the pre-fetch achieved ANYTHING, not whether it
            // achieved EVERYTHING. Flagging the step amber because one of four items
            // was missing read as a failure when tags, baseline and tag ids had all
            // been gathered -- the same misleading-progress trap as the old checklist.
            int got = (gotTags ? 1 : 0) + (gotRange ? 1 : 0) + (gotTagIds ? 1 : 0) + (_jsonGotHistory ? 1 : 0)

                    + (gotPred ? 1 : 0) + (gotAudit ? 1 : 0) + (gotAlerts ? 1 : 0);
            string statusNote = got + "/" + (predTool != null ? 7 : 6) + " gathered";
            if (!_jsonGotHistory) { statusNote += " \u00b7 history left to the model"; }
            WriteSse("step", new { phase = "tool_done", name = "prefetch_evidence",
                                   engine = _engineName1, ms = sw.ElapsedMilliseconds,
                                   chars = ev.Length, ok = got > 0, note = statusNote });
            return ev.ToString();
            }
            finally
            {
                // v1.0.160.110 SL5: wall-clock for the prefetch phase, recorded on EVERY exit path
                // (including the early `return null` when there is no assetId).
                _swPrefetchPhase.Stop();
                _trPrefetchWallMs += _swPrefetchPhase.ElapsedMilliseconds;
            }
        }

        private static JObject NewArgs(string k, string v)
        {
            JObject o = new JObject();
            long n;
            if (long.TryParse(v, out n)) { o[k] = n; } else { o[k] = v; }
            return o;
        }

        // v1.0.160.109 CUT A: deliberately NOT HistWindowArgs. This serves get_attribute_range_history,
        // which takes a NAIVE DateTime server-side and is already CORRECT -- applying the history_get
        // UTC compensation here would introduce the very 5.5 h skew Cut A removes.
        // v1.0.117.0: args for get_attribute_range_history - AssetId + a ddMMyyyy_HHmmss window
        // ending just after incidence and reaching back the evidence window (same window the
        // component/history fetches use, so the trend lines up with the samples).
        private static JObject NewRangeHistoryArgs(string assetId, DateTime incidence)
        {
            JObject o = new JObject();
            long n;
            if (long.TryParse(assetId, out n)) { o["AssetId"] = n; } else { o["AssetId"] = assetId; }
            o["StartDate"] = incidence.AddDays(-_evidenceWindowDays).ToString(_ddFmt);
            o["EndDate"] = incidence.AddHours(2).ToString(_ddFmt);
            return o;
        }

        private static async Task<string> SafeAwait(Task<string> t)
        {
            if (t == null) { return null; }
            try { return await t.ConfigureAwait(false); }
            catch { return null; }
        }

        // Same policy path a model-issued call takes: clamps, budget, routing.
        // -- v1.0.78.0 -- preserveJson: the AssetId metadata probe needs named
        // fields (TagID, AssetAttributeName) to resolve the alerting tag, but
        // ClampToolArgs pins evidence tools to outputMode=columnar (positional
        // cols/rows, no field names). When preserveJson is set, restore json
        // AFTER the clamp -- probe only; the trend pull keeps columnar.
        // v1.0.160.110 SL5: thin timing wrapper. The body is unchanged (renamed to ...CoreAsync) --
        // wrapping it in place would have meant a try/finally around a long method with early
        // returns, which the 160.63 note rightly called a bigger edit than the fix needs. Every
        // existing call site keeps calling PrefetchCallAsync and is timed for free.
        private async Task<string> PrefetchCallAsync(string tool, JObject args, ToolLoadResult loaded, System.Threading.CancellationToken ct, bool preserveJson = false)
        {
            var sw = System.Diagnostics.Stopwatch.StartNew();
            try
            {
                // v1.0.160.172 (Fix 3): serve static range calls from cache when fresh.
                string ck = PrefetchCacheKey(tool, args);
                if (ck != null)
                {
                    string cached;
                    if (TryGetPrefetchCache(ck, out cached)) { return cached; }
                    string fresh = await PrefetchWithTimeoutAsync(tool, args, loaded, ct, preserveJson).ConfigureAwait(false);
                    if (LooksUsableToolResult(fresh, IsEvidenceTool(tool))) { SetPrefetchCache(ck, fresh); }
                    return fresh;
                }
                return await PrefetchWithTimeoutAsync(tool, args, loaded, ct, preserveJson).ConfigureAwait(false);
            }
            finally
            {
                sw.Stop();
                // Interlocked: prefetch tasks run CONCURRENTLY (tagsT/rangeT/stagsT/predT/alertsT/
                // rangeHistT all start before any await), so this is a genuine race without it.
                System.Threading.Interlocked.Add(ref _trToolCallMsSum, sw.ElapsedMilliseconds);
            }
        }

        // v1.0.160.172 (Fix 4): per-call timeout + one retry, active only in parallel mode
        // (!_serializeClients). The underlying client call cannot be cancelled mid-flight, but
        // AwaitWithCancel abandons the caller on the linked-token timeout, so a stalled call stops
        // holding up THIS caller; the retry usually lands on a free slot. In serialized mode the
        // timeout is disabled (no CancelAfter) so legit lock-waits are never killed.
        private async Task<string> PrefetchWithTimeoutAsync(string tool, JObject args, ToolLoadResult loaded, System.Threading.CancellationToken ct, bool preserveJson)
        {
            if (_serializeClients)
            {
                return await PrefetchCallCoreAsync(tool, args, loaded, ct, preserveJson).ConfigureAwait(false);
            }
            int attempts = _prefetchRetries + 1;
            for (int i = 0; i < attempts; i++)
            {
                using (var cts = System.Threading.CancellationTokenSource.CreateLinkedTokenSource(ct))
                {
                    cts.CancelAfter(_prefetchTimeoutMs);
                    try
                    {
                        return await PrefetchCallCoreAsync(tool, args, loaded, cts.Token, preserveJson).ConfigureAwait(false);
                    }
                    catch (OperationCanceledException) when (!ct.IsCancellationRequested)
                    {
                        AiLog("WARN", "PREFETCH", tool + " timed out after " + _prefetchTimeoutMs + "ms (attempt " + (i + 1) + "/" + attempts + ")");
                    }
                }
            }
            return null;
        }

        private async Task<string> PrefetchCallCoreAsync(string tool, JObject args, ToolLoadResult loaded, System.Threading.CancellationToken ct, bool preserveJson = false)
        {
            if (loaded.OwnerMap == null || !loaded.OwnerMap.ContainsKey(tool)) { return null; }
            // Pre-fetch must NOT consume the model's per-tool budget. It made 3 calls
            // of its own, one of them search_tags -- which left the model only ONE
            // search_tags before the cap of 2 refused it, and a denied lookup is worse
            // than no pre-fetch at all. Pre-fetch is bounded by construction (a fixed
            // set of calls, once), so the allowlist alone is the right guard here.
            if (!_jsonToolCaps.ContainsKey(tool)) { return null; }
            HashSet<string> declared = null;
            if (loaded.ArgMap != null && loaded.ArgMap.ContainsKey(tool)) { declared = loaded.ArgMap[tool]; }
            // v1.0.160.63: count prefetch tool calls. The agentic-loop counter (L13756) never sees
            // these, so the audit reported 0 for a run that made 8. Count only -- no try/finally
            // wrapper around this long method, which would be a far bigger edit than the fix needs.
            _trPrefetchCalls++;
            JToken clamped = ClampToolArgs(tool, args, declared);
            if (preserveJson)
            {
                JObject co = clamped as JObject;
                // only if the tool actually declares outputMode (undeclared args are dropped)
                if (co != null && declared != null && declared.Contains("outputMode"))
                {
                    string omName = null;
                    foreach (string dn in declared)
                    {
                        if (string.Equals(dn, "outputMode", StringComparison.OrdinalIgnoreCase)) { omName = dn; break; }
                    }
                    co[omName ?? "outputMode"] = "json";
                }
            }
            int owner = loaded.OwnerMap[tool];
            System.Diagnostics.Stopwatch sw = System.Diagnostics.Stopwatch.StartNew();
            string res = await CallToolRoutedAsync(tool, clamped, ct, owner).ConfigureAwait(false);
            // v1.0.149.0: per-call CHECK -- one automatic retry when a prefetch response is
            // absent/tiny/errored, so a transient MCP hiccup does not silently cost a section.
            if (res == null || res.Length < 25 || res.IndexOf("\"isError\":true", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                AiLog("INFO", "PREFETCH", "retrying " + tool + " (first response " + (res == null ? "null" : (res.Length + "B")) + ")");
                try { await Task.Delay(300, ct).ConfigureAwait(false); } catch { }
                string res2 = await CallToolRoutedAsync(tool, clamped, ct, owner).ConfigureAwait(false);
                if (res2 != null && (res == null || res2.Length > res.Length)) { res = res2; }
            }
            sw.Stop();
            // v1.0.158.4: if the series was cut, re-fetch just the TAIL of the window. The tail
            // holds the incidence, which is the part the verdict actually needs; without this the
            // analysis reasons from telemetry that stops a day or more before the event.
            if (NoteHistoryTruncation(tool, clamped, res))
            {
                if (_histPagingEnabled)
                {
                    res = await HistoryPageToEndAsync(tool, clamped, res, ct, owner).ConfigureAwait(false);
                }
                else
                try
                {
                    JObject ta = clamped as JObject;
                    string endStr = (ta != null && ta["EndDate"] != null) ? ta["EndDate"].ToString() : null;
                    DateTime endDt;
                    if (!string.IsNullOrEmpty(endStr)
                        && DateTime.TryParseExact(endStr, _ddFmt, System.Globalization.CultureInfo.InvariantCulture,
                            System.Globalization.DateTimeStyles.None, out endDt))
                    {
                        // v1.0.160.109 CUT A: derived from the already-stamped EndDate, so it stays in
                        // whatever frame the builder produced -- do NOT re-apply HistStamp here.
                        JObject tailArgs = (JObject)ta.DeepClone();
                        tailArgs["StartDate"] = endDt.AddHours(-_histTailHours).ToString(_ddFmt);
                        AiLog("INFO", "HIST", "re-fetching TAIL " + _histTailHours + "h for " + tool
                            + " (cut series -> the incidence was outside the returned rows)");
                        string tailRes = await CallToolRoutedAsync(tool, tailArgs, ct, owner).ConfigureAwait(false);
                        if (!string.IsNullOrEmpty(tailRes) && tailRes.IndexOf("\"ts\"", StringComparison.Ordinal) >= 0)
                        {
                            res = tailRes;   // the tail reaches the event; the head did not
                            NoteHistoryTruncation(tool, tailArgs, tailRes);
                        }
                    }
                }
                catch (Exception tex) { AiLog("WARN", "HIST", "tail re-fetch failed: " + tex.Message); }
            }
            _jsonToolOk += LooksUsableToolResult(res, IsEvidenceTool(tool)) ? 1 : 0;
            // v1.0.158.2 (P0): log prefetch calls under the RUN's trace id, not the literal string
            // "prefetch". Since the prefetch-v2 work most evidence is gathered BEFORE the model loop,
            // so a typical run makes ZERO in-loop tool calls -- every call was filed under "prefetch"
            // and a Tool trace lookup by sse-... found nothing. That is why the trace looked broken
            // even with logging enabled. toolUseId stays "prefetch" so the reader can badge the stage.
            LogToolEvent(string.IsNullOrEmpty(_traceId) ? "prefetch" : _traceId,
                "response", -1, "prefetch", tool, owner, clamped, res, null, sw.ElapsedMilliseconds);
            RecordToolTiming(tool, clamped, res, -1, sw.ElapsedMilliseconds);
            return res;
        }

        // Match the alert's triggered parameter against the tag list. The card names
        // the parameter that actually breached (e.g. "ITC RELAY END (Ir) mA"), so the
        // series we want is the tag whose attribute name shares the most words with it.
        // Cause-code prefix identifies the asset class, which selects the ML tool.
        private static string PredictToolFor(string causeCode)
        {
            if (string.IsNullOrEmpty(causeCode)) { return null; }
            string c = causeCode.Trim().ToUpperInvariant();
            if (c.StartsWith("TC ")) { return "predict_track_health"; }
            if (c.StartsWith("PT ")) { return "predict_pm_operation"; }
            return null;   // signals and power supply have no ML analysis
        }

        private static JObject NewPredictArgs(string tool, string siteId, string assetId)
        {
            JObject o = new JObject();
            long sn, an;
            if (long.TryParse(siteId, out sn)) { o["SiteId"] = sn; }
            if (long.TryParse(assetId, out an))
            {
                // predict_track_health takes an ARRAY of track ids; the PM tools take one
                if (string.Equals(tool, "predict_track_health", StringComparison.OrdinalIgnoreCase))
                {
                    JArray ids = new JArray(); ids.Add(an); o["TrackIds"] = ids;
                }
                else { o["AssetId"] = an; }
            }
            return o;
        }

        private void MarkPrefetched(string tool)
        {
            if (_prefetchDone != null && !string.IsNullOrEmpty(tool)) { _prefetchDone.Add(tool); }
        }

        // history_get is deliberately NOT deniable: the model may legitimately want a
        // DIFFERENT tag than the one pre-fetch chose. Only asset-level, one-shot
        // lookups are refused, because a second call returns identical bytes.
        // v1.0.160.166: pull every asset-ish id out of a tool-call's arguments. AssetId / AssetIds[]
        // / TrackIds[] all name an asset; a call carrying an id that prefetch did NOT cover is a new
        // question, not a repeat.
        private static void CollectArgAssetIds(JObject args, List<string> into)
        {
            if (args == null || into == null) { return; }
            string[] keys = new string[] { "AssetId", "assetId", "AssetIds", "assetIds", "TrackIds", "trackIds" };
            for (int i = 0; i < keys.Length; i++)
            {
                JToken t = args[keys[i]];
                if (t == null) { continue; }
                if (t.Type == JTokenType.Array)
                {
                    foreach (JToken e in (JArray)t)
                    {
                        string s = e != null ? e.ToString().Trim() : "";
                        if (s.Length > 0) { into.Add(s); }
                    }
                }
                else
                {
                    string s = t.ToString().Trim();
                    if (s.Length > 0) { into.Add(s); }
                }
            }
        }

        private string PrefetchAlreadyHas(string tool, JObject args)
        {
            if (_prefetchDone == null || !_prefetchDone.Contains(tool)) { return null; }
            // v1.0.160.166: SCOPE THE DENIAL TO THE PREFETCHED ASSET. Prefetch only ever gathered
            // the alerting asset, so a call naming a different asset -- a family track, an adjacent
            // track, another asset at the site -- is genuinely new data and must go through.
            // Without this the model is told to check the adjacent family-track log and then
            // refused the only call that resolves its TagId, which is why verdicts kept carrying
            // "No adjacent track telemetry".
            if (!string.IsNullOrEmpty(_prefetchAssetId))
            {
                List<string> ids = new List<string>();
                CollectArgAssetIds(args, ids);
                bool namesOther = false;
                for (int i = 0; i < ids.Count; i++)
                {
                    if (!string.Equals(ids[i], _prefetchAssetId, StringComparison.OrdinalIgnoreCase))
                    {
                        namesOther = true;
                        break;
                    }
                }
                if (namesOther)
                {
                    AiLog("INFO", "TOOL", tool + " allowed for a non-prefetched asset ("
                        + string.Join(",", ids.ToArray()) + "; prefetch covered " + _prefetchAssetId + ")");
                    return null;
                }
            }
            // DEAD END GUARD. search_tags is the ONLY source of a TagId, and history_get
            // needs one. If pre-fetch ran search_tags but could not match the alerting
            // attribute, denying it leaves the model unable to find the tag itself --
            // observed: "series": [] and no chart, because every route to a TagId was
            // closed. Only suppress it once history is actually in hand.
            if (string.Equals(tool, "search_tags", StringComparison.OrdinalIgnoreCase)
                && !_jsonGotHistory)
            {
                return null;
            }
            return "Already provided: '" + tool + "' output is in the PRE-FETCHED EVIDENCE block "
                 + "at the top of this conversation. Calling it again returns identical bytes and "
                 + "costs a full turn. Read it there and continue.";
        }

        // analyse_alert takes the station CODE directly plus the alert facts, so it
        // needs no lookup of any kind.
        private static JObject NewAuditArgs(JObject ctx, string siteId, string assetId, DateTime inc)
        {
            JObject o = new JObject();
            o["cause_code"] = GetCtx(ctx, "causeCode");
            o["asset_name"] = GetCtx(ctx, "assetName");
            o["site_code"] = GetCtx(ctx, "station");
            o["asset_type"] = AssetTypeFor(GetCtx(ctx, "causeCode"));
            o["alert_timestamp"] = inc.ToString("yyyy-MM-dd HH:mm:ss");
            long n;
            if (long.TryParse(siteId, out n)) { o["site_id"] = n; }
            if (long.TryParse(assetId, out n)) { o["asset_id"] = n; }
            return o;
        }

        private static string AssetTypeFor(string causeCode)
        {
            string c = (causeCode ?? "").Trim().ToUpperInvariant();
            if (c.StartsWith("PT ")) { return "POINT MACHINE"; }
            if (c.StartsWith("SIG") || c.StartsWith("SHSIG") || c.StartsWith("ROSIG") || c.StartsWith("COSIG")) { return "SIGNAL"; }
            if (c.StartsWith("TC ")) { return "TRACK"; }
            // Anything else (IPS power supply, datalogger, unknown prefixes) must NOT
            // be submitted as TRACK -- that contaminates the audit with the wrong
            // cause-code definition. Return null and skip the audit instead.
            return null;
        }

        // Alerts across the SITE around the incidence. Simultaneous alerts on other
        // assets are what separate a site-wide event from a local defect, and that
        // correlation has produced the strongest verdicts in testing.
        // v1.0.160.154 Layer A: THIS asset's own alert record over the lookback window --
        // ground-truth recurrence, distinct from the +/-2h SITE window (NewSiteAlertArgs).
        private static JObject NewAssetHistoryArgs(string siteId, string assetId, DateTime inc, int lookbackDays)
        {
            JObject o = new JObject();
            long n;
            // v1.0.160.155: SiteIds is REQUIRED by the tool schema (v1.0.118.0 note) -- .154 sent
            // AssetIds alone and the server refused with "SiteIds (int array) is required."
            if (long.TryParse(siteId, out n))
            {
                JArray s = new JArray();
                s.Add(n);
                o["SiteIds"] = s;
            }
            if (long.TryParse(assetId, out n))
            {
                JArray a = new JArray();
                a.Add(n);
                o["AssetIds"] = a;
            }
            o["FromDate"] = inc.AddDays(-lookbackDays).ToString("yyyy-MM-ddTHH:mm:ss");
            o["ToDate"] = inc.ToString("yyyy-MM-ddTHH:mm:ss");
            o["PageSize"] = 50;
            return o;
        }

        // v1.0.160.154 Layer A: extract the cause code from an FRS alert row. Explicit fields
        // first; else the LAST >=3-char double-quoted token in the description's head -- FRS
        // descriptions read <station>,"<asset>","<CAUSE>"..., station codes are 2 chars and drop
        // out, and nothing after the cause is quoted in the observed TC/SIG/PT shapes. Scan is
        // capped at 400 chars: causes appear early, and later free text must not hijack the pick.
        private static string FrsRowCause(JObject ro)
        {
            string cc = FirstStr(ro, "causeCode", "alertCode", "cause_code", "CauseCode", "AlertCode");
            if (!string.IsNullOrEmpty(cc))
            {
                return cc.Trim();
            }
            string desc = FirstStr(ro, "Description", "description");
            if (string.IsNullOrEmpty(desc))
            {
                return "";
            }
            string head = desc.Length > 400 ? desc.Substring(0, 400) : desc;
            string last = "";
            int i = 0;
            while (i < head.Length)
            {
                int q1 = head.IndexOf('"', i);
                if (q1 < 0)
                {
                    break;
                }
                int q2 = head.IndexOf('"', q1 + 1);
                if (q2 < 0)
                {
                    break;
                }
                string inner = head.Substring(q1 + 1, q2 - q1 - 1).Trim();
                if (inner.Length >= 3)
                {
                    last = inner;
                }
                i = q2 + 1;
            }
            return last;
        }

        // v1.0.160.154 Layer A: reduce the raw asset-history rows to the summary the prompt and
        // the story pie consume. Excludes the current alert; de-dupes by row id (SelectTokens can
        // revisit nested copies -- same guard as the triage counter).
        private JObject BuildAssetHistory(string raw, string currentAlertId, string causeNow, int lookbackDays)
        {
            try
            {
                List<JToken> docs = ParseJsonDocuments(raw);
                if (docs.Count == 0)
                {
                    return null;
                }
                System.Collections.Generic.HashSet<string> seen = new System.Collections.Generic.HashSet<string>(StringComparer.OrdinalIgnoreCase);
                JObject byCause = new JObject();
                int total = 0;
                int sameCause = 0;
                DateTime lastSame = DateTime.MinValue;
                double lastSameResetMin = -1.0;
                DateTime spanMin = DateTime.MaxValue;
                DateTime spanMax = DateTime.MinValue;
                for (int d = 0; d < docs.Count; d++)
                {
                    if (docs[d] == null)
                    {
                        continue;
                    }
                    foreach (JToken tok in docs[d].SelectTokens("$..*"))
                    {
                        if (tok == null || tok.Type != JTokenType.Object)
                        {
                            continue;
                        }
                        JObject ro = (JObject)tok;
                        string cause = FrsRowCause(ro);
                        if (string.IsNullOrEmpty(cause))
                        {
                            continue;
                        }
                        string rowId = FirstStr(ro, "Id", "id", "AlertId", "alertId");
                        if (!string.IsNullOrEmpty(currentAlertId) && !string.IsNullOrEmpty(rowId)
                            && string.Equals(rowId, currentAlertId, StringComparison.OrdinalIgnoreCase))
                        {
                            continue;
                        }
                        if (!string.IsNullOrEmpty(rowId))
                        {
                            if (seen.Contains(rowId))
                            {
                                continue;
                            }
                            seen.Add(rowId);
                        }
                        total++;
                        int prev = byCause[cause] != null ? (int)byCause[cause] : 0;
                        byCause[cause] = prev + 1;
                        DateTime setT;
                        bool haveSet = DateTime.TryParse(FirstStr(ro, "SetTimeStamp", "setTimeStamp"), out setT);
                        if (haveSet)
                        {
                            if (setT < spanMin)
                            {
                                spanMin = setT;
                            }
                            if (setT > spanMax)
                            {
                                spanMax = setT;
                            }
                        }
                        if (!string.IsNullOrEmpty(causeNow) && string.Equals(cause, causeNow, StringComparison.OrdinalIgnoreCase))
                        {
                            sameCause++;
                            if (haveSet && setT > lastSame)
                            {
                                lastSame = setT;
                                DateTime rstT;
                                if (DateTime.TryParse(FirstStr(ro, "ResetTimeStamp", "resetTimeStamp"), out rstT) && rstT > setT)
                                {
                                    lastSameResetMin = (rstT - setT).TotalMinutes;
                                }
                                else
                                {
                                    lastSameResetMin = -1.0;
                                }
                            }
                        }
                    }
                }
                if (total <= 0)
                {
                    return null;
                }
                JObject o = new JObject();
                o["windowDays"] = lookbackDays;
                o["total"] = total;
                o["sameCause"] = sameCause;
                o["byCause"] = byCause;
                if (spanMax != DateTime.MinValue)
                {
                    o["span"] = spanMin.ToString("dd.MM") + " .. " + spanMax.ToString("dd.MM.yyyy");
                }
                if (lastSame != DateTime.MinValue)
                {
                    o["lastSame"] = lastSame.ToString("dd.MM.yyyy HH:mm");
                    if (lastSameResetMin >= 0.0)
                    {
                        o["lastSameResetMin"] = Math.Round(lastSameResetMin);
                    }
                }
                // TRACK family rollup (design 6b Q2): exact cause stays the PRIMARY count; the
                // family total is one secondary line, and only when this alert is a TC cause.
                if (!string.IsNullOrEmpty(causeNow) && causeNow.TrimStart().StartsWith("TC ", StringComparison.OrdinalIgnoreCase))
                {
                    int fam = 0;
                    foreach (var p in byCause.Properties())
                    {
                        if (p.Name.TrimStart().StartsWith("TC ", StringComparison.OrdinalIgnoreCase))
                        {
                            fam += (int)p.Value;
                        }
                    }
                    o["trackFamily"] = fam;
                }
                return o;
            }
            catch
            {
                return null;
            }
        }

        // v1.0.160.154 Layer A: the evidence block. Numbers plus stated reading boundaries -- no
        // pre-baked severity score (design 6b Q3).
        private static string FormatAssetHistoryEvidence(JObject ah)
        {
            StringBuilder sb = new StringBuilder();
            sb.Append("[ASSET ALERT HISTORY - ").Append(ah["windowDays"]).Append("d, THIS asset only, field record (ground truth)]").Append("\n");
            sb.Append(" total alerts: ").Append(ah["total"]);
            JObject bc = ah["byCause"] as JObject;
            if (bc != null)
            {
                sb.Append(" across ").Append(bc.Count).Append(" causes");
            }
            if (ah["span"] != null)
            {
                sb.Append("; span ").Append(ah["span"]);
            }
            sb.Append("\n");
            sb.Append(" same-cause as this alert: ").Append(ah["sameCause"]).Append(" (current excluded)");
            if (ah["lastSame"] != null)
            {
                sb.Append("; last ").Append(ah["lastSame"]);
                sb.Append(ah["lastSameResetMin"] != null ? ", reset in " + ah["lastSameResetMin"] + " min" : ", no reset recorded");
            }
            sb.Append("\n");
            if (ah["trackFamily"] != null)
            {
                sb.Append(" track-health family total: ").Append(ah["trackFamily"]).Append("\n");
            }
            if (bc != null)
            {
                sb.Append(" by cause: ");
                bool firstP = true;
                foreach (var p in bc.Properties())
                {
                    if (!firstP)
                    {
                        sb.Append(", ");
                    }
                    sb.Append(p.Name).Append("=").Append(p.Value);
                    firstP = false;
                }
                sb.Append("\n");
            }
            sb.Append(" read: repeats that reset <15 min = transient/managed; 15-120 min = sustained-but-recovered;");
            sb.Append(" >120 min or never-reset = serious. Recurrence is CONTEXT; the electrical trend decides the verdict.");
            return sb.ToString();
        }

        // v1.0.160.162: the greeting header (owner option D). First name only, and only for a
        // logged-in session -- an anonymous view gets no name. TASK reassurance, not a personal
        // check-in: on a safety tool the calming line is what the tool is DOING, not "how are
        // you". Best-effort: any missing piece is simply dropped, and the whole thing is a
        // header that never affects the verdict.
        // withSynopsis=false at meta time (prefetch has not run, _assetHistory is null); a second
        // call with true is emitted once Layer A lands, so the synopsis is accurate, not guessed.
        // v1.0.160.167: railway-only scope for FREE-TEXT answers on the follow-up surface. Mirrors
        // ChatBot 1.2.9.3 exactly -- deliberately the same words, so the same question does not get
        // a different character depending on where it was asked. NOTE: this constrains what a plan
        // or defect list may CONTAIN; it does not touch the verdict's diagnosis fields, which must
        // still be able to name the measurement chain (see .165).
        private static string RailwayScopeRule()
        {
            return "\n\n=== RAILWAY MAINTENANCE SCOPE ===\n"
                 + "For railway maintenance, defect-list or action requests, output only defects "
                 + "belonging to railway signalling and field equipment: track circuits, rails, bonds, "
                 + "glued joints, relays, feed/TR circuits, signals and lamps, point machines, axle "
                 + "counters, IPS/batteries/chargers, field power supplies, cables and terminations. "
                 + "OMIT monitoring and telemetry conditions ENTIRELY -- modem/OFC/4G/TCP/MQTT "
                 + "connectivity, A10/datalogger/ADC health, gateway, LogWatch, reboots, RSSI, "
                 + "ingestion gaps: no section, heading, appendix, footnote or closing remark, and do "
                 + "not state that they were excluded, that they are stale, or that anyone should "
                 + "clear or acknowledge them. Say nothing about them at all. A power or "
                 + "communication fault is railway-side only when it affects railway signalling "
                 + "equipment, not the monitoring chain. Monitoring status is answered only when the "
                 + "request is ITSELF a question about the monitoring chain, asked on its own.\n"
                 + "=== END SCOPE ===";
        }

        // v1.0.160.167: plan shape + 15-day evidence + card output. Same text as ChatBot 1.2.9.5.
        private static string MaintenancePlanRule()
        {
            return "\n\n=== MAINTENANCE PLAN FORMAT ===\n"
                 + "A maintenance / daily-plan / what-to-attend request is one of TWO shapes. "
                 + "STATION PLAN (no asset named): rank the station's assets and report the ones "
                 + "needing attention. SINGLE ASSET (an asset is named): that asset only, in depth, "
                 + "no ranking.\n"
                 + "EVIDENCE -- gather over the LAST 15 DAYS for every asset you report, and state "
                 + "each item explicitly:\n"
                 + "1. Alert count in 15 days (get_frs_alerts, FromDate = today minus 15 days).\n"
                 + "2. Whether any alert is ACTIVE now (IsActive true / no ResetTimeStamp). An "
                 + "ACTIVE alert outranks a higher count that has fully reset.\n"
                 + "3. Improving vs degrading: split the 15 days in half and give BOTH numbers, "
                 + "e.g. 'degrading (2 -> 5)'. Never a bare adjective with no figures.\n"
                 + "4. ML classification: predict_track_health for track circuits, "
                 + "predict_pm_operation for point machines. Always label it as a model "
                 + "classification to confirm on site, never as an established fact.\n"
                 + "5. Point machines: the latest operation signature (avg / max current and "
                 + "operation time per end).\n"
                 + "PAGING: get_frs_alerts returns at most 50 rows per call. If Pager.TotalRecord "
                 + "exceeds the rows you received, call again with Skip / CurrentPage until the "
                 + "window is covered. If you cannot cover it, say so on the card -- write "
                 + "'ranking partial: N of TotalRecord alerts read' rather than presenting an "
                 + "incomplete count as complete.\n"
                 + "ORDER: 1 active alert now = URGENT; 2 degrading with a high 15-day count = "
                 + "URGENT; 3 high count but stable = INSPECT SOON; 4 ML flag with a low count = "
                 + "INSPECT SOON; 5 resolved or healthy = MONITOR.\n"
                 + "OUTPUT -- one CARD per asset, in this EXACT block form, and nothing else "
                 + "between the markers:\n"
                 + "[[CARD]] priority=URGENT | asset=PT-115/116 | type=Point Machine | site=SAKHUN\n"
                 + "15-DAY: 7 alerts; 2 active; degrading (2 -> 5)\n"
                 + "ML: Machine A 72.7% faulty; obstruction 27.3%; Machine B healthy\n"
                 + "LASTOP: A 2.30 A avg / 5.02 A max / 2.88 s; B 2.42 A avg / 5.98 A max / 2.92 s\n"
                 + "ACTION: Inspect PT-115 switch mechanism for blockage; check slide-chair "
                 + "friction and stroke-end lubrication\n"
                 + "NOTE: model classification -- confirm with the waveform on site\n"
                 + "[[/CARD]]\n"
                 + "priority is URGENT, INSPECT SOON or MONITOR. Omit a line whose data you do not "
                 + "have -- never invent one, and never write a placeholder. Put every MONITOR "
                 + "asset in ONE card with priority=MONITOR, listing them as short lines. Write at "
                 + "most 8 URGENT/INSPECT SOON cards. A short sentence before or after the cards is "
                 + "fine; the per-asset detail belongs INSIDE a card, not in prose.\n"
                 + "=== END PLAN FORMAT ===";
        }

        private string BuildGreeting(JObject ctx, bool withSynopsis)
        {
            if (string.Equals(_greetTone, "off", StringComparison.OrdinalIgnoreCase))
            {
                return "";
            }
            // Name + honorific: "Anil sir", "Siddharth sir" (owner). Logged-in sessions only;
            // an anonymous view simply drops the name. honorific="none" gives the bare name.
            string first = "";
            string full = (_luName ?? "").Trim();
            if (full.Length > 0)
            {
                int sp = full.IndexOf(' ');
                first = sp > 0 ? full.Substring(0, sp) : full;
            }
            string named = first;
            if (first.Length > 0 && !string.IsNullOrEmpty(_greetHonorific)
                && !string.Equals(_greetHonorific, "none", StringComparison.OrdinalIgnoreCase))
            {
                named = first + " " + _greetHonorific.Trim();
            }

            string tod = "Hello";
            try
            {
                int h = (DateTime.UtcNow + _istOffset).Hour;
                if (h < 12) { tod = "Good morning"; }
                else if (h < 17) { tod = "Good afternoon"; }
                else { tod = "Good evening"; }
            }
            catch { }

            string asset = GetCtx(ctx, "assetName");
            string station = GetCtx(ctx, "station");
            string alertType = GetCtx(ctx, "alertType");
            bool isFailure = alertType.IndexOf("fail", StringComparison.OrdinalIgnoreCase) >= 0;

            // Humour is allowed only when tone=light AND the alert is NOT a failure AND either it
            // has already reset (finished history, low stakes) or Layer A shows this asset is a
            // repeat visitor. A live failure or a firm confirmation never gets a light line.
            bool reset = GetCtx(ctx, "resetTime").Trim().Length > 0;
            bool light = string.Equals(_greetTone, "light", StringComparison.OrdinalIgnoreCase) && !isFailure;

            StringBuilder sb = new StringBuilder();
            sb.Append(tod);
            if (named.Length > 0)
            {
                sb.Append(", ").Append(named);
            }
            sb.Append(". ");

            int same = -1;
            if (withSynopsis && _assetHistory != null)
            {
                try { if (_assetHistory["sameCause"] != null) { same = (int)_assetHistory["sameCause"]; } }
                catch { same = -1; }
            }

            // The asset line -- a dry, still-deferential touch only where it is safe.
            bool usedLight = false;
            if (light && asset.Length > 0 && same >= 2)
            {
                sb.Append(asset).Append(" once more");
                if (station.Length > 0) { sb.Append(" at ").Append(station); }
                sb.Append(" -- this asset and I are well acquainted by now. ");
                usedLight = true;
            }
            else if (light && asset.Length > 0 && reset && withSynopsis && same == 0)
            {
                sb.Append(asset);
                if (station.Length > 0) { sb.Append(" at ").Append(station); }
                sb.Append(" -- already reset, and nothing on its record. A quiet one, thankfully. ");
                usedLight = true;
            }
            else
            {
                if (asset.Length > 0)
                {
                    sb.Append("Analysing ").Append(asset);
                    if (station.Length > 0) { sb.Append(" at ").Append(station); }
                    sb.Append(isFailure ? " -- this needs a careful look. " : " for you. ");
                }
                else
                {
                    sb.Append("Analysing this alert. ");
                }
            }

            // Synopsis line -- plain and factual, appended when Layer A has landed. Skipped when a
            // light asset line already conveyed the recurrence, to avoid saying it twice.
            if (withSynopsis && _assetHistory != null && same >= 0 && !usedLight)
            {
                int days = _assetHistDays;
                if (same > 0)
                {
                    sb.Append(same == 1
                        ? "This asset raised this cause once before in the last " + days + " days. "
                        : "This asset has raised this cause " + same + " times in the last " + days + " days. ");
                }
                else
                {
                    sb.Append("No earlier alert of this cause on this asset in the last " + days + " days. ");
                }
            }

            // Task reassurance -- courteous, about what the tool is doing. Keyed off alertId so it
            // is stable per alert. A failure gets the steadiest of the phrasings.
            string[] rea = new string[]
            {
                "I have pulled its telemetry, history and ML evidence -- a moment, please, while I correlate them.",
                "Cross-checking the last few days of telemetry against this asset's baseline now.",
                "Reviewing the site's alerts and this asset's record before I commit to a verdict.",
                "Working carefully through the derived-value components and the field history."
            };
            int pick = isFailure ? 0 : 3;
            try
            {
                string aid = GetCtx(ctx, "alertId");
                long an;
                if (long.TryParse(aid, out an) && !isFailure) { pick = (int)(Math.Abs(an) % rea.Length); }
            }
            catch { }
            sb.Append(rea[pick]);
            return sb.ToString();
        }

        private static JObject NewSiteAlertArgs(string siteId, DateTime inc)
        {
            JObject o = new JObject();
            long n;
            if (long.TryParse(siteId, out n)) { JArray a = new JArray(); a.Add(n); o["SiteIds"] = a; }
            // v1.0.160.129: ISO, NOT _ddFmt. get_frs_alerts is the one tool in the catalog that
            // takes yyyy-MM-ddTHH:mm:ss; sending ddMMyyyy_HHmmss made the server drop the window
            // entirely and return an unfiltered page.
            o["FromDate"] = inc.AddHours(-2).ToString("yyyy-MM-ddTHH:mm:ss");
            o["ToDate"] = inc.AddHours(1).ToString("yyyy-MM-ddTHH:mm:ss");
            o["PageSize"] = 25;
            return o;
        }

        // v1.0.118.0: get_frs_alerts probe args for DryRunTools (tool-health check, no incidence
        // time). SiteIds/AssetIds are ARRAYS per the declared schema (required: SiteIds). Prefer
        // SiteId; fall back to AssetIds if only an asset is known.
        // v1.0.160.180: LIVE reset re-check for the CACHE-SERVE path. A verdict cached while the
        // alert was ACTIVE stored an empty resetTime; if the alert has since RESET, the served panel
        // still announces "Still active" on a cleared fault. This fetches the CURRENT FRS row for
        // THIS alert and reports its reset state so the serve path can override the frozen value.
        // Returns: a non-empty stamp (dd/MM/yyyy HH:mm:ss) => RESET now; "" => row found, still
        // ACTIVE; null => cannot determine (no site/asset id, call failed, row absent) -> leave the
        // cached value untouched, never regress a good serve on a transient fetch failure.
        private async Task<string> TryLiveResetTimeAsync(JObject ctx, System.Threading.CancellationToken ct)
        {
            try
            {
                string siteId = GetCtx(ctx, "siteId");
                string assetId = GetCtx(ctx, "assetId");
                string wantId = GetCtx(ctx, "alertId");
                if (wantId.Length == 0) { return null; }
                if (siteId.Length == 0 && assetId.Length == 0) { return null; }
                string alerts = await CallToolRoutedAsync("get_frs_alerts", NewFrsAlertsProbeArgs(siteId, assetId), ct).ConfigureAwait(false);
                if (string.IsNullOrEmpty(alerts)) { return null; }
                JObject ao = JObject.Parse(alerts);
                JArray rows = ao["mFRSAlerts"] as JArray;
                if (rows == null) { return null; }
                for (int ri = 0; ri < rows.Count; ri++)
                {
                    JObject r = rows[ri] as JObject;
                    if (r == null || r["Id"] == null) { continue; }
                    if (!string.Equals(r["Id"].ToString(), wantId, StringComparison.Ordinal)) { continue; }
                    JToken rt = r["ResetTimeStamp"];
                    if (rt == null || rt.Type == JTokenType.Null) { return ""; }   // found, still active
                    DateTime rtd;
                    if (DateTime.TryParse(rt.ToString(), System.Globalization.CultureInfo.InvariantCulture,
                            System.Globalization.DateTimeStyles.None, out rtd))
                    { return rtd.ToString("dd/MM/yyyy HH:mm:ss"); }
                    return "";
                }
                return null;   // this alert was not in the returned page
            }
            catch { return null; }
        }

        private static JObject NewFrsAlertsProbeArgs(string siteId, string assetId)
        {
            JObject o = new JObject();
            long n;
            if (!string.IsNullOrWhiteSpace(siteId) && long.TryParse(siteId, out n))
            { JArray a = new JArray(); a.Add(n); o["SiteIds"] = a; }
            else if (!string.IsNullOrWhiteSpace(assetId) && long.TryParse(assetId, out n))
            { JArray a = new JArray(); a.Add(n); o["AssetIds"] = a; }
            o["PageSize"] = 20;
            return o;
        }

        // v1.0.86.0: static, side-effect-free check of whether the card's triggered
        // condition is derived -- usable before the _derivedAlert field is set (the
        // prefetch search_tags call needs it to suppress AttributeName narrowing).
        private static bool IsDerivedCard(JObject ctx)
        {
            string p, f;
            return DetectDerived(ctx, out p, out f);
        }

        // v1.0.82.0 rev J: is this alert's triggered attribute DERIVED (a formula
        // over component tags, e.g. RRAIL)? Reads triggeredConditions[0]:
        //   "type":"derived"  and/or a "formula" field. Returns the formula (or null)
        // and the paramLabel. Derived attributes have NO telemetry tag of their own.
        private static bool DetectDerived(JObject ctx, out string param, out string formula)
        {
            param = null; formula = null;
            if (ctx == null) { return false; }
            JToken card = ctx["alertCard"];
            if (card == null || card.Type != JTokenType.Object) { return false; }
            JToken tc = card["triggeredConditions"];
            if (tc == null || tc.Type != JTokenType.Array || ((JArray)tc).Count == 0) { return false; }
            JObject cond = ((JArray)tc)[0] as JObject;
            if (cond == null) { return false; }
            JToken p = cond["paramLabel"];
            if (p != null) { param = p.ToString().Trim(); }
            JToken f = cond["formula"];
            if (f != null && f.Type != JTokenType.Null) { formula = f.ToString(); }
            JToken t = cond["type"];
            bool typed = t != null && string.Equals(t.ToString(), "derived", StringComparison.OrdinalIgnoreCase);
            return typed || !string.IsNullOrEmpty(formula);
        }

        // v1.0.88.0: evaluate a derived formula (the card's own formula string) over the
        // components' as-of values. Grammar is exactly what the formulas use: numbers,
        // component identifiers (aliases), the 4 binary ops + - * /, parentheses, and
        // unary minus. Shunting-yard to RPN, then evaluate. The component map is keyed
        // by the CANONICAL names ExtractFormulaComponents produced; the formula's alias
        // tokens are canonicalised the same way (DomainAttributeName) before lookup, so
        // "ITC FEED END(mA)" in the formula resolves to the same key as the component
        // "If mA". Division-by-zero or any unknown token -> false (no wrong number).
        private static bool TryEvalFormula(string formula, Dictionary<string, double> vals, out double result)
        {
            result = double.NaN;
            if (string.IsNullOrEmpty(formula)) { return false; }
            string rhs = formula;
            int eq = formula.IndexOf('=');
            if (eq >= 0 && eq + 1 < formula.Length) { rhs = formula.Substring(eq + 1); }
            // tokenize: numbers, identifiers (letters/digits/space/slash/dot), operators, parens
            List<string> toks = new List<string>();
            int i = 0; int n = rhs.Length;
            while (i < n)
            {
                char c = rhs[i];
                if (char.IsWhiteSpace(c)) { i++; continue; }
                if (c == '(' || c == ')' || c == '+' || c == '-' || c == '*' || c == '/')
                { toks.Add(c.ToString()); i++; continue; }
                if (char.IsDigit(c) || c == '.')
                {
                    int j = i; while (j < n && (char.IsDigit(rhs[j]) || rhs[j] == '.')) { j++; }
                    toks.Add(rhs.Substring(i, j - i)); i = j; continue;
                }
                if (char.IsLetter(c))
                {
                    int j = i;
                    while (j < n && (char.IsLetterOrDigit(rhs[j]) || rhs[j] == ' ' || rhs[j] == '/' || rhs[j] == '.'))
                    { j++; }
                    // trim a trailing "(unit)" that may have been attached
                    string id = rhs.Substring(i, j - i).Trim();
                    // if the identifier is immediately followed by "(x)" unit, skip it
                    if (j < n && rhs[j] == '(')
                    {
                        int k = rhs.IndexOf(')', j);
                        if (k > j && k - j <= 6) { j = k + 1; }   // short (unit) only
                    }
                    toks.Add("$" + id); i = j; continue;
                }
                return false;   // unexpected char
            }
            // shunting-yard
            List<string> outq = new List<string>();
            Stack<string> ops = new Stack<string>();
            string prev = null;
            for (int t = 0; t < toks.Count; t++)
            {
                string tok = toks[t];
                if (tok.StartsWith("$"))
                {
                    string key = DomainAttributeName(tok.Substring(1));
                    double dv;
                    if (key != null && vals.TryGetValue(key, out dv)) { outq.Add(dv.ToString("R", System.Globalization.CultureInfo.InvariantCulture)); }
                    else if (vals.TryGetValue(tok.Substring(1), out dv)) { outq.Add(dv.ToString("R", System.Globalization.CultureInfo.InvariantCulture)); }
                    else { return false; }   // unknown component -> cannot compute
                    prev = "num"; continue;
                }
                double num;
                if (double.TryParse(tok, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out num))
                { outq.Add(tok); prev = "num"; continue; }
                if (tok == "(") { ops.Push(tok); prev = "("; continue; }
                if (tok == ")")
                {
                    while (ops.Count > 0 && ops.Peek() != "(") { outq.Add(ops.Pop()); }
                    if (ops.Count == 0) { return false; }
                    ops.Pop(); prev = "num"; continue;
                }
                // operator; detect unary minus (start, after '(' or after another operator)
                bool unary = tok == "-" && (prev == null || prev == "(" || prev == "op");
                string op = unary ? "u-" : tok;
                while (ops.Count > 0 && ops.Peek() != "(" && Prec(ops.Peek()) >= Prec(op) && op != "u-")
                { outq.Add(ops.Pop()); }
                ops.Push(op); prev = "op"; continue;
            }
            while (ops.Count > 0) { string op = ops.Pop(); if (op == "(") { return false; } outq.Add(op); }
            // evaluate RPN
            Stack<double> st = new Stack<double>();
            for (int t = 0; t < outq.Count; t++)
            {
                string tok = outq[t];
                double num;
                if (double.TryParse(tok, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out num))
                { st.Push(num); continue; }
                if (tok == "u-") { if (st.Count < 1) { return false; } st.Push(-st.Pop()); continue; }
                if (st.Count < 2) { return false; }
                double b = st.Pop(); double a = st.Pop();
                if (tok == "+") { st.Push(a + b); }
                else if (tok == "-") { st.Push(a - b); }
                else if (tok == "*") { st.Push(a * b); }
                else if (tok == "/") { if (Math.Abs(b) < 1e-12) { return false; } st.Push(a / b); }
                else { return false; }
            }
            if (st.Count != 1) { return false; }
            double r = st.Pop();
            if (double.IsNaN(r) || double.IsInfinity(r)) { return false; }
            result = r; return true;
        }

        private static int Prec(string op)
        {
            if (op == "u-") { return 3; }
            if (op == "*" || op == "/") { return 2; }
            if (op == "+" || op == "-") { return 1; }
            return 0;
        }

        // v1.0.90.0: render a COMPACT, human-readable window of a component's history
        // around the incidence, instead of dumping raw epoch arrays the model can't read.
        // Since 1.0.88 the controller already computes+supplies the as-of value, age, and
        // the derived value, so the model no longer needs the full 300-sample series -- it
        // needs a short readable trend around the incidence (to judge development/recovery).
        // Emits up to `keep` samples straddling the incidence: the last few BEFORE and the
        // first few AFTER, as "HH:MM:SS=value". Falls back to empty on parse failure (the
        // reduced raw tail still follows as a safety net).
        private static string CompactWindow(string histJson, DateTime incidence, int keep)
        {
            if (string.IsNullOrEmpty(histJson)) { return ""; }
            try
            {
                JObject o = JObject.Parse(histJson);
                JToken tsT = o["ts"]; JToken vT = o["v"];
                if (tsT == null || vT == null || tsT.Type != JTokenType.Array || vT.Type != JTokenType.Array)
                { return ""; }
                JArray ts = (JArray)tsT; JArray v = (JArray)vT;
                int n = Math.Min(ts.Count, v.Count);
                if (n == 0) { return ""; }
                long inc = ToUnixSeconds(incidence);
                // find split: last index with ts <= incidence
                int split = -1;
                long[] tt = new long[n]; string[] vv = new string[n];
                for (int i = 0; i < n; i++)
                {
                    long t; long.TryParse(ts[i].ToString(), out t); tt[i] = t;
                    vv[i] = v[i].ToString();
                    if (t <= inc) { split = i; }
                }
                int half = keep / 2;
                int startB = Math.Max(0, (split < 0 ? 0 : split) - half + 1);
                int endA = Math.Min(n - 1, (split < 0 ? -1 : split) + half);
                StringBuilder w = new StringBuilder();
                for (int i = startB; i <= endA && i < n; i++)
                {
                    if (i < 0) { continue; }
                    DateTimeOffset dto = DateTimeOffset.FromUnixTimeSeconds(tt[i]).ToOffset(TimeSpan.FromHours(5.5));
                    w.Append(dto.ToString("HH:mm:ss")).Append("=").Append(vv[i]);
                    if (i == split) { w.Append("<-as-of"); }
                    w.Append("  ");
                }
                return w.ToString().TrimEnd();
            }
            catch { return ""; }
        }

        // v1.0.88.0: COV-correct as-of extraction. The history API is change-of-value:
        // a row appears only when the value CHANGES. If nothing changed in the window,
        // it returns the last-known value as bracket rows (confirmed empirically: a
        // 10:00-11:00 request returned n=2 identical rows both stamped 05:17 -- the
        // steady value carried forward). So "no row inside the window" means STEADY,
        // not missing. This parses the columnar {ts,v} and returns the value of the
        // last sample with ts <= incidence (the as-of / carried-forward value), its
        // age in seconds, whether the window was bracket-only (steady), and how many
        // rows fell strictly inside the window. Returns false only when NO row at all
        // is <= incidence (the single genuine no-data case).
        // v1.0.109.0: mean of a columnar {ts:[],v:[]} history series - used as a component's
        // baseline for the derived_inputs drift %. Parses the same shape AsOfValue does.
        private static bool SeriesMean(string histJson, out double mean)
        {
            mean = double.NaN;
            if (string.IsNullOrEmpty(histJson)) { return false; }
            try
            {
                JObject o = JObject.Parse(histJson);
                JToken vT = o["v"];
                if (vT == null || vT.Type != JTokenType.Array) { return false; }
                JArray v = (JArray)vT;
                // v1.0.160.101: MEDIAN, not mean. A track circuit alternates between resting and
                // train-shunted; the mean of both modes describes neither, and comparing a resting
                // at-alert value against it manufactures deviations -- and can invert their sign.
                List<double> acc = new List<double>();
                for (int i = 0; i < v.Count; i++)
                {
                    double val;
                    if (double.TryParse(v[i].ToString(), System.Globalization.NumberStyles.Any,
                            System.Globalization.CultureInfo.InvariantCulture, out val))
                    { acc.Add(val); }
                }
                if (acc.Count == 0) { return false; }
                acc.Sort();
                int m = acc.Count;
                mean = (m % 2 == 1) ? acc[m / 2] : (acc[(m / 2) - 1] + acc[m / 2]) / 2.0;
                return true;
            }
            catch { return false; }
        }

        private static bool AsOfValue(string histJson, DateTime incidence,
            out double asOf, out long ageSec, out bool bracketOnly, out int inWindow, out int nRows)
        {
            asOf = double.NaN; ageSec = -1; bracketOnly = false; inWindow = 0; nRows = 0;
            if (string.IsNullOrEmpty(histJson)) { return false; }
            try
            {
                JObject o = JObject.Parse(histJson);
                JToken tsT = o["ts"]; JToken vT = o["v"];
                if (tsT == null || vT == null || tsT.Type != JTokenType.Array || vT.Type != JTokenType.Array)
                { return false; }
                JArray ts = (JArray)tsT; JArray v = (JArray)vT;
                nRows = Math.Min(ts.Count, v.Count);
                if (nRows == 0) { return false; }
                long incEpoch = ToUnixSeconds(incidence);
                long fromEpoch = o["from"] != null ? (long)o["from"] : long.MinValue;
                long asOfTs = long.MinValue; double asOfVal = double.NaN; bool have = false;
                for (int i = 0; i < nRows; i++)
                {
                    long t; double val;
                    if (!long.TryParse(ts[i].ToString(), out t)) { continue; }
                    if (!double.TryParse(v[i].ToString(), System.Globalization.NumberStyles.Any,
                            System.Globalization.CultureInfo.InvariantCulture, out val)) { continue; }
                    if (fromEpoch != long.MinValue && t > fromEpoch) { inWindow++; }
                    if (t <= incEpoch && (!have || t >= asOfTs)) { asOfTs = t; asOfVal = val; have = true; }
                }
                if (!have) { return false; }   // no value at/before incidence = true no-data
                asOf = asOfVal;
                ageSec = incEpoch - asOfTs;
                // bracket-only (steady): the caller's detection rule -- few rows AND all
                // rows at/before the window start (i.e. none strictly inside the window).
                bracketOnly = (inWindow == 0);
                return true;
            }
            catch { return false; }
        }

        // v1.0.160.103: result of the previous-in-envelope comparison for one derived component.
        private sealed class DerivedCompare
        {
            public double AtVal;              // at-alert value (ALWAYS set; never envelope-gated)
            public long AtTs;                 // Unix epoch seconds of the at-alert sample
            public long AtAgeSec;             // anchor-relative age of the at-alert sample (anchor - AtTs)
            public bool StaleAtSample;        // v1.0.160.109: at-sample older than AtSampleMaxAgeMin
            public bool CurrentOutside;       // at-alert value is outside the configured envelope (possible genuine step)
            public bool HasRef;               // a previous in-envelope reference was found
            public double RefVal;             // reference value
            public long RefTs;                // Unix epoch seconds of the reference sample
            public long RefAgeSec;            // incidence-relative age of the reference (anchor - refTs)
            public bool HasDelta;             // deltaPct is valid (reference non-zero)
            public double DeltaPct;           // (AtVal - RefVal)/|RefVal|*100
            public string Kind;               // "in_envelope" (track) | "previous_sample" (non-track)
            public string Reason;             // explanatory string when no delta
        }

        // v1.0.160.104: resolve a component's TagID AND AssetAttributeId from the SAME search_tags
        // row, so the history tag and the envelope lookup are guaranteed to reference the same
        // attribute (not two independent scans that could match different rows). tag=null / attid=-1
        // when unresolved. Mirrors the tag resolver's two matching passes.
        private static void ResolveTagAndAttidForAsset(string tagsJson, string canonical, string assetId, out string tag, out int attid)
        {
            tag = null; attid = -1;
            if (string.IsNullOrEmpty(tagsJson) || string.IsNullOrEmpty(canonical)) { return; }
            List<string> wants = new List<string> { canonical };
            if (canonical.StartsWith("TR V")) { wants.Add("VR"); wants.Add("TR V"); }
            try
            {
                List<JToken> docs = ParseJsonDocuments(tagsJson);
                for (int pass = 0; pass < 2; pass++)
                {
                    for (int d = 0; d < docs.Count; d++)
                    {
                        foreach (JToken row in docs[d].SelectTokens("$..*"))
                        {
                            JObject o = row as JObject;
                            if (o == null) { continue; }
                            JToken nm = PropCI(o, "AssetAttributeName");
                            JToken tid = PropCI(o, "TagID") ?? PropCI(o, "TagId");
                            if (nm == null || tid == null) { continue; }
                            if (!RowAssetOk(o, assetId, false)) { continue; }
                            string upper = nm.ToString().ToUpperInvariant().Trim();
                            for (int w = 0; w < wants.Count; w++)
                            {
                                bool hit = pass == 0
                                    ? upper == wants[w]
                                    : (upper.IndexOf(wants[w], StringComparison.Ordinal) >= 0 || wants[w].IndexOf(upper, StringComparison.Ordinal) >= 0);
                                if (hit)
                                {
                                    tag = tid.ToString();
                                    JToken aid = PropCI(o, "AssetAttributeId");
                                    int parsed;
                                    if (aid != null && int.TryParse(aid.ToString(), out parsed)) { attid = parsed; }
                                    return;
                                }
                            }
                        }
                    }
                }
            }
            catch { }
        }

        // v1.0.160.103: resolve the configured operating bounds for (assetId, attid) from the
        // get_attribute_range payload. Handles BOTH the compact NarrowAttributeRange shape
        // (rows[]: a/t/min/max/fail) and the raw shape (AssetId/AssetAttributeId/MinSafeValue/
        // MaxSafeValue/MinFailValue), matching on BOTH asset and attribute. minFail is NaN when the
        // configured value is null (caller applies a floor). Returns false -> fail closed.
        private static bool RangeBoundsForAsset(string rangeJson, string assetId, int attid, out double minSafe, out double maxSafe, out double minFail)
        {
            minSafe = double.NaN; maxSafe = double.NaN; minFail = double.NaN;
            if (string.IsNullOrEmpty(rangeJson) || attid < 0) { return false; }
            try
            {
                List<JToken> docs = ParseJsonDocuments(rangeJson);
                for (int d = 0; d < docs.Count; d++)
                {
                    foreach (JToken row in docs[d].SelectTokens("$..*"))
                    {
                        JObject o = row as JObject;
                        if (o == null) { continue; }
                        JToken tTok = PropCI(o, "t") ?? PropCI(o, "AssetAttributeId");
                        if (tTok == null) { continue; }
                        int rowAttid;
                        if (!int.TryParse(tTok.ToString(), out rowAttid) || rowAttid != attid) { continue; }
                        JToken aTok = PropCI(o, "a") ?? PropCI(o, "AssetId");
                        // Fix 5: match on BOTH asset and attribute. A row without a resolvable AssetId
                        // is NOT accepted (fail closed) so bounds are never taken from another asset.
                        if (aTok == null || (!string.IsNullOrEmpty(assetId) && aTok.ToString() != assetId)) { continue; }
                        JToken maxTok = PropCI(o, "max") ?? PropCI(o, "MaxSafeValue");
                        JToken minTok = PropCI(o, "min") ?? PropCI(o, "MinSafeValue");
                        JToken failTok = PropCI(o, "fail") ?? PropCI(o, "MinFailValue");
                        double mx, mn;
                        if (maxTok == null || !double.TryParse(maxTok.ToString(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out mx)) { continue; }
                        if (minTok == null || !double.TryParse(minTok.ToString(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out mn)) { continue; }
                        maxSafe = mx; minSafe = mn;
                        double fl;
                        if (failTok != null && failTok.Type != JTokenType.Null && double.TryParse(failTok.ToString(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out fl)) { minFail = fl; }
                        return true;
                    }
                }
            }
            catch { }
            return false;
        }

        // v1.0.160.103: a value is IN-ENVELOPE when it lies within the configured operating band.
        // When MinFail is not configured, the floor is half of MinSafe. This excludes track-shunt
        // samples in BOTH directions (current rises above MaxSafe, voltage/relay current falls below
        // the floor) without any TPR timestamp alignment.
        private static bool InEnvelope(double v, double minSafe, double maxSafe, double minFail)
        {
            double floor = !double.IsNaN(minFail) ? minFail : (minSafe * 0.5);
            return v >= floor && v <= maxSafe;
        }

        // v1.0.160.103: the movement-panel comparator. Selects the at-alert sample (latest ts <=
        // anchor; ALWAYS returned, never envelope-gated) and, for track assets, the latest earlier
        // sample whose value is IN-ENVELOPE within maxAge (measured from the at-alert sample). For
        // non-track assets the reference is simply the immediately-preceding sample. Fails closed
        // (reason) when the envelope is unavailable, when no comparable reference exists, or when the
        // reference is zero. Parses the columnar {ts:[],v:[]} shape AsOfValue uses.
        private static DerivedCompare PrevInEnvelopeSample(string cHist, long anchorEpoch, long incidenceEpoch, bool trackAsset,
            bool haveBounds, double minSafe, double maxSafe, double minFail, long maxAgeSec)
        {
            if (string.IsNullOrEmpty(cHist)) { return null; }
            try
            {
                JObject o = JObject.Parse(cHist);
                JToken tsT = o["ts"]; JToken vT = o["v"];
                if (tsT == null || vT == null || tsT.Type != JTokenType.Array || vT.Type != JTokenType.Array) { return null; }
                JArray ts = (JArray)tsT; JArray v = (JArray)vT;
                int nRows = Math.Min(ts.Count, v.Count);
                if (nRows == 0) { return null; }
                List<long> rt = new List<long>();
                List<double> rv = new List<double>();
                for (int i = 0; i < nRows; i++)
                {
                    long t; double val;
                    if (!long.TryParse(ts[i].ToString(), out t)) { continue; }
                    if (!double.TryParse(v[i].ToString(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out val)) { continue; }
                    rt.Add(t); rv.Add(val);
                }
                if (rt.Count == 0) { return null; }
                // sort ascending by ts (the source may be desc)
                int[] idx = new int[rt.Count];
                for (int i = 0; i < idx.Length; i++) { idx[i] = i; }
                Array.Sort(idx, delegate(int a, int b) { return rt[a].CompareTo(rt[b]); });
                // at-alert = latest ts <= anchor
                int atPos = -1;
                for (int i = 0; i < idx.Length; i++)
                {
                    if (rt[idx[i]] <= anchorEpoch) { atPos = i; }
                    else { break; }
                }
                if (atPos < 0) { return null; }
                DerivedCompare dc = new DerivedCompare();
                dc.AtTs = rt[idx[atPos]];
                dc.AtVal = rv[idx[atPos]];
                dc.AtAgeSec = anchorEpoch - dc.AtTs;   // anchor-relative staleness of the DISPLAYED value
                // v1.0.160.109 CUT A (SL 1): fail closed on a stale at-alert sample. Cut A's sort fix
                // removes the cause seen in 543194, but a GENUINE data outage (e.g. the real 8 h
                // Charger mA gap on 11 Aug) can still leave nothing near the anchor. Saying "no
                // comparable reading" is correct; publishing a movement from day-old data is not.
                if (dc.AtAgeSec > (long)_atSampleMaxAgeMin * 60L)
                {
                    dc.StaleAtSample = true;
                    dc.Kind = "no_recent_sample";
                }
                dc.Kind = trackAsset ? "in_envelope" : "previous_sample";
                if (trackAsset && !haveBounds)
                {
                    dc.Reason = "configured envelope unavailable";
                    return dc;
                }
                if (trackAsset)
                {
                    dc.CurrentOutside = !InEnvelope(dc.AtVal, minSafe, maxSafe, minFail);
                }
                // reference = latest EARLIER sample; track -> must be in-envelope; within maxAge of at-alert
                int refPos = -1;
                for (int i = atPos - 1; i >= 0; i--)
                {
                    long candTs = rt[idx[i]];
                    // Fix 4: enforce strict candTs < atTs -- duplicate timestamps must never become a
                    // same-time reference (which would print a spurious 0% or an invalid comparison).
                    if (candTs >= dc.AtTs) { continue; }
                    if (dc.AtTs - candTs > maxAgeSec) { break; }
                    double candV = rv[idx[i]];
                    if (trackAsset && !InEnvelope(candV, minSafe, maxSafe, minFail)) { continue; }
                    refPos = i;
                    break;
                }
                if (refPos < 0)
                {
                    dc.Reason = "no recent comparable reading";
                    return dc;
                }
                dc.HasRef = true;
                dc.RefTs = rt[idx[refPos]];
                dc.RefVal = rv[idx[refPos]];
                dc.RefAgeSec = incidenceEpoch - dc.RefTs;   // incidence-relative age (design schema: incidence - referenceTs)
                if (Math.Abs(dc.RefVal) < 1e-9)
                {
                    dc.Reason = "previous comparable reading is zero; percentage unavailable";
                    return dc;
                }
                dc.HasDelta = true;
                dc.DeltaPct = (dc.AtVal - dc.RefVal) / Math.Abs(dc.RefVal) * 100.0;
                return dc;
            }
            catch { return null; }
        }

        // v1.0.160.103: the MAIN triggered-condition timestamp from the alert card
        // (alertCard.triggeredConditions[type=="main"].time), used to anchor the movement panel on
        // the real trigger sample rather than the (possibly later) stamped incidence. Null when absent.
        private static string MainTriggeredTime(JObject ctx)
        {
            try
            {
                JToken card = ctx != null ? ctx["alertCard"] : null;
                JToken tc = card != null ? card["triggeredConditions"] : null;
                if (tc == null || tc.Type != JTokenType.Array) { return null; }
                JArray arr = (JArray)tc;
                for (int i = 0; i < arr.Count; i++)
                {
                    JObject cnd = arr[i] as JObject;
                    if (cnd == null) { continue; }
                    JToken ty = cnd["type"];
                    if (ty != null && string.Equals(ty.ToString(), "main", StringComparison.OrdinalIgnoreCase) && cnd["time"] != null)
                    {
                        return cnd["time"].ToString();
                    }
                }
            }
            catch { }
            return null;
        }

        // v1.0.160.104: the AUTHORITATIVE derived value AND its matching limit from the alert card.
        // Selects the triggered condition whose paramLabel canonicalizes to the derived param
        // (IBALST/RRAIL); falls back to the type=="main" condition. Parses 'measured' directly (already
        // unit-free) -- never the unit-appended dMeasured string. Also returns the FAILing threshold
        // from the SAME condition (its value/unit and whether the breach is above or below), so the
        // derived hero pairs the derived value with ITS OWN limit -- not the model viz.metric's limit
        // (on 527969 viz.metric is ITC RELAY END while the derived param is IBALST).
        private static bool CardDerivedValue(JObject ctx, string derivedParam, out double val,
            out double limit, out bool haveLimit, out string limitUnit, out bool breachAbove)
        {
            val = double.NaN; limit = double.NaN; haveLimit = false; limitUnit = null; breachAbove = true;
            try
            {
                JToken card = ctx != null ? ctx["alertCard"] : null;
                JToken tc = card != null ? card["triggeredConditions"] : null;
                if (tc == null || tc.Type != JTokenType.Array) { return false; }
                JArray arr = (JArray)tc;
                string wantParam = string.IsNullOrEmpty(derivedParam) ? null : derivedParam.ToUpperInvariant().Trim();
                JObject mainCnd = null;
                for (int i = 0; i < arr.Count; i++)
                {
                    JObject cnd = arr[i] as JObject;
                    if (cnd == null) { continue; }
                    JToken ty = cnd["type"];
                    if (ty != null && string.Equals(ty.ToString(), "main", StringComparison.OrdinalIgnoreCase) && mainCnd == null) { mainCnd = cnd; }
                    if (wantParam == null) { continue; }
                    JToken pl = cnd["paramLabel"];
                    if (pl == null) { continue; }
                    string canon = DomainAttributeName(pl.ToString());
                    if (canon != null && canon.ToUpperInvariant().Trim() == wantParam)
                    {
                        double dv;
                        if (cnd["measured"] != null && double.TryParse(cnd["measured"].ToString(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out dv))
                        {
                            val = dv;
                            ExtractFailingThreshold(cnd, out limit, out haveLimit, out limitUnit, out breachAbove);
                            return true;
                        }
                    }
                }
                if (mainCnd != null && mainCnd["measured"] != null)
                {
                    double dv2;
                    if (double.TryParse(mainCnd["measured"].ToString(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out dv2))
                    {
                        val = dv2;
                        ExtractFailingThreshold(mainCnd, out limit, out haveLimit, out limitUnit, out breachAbove);
                        return true;
                    }
                }
            }
            catch { }
            return false;
        }

        // v1.0.160.104: the FAILing threshold of a triggered condition -- its numeric value, unit, and
        // whether the breach is above (comparison ">") or below ("<"). Picks the first status=="FAIL";
        // if none is marked, the first parseable threshold. haveLimit=false when none resolves.
        private static void ExtractFailingThreshold(JObject cnd, out double limit, out bool haveLimit, out string limitUnit, out bool breachAbove)
        {
            limit = double.NaN; haveLimit = false; limitUnit = null; breachAbove = true;
            try
            {
                JToken thsT = cnd["thresholds"];
                if (thsT == null || thsT.Type != JTokenType.Array) { return; }
                JArray ths = (JArray)thsT;
                JObject firstParsable = null;
                for (int i = 0; i < ths.Count; i++)
                {
                    JObject th = ths[i] as JObject;
                    if (th == null || th["value"] == null) { continue; }
                    double tv;
                    if (!double.TryParse(th["value"].ToString(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out tv)) { continue; }
                    if (firstParsable == null) { firstParsable = th; }
                    JToken st = th["status"];
                    if (st != null && string.Equals(st.ToString(), "FAIL", StringComparison.OrdinalIgnoreCase))
                    {
                        limit = tv; haveLimit = true;
                        if (th["unit"] != null) { limitUnit = th["unit"].ToString(); }
                        JToken cmp = th["comparison"];
                        if (cmp != null) { breachAbove = cmp.ToString().IndexOf('<') < 0; }
                        return;
                    }
                }
                if (firstParsable != null)
                {
                    double tv2;
                    if (double.TryParse(firstParsable["value"].ToString(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out tv2))
                    {
                        limit = tv2; haveLimit = true;
                        if (firstParsable["unit"] != null) { limitUnit = firstParsable["unit"].ToString(); }
                        JToken cmp2 = firstParsable["comparison"];
                        if (cmp2 != null) { breachAbove = cmp2.ToString().IndexOf('<') < 0; }
                    }
                }
            }
            catch { }
        }

        // Unix seconds for a DateTime treated as IST wall-clock (history ts are IST epoch).
        private static long ToUnixSeconds(DateTime ist)
        {
            DateTimeOffset dto = new DateTimeOffset(
                DateTime.SpecifyKind(ist, DateTimeKind.Unspecified),
                TimeSpan.FromHours(5.5));
            return dto.ToUnixTimeSeconds();
        }

        // v1.0.82.0 rev J: pull the COMPONENT attribute canonical names out of a
        // derived formula. Tokenizes identifier-ish runs (letters/digits/spaces,
        // optional "(unit)") and keeps those DomainAttributeName can canonicalise --
        // e.g. "RRAIL(ohm) = 2*(VTC FEED END(V) - VTC TR) / ((ITC FEED END(mA) +
        // ITC RELAY END(mA))/1000)" -> VF, TR V, IF MA, IR MA. The derived param
        // itself maps to null (no rule) and numeric/unit tokens are filtered out.
        // v1.0.160.30 (Item 4c): the PINNED base-sensor inputs for each derived attid, by CANONICAL
        // name (matches DomainAttributeName output, so they resolve against search_tags reliably --
        // the prose formula's short forms ChgOpV/Vf/If do NOT resolve, which is why the inputs were
        // silently dropped and the derived value came back uncomputable). R737-dependent attids
        // (589/590/591) additionally use TR_V571 = Ir * R737 / 1000, computed in ComputeDerivedDirect.
        private static List<string> DerivedBaseInputs(int attid)
        {
            switch (attid)
            {
                case 585: return new List<string> { "CHARGER MA", "IF MA" };                 // ITC BATT CHARG = ChgMa - If
                case 586: return new List<string> { "CHARGER OP V", "VF", "CHOKE V" };        // VTC VAR RES = ChgOpV - Vf - Choke
                case 587: return new List<string> { "CHOKE V", "IF MA" };                     // RTC CH FEED END = Choke/If*1000
                case 588: return new List<string> { "CHARGER OP V", "VF", "CHOKE V", "IF MA" }; // RTC VAR RES = (ChgOpV-Vf-Choke)/If*1000
                case 589: return new List<string> { "VR", "IR MA" };                          // RTC CH RELAY END (+ R737)
                case 590: return new List<string> { "VF", "IF MA", "IR MA" };                 // RRAIL (+ R737)
                case 591: return new List<string> { "VR", "IR MA" };                          // VTC CH RELAY END (+ R737)
                case 684: return new List<string> { "IF MA", "IR MA" };                       // IBALST = If - Ir
                default: return null;
            }
        }

        private static bool DerivedNeedsR737(int attid) { return attid == 589 || attid == 590 || attid == 591; }

        // Extract R737 (attid 737, Track Relay resistance) from the fetched FRS range JSON = the
        // AverageValue of the attid-737 row. R737 is a fixed per-asset constant; NEVER the measured
        // 571 sensor. Returns null if absent (then the R737-dependent derived attids fall back).
        private static double? RangeAvgForAttid(string rangeJson, int attid)
        {
            if (string.IsNullOrEmpty(rangeJson)) { return null; }
            try
            {
                List<JToken> docs = ParseJsonDocuments(rangeJson);
                for (int d = 0; d < docs.Count; d++)
                {
                    if (docs[d] == null) { continue; }
                    foreach (JToken row in docs[d].SelectTokens("$..*"))
                    {
                        JObject o = row as JObject;
                        if (o == null) { continue; }
                        JToken att = PropCI(o, "AssetAttributeId");
                        if (att == null) { att = PropCI(o, "AttributeId"); }
                        if (att == null) { att = PropCI(o, "Id"); }
                        if (att == null) { att = PropCI(o, "t"); }
                        if (att == null) { continue; }
                        int aid;
                        if (!int.TryParse(att.ToString().Trim(), out aid) || aid != attid) { continue; }
                        JToken av = PropCI(o, "AverageValue");
                        if (av == null) { av = PropCI(o, "avg"); }
                        if (av == null) { av = PropCI(o, "Average"); }
                        if (av == null) { continue; }
                        double v;
                        if (double.TryParse(av.ToString().Trim(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out v)) { return v; }
                    }
                }
            }
            catch { }
            return null;
        }

        // Compute a derived attribute directly from the base-sensor as-of values (keyed by canonical
        // name) + R737. Hardcoded from RdpmsMaps.DerivedFormula (no prose parsing, no drift risk).
        // Returns false when a required input is missing or a divisor is ~0 (caller then keeps the
        // existing behaviour). TR_V571 (the derived track-relay voltage) = Ir * R737 / 1000.
        private static bool ComputeDerivedDirect(int attid, Dictionary<string, double> c, double? r737, out double val)
        {
            val = double.NaN;
            if (c == null) { return false; }
            double If, Ir, Vf, Vr, Choke, ChgMa, ChgOpV;
            bool hIf = c.TryGetValue("IF MA", out If);
            bool hIr = c.TryGetValue("IR MA", out Ir);
            bool hVf = c.TryGetValue("VF", out Vf);
            bool hVr = c.TryGetValue("VR", out Vr);
            bool hChoke = c.TryGetValue("CHOKE V", out Choke);
            bool hChgMa = c.TryGetValue("CHARGER MA", out ChgMa);
            bool hChgOpV = c.TryGetValue("CHARGER OP V", out ChgOpV);
            double trV = 0.0; bool hTr = false;
            if (r737.HasValue && hIr) { trV = Ir * r737.Value / 1000.0; hTr = true; }   // derived TR_V571
            switch (attid)
            {
                case 585: if (hChgMa && hIf) { val = ChgMa - If; return true; } return false;
                case 586: if (hChgOpV && hVf && hChoke) { val = ChgOpV - Vf - Choke; return true; } return false;
                case 587: if (hChoke && hIf && Math.Abs(If) > 1e-9) { val = (Choke / If) * 1000.0; return true; } return false;
                case 588: if (hChgOpV && hVf && hChoke && hIf && Math.Abs(If) > 1e-9) { val = ((ChgOpV - Vf - Choke) / If) * 1000.0; return true; } return false;
                case 684: if (hIf && hIr) { val = If - Ir; return true; } return false;
                case 589: if (hTr && hVr && hIr && Math.Abs(Ir) > 1e-9) { val = ((Vr - trV) / Ir) * 1000.0; return true; } return false;
                case 590: if (hTr && hVf && hIf && hIr && Math.Abs(If + Ir) > 1e-9) { val = 2.0 * (Vf - trV) / (If + Ir) * 1000.0; return true; } return false;
                case 591: if (hTr && hVr) { val = Vr - trV; return true; } return false;
                default: return false;
            }
        }

        // v1.0.160.31 (Item 4b): parse a history_get result {"ts":[epochSec..],"v":[..]} into a
        // sorted (epochSec, value) series.
        private static List<double[]> ParseTsvSeries(string histJson)
        {
            List<double[]> outp = new List<double[]>();
            if (string.IsNullOrEmpty(histJson)) { return outp; }
            try
            {
                JObject o = JObject.Parse(histJson);
                JToken tsT = o["ts"]; JToken vT = o["v"];
                if (tsT == null || vT == null || tsT.Type != JTokenType.Array || vT.Type != JTokenType.Array) { return outp; }
                JArray ts = (JArray)tsT; JArray v = (JArray)vT;
                int n = Math.Min(ts.Count, v.Count);
                for (int i = 0; i < n; i++)
                {
                    double ep, vv;
                    if (!double.TryParse(ts[i].ToString(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out ep)) { continue; }
                    if (ep > 1e12) { ep = ep / 1000.0; }   // ms -> s
                    if (!double.TryParse(v[i].ToString(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out vv)) { continue; }
                    outp.Add(new double[] { ep, vv });
                }
                outp.Sort(delegate(double[] a, double[] b) { return a[0].CompareTo(b[0]); });
            }
            catch { }
            return outp;
        }

        // carry-forward as-of: last value at or before t in a sorted series. False if none <= t.
        private static bool SeriesAsOf(List<double[]> series, double t, out double val)
        {
            val = double.NaN;
            if (series == null || series.Count == 0) { return false; }
            bool have = false;
            for (int i = 0; i < series.Count; i++)
            {
                if (series[i][0] <= t) { val = series[i][1]; have = true; } else { break; }
            }
            return have;
        }

        // v1.0.160.31 (Item 4b): compute the derived value on the UNION timeline of all input series,
        // carrying each input forward (deadband). Returns (epochSec, derivedValue) points.
        private static List<double[]> ComputeDerivedSeries(int attid, Dictionary<string, List<double[]>> comp, double? r737, double incidenceEpoch)
        {
            List<double[]> outp = new List<double[]>();
            if (comp == null || comp.Count == 0) { return outp; }
            SortedSet<double> tsSet = new SortedSet<double>();
            foreach (KeyValuePair<string, List<double[]>> kv in comp)
            {
                if (kv.Value == null) { continue; }
                for (int i = 0; i < kv.Value.Count; i++) { tsSet.Add(kv.Value[i][0]); }
            }
            if (incidenceEpoch > 0) { tsSet.Add(incidenceEpoch); }   // force an as-of at the alert time
            List<double> uni = new List<double>(tsSet);
            for (int u = 0; u < uni.Count; u++)
            {
                double t = uni[u];
                Dictionary<string, double> bind = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
                bool ok = true;
                foreach (KeyValuePair<string, List<double[]>> kv in comp)
                {
                    double vv;
                    if (SeriesAsOf(kv.Value, t, out vv)) { bind[kv.Key] = vv; } else { ok = false; break; }
                }
                if (!ok) { continue; }   // not all inputs known yet at t
                double dv;
                if (ComputeDerivedDirect(attid, bind, r737, out dv)) { outp.Add(new double[] { t, dv }); }
            }
            return outp;
        }

        // v1.0.160.31 (Item 4b): longest continuous run breaching the threshold (upper=true: value >
        // threshold; else value < threshold). Deadband-aware: a breached value persists until the NEXT
        // change, so a run is counted from its start up to the recovery sample (or the last point if it
        // never recovers). Returns the run duration in seconds + its window/peak.
        private static double LongestBreachRun(List<double[]> series, double threshold, bool upper, out double startTs, out double endTs, out double peak)
        {
            startTs = 0; endTs = 0; peak = upper ? double.MinValue : double.MaxValue;
            if (series == null || series.Count == 0) { return 0.0; }
            double bestDur = 0.0, bestStart = 0, bestEnd = 0, bestPeak = peak;
            double runStart = 0, runPeak = 0; bool inRun = false;
            for (int i = 0; i < series.Count; i++)
            {
                double t = series[i][0], val = series[i][1];
                bool breach = upper ? (val > threshold) : (val < threshold);
                if (breach)
                {
                    if (!inRun) { inRun = true; runStart = t; runPeak = val; }
                    else { runPeak = upper ? Math.Max(runPeak, val) : Math.Min(runPeak, val); }
                }
                else if (inRun)
                {
                    // breach held from runStart until THIS recovery sample (carry-forward).
                    double dur = t - runStart;
                    if (dur >= bestDur) { bestDur = dur; bestStart = runStart; bestEnd = t; bestPeak = runPeak; }
                    inRun = false;
                }
            }
            if (inRun)
            {
                double lastT = series[series.Count - 1][0];   // breach never recovered -> held to the last point
                double dur = lastT - runStart;
                if (dur >= bestDur) { bestDur = dur; bestStart = runStart; bestEnd = lastT; bestPeak = runPeak; }
            }
            startTs = bestStart; endTs = bestEnd; peak = bestPeak;
            return bestDur;
        }

        // v1.0.160.31 (Item 4b): the FRS sustain window ("... for 15s") from the cause-logic string.
        private static int FrsSustainSeconds(string causeLogic)
        {
            if (string.IsNullOrEmpty(causeLogic)) { return 15; }
            System.Text.RegularExpressions.Match m =
                System.Text.RegularExpressions.Regex.Match(causeLogic, @"for\s+(\d+)\s*s");
            int s;
            if (m.Success && int.TryParse(m.Groups[1].Value, out s) && s > 0) { return s; }
            return 15;
        }

        // v1.0.160.37: build the computed-verdict decision from the sustain result and stash it on the
        // instance. Owner rule (PREDICTIVE/ANALOG): a breach sustained for >= the FRS window is CONFIRMED;
        // a breach that did not hold is NOT_CONFIRMED (transient). Coherence, where structured, scales the
        // confidence; where not defined the breach alone decides (owner ruling). Best-effort: any fault
        // leaves _computedVerdict null so the model keeps deciding. No AiLog/prefetch calls (no CS0120).
        // v1.0.160.42: build the digital TPR state series (epoch seconds, value 0/1) for the gate,
        // from the already-fetched raw TPR trend. Empty when no digital TPR series is resolvable
        // (=> the gate is a no-op and samples are kept). No I/O.
        // v1.0.160.115 CUT B. OBSERVE-ONLY: classify and record. No verdict, confidence or caveat
        // depends on any of this.
        private JArray BuildSensorHealth()
        {
            JArray outArr = new JArray();
            try
            {
                if (_trendRawByAttr == null || _trendRawByAttr.Count == 0) { return outArr; }
                // Occupancy, from the digital TPR state we already fetch. Recorded per channel rather
                // than applied as a blanket rule: a shunt suppresses If/Ir/Vf/TPR V but NOT the
                // charger family, so "occupied" does not excuse silence on every channel.
                List<double[]> tpr = BuildTprStateSeries();
                bool occupiedAtEnd = false;
                double occSinceEpoch = 0;
                if (tpr != null && tpr.Count > 0)
                {
                    tpr.Sort(delegate (double[] x, double[] y) { return x[0].CompareTo(y[0]); });
                    double[] last = tpr[tpr.Count - 1];
                    occupiedAtEnd = last[1] < 0.5;   // 0 = DROP = occupied
                    if (occupiedAtEnd) { occSinceEpoch = last[0]; }
                }
                foreach (KeyValuePair<string, List<object[]>> kv in _trendRawByAttr)
                {
                    List<object[]> raw = kv.Value;
                    if (raw == null || raw.Count == 0) { continue; }
                    List<double> eps = new List<double>();
                    List<double> vals = new List<double>();
                    for (int i = 0; i < raw.Count; i++)
                    {
                        object[] pt = raw[i];
                        if (pt == null || pt.Length < 2 || pt[0] == null || pt[1] == null) { continue; }
                        double ep = TrendTsToEpoch(new JValue(pt[0].ToString()));
                        if (double.IsNaN(ep)) { continue; }
                        double vv;
                        if (!double.TryParse(pt[1].ToString(), System.Globalization.NumberStyles.Float,
                                System.Globalization.CultureInfo.InvariantCulture, out vv)) { continue; }
                        eps.Add(ep); vals.Add(vv);
                    }
                    if (eps.Count == 0) { continue; }
                    double first = eps[0], lastTs = eps[0];
                    for (int i = 1; i < eps.Count; i++)
                    { if (eps[i] < first) { first = eps[i]; } if (eps[i] > lastTs) { lastTs = eps[i]; } }
                    double spanH = (lastTs - first) / 3600.0;
                    JObject o = new JObject();
                    o["attr"] = kv.Key;
                    o["rows"] = eps.Count;
                    o["observedSpanHours"] = Math.Round(spanH, 2);
                    // OBSERVED rate over the rows actually returned -- NOT rows/requestedWindow, which
                    // understates a capped block by an order of magnitude.
                    o["observedRate"] = spanH > 0 ? Math.Round((eps.Count - 1) / spanH, 2) : 0;
                    // A block returning exactly the cap is CENSORED: its rate is a lower bound and its
                    // boundary sample is not necessarily the nearest reading.
                    o["censored"] = (eps.Count >= 500);
                    o["lastSampleAgeSec"] = (long)(ToEpochIst(DateTime.Now) - lastTs);
                    // longest run of identical values -- a frozen channel and a steady one look the
                    // same on value alone, which is the whole difficulty.
                    int flat = 1, maxFlat = 1;
                    for (int i = 1; i < vals.Count; i++)
                    { if (vals[i] == vals[i - 1]) { flat++; if (flat > maxFlat) { maxFlat = flat; } } else { flat = 1; } }
                    o["longestFlatRun"] = maxFlat;
                    if (occupiedAtEnd)
                    {
                        o["trackOccupied"] = true;
                        o["occupiedSinceSec"] = (long)(ToEpochIst(DateTime.Now) - occSinceEpoch);
                    }
                    outArr.Add(o);
                }
            }
            catch { }
            return outArr;
        }

        private List<double[]> BuildTprStateSeries()
        {
            List<double[]> outp = new List<double[]>();
            string tprKey = ResolveTprStateKey();
            if (tprKey == null) { return outp; }
            List<object[]> raw;
            if (!_trendRawByAttr.TryGetValue(tprKey, out raw) || raw == null) { return outp; }
            foreach (object[] pt in raw)
            {
                if (pt == null || pt.Length < 2 || pt[0] == null || pt[1] == null) { continue; }
                double ep = TrendTsToEpoch(new JValue(pt[0].ToString()));
                if (double.IsNaN(ep)) { continue; }
                double vv;
                if (!double.TryParse(pt[1].ToString(), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out vv)) { continue; }
                outp.Add(new double[] { ep, vv >= 0.5 ? 1.0 : 0.0 });
            }
            outp.Sort(delegate(double[] a, double[] b) { return a[0].CompareTo(b[0]); });
            return outp;
        }

        // v1.0.160.42: TRUE if the relay is STEADY UP across [ts-guard, ts+guard] with no transition.
        // Discard (FALSE) on a toggle inside the window (train edge / device-clock skew) or a steady
        // DOWN (train present). Unknown / no relay data => TRUE (keep -- never drop real degradation).
        private static bool GateSteadyUp(List<double[]> tpr, double ts, int guardSec)
        {
            if (tpr == null || tpr.Count == 0) { return true; }
            double lo = ts - guardSec;
            double hi = ts + guardSec;
            int haveSeed = 0; int seedState = 0;
            for (int i = 0; i < tpr.Count; i++)
            {
                if (tpr[i][0] <= lo) { seedState = tpr[i][1] >= 0.5 ? 1 : 0; haveSeed = 1; }
                else { break; }
            }
            int curState = seedState; int haveCur = haveSeed; int transition = 0;
            for (int i = 0; i < tpr.Count; i++)
            {
                double e = tpr[i][0];
                if (e <= lo) { continue; }
                if (e > hi) { break; }
                int st = tpr[i][1] >= 0.5 ? 1 : 0;
                if (haveCur == 1 && st != curState) { transition = 1; break; }
                curState = st; haveCur = 1;
            }
            if (transition == 1) { return false; }
            if (haveCur == 1 && curState == 0) { return false; }
            return true;
        }

        // v1.0.160.42: keep only the component samples taken while the relay is steady UP.
        private static List<double[]> FilterCompSeriesByGate(List<double[]> cs, List<double[]> tpr, int guardSec)
        {
            if (cs == null) { return new List<double[]>(); }
            if (tpr == null || tpr.Count == 0) { return cs; }
            List<double[]> outp = new List<double[]>(cs.Count);
            for (int i = 0; i < cs.Count; i++)
            {
                if (cs[i] != null && cs[i].Length >= 2 && GateSteadyUp(tpr, cs[i][0], guardSec)) { outp.Add(cs[i]); }
            }
            return outp;
        }

        private void StashComputedVerdict(bool sustained, long durSec, int needSec, string basis)
        {
            try
            {
                JObject cv = new JObject();
                cv["class"] = sustained ? "CONFIRMED" : "NOT_CONFIRMED";
                int conf = sustained ? (needSec > 0 && durSec >= (long)needSec * 4 ? 85 : 70) : 75;
                cv["confidence"] = conf;
                // v1.0.160.87: the COMPUTED path knows which case this is -- say so, rather than
                // leaving the label to the model. A breach that held < the FRS window is a real breach
                // that recovered, not a false alert.
                if (!sustained) { cv["category"] = "Transient - no action"; }
                cv["reason"] = sustained
                    ? ("computed: breach held " + durSec + "s >= FRS sustain " + needSec + "s (" + basis + ")")
                    : ("computed: breach held only " + durSec + "s < FRS sustain " + needSec + "s -- transient (" + basis + ")");
                cv["sustained"] = sustained;
                cv["durSec"] = durSec;
                cv["needSec"] = needSec;
                _computedVerdict = cv;
            }
            catch { _computedVerdict = null; }
        }

        // generalized numeric field extraction from the FRS range for an attid (avg/max/min/fail).
        private static double? RangeNumForAttid(string rangeJson, int attid, string[] fields)
        {
            if (string.IsNullOrEmpty(rangeJson) || fields == null) { return null; }
            try
            {
                List<JToken> docs = ParseJsonDocuments(rangeJson);
                for (int d = 0; d < docs.Count; d++)
                {
                    if (docs[d] == null) { continue; }
                    foreach (JToken row in docs[d].SelectTokens("$..*"))
                    {
                        JObject o = row as JObject;
                        if (o == null) { continue; }
                        JToken att = PropCI(o, "AssetAttributeId");
                        if (att == null) { att = PropCI(o, "AttributeId"); }
                        if (att == null) { att = PropCI(o, "Id"); }
                        if (att == null) { att = PropCI(o, "t"); }
                        if (att == null) { continue; }
                        int aid;
                        if (!int.TryParse(att.ToString().Trim(), out aid) || aid != attid) { continue; }
                        for (int f = 0; f < fields.Length; f++)
                        {
                            JToken fv = PropCI(o, fields[f]);
                            if (fv == null) { continue; }
                            double v;
                            if (double.TryParse(fv.ToString().Trim(), System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out v)) { return v; }
                        }
                    }
                }
            }
            catch { }
            return null;
        }

        private static List<string> ExtractFormulaComponents(string formula)
        {
            List<string> outp = new List<string>();
            if (string.IsNullOrEmpty(formula)) { return outp; }
            // v1.0.84.0: strip the LHS ("RTC CH FEED END(ohm) =") so the derived name
            // itself is not mistaken for a component, then tokenize the RHS.
            string rhs = formula;
            int eq = formula.IndexOf('=');
            if (eq >= 0 && eq + 1 < formula.Length) { rhs = formula.Substring(eq + 1); }
            // v1.0.84.0: allow '/' and '.' INSIDE an attribute name so "ITC TFC O/P"
            // stays one token (the old class split it at '/' into "ITC TFC O" + "P").
            // Operator '/' (division) is always flanked by spaces in these formulas
            // ("... / (ITC FEED END..."), whereas name-internal '/' is not (O/P),
            // so a non-space-delimited slash is treated as part of the name.
            foreach (System.Text.RegularExpressions.Match m in
                System.Text.RegularExpressions.Regex.Matches(
                    rhs, @"[A-Za-z][A-Za-z0-9]*(?:[ /.][A-Za-z0-9]+)*(?:\([A-Za-z]+\))?"))
            {
                string tok = m.Value.Trim();
                if (tok.Length < 3) { continue; }
                string canon = DomainAttributeName(tok);
                if (canon == null) { continue; }
                if (!outp.Contains(canon)) { outp.Add(canon); }
            }
            return outp;
        }

        // v1.0.82.0 rev J: resolve a canonical attribute name to a TagID using the
        // asset's search_tags rows (which carry TagID + AssetAttributeName in the
        // standard profile). Exact uppercase match first, then Contains either way.
        // "TR V" additionally accepts "VR" (site naming varies for the track-relay
        // voltage: "Vr" vs "TR V (Relay)").
        private static string TagIdForAttributeName(string tagsJson, string canonical)
        {
            if (string.IsNullOrEmpty(tagsJson) || string.IsNullOrEmpty(canonical)) { return null; }
            List<string> wants = new List<string> { canonical };
            // v1.0.85.0: the track-relay voltage Title is "TR V (Relay)"; some sites
            // name it "Vr" instead. Accept both. Match is whitespace/unit-normalized.
            if (canonical.StartsWith("TR V")) { wants.Add("VR"); wants.Add("TR V"); }
            try
            {
                List<JToken> docs = ParseJsonDocuments(tagsJson);
                for (int pass = 0; pass < 2; pass++)   // pass 0 exact, pass 1 contains
                {
                    for (int d = 0; d < docs.Count; d++)
                    {
                        foreach (JToken row in docs[d].SelectTokens("$..*"))
                        {
                            JObject o = row as JObject;
                            if (o == null) { continue; }
                            JToken nm = PropCI(o, "AssetAttributeName");
                            JToken tid = PropCI(o, "TagID") ?? PropCI(o, "TagId");
                            if (nm == null || tid == null) { continue; }
                            string upper = nm.ToString().ToUpperInvariant().Trim();
                            for (int w = 0; w < wants.Count; w++)
                            {
                                bool hit = pass == 0
                                    ? upper == wants[w]
                                    : (upper.IndexOf(wants[w], StringComparison.Ordinal) >= 0
                                       || wants[w].IndexOf(upper, StringComparison.Ordinal) >= 0);
                                if (hit) { return tid.ToString(); }
                            }
                        }
                    }
                }
            }
            catch { }
            return null;
        }

        // v1.0.80.0: extract the alerting attribute's thresholds from the alert card
        // as a DEGRADED baseline, used only when get_attribute_range yields nothing.
        // Card shape (per triggeredConditions[0]):
        //   paramLabel: "ITC RELAY END(mA)", measured: "160.26", unit: "mA",
        //   thresholds: [ {label:"80% Avg", value:"214.80", comparison:"<", status:"FAIL"},
        //                 {label:"Min Safe", value:"210.00", comparison:"<", status:"FAIL"} ]
        // Returns a compact text block, or null if the card has no usable thresholds
        // (then the caller behaves exactly as before -- gap recorded, model may fetch).
        private static string BuildCardBaseline(JObject ctx)
        {
            if (ctx == null) { return null; }
            JToken card = ctx["alertCard"];
            if (card == null || card.Type != JTokenType.Object) { return null; }
            JToken tc = card["triggeredConditions"];
            if (tc == null || tc.Type != JTokenType.Array || ((JArray)tc).Count == 0) { return null; }
            JObject cond = ((JArray)tc)[0] as JObject;
            if (cond == null) { return null; }

            string param = cond["paramLabel"] != null ? cond["paramLabel"].ToString() : "";
            string measured = cond["measured"] != null ? cond["measured"].ToString() : "";
            string unit = cond["unit"] != null ? cond["unit"].ToString() : "";
            string canonical = DomainAttributeName(param);   // map to the tag name if we can

            JToken th = cond["thresholds"];
            if (th == null || th.Type != JTokenType.Array || ((JArray)th).Count == 0) { return null; }

            System.Text.StringBuilder sb = new System.Text.StringBuilder();
            sb.Append("attribute: ").Append(param);
            if (!string.IsNullOrEmpty(canonical)) { sb.Append(" (tag: ").Append(canonical).Append(")"); }
            if (measured.Length > 0) { sb.Append("  measured: ").Append(measured).Append(" ").Append(unit); }
            sb.Append("\n");
            bool any = false;
            foreach (JToken t in (JArray)th)
            {
                JObject to = t as JObject;
                if (to == null) { continue; }
                string label = to["label"] != null ? to["label"].ToString() : "";
                string val = to["value"] != null ? to["value"].ToString() : "";
                string cmp = to["comparison"] != null ? to["comparison"].ToString() : "";
                string status = to["status"] != null ? to["status"].ToString() : "";
                if (label.Length == 0 && val.Length == 0) { continue; }
                sb.Append("  ").Append(label).Append(": ").Append(cmp).Append(" ").Append(val).Append(" ").Append(unit);
                if (status.Length > 0) { sb.Append("  [").Append(status).Append("]"); }
                sb.Append("\n");
                any = true;
            }
            if (!any) { return null; }
            sb.Append("NOTE: degraded baseline - only the triggered attribute's card thresholds are available; MaxSafe/MinFail/true-average are NOT (get_attribute_range unavailable).");
            return sb.ToString();
        }

        // -- v1.0.79.0 -- The MCP server (v1.5.55.1) does NOT read a "query" param on
        // search_tags; the real search-text filter is "AssetName" (ILIKE), with an
        // optional "AttributeName" (ILIKE) to narrow to one attribute. The dead
        // "query" param this used to send was ignored, so the server returned
        // unfiltered/arbitrary tags -- the "wrong assets" failure that made every
        // track-circuit alert fall through to the AssetId fallback. AssetName is the
        // asset's name; AttributeName is added ONLY when DomainAttributeName resolves
        // the alert's triggered parameter to a canonical tag name, because the raw
        // paramLabel ("ITC RELAY END(mA)") does not ILIKE-match the real name
        // ("Ir mA") and would filter the correct tag OUT. When no canonical name is
        // known, AssetName alone is sent and the matcher picks among the asset's tags.
        // v1.0.160.55: upstream drivers of a DERIVED attribute, per the circuit invariants. A derived
        // name is not a stored tag, so it must be expanded to the measured components that produce it
        // or the series never gets fetched (and the K2 residual then has nothing to work with).
        private static string[] CircuitDriversFor(string canonicalAttr)
        {
            if (string.IsNullOrEmpty(canonicalAttr)) { return null; }
            string a = canonicalAttr.Trim().ToUpperInvariant();
            // v1.0.160.63: MEASURED partners too, not just derived expansions. TC TR VOLT LOW maps
            // to ITC RELAY END alone, so without this If is never fetched and K2 cannot run --
            // confirmed on alert 524613, where Phase 1 injected 7 circuit rules and Phase 2
            // produced no [circuit] line at all.
            if (a == "IR MA") { return new string[] { "IF MA" }; }                                 // K2 partner
            if (a == "IF MA") { return new string[] { "IR MA" }; }                                 // K2 partner
            // v1.0.160.66: the range table spells it "IBlAST" (attribute 684), so the canonical
            // form is IBLAST. Keying only on IBALST meant this expansion never matched.
            if (a == "IBALST" || a == "IBLAST") { return new string[] { "IF MA", "IR MA" }; }      // K2
            if (a == "RRAIL") { return new string[] { "VF", "VR", "IF MA", "IR MA" }; }            // K3/K4
            if (a == "RTC VAR RES") { return new string[] { "VTC VAR RES", "IF MA" }; }            // K3
            if (a == "RTC CH FEED END") { return new string[] { "CHOKE V", "IF MA" }; }            // K3
            if (a == "TR V (RELAY)") { return new string[] { "IR MA" }; }                          // K4
            if (a == "ITC BATT CHARG") { return new string[] { "CHARGER MA", "IF MA" }; }          // K1
            return null;
        }

        // v1.0.160.55: the attributes this cause actually depends on. Ordered so the most
        // authoritative source wins the cap: L1 the RDPMS cause map, L2 the card's own conditions
        // (failing first), L3 circuit-wisdom drivers of any derived member.
        // v1.0.160.80: canonical name of the FIRST FAILING triggered condition -- i.e. the attribute
        // the alerting-tag path resolves and fetches. Same failing-first rule DriverSetForCause
        // uses, so the two cannot disagree about which attribute is "the alerting one".
        private static string FirstFailingParamCanon(JObject ctx)
        {
            try
            {
                JObject card = ctx != null ? ctx["alertCard"] as JObject : null;
                JArray tc = card != null ? card["triggeredConditions"] as JArray : null;
                if (tc == null) { return ""; }
                for (int i = 0; i < tc.Count; i++)
                {
                    JObject c = tc[i] as JObject;
                    if (c == null || c["paramLabel"] == null) { continue; }
                    JArray th = c["thresholds"] as JArray;
                    if (th == null) { continue; }
                    for (int k = 0; k < th.Count; k++)
                    {
                        JObject t0 = th[k] as JObject;
                        if (t0 != null && t0["status"] != null
                            && string.Equals(t0["status"].ToString().Trim(), "FAIL", StringComparison.OrdinalIgnoreCase))
                        {
                            string cn = DomainAttributeName(c["paramLabel"].ToString());
                            return string.IsNullOrEmpty(cn) ? c["paramLabel"].ToString() : cn;
                        }
                    }
                }
            }
            catch { }
            return "";
        }

        // v1.0.160.169 (BUG-3a/4 + 3b): a deterministic verdict anchor built from the alert card, placed
        // at the TOP of the evidence so the model judges the INCIDENCE value, not the recovered one. A
        // card-FAIL that recovered is a CONFIRMED transient breach -- recovery sets severity, never the
        // verdict. Stops "it recovered -> INCONCLUSIVE" softening (542185/533604/534685/534033), flags a
        // systemic all-attributes-drop as NOT a per-attribute fault, and routes an impossible If<Ir to a
        // data-quality note (553745). Returns "" when the card carries no FAIL condition.
        private static string BuildVerdictAnchor(JObject ctx)
        {
            try
            {
                JObject card = ctx != null ? ctx["alertCard"] as JObject : null;
                JArray tc = card != null ? card["triggeredConditions"] as JArray : null;
                if (tc == null) { return ""; }
                for (int i = 0; i < tc.Count; i++)
                {
                    JObject c = tc[i] as JObject;
                    if (c == null || c["paramLabel"] == null) { continue; }
                    JArray th = c["thresholds"] as JArray;
                    if (th == null) { continue; }
                    for (int k = 0; k < th.Count; k++)
                    {
                        JObject t0 = th[k] as JObject;
                        if (t0 == null || t0["status"] == null
                            || !string.Equals(t0["status"].ToString().Trim(), "FAIL", StringComparison.OrdinalIgnoreCase))
                        { continue; }
                        string attr = c["paramLabel"].ToString();
                        string meas = c["measured"] != null ? c["measured"].ToString() : "?";
                        string unit = c["unit"] != null ? c["unit"].ToString() : "";
                        string thL = t0["label"] != null ? t0["label"].ToString() : "limit";
                        string thV = t0["value"] != null ? t0["value"].ToString() : "?";
                        string cmp = t0["comparison"] != null ? t0["comparison"].ToString() : "vs";
                        bool reset = GetCtx(ctx, "resetTime").Trim().Length > 0;
                        StringBuilder a = new StringBuilder();
                        a.Append("[VERDICT ANCHOR (deterministic, from the alert card) -- ").Append(attr)
                         .Append(": incidence measured = ").Append(meas).Append(" ").Append(unit)
                         .Append(", status FAIL vs ").Append(thL).Append(" ").Append(cmp).Append(" ").Append(thV)
                         .Append(". This IS a confirmed breach at the incidence.");
                        if (reset)
                        {
                            a.Append(" It RESET (recovered) -> a CONFIRMED *TRANSIENT* breach; recovery sets SEVERITY, never the verdict.");
                        }
                        a.Append(" DECIDE from the INCIDENCE value, not the recovered one: fetched incidence sample agrees with this FAIL -> CONFIRMED")
                         .Append(reset ? " (transient)" : "")
                         .Append("; fetched incidence sample shows NO breach at the incidence -> NOT_CONFIRMED; ALL attributes read 0 together at the incidence (systemic power/comms/DL drop) -> NOT_CONFIRMED (systemic, not a per-attribute fault); value cannot be established at all -> INCONCLUSIVE (rare). Do NOT return INCONCLUSIVE for a card-FAIL that merely recovered. A physically-impossible reading (e.g. If < Ir, IBALST negative) is a channel/calibration artifact -> report as DATA QUALITY, never a verdict driver.]").Append("\n\n");
                        return a.ToString();
                    }
                }
            }
            catch { }
            return "";
        }

        // v1.0.160.171: the POINT MACHINE common-condition anchor (all PT causes) -- the PM analogue
        // of BuildVerdictAnchor. Structures the verdict around the 4 PM steps: (1) card verification,
        // (2) cause-logic mapped-attribute check at the incidence, (3) operation ARRAY pattern
        // (predict_pm_operation), (4) DataLogger RELAY state as the DECIDER. A card-FAIL that recovered
        // is CONFIRMED (transient); a PM failure never ends INCONCLUSIVE. Returns "" for non-PM alerts.
        private static string BuildPmVerdictAnchor(JObject ctx)
        {
            try
            {
                string cause = GetCtx(ctx, "causeCode");
                string atype = GetCtx(ctx, "assetType");
                bool isPm = (atype != null && atype.ToUpperInvariant().Contains("POINT"))
                            || (cause != null && cause.TrimStart().ToUpperInvariant().StartsWith("PT "));
                if (!isPm) { return ""; }

                string attr = "", meas = "?", unit = "", thL = "limit", thV = "?", cmp = "vs";
                JObject card = ctx != null ? ctx["alertCard"] as JObject : null;
                JArray tc = card != null ? card["triggeredConditions"] as JArray : null;
                if (tc != null)
                {
                    for (int i = 0; i < tc.Count && attr.Length == 0; i++)
                    {
                        JObject c = tc[i] as JObject;
                        if (c == null || c["paramLabel"] == null) { continue; }
                        JArray th = c["thresholds"] as JArray;
                        if (th == null) { continue; }
                        for (int k = 0; k < th.Count; k++)
                        {
                            JObject t0 = th[k] as JObject;
                            if (t0 == null || t0["status"] == null
                                || !string.Equals(t0["status"].ToString().Trim(), "FAIL", StringComparison.OrdinalIgnoreCase)) { continue; }
                            attr = c["paramLabel"].ToString();
                            meas = c["measured"] != null ? c["measured"].ToString() : "?";
                            unit = c["unit"] != null ? c["unit"].ToString() : "";
                            thL = t0["label"] != null ? t0["label"].ToString() : "limit";
                            thV = t0["value"] != null ? t0["value"].ToString() : "?";
                            cmp = t0["comparison"] != null ? t0["comparison"].ToString() : "vs";
                            break;
                        }
                    }
                }
                bool reset = GetCtx(ctx, "resetTime").Trim().Length > 0;
                bool isFail = (GetCtx(ctx, "alertType") ?? "").Trim().ToUpperInvariant().StartsWith("F");

                StringBuilder a = new StringBuilder();
                a.Append("[POINT MACHINE VERDICT ANCHOR -- ").Append(cause).Append(". Decide from these four, in order:\n");
                a.Append(" 1. CARD: ");
                if (attr.Length > 0)
                {
                    a.Append(attr).Append(" measured ").Append(meas).Append(" ").Append(unit)
                     .Append(" FAIL vs ").Append(thL).Append(" ").Append(cmp).Append(" ").Append(thV)
                     .Append(" at incidence -- breach established (card authoritative).");
                }
                else { a.Append("the card's failing condition is authoritative for the incidence."); }
                a.Append("\n 2. CAUSE LOGIC -- verify the cause's mapped attributes at the INCIDENCE value (not the recovered one): the alerting attribute plus its coupled partners (LOC / room voltage, feed & relay-end current, indication voltage). Coherent with the cause -> supports CONFIRMED.");
                a.Append("\n 3. ARRAY PATTERN -- read predict_pm_operation for this asset/end: creeping / obstruction / voltage-sag / sluggish / normal signature.");
                a.Append("\n 4. DATALOGGER RELAY (the DECIDER) -- Combined-NWKR / RWKR / NWCR / RWCR (attid 267/268/282/283, DataLogger) states at the incidence. A relay drop/pick consistent with the cause -> CONFIRMED; relays healthy with a normal throw -> re-examine (possible normal throw-related de-energization).");
                if (reset) { a.Append("\n A card-FAIL that RESET (recovered) is a CONFIRMED *TRANSIENT* breach -- recovery sets severity, never the verdict."); }
                if (isFail) { a.Append(" A point-machine FAILURE never ends INCONCLUSIVE: resolve CONFIRMED (genuine) or NOT_CONFIRMED (normal throw / train)."); }
                a.Append("]\n\n");
                return a.ToString();
            }
            catch { }
            return "";
        }

        // v1.0.160.173: some alerts arrive with NO alertCard -- only a rawMessage sentence carrying
        // the breach value in <b>..</b> (e.g. "Operation Time high. <b>TPT N: 9.04</b>") or a failure
        // statement ("failed in R ... reasons not diagnosed"). Extract attribute/value/direction so a
        // cardless alert can still anchor on its stated breach. Returns false when there IS a card
        // (the card path handles it) or nothing parseable and it is not an undiagnosed failure.
        private static bool RawMessageBreach(JObject ctx, out string attr, out string val, out string dir, out bool undiagnosed)
        {
            attr = ""; val = ""; dir = ""; undiagnosed = false;
            try
            {
                JToken card = ctx != null ? ctx["alertCard"] : null;
                if (card != null && card.Type == JTokenType.Object) { return false; }
                string raw = GetCtx(ctx, "rawMessage");
                if (string.IsNullOrEmpty(raw)) { return false; }
                string low = raw.ToLowerInvariant();
                if (low.Contains("not diagnosed") || (low.Contains("reason") && low.Contains("not"))) { undiagnosed = true; }
                dir = low.Contains("high") ? "high" : (low.Contains("low") ? "low" : "");
                System.Text.RegularExpressions.Match m = System.Text.RegularExpressions.Regex.Match(
                    raw, @"<b>\s*([A-Za-z0-9 _/().-]+?)\s*:\s*([-0-9.]+)", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                if (m.Success) { attr = m.Groups[1].Value.Trim(); val = m.Groups[2].Value.Trim(); return true; }
                System.Text.RegularExpressions.Match m2 = System.Text.RegularExpressions.Regex.Match(
                    raw, @"([A-Za-z][A-Za-z0-9 _/().-]{1,24}?)\s*:\s*([-0-9.]+)\s*(A|V|sec|s)\b", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                if (m2.Success) { attr = m2.Groups[1].Value.Trim(); val = m2.Groups[2].Value.Trim(); return true; }
                return undiagnosed;
            }
            catch { }
            return false;
        }

        // v1.0.160.173: anchor for a cardless alert -- surfaces the rawMessage breach so the verdict
        // is judged on the stated value, not on the absent card / missing telemetry.
        private static string BuildRawMessageAnchor(JObject ctx)
        {
            try
            {
                string attr, val, dir; bool undiag;
                if (!RawMessageBreach(ctx, out attr, out val, out dir, out undiag)) { return ""; }
                string cause = GetCtx(ctx, "causeCode");
                bool isFail = (GetCtx(ctx, "alertType") ?? "").Trim().ToUpperInvariant().StartsWith("F");
                StringBuilder a = new StringBuilder();
                a.Append("[RAW-MESSAGE ANCHOR -- this alert has NO structured card; the FRS reported it as text. Cause: ").Append(cause).Append(". ");
                if (attr.Length > 0 && val.Length > 0)
                {
                    a.Append("Stated breach: ").Append(attr).Append(" = ").Append(val);
                    if (dir.Length > 0) { a.Append(" (").Append(dir).Append(")"); }
                    a.Append(". This measured value IS the alert's evidence -- the alert fired on it. ");
                    a.Append(isFail
                        ? "A FAILURE with a stated value is CONFIRMED."
                        : "A predictive breach with a stated value is CONFIRMED (single event; transient if it reset).");
                }
                else if (undiag)
                {
                    a.Append("The FRS states a FAILURE occurred (reason not diagnosed). The failure is real -> CONFIRMED with mechanism undiagnosed.");
                }
                a.Append(" This asset may have NO configured telemetry; absence of history does NOT downgrade a stated breach or a failure. INCONCLUSIVE only if there is neither a stated value nor any telemetry AND it is not a failure.]");
                return a.ToString() + "\n\n";
            }
            catch { }
            return "";
        }

        private static List<string> DriverSetForCause(JObject ctx)
        {
            List<string> outp = new List<string>();
            if (ctx == null) { return outp; }
            try
            {
                // ---- L1: the authoritative cause -> attribute map (already generated from the master)
                string cc = (GetCtx(ctx, "causeCode") ?? "").Trim();
                string[] mapped;
                if (cc.Length > 0 && RdpmsMaps.CauseToAttributes.TryGetValue(cc, out mapped) && mapped != null)
                {
                    for (int i = 0; i < mapped.Length; i++) { AddCanon(outp, mapped[i]); }
                }
                // ---- L2: every triggered condition, FAILING ones first (never just [0])
                JObject card = ctx["alertCard"] as JObject;
                JArray tc = card != null ? card["triggeredConditions"] as JArray : null;
                if (tc != null)
                {
                    for (int pass = 0; pass < 2; pass++)
                    {
                        for (int i = 0; i < tc.Count; i++)
                        {
                            JObject c = tc[i] as JObject;
                            if (c == null || c["paramLabel"] == null) { continue; }
                            bool failed = false;
                            JArray th = c["thresholds"] as JArray;
                            if (th != null)
                            {
                                for (int k = 0; k < th.Count; k++)
                                {
                                    JObject t0 = th[k] as JObject;
                                    if (t0 != null && t0["status"] != null
                                        && string.Equals(t0["status"].ToString().Trim(), "FAIL", StringComparison.OrdinalIgnoreCase))
                                    { failed = true; break; }
                                }
                            }
                            if ((pass == 0) != failed) { continue; }   // pass 0 = failing, pass 1 = the rest
                            AddCanon(outp, c["paramLabel"].ToString());
                        }
                    }
                }
                // ---- L3: circuit-wisdom drivers of any DERIVED member already collected
                List<string> seed = new List<string>(outp);
                for (int i = 0; i < seed.Count; i++)
                {
                    string[] drv = CircuitDriversFor(seed[i]);
                    if (drv == null) { continue; }
                    for (int d = 0; d < drv.Length; d++) { AddCanon(outp, drv[d]); }
                }
            }
            catch { }
            // Cap so a wide IPS cause cannot fan out unbounded; L1 members were added first.
            int cap = ClampCfg(ReadInt("AnalyzeDriverSetMax", 6), 1, 12);
            if (outp.Count > cap) { outp.RemoveRange(cap, outp.Count - cap); }
            return outp;
        }

        // canonicalise + de-duplicate in one step; unmappable names are dropped rather than guessed.
        private static void AddCanon(List<string> list, string raw)
        {
            // v1.0.160.66: DomainAttributeName maps LABELS ("ITC FEED END(mA)") and does NOT round-trip
            // its own output, so an already-canonical name such as "IF MA" -- exactly what
            // CircuitDriversFor returns -- resolved to nothing and was silently dropped. That is why
            // the K2 partner never reached the driver set. Fall back to the raw upper-cased name.
            string c = DomainAttributeName(raw);
            if (string.IsNullOrEmpty(c)) { c = (raw ?? "").Trim().ToUpperInvariant(); }
            if (string.IsNullOrEmpty(c)) { return; }
            for (int i = 0; i < list.Count; i++)
            {
                if (string.Equals(list[i], c, StringComparison.OrdinalIgnoreCase)) { return; }
            }
            list.Add(c);
        }

        // v1.0.160.56: instance passthrough so the driver set can be LOGGED (AiLog is an instance
        // member and NewSearchArgs is static). Returns the args untouched; recomputing the set is a
        // few dictionary lookups over the alert card, no I/O.
        private JObject LogDriverSet(JObject args, JObject ctx)
        {
            try
            {
                List<string> d = DriverSetForCause(ctx);
                if (d.Count > 0)
                {
                    _driverSetStr = string.Join(", ", d.ToArray());   // v1.0.160.57: for the audit record
                    AiLog("INFO", "PREFETCH", "driver set (" + d.Count + "): " + string.Join(", ", d.ToArray())
                        + (d.Count > 1 ? " -- full tag list (not narrowed to one attribute)" : " -- narrowed"));
                }
            }
            catch { }
            return args;
        }

        private static JObject NewSearchArgs(string assetName, string siteId, JObject ctx, bool isDerived)
        {
            JObject o = new JObject();
            o["AssetName"] = assetName;
            long n;
            if (siteId != null && long.TryParse(siteId, out n)) { o["SiteId"] = n; }

            // v1.0.160.55: a cause depends on a SET of attributes, not one. Build the set (L1 cause map,
            // L2 every condition failing-first, L3 circuit-wisdom drivers of derived members). Taking
            // triggeredConditions[0] was the 522365 bug: that card's [0] is the condition that PASSED.
            List<string> drivers = DriverSetForCause(ctx);
            string want = "";
            if (drivers.Count > 0) { want = drivers[0]; }
            else if (ctx != null) { want = GetCtx(ctx, "causeCode"); }
            string canonical = DomainAttributeName(want);
            // v1.0.86.0: for a DERIVED alert, DO NOT narrow by AttributeName. The
            // derived name ("RRAIL") is NOT a stored tag, so AttributeName="RRAIL"
            // makes the server return ZERO rows (confirmed on the wire: prefetch
            // search {AssetName:117T, AttributeName:RRAIL} -> "No tags found", while
            // the same asset by AssetId returns all 11 component tags). The derived
            // branch needs the FULL tag list to resolve its formula components, so
            // suppress the narrowing here and let it come back unfiltered.
            // v1.0.152.2: SAME problem for POINT MACHINE and IPS -- their tags are named by
            // number ("NNNNN-PM-02002-*"), so narrowing by the human AttributeName returns
            // few/zero rows and starves the attid resolver (which needs the asset's FULL tag
            // list to match by attid). Confirmed on the wire (asset 41898): {AttributeName:
            // "B END - NW-V"} -> 1 row, while AssetId returns all 32 tags. Suppress narrowing
            // for PM/IPS too; fetch the full list and let the attid fast-path pick by number.
            string _ccW = ctx != null ? GetCtx(ctx, "causeCode") : null;
            bool _pmOrIps = (ctx != null && IsPointCard(ctx))
                || (!string.IsNullOrEmpty(_ccW) && _ccW.Trim().ToUpperInvariant().StartsWith("PT "))
                || (!string.IsNullOrEmpty(_ccW) && _ipsCauseAttid.ContainsKey(_ccW.Trim()));
            // v1.0.160.55: more than one driver -> do NOT narrow. AttributeName selects ONE attribute,
            // so a multi-driver cause would starve on the others. Fetch the asset's full tag list and
            // let the matcher pick, exactly as the derived and PM/IPS branches already do.
            // v1.0.160.56: NO AiLog here -- this method is static and AiLog is an instance member
            // (that was the 160.55 CS0120). The driver set is logged at the instance call site below.
            bool _multiDriver = drivers.Count > 1;
            if (!string.IsNullOrEmpty(canonical) && !isDerived && !_pmOrIps && !_multiDriver)
            {
                // DomainAttributeName returns an UPPERCASE canonical ("IR MA"); the
                // server ILIKE is case-insensitive, so this matches "Ir mA".
                o["AttributeName"] = canonical;
            }
            // search_tags default Limit is 3 (doc 2.1); keep an explicit higher value
            // so an asset's full attribute set is available to the matcher. Server
            // hard cap is 50, so ask for exactly that (60 previously exceeded the cap).
            o["Limit"] = 50;
            return o;
        }

        // Word overlap alone cannot do this. The alert names the parameter in
        // ENGINEERING terms -- "ITC RELAY END(mA)" -- while the tag is called "Ir mA".
        // "RELAY" appears in neither tag name, and "MA" matches If/Ir/Charger equally,
        // so the overlap score picked whichever came first. The mapping is domain
        // knowledge: Ir is relay-end current, If is feed-end current, Vr/Vf the
        // corresponding voltages. Returns null when no rule applies, and the caller
        // then falls back to word overlap.
        // v1.0.85.0: authoritative alias -> Title map (Track), from the site's
        // Attribute alias table. The ALERT CARD formula uses ALIAS names
        // ("ITC FEED END(mA)"); search_tags works on the REAL Title name ("If mA").
        // So component resolution MUST go alias -> Title -> tag. Keys are the alias
        // NORMALIZED (unit stripped, whitespace collapsed, upper). This replaces the
        // old Contains()-based guesswork, which mis-resolved names like
        // "ITC TFC O/P" (-> should be Charger mA) and could not handle O/P at all.
        // v1.0.91.0 STAGE 1: the alias->Title map now comes from RdpmsMaps.AliasToTitle,
        // GENERATED from the RDPMS wisdom xlsx (all asset types: Track/Signal/Point/IPS/
        // LC/env), replacing the hand-built Track-only table from 1.0.85. The generated
        // map is the single source of truth; edit the xlsx and re-run the converter to
        // update it. See RdpmsMaps.generated.cs.
        private static Dictionary<string, string> _aliasToTitle { get { return RdpmsMaps.AliasToTitle; } }

        // v1.0.91.0 STAGE 2: format the sensor health band + correlation partner for an
        // attribute, from RdpmsMaps.HealthBands (generated from the wisdom xlsx). Returns
        // "" if the attribute has no band (e.g. DERIVED/computed values have none -- they
        // are judged by the computed value, not a sensor band). Keys are matched on the
        // normalized Title AND on the raw component name, since the health table is keyed
        // by tag name (If_mA) which may differ from the alias/title form.
        // v1.0.91.0 STAGE 4: resolve a point-machine OPERATION attid from (assetAttr,
        // direction, dataType) via RdpmsMaps.PmOpAttid (generated from the wisdom xlsx).
        // Point machines carry per-operation telemetry (A/B end x Normal/Reverse x metric)
        // as COMPUTED EdgeX attids (BaseCode+Offset), distinct from the sensed INDICATION
        // channels. assetAttr is AC/AV/BC/BV (A-Current/A-Voltage/B-Current/B-Voltage),
        // dataType is Array/Avg/Min/Max/OperationTime/Count. Returns null if not mapped.
        // NOTE: this resolver is available for a future PM-specific prefetch branch; the
        // PM data model (per-operation, no freshness) differs enough to warrant its own
        // grounding path, mirroring the derived branch. Wired but not yet on the hot path.
        // v1.0.92.0 STAGE 4 (PM branch), room/loc mapping CONFIRMED in 1.0.94.0: the eight
        // DETECTION attribute Titles for a point machine, both ends and both sides. A point end
        // is normally Normal (NWKR up) XOR Reverse (RWKR up); A-END normally agrees with B-END.
        // Owner-confirmed model: ROOM-SIDE (A/B End - NWKR/RWKR) is AUTHORITATIVE (what the
        // interlocking acts on); LOCATION-SIDE (...(Loc)) is field truth before the cable run
        // back to the relay room. A (Loc)-vs-room mismatch supports localizing to the cable
        // path (telemetry alone does not name the failed part). All eight are listed so the
        // model can tell relay-room vs cable vs location-side incoherence apart; it is told to
        // trust a value for incidence coherence only when timestamp-aligned. Live per-relay
        // fetch is still not built (needs a real PM alert to validate against).
        private static readonly string[] _pmDetectionAttrs = new string[]
        {
            "A End - NWKR", "A End - RWKR", "B End - NWKR", "B End - RWKR",
            "A End - NWKR (Loc)", "A End - RWKR (Loc)", "B End - NWKR (Loc)", "B End - RWKR (Loc)"
        };

        // Is this a point-machine alert? (cause code PT * -> POINT MACHINE)
        private static bool IsPointCard(JObject ctx)
        {
            return AssetTypeFor(GetCtx(ctx, "causeCode")) == "POINT MACHINE";
        }

        // v1.0.96.0: is this specifically a point DETECTION-RELAY cause? For these, detection
        // disagreement MAY CONFIRM the reported condition; for all other point causes
        // (operation/current/voltage) disagreement weakens the mechanical assessment. Labeling
        // the class explicitly stops the model inferring it from similar cause-code wording.
        private static bool IsPointDetectionRelayCause(string causeCode)
        {
            string c = (causeCode ?? "").Trim().ToUpperInvariant();
            return c == "PT NWKR RELAY DEFECT"
                || c == "PT RWKR RELAY DEFECT"
                || c == "PT NWKR RELAY DEFECT OP"
                || c == "PT RWKR RELAY DEFECT OP";
        }

        // v1.0.123.0: resolve which point-machine END (A or B) an alert refers to, from the
        // alert's paramLabel/description (e.g. "A TPT R" -> A, "B TPT R" -> B). Returns "A", "B",
        // or null if not stated. Card shows paramLabel like "A TPT R", so this is reliable.
        private static string PmEndFromAlert(JObject ctx)
        {
            string[] probes = {
                GetCtx(ctx, "paramLabel"), GetCtx(ctx, "description"),
                GetCtx(ctx, "rawMessage"), GetCtx(ctx, "assetName")
            };
            // also look inside alertCard.triggeredConditions[0].paramLabel
            JToken card = ctx["alertCard"];
            JObject co = card as JObject;
            if (co != null)
            {
                JArray tc = co["triggeredConditions"] as JArray;
                JObject t0 = (tc != null && tc.Count > 0) ? tc[0] as JObject : null;
                if (t0 != null && t0["paramLabel"] != null)
                { probes = AppendOne(probes, t0["paramLabel"].ToString()); }
            }
            for (int i = 0; i < probes.Length; i++)
            {
                string p = probes[i];
                if (string.IsNullOrEmpty(p)) { continue; }
                string u = " " + p.Trim().ToUpperInvariant() + " ";
                // "A TPT", "A END", "A-END", leading "A "
                if (u.Contains(" A TPT") || u.Contains(" A END") || u.Contains(" A-END") || u.StartsWith(" A ")) { return "A"; }
                if (u.Contains(" B TPT") || u.Contains(" B END") || u.Contains(" B-END") || u.StartsWith(" B ")) { return "B"; }
            }
            return null;
        }

        private static string[] AppendOne(string[] arr, string v)
        {
            string[] o = new string[arr.Length + 1];
            Array.Copy(arr, o, arr.Length); o[arr.Length] = v; return o;
        }

        // v1.0.123.0: the EXACT tags a point operation-TIME cause needs (owner spec): the
        // operation-TIME of the alerting END (A or B, resolved from the description) + the two
        // proving relays WCR and WKR (they prove the operation actually occurred and completed).
        // Reverse (PT R TIME): op-time 6005(A)/8005(B) + RWCR 283 + RWKR 268.
        // Normal  (PT N TIME): op-time 1005(A)/3005(B) + NWCR 282 + NWKR 267.
        // Returns (attid, label) pairs; empty if not a TIME cause. If the end is unknown, BOTH
        // ends' op-time are included (so it still fetches something useful).
        // v1.0.124.0: UNIFIED per-cause point-machine tag spec, from the CORRECTED owner mapping.
        // Each point cause -> the exact tags its FRS logic needs, resolved by AssetAttributeId via
        // search_tags -> history_get. End-specific tags (op-time/current/voltage, and the per-END
        // indication voltages) carry A & B attids and are picked by the alert's END. Relays carry a
        // primary + alt attid (e.g. NWCR 282/284). The VPT-110 DC / IPT / VIPS-110 params resolve
        // via the EXISTING attribute mapping and are deliberately NOT repeated here (owner).
        private sealed class PmTag
        {
            public readonly string A;     // A-end attid (or the single attid)
            public readonly string B;     // B-end attid; null if not end-specific
            public readonly string Alt;   // alternate attid; null if none
            public readonly string Label;
            public PmTag(string a, string b, string alt, string label) { A = a; B = b; Alt = alt; Label = label; }
        }

        // reusable tag templates -------------------------------------------------
        // operation (EdgeX op attids), end-specific A/B:
        private static readonly PmTag PmOpTimeN = new PmTag("1005", "3005", null, "op-time (N)");
        private static readonly PmTag PmOpTimeR = new PmTag("6005", "8005", null, "op-time (R)");
        private static readonly PmTag PmCurrN   = new PmTag("1002", "3002", null, "current (N)");
        private static readonly PmTag PmCurrR   = new PmTag("6002", "8002", null, "current (R)");
        private static readonly PmTag PmVoltN   = new PmTag("2002", "4002", null, "voltage (N)");
        private static readonly PmTag PmVoltR   = new PmTag("7002", "9002", null, "voltage (R)");
        // indication (RDPMS), corrected per-END attids:
        private static readonly PmTag PmInd24N  = new PmTag("576", "578", null, "VPT 24 DC LOC N");
        private static readonly PmTag PmInd24R  = new PmTag("577", "579", null, "VPT 24 DC LOC R");
        private static readonly PmTag PmIndNWKR = new PmTag("25", "27", null, "VPT NWKR");
        private static readonly PmTag PmIndRWKR = new PmTag("26", "28", null, "VPT RWKR");
        // datalogger relays (primary + alt; not end-specific):
        private static readonly PmTag PmNWCR = new PmTag("282", null, null, "NWCR relay");   // v1.0.152.2: alt 284 removed (NWCR resolves on 282 only)
        private static readonly PmTag PmRWCR = new PmTag("283", null, null, "RWCR relay");
        private static readonly PmTag PmNWKR = new PmTag("267", null, null, "NWKR relay");
        private static readonly PmTag PmRWKR = new PmTag("268", null, null, "RWKR relay");

        // v1.0.160.6: point-machine VALUE-attid -> FRS-RANGE-attid map. The operation VALUE lives
        // under the EdgeX/search_tags attid (2002 "..-PM-02002-Avg"), but its Min/MaxSafe RANGE
        // lives under a DIFFERENT RDPMS attid in the FRS range DB (216 "A End - NW-V"). Two
        // databases, two attid schemes for the SAME physical quantity -- so a PT operation cause
        // must translate the value-attid to its range-attid to read the threshold from
        // get_attribute_range / get_asset_tags. Confirmed on asset 43022: attid 216 carries
        // MinValue 90 / MaxValue 135 for the NW voltage whose value is attid 2002.
        //   voltage N: 2002/4002(A/B value) -> 216/212(range)   current N: 1002/3002 -> 217/213
        //   voltage R: 7002/9002            -> 218/214          current R: 6002/8002 -> 219/215
        //   op-time N: 1005/3005            -> 581/583          op-time R: 6005/8005 -> 582/584
        private static readonly Dictionary<string, string> _pmValueToRangeAttid =
            new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            { "2002", "216" }, { "4002", "212" },   // NW voltage A / B
            { "1002", "217" }, { "3002", "213" },   // NW current A / B
            { "7002", "218" }, { "9002", "214" },   // RW voltage A / B
            { "6002", "219" }, { "8002", "215" },   // RW current A / B
            { "1005", "581" }, { "3005", "583" },   // NW op-time A / B
            { "6005", "582" }, { "8005", "584" },   // RW op-time A / B
        };

        // Returns the FRS-range attid for a point-machine operation VALUE attid, or the input
        // unchanged when there is no distinct range attid (indication/relay attids already carry
        // their own range).
        private static string PmRangeAttidFor(string valueAttid)
        {
            if (string.IsNullOrEmpty(valueAttid)) { return valueAttid; }
            string r;
            return _pmValueToRangeAttid.TryGetValue(valueAttid.Trim(), out r) ? r : valueAttid;
        }

        // v1.0.143.0: IPS cause -> attid (same model as point machines). IPS cause -> attid ->
        // PickTagIdByAttrId(AssetId, attid) -> TagID, matching AssetAttributeId (not name). 42 of 46
        // IPS causes mapped; the 4 bare 24V/60V causes have no attribute in CauseToAttributes.
        private static readonly Dictionary<string, string> _ipsCauseAttid =
            new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            { "IPS 110V DC LOW", "616" }, { "IPS 110V AC LOW", "617" },
            { "IPS 110 DC BATT VOLT LOW (Charging)", "616" }, { "IPS 110 DC BATT VOLT LOW (Discharging)", "616" },
            { "IPS 110 AC Sig-1 VOLT LOW", "617" }, { "IPS 110 AC TR-1 VOLT LOW", "621" },
            { "IPS SMR-1 VOLT LOW", "625" }, { "IPS DC-DC R INT VOLT LOW", "647" },
            { "IPS DC-DC R EXT VOLT LOW", "648" }, { "IPS DC-DC AXLE C VOLT LOW", "649" },
            { "IPS DC-DC PAN IND VOLT LOW", "650" }, { "IPS DC-DC BLOCK LOCAL VOLT LOW", "651" },
            { "IPS DC-DC HKT MAG VOLT LOW", "652" }, { "IPS DC-DC BLOCK LINE UP VOLT LOW", "653" },
            { "IPS DC-DC BLOCK LINE DN VOLT LOW", "654" }, { "IPS DC-DC BLOCK TEL UP VOLT LOW", "655" },
            { "IPS DC-DC BLOCK TEL DN VOLT LOW", "656" }, { "IPS DC-DC DATALOG VOLT LOW", "657" },
            { "IPS 110V DC FAIL", "616" }, { "IPS 110V AC FAIL", "617" },
            { "IPS 110 DC VOLT FAIL", "616" }, { "IPS 110 AC Sig-1 VOLT FAIL", "617" },
            { "IPS 110 AC TR-1 VOLT FAIL", "621" }, { "IPS SMR-1 VOLT FAIL", "625" },
            { "IPS DC-DC R INT VOLT FAIL", "647" }, { "IPS DC-DC R EXT VOLT FAIL", "648" },
            { "IPS DC-DC AXLE C VOLT FAIL", "649" }, { "IPS DC-DC PAN IND VOLT FAIL", "650" },
            { "IPS DC-DC BLOCK LOCAL VOLT FAIL", "651" }, { "IPS DC-DC HKT MAG VOLT FAIL", "652" },
            { "IPS DC-DC BLOCK LINE UP VOLT FAIL", "653" }, { "IPS DC-DC BLOCK LINE DN VOLT FAIL", "654" },
            { "IPS DC-DC BLOCK TEL UP VOLT FAIL", "655" }, { "IPS DC-DC BLOCK TEL DN VOLT FAIL", "656" },
            { "IPS DC-DC DATALOG VOLT FAIL", "657" },
            { "IPS I/P VOLT LOW", "660" }, { "IPS I/P VOLT FAIL", "660" },
            { "IPS DC-DC EI VOLT LOW", "658" }, { "IPS DC-DC EI VOLT FAIL", "658" },
            { "IPS BATT CHAR CURR LOW", "659" }, { "IPS BATT CHAR CURR FAIL", "659" },
            { "IPS DC-DC BATT CHAR CURR FAIL", "659" },
        };

        private static readonly Dictionary<string, PmTag[]> _pmCauseTags =
            new Dictionary<string, PmTag[]>(StringComparer.OrdinalIgnoreCase)
        {
            // operation causes (op tags + proving relays)
            { "PT N TIME HIGH",          new PmTag[] { PmOpTimeN, PmNWCR, PmNWKR } },
            { "PT R TIME HIGH",          new PmTag[] { PmOpTimeR, PmRWCR, PmRWKR } },
            { "PT N VOLT/CURR LOW",      new PmTag[] { PmVoltN, PmCurrN, PmNWCR, PmNWKR } },
            { "PT R VOLT/CURR LOW",      new PmTag[] { PmVoltR, PmCurrR, PmRWCR, PmRWKR } },
            { "PT N VOLT/CURR FAIL",     new PmTag[] { PmVoltN, PmCurrN, PmNWCR, PmNWKR } },
            { "PT R VOLT/CURR FAIL",     new PmTag[] { PmVoltR, PmCurrR, PmRWCR, PmRWKR } },
            { "PT N OBS",                new PmTag[] { PmVoltN, PmCurrN, PmOpTimeN, PmNWCR, PmNWKR } },
            { "PT R OBS",                new PmTag[] { PmVoltR, PmCurrR, PmOpTimeR, PmRWCR, PmRWKR } },
            { "PT VOLT FAIL AT NWKR OP", new PmTag[] { PmInd24N, PmIndNWKR, PmNWCR, PmNWKR } },
            { "PT VOLT FAIL AT RWKR OP", new PmTag[] { PmInd24R, PmIndRWKR, PmRWCR, PmRWKR } },
            { "PT NWKR RELAY DEFECT OP", new PmTag[] { PmIndNWKR, PmNWCR, PmNWKR } },
            { "PT RWKR RELAY DEFECT OP", new PmTag[] { PmIndRWKR, PmRWCR, PmRWKR } },
            // indication / relay-defect causes (per-END indication + relays)
            { "PT N IND VOLT LOW AT LOC",  new PmTag[] { PmInd24N, PmNWKR } },
            { "PT R IND VOLT LOW AT LOC",  new PmTag[] { PmInd24R, PmRWKR } },
            { "PT VOLT LOW AT NWKR",       new PmTag[] { PmInd24N, PmIndNWKR, PmNWKR } },
            { "PT VOLT LOW AT RWKR",       new PmTag[] { PmInd24R, PmIndRWKR, PmRWKR } },
            { "PT NWKR RELAY DEFECT",      new PmTag[] { PmIndNWKR, PmNWCR, PmRWCR, PmRWKR, PmNWKR } },
            { "PT RWKR RELAY DEFECT",      new PmTag[] { PmIndRWKR, PmNWCR, PmRWCR, PmNWKR, PmRWKR } },
            { "PT N IND VOLT FAIL AT LOC", new PmTag[] { PmInd24N, PmNWCR, PmRWCR, PmRWKR, PmNWKR } },
            { "PT R IND VOLT FAIL AT LOC", new PmTag[] { PmInd24R, PmNWCR, PmRWCR, PmNWKR, PmRWKR } },
            { "PT VOLT FAIL AT NWKR",      new PmTag[] { PmInd24N, PmIndNWKR, PmNWCR, PmRWCR, PmRWKR, PmNWKR } },
            { "PT VOLT FAIL AT RWKR",      new PmTag[] { PmInd24R, PmIndRWKR, PmNWCR, PmRWCR, PmNWKR, PmRWKR } },
            // unknown causes (relays + OPERATION values so the model can RECLASSIFY -- v1.0.160.22:
            // fetch the end's op voltage/current/op-time; if one clearly breaches (110V collapsed,
            // op-time > 150% avg, current abnormal) the verdict can name the REAL cause instead of
            // echoing UNKNOWN. Op tags resolve by EdgeX-op attid; range via PmRangeAttidFor (RDPMS).
            { "PT N FAIL UNKNOWN",         new PmTag[] { PmVoltN, PmCurrN, PmOpTimeN, PmNWCR, PmRWCR, PmRWKR, PmNWKR } },
            { "PT R FAIL UNKNOWN",         new PmTag[] { PmVoltR, PmCurrR, PmOpTimeR, PmNWCR, PmRWCR, PmNWKR, PmRWKR } },
            { "PT N FAIL UNKNOWN OP",      new PmTag[] { PmVoltN, PmCurrN, PmOpTimeN, PmNWCR, PmNWKR } },
            { "PT R FAIL UNKNOWN OP",      new PmTag[] { PmVoltR, PmCurrR, PmOpTimeR, PmRWCR, PmRWKR } },
        };

        // v1.0.124.0: resolve a point cause + END to the flat list of [attid, alt, label] to fetch.
        // End-specific tags are picked by END (unknown -> both A & B). Relays/single tags pass
        // through. VPT-110/IPT/VIPS-110 are handled by the existing mapping and not included here.
        private static List<string[]> PmTagsForCause(string causeCode, string end)
        {
            List<string[]> outp = new List<string[]>();
            if (string.IsNullOrEmpty(causeCode)) { return outp; }
            PmTag[] spec;
            if (!_pmCauseTags.TryGetValue(causeCode.Trim(), out spec) || spec == null) { return outp; }
            for (int i = 0; i < spec.Length; i++)
            {
                PmTag t = spec[i];
                if (!string.IsNullOrEmpty(t.B))   // end-specific (A/B)
                {
                    // v1.0.154.0: emit the alert's end FIRST, then the OTHER end as a fallback in
                    // the SAME entry (Item2). Some point machines store both ends' operation
                    // voltage/current in ONE channel (proven on asset 41898: B-end attid 4002 is
                    // absent, but A-end 2002 carries the B-end incidence value 72.64V). Without the
                    // cross-end fallback a B-end alert looks for 4002, misses, and goes INCONCLUSIVE
                    // even though 2002 has the data. PickTagIdByAttrId tries Item1 then Item2.
                    if (end == "A") { outp.Add(new string[] { t.A, t.B, t.Label + " A" }); }
                    else if (end == "B") { outp.Add(new string[] { t.B, t.A, t.Label + " B" }); }
                    else
                    {
                        outp.Add(new string[] { t.A, t.B, t.Label + " A" });
                        outp.Add(new string[] { t.B, t.A, t.Label + " B" });
                    }
                }
                else { outp.Add(new string[] { t.A, t.Alt, t.Label }); }
            }
            return outp;
        }

        // v1.0.120.0: resolve a TagId from an already-fetched search_tags result by NUMERIC
        // AssetAttributeId (the EdgeX op attid), scoped to this asset. This is the option-A
        // resolution path: get_asset_tags carries no TagId, search_tags is the only source, so we
        // reuse the prefetched search_tags payload and match on AssetAttributeId (exact, numeric -
        // more robust than name matching). Returns null if not present.
        // v1.0.144.0: IPS-only fallback resolver - return the TagID of ANY tag registered for the
        // given assetId (the first one found), regardless of attribute. Used only when the mapped
        // IPS attid does not resolve, to ground on the asset's available telemetry instead of going
        // INCONCLUSIVE. NOTE: the returned tag may be a DIFFERENT attribute than the alerting one.
        private static string PickAnyTagIdForAsset(string tagsJson, string assetId)
        {
            if (string.IsNullOrEmpty(tagsJson) || string.IsNullOrEmpty(assetId)) { return null; }
            try
            {
                List<JToken> docs = ParseJsonDocuments(tagsJson);
                for (int d = 0; d < docs.Count; d++)
                {
                    foreach (JToken row in docs[d].SelectTokens("$..*"))
                    {
                        JObject o = row as JObject;
                        if (o == null) { continue; }
                        JToken tid = PropCI(o, "TagID") ?? PropCI(o, "TagId") ?? PropCI(o, "tag");
                        if (tid == null) { continue; }
                        JToken aid = PropCI(o, "AssetId");
                        if (aid != null && string.Equals(aid.ToString(), assetId, StringComparison.Ordinal))
                        { return tid.ToString(); }
                    }
                }
            }
            catch { }
            return null;
        }

        private static string PickTagIdByAttrId(string tagsJson, string assetId, string attid)
        {
            if (string.IsNullOrEmpty(tagsJson) || string.IsNullOrEmpty(attid)) { return null; }
            try
            {
                List<JToken> docs = ParseJsonDocuments(tagsJson);
                for (int d = 0; d < docs.Count; d++)
                {
                    foreach (JToken row in docs[d].SelectTokens("$..*"))
                    {
                        JObject o = row as JObject;
                        if (o == null) { continue; }
                        JToken tid = PropCI(o, "TagID") ?? PropCI(o, "TagId") ?? PropCI(o, "tag");
                        // v1.0.122.0: the tag table exposes the op attid under BOTH AssetAttributeId
                        // and EdgeXAttributeId (= 6005); other history responses use AttributeId.
                        // Match any of them so resolution works across formats.
                        JToken aaid = PropCI(o, "AssetAttributeId") ?? PropCI(o, "EdgeXAttributeId") ?? PropCI(o, "AttributeId");
                        if (tid == null || aaid == null) { continue; }
                        if (!string.Equals(aaid.ToString().Trim(), attid, StringComparison.Ordinal)) { continue; }
                        JToken aid = PropCI(o, "AssetId");
                        if (assetId != null && aid != null && !string.Equals(aid.ToString(), assetId, StringComparison.Ordinal)) { continue; }
                        return tid.ToString();
                    }
                }
            }
            catch { }
            return null;
        }

        // v1.0.160.108: datatype is binary -- RoleType starting 'D' = DataLogger, everything else
        // (RDPMS, empty, unknown) = RDPMS. This is the fixed rule the resolver keys on.
        private static bool IsDataLoggerRole(string roleType)
        {
            string r = (roleType ?? "").Trim();
            return r.Length > 0 && (r[0] == 'D' || r[0] == 'd');
        }

        // v1.0.160.108: THE fixed resolution rule -- AssetId + attid + datatype -> TagID. Splits the
        // attid-6 collision (TPR DataLogger vs TPR V RDPMS) that the datatype-blind 3-arg form cannot.
        private static string PickTagIdByAttrId(string tagsJson, string assetId, string attid, bool wantDataLogger)
        {
            if (string.IsNullOrEmpty(tagsJson) || string.IsNullOrEmpty(attid)) { return null; }
            try
            {
                List<JToken> docs = ParseJsonDocuments(tagsJson);
                for (int d = 0; d < docs.Count; d++)
                {
                    foreach (JToken row in docs[d].SelectTokens("$..*"))
                    {
                        JObject o = row as JObject;
                        if (o == null) { continue; }
                        JToken tid = PropCI(o, "TagID") ?? PropCI(o, "TagId") ?? PropCI(o, "tag");
                        JToken aaid = PropCI(o, "AssetAttributeId") ?? PropCI(o, "EdgeXAttributeId") ?? PropCI(o, "AttributeId");
                        if (tid == null || aaid == null) { continue; }
                        if (!string.Equals(aaid.ToString().Trim(), attid, StringComparison.Ordinal)) { continue; }
                        JToken aid = PropCI(o, "AssetId");
                        if (assetId != null && aid != null && !string.Equals(aid.ToString(), assetId, StringComparison.Ordinal)) { continue; }
                        JToken rt = PropCI(o, "RoleType");
                        if (IsDataLoggerRole(rt == null ? "" : rt.ToString()) != wantDataLogger) { continue; }
                        return tid.ToString();
                    }
                }
            }
            catch { }
            return null;
        }

        // v1.0.92.0: reverse index into HealthBands built from each band's Resolves field
        // (e.g. "RDPMS: TR V (Relay) / VTC TR") plus the raw band key. The direct key match
        // misses titles whose normalized form keeps a non-unit qualifier - e.g. component
        // "TR V (Relay)" normalizes to TR_V_(RELAY) but the band key is TR_V. Indexing every
        // name that appears in Resolves (and the key itself) lets a component Title, alias, or
        // tag-name all reach the right band. Built once, lazily.
        private static Dictionary<string, RdpmsMaps.HealthBand> _healthBandIndex;
        private static readonly object _hbLock = new object();
        private static Dictionary<string, RdpmsMaps.HealthBand> HealthBandIndex()
        {
            if (_healthBandIndex != null) { return _healthBandIndex; }
            lock (_hbLock)
            {
                if (_healthBandIndex != null) { return _healthBandIndex; }
                var idx = new Dictionary<string, RdpmsMaps.HealthBand>(StringComparer.Ordinal);
                foreach (var kv in RdpmsMaps.HealthBands)
                {
                    // the raw key (IF_MA) and its space form
                    idx[kv.Key] = kv.Value;
                    idx[kv.Key.Replace('_', ' ')] = kv.Value;
                    // every name in Resolves: "RDPMS: TR V (Relay) / VTC TR"
                    string res = kv.Value.Resolves ?? "";
                    int colon = res.IndexOf(':');
                    if (colon >= 0) { res = res.Substring(colon + 1); }
                    foreach (string part in res.Split('/'))
                    {
                        string nk = NormAttrKey(part);
                        if (nk.Length > 0 && !idx.ContainsKey(nk)) { idx[nk] = kv.Value; }
                        string nku = nk.Replace(' ', '_');
                        if (nku.Length > 0 && !idx.ContainsKey(nku)) { idx[nku] = kv.Value; }
                    }
                }
                _healthBandIndex = idx;
                return idx;
            }
        }

        private static string HealthBandNote(string attrName)
        {
            if (string.IsNullOrEmpty(attrName)) { return ""; }
            var idx = HealthBandIndex();
            RdpmsMaps.HealthBand band;
            bool found = idx.TryGetValue(NormAttrKey(attrName), out band)
                      || idx.TryGetValue(NormAttrKey(attrName).Replace(' ', '_'), out band);
            if (!found)
            {
                // resolve alias -> Title, then try again
                string title;
                if (_aliasToTitle.TryGetValue(NormAttrKey(attrName), out title))
                {
                    found = idx.TryGetValue(NormAttrKey(title), out band)
                         || idx.TryGetValue(NormAttrKey(title).Replace(' ', '_'), out band);
                }
            }
            if (!found) { return ""; }
            string note = " valid [" + band.Min.ToString(System.Globalization.CultureInfo.InvariantCulture)
                + "-" + band.Max.ToString(System.Globalization.CultureInfo.InvariantCulture) + "]";
            if (!string.IsNullOrEmpty(band.Corr)) { note += ", correlate with " + band.Corr; }
            return note;
        }

        // Normalize an attribute name for alias-map lookup. v1.0.91.0: strip only a
        // recognized FINAL unit suffix -- (mA),(V),(A),(ohm),(C),(%) etc. -- and PRESERVE
        // semantic qualifiers like (BUG),(CUG),(AUG),(Sig),(Loc). Stripping from the first
        // '(' (the old behavior) collapsed distinct attributes: IROSIG (CUG) and
        // IROSIG (BUG) are different route-signal phases, not units. Must match the
        // converter's norm() exactly so lookups hit the generated keys.
        private static readonly System.Text.RegularExpressions.Regex _unitSuffix =
            new System.Text.RegularExpressions.Regex(
                @"\s*\((?:mA|A|V|ohm|C|%|sec|s|Hz|W|kW|VA)\)\s*$",
                System.Text.RegularExpressions.RegexOptions.IgnoreCase);
        private static string NormAttrKey(string s)
        {
            if (string.IsNullOrEmpty(s)) { return ""; }
            string prev = null;
            while (prev != s) { prev = s; s = _unitSuffix.Replace(s, ""); }
            s = System.Text.RegularExpressions.Regex.Replace(s, @"\s+", " ").Trim();
            return s.ToUpperInvariant();
        }

        // v1.0.85.0: resolve an alert-card attribute name (alias OR already-Title) to
        // the real Title used by search_tags. Falls back to the legacy heuristic only
        // if the alias table has no entry (keeps behavior for anything not yet mapped).
        private static string DomainAttributeName(string want)
        {
            if (string.IsNullOrEmpty(want)) { return null; }
            string key = NormAttrKey(want);
            string title;
            if (_aliasToTitle.TryGetValue(key, out title)) { return title.ToUpperInvariant(); }
            // legacy fallback (unmapped names): old Contains heuristic
            string u = want.ToUpperInvariant();
            bool isI = u.Contains("(MA)") || u.Contains(" MA") || u.Contains("CURR") || u.StartsWith("I");
            if (u.Contains("CHOKE")) { return "CHOKE V"; }
            if (u.Contains("CHARGER")) { return isI ? "CHARGER MA" : "CHARGER OP V"; }
            if (u.Contains("TPR"))
            {
                if (u.Contains("LOC")) { return "TPR V (LOC)"; }
                return "TPR V";
            }
            if (u.Contains(" TR") || u.EndsWith("TR") || u.Contains("TRACK RELAY")) { return "TR V (RELAY)"; }
            bool relay = u.Contains("RELAY END") || u.Contains("RELAY-END") || u.Contains("(IR)");
            bool feed = u.Contains("FEED END") || u.Contains("FEED-END") || u.Contains("(IF)");
            if (relay) { return isI ? "IR MA" : "VR"; }
            if (feed) { return isI ? "IF MA" : "VF"; }
            return null;
        }

        // v1.0.160.12: a triggered condition "failed" if its own status is FAIL, or any of its
        // threshold rows is FAIL. Card 'main' conditions carry status on thresholds[]; some (ips)
        // carry a top-level status. Used to anchor coverage on the DECIDING (failed) attribute.
        private static bool TriggeredConditionFailed(JObject cond)
        {
            if (cond == null) { return false; }
            JToken st = cond["status"];
            if (st != null && st.ToString().ToUpperInvariant() == "FAIL") { return true; }
            JToken thrs = cond["thresholds"];
            if (thrs != null && thrs.Type == JTokenType.Array)
            {
                foreach (JToken tk in (JArray)thrs)
                {
                    JObject to = tk as JObject; if (to == null) { continue; }
                    JToken ts = to["status"];
                    if (ts != null && ts.ToString().ToUpperInvariant() == "FAIL") { return true; }
                }
            }
            return false;
        }

        // v1.0.160.111 (BUG-5): true if ANY triggered condition on the card carries a FAIL. When the
        // card provides the failing value, the incidence is established regardless of history density,
        // so the coverage gate must not downgrade to "Coverage gap".
        private static bool CardHasFailCondition(JObject ctx)
        {
            try
            {
                JToken card = ctx != null ? ctx["alertCard"] : null;
                JToken tc = card != null ? card["triggeredConditions"] : null;
                if (tc is JArray)
                {
                    foreach (JToken c in (JArray)tc)
                    {
                        if (TriggeredConditionFailed(c as JObject)) { return true; }
                    }
                }
            }
            catch { }
            return false;
        }

        // v1.0.160.170: the 10 TC FAILURE causes (same list as the TRACK-FAILURE TRAIN-MOVEMENT CHECK
        // in the prompt). A failure on any of these cannot end INCONCLUSIVE -- the card FAIL is
        // authoritative; only CONFIRMED (genuine) or NOT_CONFIRMED (train movement) are valid.
        private static readonly HashSet<string> _trackFailureCauses = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
        {
            "TC CKT OPEN", "TC SHORT", "TC RAIL RES OPEN", "TC VAR RES OPEN", "TC CH RES OPEN",
            "TC TFC O/P VOLT FAIL", "TC TR RELAY DEFECT", "TC TR UP TPR DN", "TC TPR RELAY DEFECT",
            "REASON UNKNOWN"
        };
        private static bool IsTrackFailureCauseCode(string cause)
        {
            return !string.IsNullOrEmpty(cause) && _trackFailureCauses.Contains(cause.Trim());
        }

        private static string PickAlertingTagId(string tagsJson, JObject ctx, string assetId)
        {
            if (string.IsNullOrEmpty(tagsJson)) { return null; }
            // v1.0.143.0: ATTID fast paths - resolve the alerting tag by number, not name. PM tags
            // are named "NNNNN-PM-06005-*" (name match fails); IPS resolves the same clean way. Both
            // match AssetAttributeId via PickTagIdByAttrId. Falls through to the name matcher below.
            {
                string cc0 = GetCtx(ctx, "causeCode");
                if (!string.IsNullOrEmpty(cc0) && cc0.Trim().ToUpperInvariant().StartsWith("PT "))
                {
                    List<string[]> pmt = PmTagsForCause(cc0.Trim(), PmEndFromAlert(ctx));
                    for (int i = 0; i < pmt.Count; i++)
                    {
                        string tid = PickTagIdByAttrId(tagsJson, assetId, pmt[i][0]);
                        if (string.IsNullOrEmpty(tid) && !string.IsNullOrEmpty(pmt[i][1]))
                        { tid = PickTagIdByAttrId(tagsJson, assetId, pmt[i][1]); }
                        if (!string.IsNullOrEmpty(tid)) { return tid; }
                    }
                }
                if (!string.IsNullOrEmpty(cc0))
                {
                    string ipsAttid;
                    if (_ipsCauseAttid.TryGetValue(cc0.Trim(), out ipsAttid) && !string.IsNullOrEmpty(ipsAttid))
                    {
                        string tid = PickTagIdByAttrId(tagsJson, assetId, ipsAttid);
                        // v1.0.144.0: IPS-ONLY fallback - if the mapped attid does not resolve,
                        // ground on ANY tag registered for this assetId (whatever attribute it is)
                        // rather than go INCONCLUSIVE for a missing exact tag. IPS only.
                        if (string.IsNullOrEmpty(tid)) { tid = PickAnyTagIdForAsset(tagsJson, assetId); }
                        if (!string.IsNullOrEmpty(tid)) { return tid; }
                    }
                }
            }
            string want = "";
            JToken card = ctx["alertCard"];
            if (card != null && card.Type == JTokenType.Object)
            {
                JToken tc = card["triggeredConditions"];
                if (tc != null && tc.Type == JTokenType.Array && ((JArray)tc).Count > 0)
                {
                    // v1.0.160.12: anchor on the condition that actually FAILED its threshold -- for
                    // a multi-condition AND rule the deciding (failed) attribute is the fault and is
                    // not always triggeredConditions[0]. (505259: [0] ITC RELAY END PASSED, [1] VTC
                    // 24 DC LOC FAILED = the fault; anchoring on [0] coverage-checked the wrong tag
                    // and spuriously downgraded.) Skip type=="ips" corroborators. Fall back to [0]
                    // when none is failed, so single-condition alerts are unchanged.
                    JArray tca = (JArray)tc;
                    JToken chosenCond = null;
                    foreach (JToken ctk in tca)
                    {
                        JObject co = ctk as JObject; if (co == null) { continue; }
                        string cty = co["type"] != null ? co["type"].ToString().ToLowerInvariant() : "";
                        if (cty == "ips") { continue; }
                        if (TriggeredConditionFailed(co)) { chosenCond = co; break; }
                    }
                    if (chosenCond == null) { chosenCond = tca[0]; }
                    JToken p = chosenCond["paramLabel"];
                    if (p != null) { want = p.ToString(); }
                }
            }
            // v1.0.91.0 STAGE 3: if the card gave no paramLabel (want still empty -- the
            // empty-payload/browser case), map the cause code to its alerting attribute via
            // RdpmsMaps.CauseToAttributes (from the wisdom xlsx) instead of matching the raw
            // cause-code text against tag names. The card's paramLabel, when present, remains
            // authoritative and is NOT overridden.
            // NOTE (multi-attribute): 74 of 151 cause codes map to MULTIPLE analog attributes
            // (e.g. TC BALST/SLPR RES LOW -> Ir mA + IBALST). PickAlertingTagId selects ONE
            // tag to anchor the grounding, so it takes the PRIMARY (first) attribute here.
            // This is the correct anchor for the alert's headline condition; the full derived
            // component set is still pulled by the derived branch when the primary is derived.
            // A future refinement (a PrimaryAttribute/role column in the xlsx, or grounding
            // every mapped attribute) is tracked as an open item -- see the changelog.
            if (want.Length == 0)
            {
                string cc = GetCtx(ctx, "causeCode");
                if (!string.IsNullOrEmpty(cc))
                {
                    string[] attrs;
                    if (RdpmsMaps.CauseToAttributes.TryGetValue(cc.Trim(), out attrs) && attrs != null && attrs.Length > 0)
                    {
                        want = attrs[0];   // PRIMARY attribute anchors the grounding tag
                    }
                    else
                    {
                        want = cc;         // no mapping (18 codes) -> raw cause code (legacy)
                    }
                }
            }
            if (want.Length == 0) { return null; }

            // v1.0.160.112 (BUG-2): resolve the alerting tag by ATTID from the AliasName (the card's
            // FAIL-condition paramLabel, or the CauseToAttributes primary). The card carries no attid;
            // RdpmsAttrMap.AttidForAlias bridges AliasName -> attid, then PickTagIdByAttrId matches the
            // series by attid + datatype (RDPMS) -- immune to the card-title <-> attribute-name alias
            // the name scorer below misses (card "VTC 24 DC TPR I/P(V)" vs tag row name "TPR V", both
            // attid 6 -> 527627). Falls through to the existing name/per-end logic when unmapped.
            {
                int aliasAttid = RdpmsAttrMap.AttidForAlias(want);
                if (aliasAttid > 0)
                {
                    string tidByAlias = PickTagIdByAttrId(tagsJson, assetId, aliasAttid.ToString(), false);
                    if (!string.IsNullOrEmpty(tidByAlias)) { return tidByAlias; }
                }
            }

            // v1.0.160.21: PER-END attid anchor -- for the PM NWKR/RWKR causes, resolve the grounding
            // tag by AssetAttributeId (the per-end attid) rather than the generic name, so we anchor
            // on the real A/B-end sensor, not the rollup. Falls through to name scoring if no match.
            {
                string ccPe = GetCtx(ctx, "causeCode");
                int[] peAttids;
                if (!string.IsNullOrEmpty(ccPe)
                    && CauseLogicMaps.CauseToAttributesPerEnd.TryGetValue(ccPe.Trim(), out peAttids))
                {
                    string peTag = PickTagByAttid(tagsJson, assetId, peAttids);
                    if (peTag != null) { return peTag; }
                }
            }

            string[] wantWords = System.Text.RegularExpressions.Regex
                .Split(want.ToUpperInvariant(), "[^A-Z0-9]+");
            string domain = DomainAttributeName(want);
            string bestTag = null; int bestScore = 0;
            string exactTag = null;
            try
            {
                List<JToken> docs = ParseJsonDocuments(tagsJson);
                for (int d = 0; d < docs.Count; d++)
                {
                    foreach (JToken row in docs[d].SelectTokens("$..*"))
                    {
                        JObject o = row as JObject;
                        if (o == null) { continue; }
                        // Real field names, confirmed from a live search_tags response:
                        // TagID, AssetId, AssetAttributeId, AssetAttributeName.
                        // The earlier guesses ("AttributeName"/"Name") matched nothing,
                        // so the matcher silently returned null every time.
                        JToken tid = PropCI(o, "TagID") ?? PropCI(o, "TagId") ?? PropCI(o, "tag");
                        JToken nm = PropCI(o, "AssetAttributeName") ?? PropCI(o, "AttributeName") ?? PropCI(o, "Name");
                        if (tid == null || nm == null) { continue; }
                        // search_tags matches by name, so it can return other assets
                        JToken aid = PropCI(o, "AssetId");
                        if (assetId != null && aid != null && !string.Equals(aid.ToString(), assetId, StringComparison.Ordinal)) { continue; }
                        string upper = nm.ToString().ToUpperInvariant().Trim();
                        // an exact domain hit wins outright -- no scoring needed
                        if (domain != null && upper == domain) { exactTag = tid.ToString(); }
                        int score = 0;
                        for (int w = 0; w < wantWords.Length; w++)
                        {
                            if (wantWords[w].Length < 2) { continue; }
                            if (upper.IndexOf(wantWords[w], StringComparison.Ordinal) >= 0) { score++; }
                        }
                        if (score > bestScore) { bestScore = score; bestTag = tid.ToString(); }
                    }
                }
            }
            catch { return null; }
            if (exactTag != null) { return exactTag; }
            // require more than a single weak word hit: "MA" alone matches several
            // attributes and picking one of them arbitrarily is worse than not guessing
            return bestScore >= 2 ? bestTag : null;
        }

        // v1.0.160.21: return the TagID of the search_tags row whose AssetAttributeId equals one of
        // the given per-end attids (tried in order -- alerting/A-end first) for this asset. Anchors
        // PM NWKR/RWKR grounding on the per-end sensor instead of the generic rollup. Attid match is
        // exact, so it is immune to the VPT110/VPT 110 name-spelling inconsistencies.
        private static string PickTagByAttid(string tagsJson, string assetId, int[] attids)
        {
            if (string.IsNullOrEmpty(tagsJson) || attids == null) { return null; }
            try
            {
                List<JToken> docs = ParseJsonDocuments(tagsJson);
                for (int a = 0; a < attids.Length; a++)
                {
                    string target = attids[a].ToString();
                    for (int d = 0; d < docs.Count; d++)
                    {
                        foreach (JToken row in docs[d].SelectTokens("$..*"))
                        {
                            JObject o = row as JObject;
                            if (o == null) { continue; }
                            JToken aaid = PropCI(o, "AssetAttributeId");
                            if (aaid == null || aaid.ToString().Trim() != target) { continue; }
                            JToken aid = PropCI(o, "AssetId");
                            if (assetId != null && aid != null && !string.Equals(aid.ToString(), assetId, StringComparison.Ordinal)) { continue; }
                            JToken tid = PropCI(o, "TagID") ?? PropCI(o, "TagId") ?? PropCI(o, "tag");
                            if (tid != null) { return tid.ToString(); }
                        }
                    }
                }
            }
            catch { }
            return null;
        }

        // v1.0.78.0: does a search_tags (or history_get) JSON payload contain any
        // row for this AssetId? Used to decide whether a search_tags result is even
        // about the alerting asset before it is shown to the model. Reuses the same
        // document parser and case-insensitive field lookup the matcher uses.
        private static bool TagsContainAsset(string tagsJson, string assetId)
        {
            if (string.IsNullOrEmpty(tagsJson) || string.IsNullOrEmpty(assetId)) { return false; }
            try
            {
                List<JToken> docs = ParseJsonDocuments(tagsJson);
                for (int d = 0; d < docs.Count; d++)
                {
                    foreach (JToken row in docs[d].SelectTokens("$..*"))
                    {
                        JObject o = row as JObject;
                        if (o == null) { continue; }
                        JToken aid = PropCI(o, "AssetId");
                        if (aid != null && string.Equals(aid.ToString(), assetId, StringComparison.Ordinal))
                        {
                            return true;
                        }
                    }
                }
            }
            catch { }
            return false;
        }

        // v1.0.79.0: search_tags result quality metrics for the prefetch log --
        // proves the AssetName-filter fix returns THIS asset's rows rather than an
        // arbitrary set. Counts rows carrying an AssetId, the distinct AssetIds among
        // them, and whether the requested AssetId is present. Reuses the matcher's
        // parser + case-insensitive lookup.
        // v1.0.160.6: shrink a search_tags result by dropping the long "-Array" waveform
        // CurrentValue strings (the 130-point operation waveforms) while keeping every tag's
        // TagID / AssetAttributeId / AssetAttributeName / RoleType / TimestampDevice. The
        // resolver keys on those identity fields, not the waveform values, so this preserves
        // every tag record and stops the payload from ballooning past the transit truncation
        // limit. Best-effort: on any parse failure the original string is returned unchanged.
        private static string StripTagWaveforms(string tagsJson)
        {
            if (string.IsNullOrEmpty(tagsJson)) { return tagsJson; }
            try
            {
                JArray arr = JArray.Parse(tagsJson);
                for (int i = 0; i < arr.Count; i++)
                {
                    JObject o = arr[i] as JObject;
                    if (o == null) { continue; }
                    string nm = (string)o["AssetAttributeName"] ?? "";
                    JToken cv = o["CurrentValue"];
                    string cvs = cv != null ? cv.ToString() : "";
                    bool isArrayName = nm.IndexOf("Array", StringComparison.OrdinalIgnoreCase) >= 0;
                    int commas = 0; for (int c = 0; c < cvs.Length; c++) { if (cvs[c] == ',') { commas++; } }
                    if ((isArrayName || commas >= 8) && cvs.Length > 40)
                    {
                        o["CurrentValue"] = "[waveform omitted]";
                    }
                }
                return arr.ToString(Formatting.None);
            }
            catch { return tagsJson; }
        }

        private static void SearchTagsStats(string tagsJson, string assetId,
            out int rowCount, out int uniqueAssets, out bool hasRequested)
        {
            rowCount = 0; uniqueAssets = 0; hasRequested = false;
            if (string.IsNullOrEmpty(tagsJson)) { return; }
            HashSet<string> seen = new HashSet<string>(StringComparer.Ordinal);
            try
            {
                List<JToken> docs = ParseJsonDocuments(tagsJson);
                for (int d = 0; d < docs.Count; d++)
                {
                    foreach (JToken row in docs[d].SelectTokens("$..*"))
                    {
                        JObject o = row as JObject;
                        if (o == null) { continue; }
                        JToken aid = PropCI(o, "AssetId");
                        if (aid == null) { continue; }
                        rowCount++;
                        string a = aid.ToString();
                        if (seen.Add(a)) { uniqueAssets++; }
                        if (!string.IsNullOrEmpty(assetId) && string.Equals(a, assetId, StringComparison.Ordinal))
                        {
                            hasRequested = true;
                        }
                    }
                }
            }
            catch { }
        }

        // Head-only truncation silently drops whatever a payload puts last, which for
        // an audit is the conclusion. Keep both ends and mark the omission.
        private static string TrimHeadAndTail(string s0, int head, int tail)
        {
            if (string.IsNullOrEmpty(s0)) { return ""; }
            if (s0.Length <= head + tail) { return s0; }
            return s0.Substring(0, head)
                 + "\n...[" + (s0.Length - head - tail) + " chars omitted from the middle]...\n"
                 + s0.Substring(s0.Length - tail);
        }

        private static string TrimForPrompt(string s0, int max)
        {
            if (string.IsNullOrEmpty(s0)) { return ""; }
            return s0.Length <= max ? s0 : s0.Substring(0, max) + " ...[trimmed]";
        }

        // v1.0.83.0: keep the TAIL of a payload, not the head. For a time series the
        // incidence and recovery samples are at the END, so when trimming a component
        // history for the prompt we want the last `max` chars, not the first. Coverage
        // grading already ran on the full raw string upstream, so this is prompt-only.
        private static string TailForPrompt(string s0, int max)
        {
            if (string.IsNullOrEmpty(s0)) { return ""; }
            if (s0.Length <= max) { return s0; }
            return "[trimmed]... " + s0.Substring(s0.Length - max);
        }

        private static void AppendResolvedIds(StringBuilder sb, JObject ctx)
        {
            string site = GetCtx(ctx, "siteId");
            string asset = GetCtx(ctx, "assetId");
            if (site.Length == 0 && asset.Length == 0) { return; }
            sb.Append("- RESOLVED IDS - authoritative, from the alert record. Use directly:").Append("\n");
            if (site.Length > 0) { sb.Append("    SiteId: ").Append(site).Append("\n"); }
            if (asset.Length > 0) { sb.Append("    AssetId: ").Append(asset).Append("\n"); }
            sb.Append("  Do NOT call search_sites or search_assets. Go straight to ");
            sb.Append("search_tags for the TagId, then history_get(TagId). ");
            // v1.0.160.72: this previously offered history_get(AssetId) as a fallback. That form
            // returns EVERY tag on the asset (~60KB), exceeds the transport limit, and the truncation
            // marker is spliced into the MIDDLE of the JSON -- so the whole result is unparseable and
            // the series is LOST rather than shortened.
            sb.Append("NEVER call history_get with AssetId: it returns every tag on the asset, exceeds ");
            sb.Append("the transport limit, and the truncated JSON is DISCARDED -- you get nothing, not ");
            sb.Append("a shorter series. One history_get per TagId instead. The station ");
            sb.Append("below is a site CODE; search_sites matches the site NAME, so searching for ");
            sb.Append("it wastes turns and fails.").Append("\n");
        }

        private static string BuildAnalyzeUserMessage(JObject ctx)
        {
            StringBuilder sb = new StringBuilder();
            sb.Append("Assess this SINGLE railway alert against telemetry and decide whether the ");
            sb.Append("alert is CONFIRMED (the telemetry supports a genuine field condition) or ");
            sb.Append("NOT_CONFIRMED (the telemetry does not support a sustained fault). Use the ");
            sb.Append("MCP tools to pull supporting evidence before deciding. Do NOT describe the ");
            sb.Append("alert as false or wrong; report what the data shows.").Append("\n\n");
            sb.Append("ALERT CONTEXT:").Append("\n");
            sb.Append("- AlertId: ").Append(GetCtx(ctx, "alertId")).Append("\n");
            AppendResolvedIds(sb, ctx);
            sb.Append("- Station/Site: ").Append(GetCtx(ctx, "station")).Append("\n");
            sb.Append("- Asset: ").Append(GetCtx(ctx, "assetName")).Append("\n");
            sb.Append("- Cause code: ").Append(GetCtx(ctx, "causeCode")).Append("\n");
            sb.Append("- Alert type: ").Append(GetCtx(ctx, "alertType")).Append("\n");
            sb.Append("- Incidence time (IST): ").Append(GetCtx(ctx, "time")).Append("\n");
            string reset = GetCtx(ctx, "resetTime");
            if (reset.Length > 0)
            {
                sb.Append("- Rectification/reset time (IST): ").Append(reset).Append("\n");
            }
            string desc = GetCtx(ctx, "description");
            if (desc.Length > 0)
            {
                sb.Append("- Description: ").Append(desc).Append("\n");
            }
            string raw = GetCtx(ctx, "rawMessage");
            if (raw.Length > 0)
            {
                sb.Append("- Alert message: ").Append(raw).Append("\n");
            }
            JToken card = ctx["alertCard"];
            if (card != null && card.Type == JTokenType.Object)
            {
                sb.Append("- Alert condition JSON: ").Append(card.ToString(Formatting.None)).Append("\n");
            }
            JToken rcard = ctx["resetCard"];
            if (rcard != null && rcard.Type == JTokenType.Object)
            {
                sb.Append("- Reset condition JSON: ").Append(rcard.ToString(Formatting.None)).Append("\n");
            }
            DateTime incidence;
            if (TryParseAlertTime(GetCtx(ctx, "time"), out incidence))
            {
                sb.Append("\nFollow the METHOD in the system prompt.").Append("\n");
            sb.Append("\nANALYSIS WINDOW - pass these EXACT strings as the history/trend date ");
                sb.Append("arguments (EdgeX format ddMMyyyy_HHmmss, already IST - do NOT reformat, ");
                sb.Append("do NOT convert to ISO, do NOT shift the timezone):").Append("\n");
                sb.Append("- StartDate: ").Append(incidence.AddDays(-_evidenceWindowDays).ToString("ddMMyyyy_HHmmss")).Append("\n");
                sb.Append("- EndDate: ").Append(incidence.AddHours(2).ToString("ddMMyyyy_HHmmss")).Append("\n");
                sb.Append("- Incidence: ").Append(incidence.ToString("ddMMyyyy_HHmmss")).Append("\n");
                sb.Append("The FRS tools (analyse_alert, get_hist_realtime, fetch_alert_details_frs) ");
                sb.Append("use a DIFFERENT format - for those pass:").Append("\n");
                sb.Append("- alert_timestamp / at_timestamp: ").Append(incidence.ToString("yyyy-MM-dd HH:mm:ss")).Append("\n");
                sb.Append("- start_date: ").Append(incidence.AddDays(-_evidenceWindowDays).ToString("yyyy-MM-dd"));
                sb.Append("   end_date: ").Append(incidence.ToString("yyyy-MM-dd")).Append("\n");
            }

            return sb.ToString();
        }

        // ==================================================================
        // SYNTHESIS PROMPT -- used ONLY when pre-fetch has already gathered the
        // evidence and no tools are being sent.
        //
        // AnalyzeSystemPrompt is ~3,500 tokens, and most of it is tool guidance:
        // which identifier each tool takes, how to size a query, what to do when a
        // lookup fails, which tool supersedes which. None of that applies here --
        // the data is already in the message. What remains is the part that decides
        // the verdict, and it is worth keeping in full.
        // ==================================================================
        private static string AnalyzeSynthesisPrompt()
        {
            StringBuilder sb = new StringBuilder();
            sb.Append("You are a railway signalling diagnostic engineer for Indian Railways RDPMS. ");
            sb.Append("All the evidence needed has already been gathered and is in the user message. ");
            sb.Append("Read it and return ONE verdict. You have no tools; do not ask for more data.").Append("\n\n");

            sb.Append("VERDICT:").Append("\n");
            sb.Append("  CONFIRMED     trustworthy data shows a genuine, sustained field condition").Append("\n");
            sb.Append("  NOT_CONFIRMED trustworthy data shows the condition was transient or within band").Append("\n");
            sb.Append("  INCONCLUSIVE  the data cannot settle it - say what is missing, never guess").Append("\n\n");
            // v1.0.91.0 STAGE 5 (synthesis path): the compact RDPMS domain rules must be on
            // THIS prompt too -- successful prefetch runs use the synthesis prompt, so putting
            // the model only in AnalyzeSystemPrompt() missed the normal fast path.
            sb.Append("RDPMS RULES:").Append("\n");
            sb.Append("  - PREDICTIVE alerts fire on drift vs a rolling average: judge the TREND and whether it self-recovered; a brief excursion that recovers is usually NOT a sustained fault.").Append("\n");
            sb.Append("  - FAILURE alerts fire on a discrete event (relay drop, out-of-band value): judge the EVENT and its duration.").Append("\n");
            sb.Append("  - A sensed value has a valid band and a correlation partner. A value in-band that does NOT track its partner (e.g. voltage present, current ~0) raises a COHERENCE concern - telemetry alone cannot establish whether the sensor, wiring, logger or field asset caused it; report the concern, do not diagnose a specific faulty part.").Append("\n");
            sb.Append("  - DERIVED values (RRAIL, IBALST, ITC BATT CHARG, RTC*) are COMPUTED from components, not sensed - no sensor band; the system supplies the computed value. Point-machine per-operation values exist only during a throw: absence is idle ONLY when timestamped control evidence confirms no NWCR/RWCR command in the same window; a commanded throw with absent IPT/VPT/TPT telemetry is a DATA GAP -> INCONCLUSIVE.").Append("\n");
            // v1.0.92.0: per-asset coherence signatures from the physical circuit topology.
            // These say what a COHERENT reading-set looks like for each asset, sharpening
            // the coherence gate. Incoherence here -> INCONCLUSIVE (not NOT_CONFIRMED).
            sb.Append("COHERENCE BY ASSET TYPE (from the circuit):").Append("\n");
            sb.Append("  - TRACK: feed current (If / ITC FEED END) and relay current (Ir / ITC RELAY END) are ONE loop through the rails. Judge the If-Ir gap against THIS asset's OWN baseline (each attribute's AverageValue is provided) - a gap consistent with the asset's normal is fine at any absolute value; a gap that has clearly WIDENED beyond this asset's baseline, with feed maintained, indicates real ballast/joint leakage (IBALST). Do NOT use a fixed mA threshold - what is normal differs per asset. If If, Ir and TR V are steady while only a derived value moved, suspect the computed value -> INCONCLUSIVE. CAUSAL CHAIN (the mechanism that ends in track loss): rising rail resistance or leakage -> Ir mA or TR V (relay-end voltage) DROPS -> the proving TPR relay at the location (driven by Ir mA / TR V) weakens -> the supply returned to energize TPR V in the relay room degrades -> the track drops SOON. So Ir mA and TR V are the LEADING indicators: a sustained drop in either, especially with the relay-room TPR feed degrading, is imminent track-stability loss - weight it strongly toward CONFIRMED, not a transient. TPR-DROP CAUTION: a TPR relay dropping / de-energizing BY ITSELF is NORMAL TRAIN MOVEMENT (a track circuit's TPR drops every time a train occupies the section) - it is NOT evidence of a fault. Repeated TPR drops are expected traffic. Do NOT treat a TPR-drop count or recurrence as fault evidence and do NOT let it drive CONFIRMED. The 'TPR weakens' in the chain above means a SUSTAINED ELECTRICAL decline of the relay-end feed (Ir mA / TR V trending down vs the asset's baseline with feed held), NOT the momentary de-energization when a train passes. Confirm a predictive rail-resistance/leakage alert from the ELECTRICAL trend, not from TPR drops; TPR drops only support a fault when a genuine TRACK-FAILURE alert also fired on that track, or the drops persist with no train present. Absent a track-fail alert, TPR drops should LOWER confidence or push toward NOT_CONFIRMED / INCONCLUSIVE. Do NOT assign an RRAIL/IBALST alert to the charger merely because charger current changed - the charger is upstream; a common upstream collapse suggests supply influence, a gap widening beyond baseline with feed held supports rail/ballast leakage.").Append("\n");
            sb.Append("  - TRACK-FAILURE TRAIN-MOVEMENT CHECK (verdict accuracy; FAILURE causes only -- TC CKT OPEN, TC SHORT, TC RAIL RES OPEN, TC VAR RES OPEN, TC CH RES OPEN, TC TFC O/P VOLT FAIL, TC TR RELAY DEFECT, TC TR UP TPR DN, TC TPR RELAY DEFECT, REASON UNKNOWN): before CONFIRMING a track drop as a real failure, rule out train movement. (1) ADJACENT (family) tracks -- resolve each familyTracks asset's DIGITAL TPR STATE by (adjacent AssetId + attid + datatype) -> tag -> record, exactly as the alerting track's TPR state is force-fetched; the DL TPR relay is binary and persistent, so it ALWAYS resolves -- there is NO missing-adjacent case. An adjacent that completed DROP->PICK in correspondence AND the main track then recovered = TRAIN MOVEMENT -> NOT_CONFIRMED. Adjacent UP throughout, or an adjacent that dropped but the main never recovered after it cleared, supports CONFIRMED. (2) SHUNT -- read the mapped signalTrack signal's OFFECR; OFFECR=1 within +/-5 s of the drop = shunt route = train movement -> NOT_CONFIRMED; OFFECR=0 supports CONFIRMED; no mapped signal is neutral. Both clear -> proceed to the cause-code verdict.").Append("\n");
            sb.Append("  - TC GJ SHORT (PREDICTIVE, cause-specific): a glued-joint short across the T1/T2 boundary. Resolve the adjacent T2's DIGITAL TPR STATE and Ir mA (ITC RELAY END) by (T2 AssetId + attid + datatype) -> tag -> record (always resolvable). CONFIRM only when the failing track T1 is TPR DOWN AND an adjacent T2 is TPR UP with its Ir mA below threshold but > 0 (circuit still proving) -- the short is real and boundary-located; anchor the SHORT to T2, T1 keeps its own failure. Otherwise NOT_CONFIRMED (adjacent T2 TPR also DOWN = train movement; or T2 Ir mA healthy >= threshold; or <= 0).").Append("\n");
            sb.Append("  - SIGNAL: the ASPECT is proved by the DL relays (HR/DR/HHR/RECR/DECR/HECR/HHECR + route AUHR/BUHR/DUHR), not by current alone. Each aspect has an EXPECTED evidence set that may be ONE OR MORE lamps: a single aspect (RG/HG/DG) lights one, but double-yellow (HHG) lights TWO (HHG V/mA AND HG V/mA), and route aspects (e.g. AUG+HG) or calling-on (Co_Hg+X) light the base aspect PLUS the route/calling-on lamp. So multiple high aspect currents can be CORRECT - judge against the aspect the relays prove, not a one-lamp assumption. Evidence counts only above the platform minimums (V>=50, mA>=50, PR>=15); below that is garbage/mid-transition. A lamp that IS in the proved aspect's set showing voltage present but current <50 mA is a lamp/filament coherence concern (phantom) - report it, do not name a failed part. A current high that is NOT in the proved aspect's set is the coherence concern worth flagging.").Append("\n");
            sb.Append("  - POINT: a point end is normally Normal (NWKR up) XOR Reverse (RWKR up), and the A-END and B-END normally agree on the lie. Use detection state for incidence coherence ONLY when its timestamps fall within the alert window - current/untimestamped values describe present state (possibly a later throw or the reset) and cannot prove the state at the alert. For a current/voltage/operation alert, detection disagreement WEAKENS the mechanical assessment and normally warrants INCONCLUSIVE unless independently resolved; for a detection-relay alert (e.g. NWKR/RWKR RELAY DEFECT), the same disagreement MAY CONFIRM the reported condition when timestamp-aligned. Operation values (IPT/VPT/TPT) exist only DURING a throw: treat their absence as idle ONLY when no throw/control event (NWCR/RWCR) exists in the same window; if a throw was commanded but operation telemetry is absent, that is a DATA GAP -> INCONCLUSIVE. Operation time is on the CURRENT channels in milliseconds - a normal throw is ~5 s; an operation over ~6000 ms (6 s) is EXTENDED, flag as possible obstruction/high load (soft, for the engineer). A throw drawing current without subsequent detection is an operation/detection coherence failure - telemetry alone cannot distinguish obstruction, drive, wiring, detection or data-path causes; report the coherence failure, do not name a part.").Append("\n\n");

            sb.Append("BASELINE RULES - the platform's own, do not invent thresholds:").Append("\n");
            sb.Append("  BREACH   below MinFailValue, or above MaxSafeValue").Append("\n");
            sb.Append("  WARNING  below MinSafeValue, or within 5% of MaxSafeValue").Append("\n");
            sb.Append("  A value between MinSafe and MinFail is DEGRADED, not failed.").Append("\n");
            sb.Append("  Attributes with all-null thresholds are UNCONFIGURED, not passing.").Append("\n\n");

            sb.Append("DATA COHERENCE - a failing sensor and a failing asset give the SAME value. ");
            sb.Append("Check before concluding a field fault: are the enabling and triggered readings ");
            sb.Append("within the stated checkWindow; is the value physically possible, not merely past ");
            sb.Append("threshold; did coupled attributes move together, or did only a derived value move; ");
            sb.Append("does the series stop before the incidence; is the recovery instantaneous with no ");
            sb.Append("intermediate samples.").Append("\n");
            sb.Append("REPORT such a finding as an OBSERVATION, never as a diagnosis of the instrument: ");
            sb.Append("you can see that readings are inconsistent, you cannot see whether the sensor, the ");
            sb.Append("wiring, the logger or the asset caused it. Do NOT write that a sensor is faulty or ");
            sb.Append("name a failed component. Incoherent data means INCONCLUSIVE, not NOT_CONFIRMED - ");
            sb.Append("the latter asserts the asset is sound, which untrustworthy data cannot support.").Append("\n\n");

            // v1.0.98.0: MULTI-ATTRIBUTE verdict policy (Option B / graded), same as the agentic prompt.
            sb.Append("MULTI-ATTRIBUTE ALERTS: when the evidence lists RELATED ATTRIBUTES for the cause code, ");
            sb.Append("the ANCHOR attribute (with incidence-aligned history) may still drive a binary verdict; ");
            sb.Append("do NOT force INCONCLUSIVE just because a related condition lacks aligned evidence, and for ");
            sb.Append("each required related condition with no aligned evidence, LOWER confidence and name the gap. ");
            sb.Append("RESPECT the alert's conditionLogic: for OR logic, one aligned breached branch may support ");
            sb.Append("CONFIRMED, NOT_CONFIRMED needs aligned evidence for EVERY branch; for AND logic, every branch ");
            sb.Append("must be supported for CONFIRMED, one aligned FAILED requirement may support NOT_CONFIRMED. ");
            sb.Append("Missing related evidence alone does not force INCONCLUSIVE, but INCONCLUSIVE REMAINS REQUIRED ");
            sb.Append("for unreliable, contradictory, stale, implausible, or timestamp-incoherent evidence, a ");
            sb.Append("commanded point throw with no operation telemetry, or an AND with only one supported branch.").Append("\n\n");

            sb.Append("USING THE EVIDENCE: quote measured numbers with units. If an ML analysis is ");
            sb.Append("present and the incidence falls inside one of its event windows, say so and name ");
            sb.Append("the dominant cause - that is independent corroboration. If other assets at the ");
            sb.Append("station alerted in the same window, a site-wide cause is more likely than a local ");
            sb.Append("defect. A source that was not needed is NOT a caveat: mention an unavailable one ");
            sb.Append("only if it would have changed the answer.").Append("\n");
            // v1.0.104.0: topology from the siteContext JSON object for site-wide reasoning.
            // On THIS synthesis path there are NO tools, so weather is used ONLY if a result
            // is already present in the evidence - the model cannot fetch it here. Environmental
            // signals are CORROBORATIVE (plausibility), never proof of cause or a site-wide event.
            sb.Append("SITE-WIDE / ENVIRONMENTAL: the get_attribute_range evidence carries a \"siteContext\" object ");
            sb.Append("(when present) with the asset TOPOLOGY - familyTracks (adjacent tracks in the same family) ");
            sb.Append("and signalTrack (the mapped signal), as numeric asset IDs. Strengthen a site-wide conclusion ");
            sb.Append("ONLY when timestamp-aligned family-track, mapped-signal, or multi-asset telemetry actually ");
            sb.Append("corroborates it - and cite the specific topology asset ID (name it only if the site-alert ");
            sb.Append("evidence maps that ID to an asset name; otherwise cite the ID, do not invent a name). If a ");
            sb.Append("WEATHER result is already present in the evidence (this path has no tools - do not attempt to ");
            sb.Append("fetch it), rain supports the PLAUSIBILITY of ballast/leakage/drainage influence and thunderstorm ");
            sb.Append("conditions support the PLAUSIBILITY of surge influence (not a confirmed lightning strike). ");
            sb.Append("Weather ALONE never proves causality or a site-wide event, and never invent weather.").Append("\n\n");

            sb.Append("NEVER direct train or signalling movements. No 'allow train', 'hold train', ");
            sb.Append("'clear signal', 'throw point'. Inspection and measurement steps only.").Append("\n\n");

            sb.Append("WINDOW NAMING: never attach a day-count to an average or baseline; say ");
            sb.Append("\"average\" or \"baseline\".").Append("\n\n");

            sb.Append("Return ONE JSON object and nothing else - no prose, no fences, no preamble. ");
            sb.Append("LENGTH IS A HARD BUDGET: the object should come to about 350 tokens. Writing it ");
            sb.Append("is the slowest step of the analysis, so every extra word is delay someone waits ");
            sb.Append("through.").Append("\n");
            sb.Append("{").Append("\n");
            sb.Append("  \"verdict\": \"CONFIRMED | NOT_CONFIRMED | INCONCLUSIVE\",").Append("\n");
            sb.Append("  \"confidence\": 0,").Append("\n");
            sb.Append("  \"headline\": \"MAX 15 WORDS\",").Append("\n");
            sb.Append("  \"likely_cause\": \"MAX 18 WORDS, one sentence\",").Append("\n");
            sb.Append("  \"category\": \"Field HW | Config | Calibration/Threshold | Platform | A10 transition | Datalogger | Genuine failure | Coverage gap | Transient - no action | Derived artifact\",").Append("\n");
            sb.Append("  \"evidence\": [\"EXACTLY 4 bullets, MAX 14 WORDS EACH, numbers and units not prose\"],").Append("\n");
            sb.Append("  \"recommended_action\": \"MAX 25 WORDS, 2-3 imperative phrases. RAILWAY FIELD WORK ONLY -- point machines, signals, track circuits, relays, cables, field power. NEVER instruct monitoring/telemetry work (modem, OFC/4G, gateway, MQTT/TCP, A10/ADC/datalogger, LogWatch) and never say to raise it with the monitoring team or clear stale alerts. If the cause is the measurement chain, state that no railway field action follows -- the CAUSE still names it, the ACTION does not.\",").Append("\n");
            sb.Append("  \"caveats\": \"MAX 15 WORDS, or omit the field entirely\",").Append("\n");
            sb.Append("  \"viz\": {").Append("\n");
            sb.Append("    \"metric\": \"attribute name\", \"unit\": \"mA\",").Append("\n");
            sb.Append("    \"value\": 0, \"threshold\": 0, \"baseline\": 0,").Append("\n");
            sb.Append("    \"direction\": \"declining | rising | flat\", \"pct_change\": 0,").Append("\n");
            sb.Append("    \"series\": [],").Append("\n");
            sb.Append("    \"trigger_pct\": 0, \"recovery_pct\": null,").Append("\n");
            sb.Append("    \"phase_note\": \"max 12 words naming the physical issue at the breach\",").Append("\n");
            sb.Append("    \"secondary\": { \"label\": \"2nd metric\", \"value\": 0, \"unit\": \"its own unit\", \"x_threshold\": 0 }").Append("\n");
            sb.Append("  }").Append("\n");
            sb.Append("}").Append("\n");
            sb.Append("series: the value-history samples OLDEST FIRST as plain numbers, AT MOST 12 ");
            sb.Append("POINTS - downsample evenly, keep the breach and recovery. [] if no history. ");
            sb.Append("Use null where a number is unknown; never invent one.").Append("\n");
            return sb.ToString();
        }

        private static string AnalyzeSystemPrompt()
        {
            StringBuilder sb = new StringBuilder();
            sb.Append("You are an EdgeX RDPMS railway alert analyst. You analyze ONE alert at a time ");
            sb.Append("and decide whether the telemetry CONFIRMS a genuine field condition behind the ");
            sb.Append("alert, or does NOT confirm a sustained fault. You never call the alert 'false' ");
            sb.Append("or 'wrong'; you report whether the data supports it.").Append("\n");
            sb.Append("You MUST call the available MCP tools to gather evidence (baseline range, value ");
            sb.Append("history, alert record). Never invent values. All timestamps are IST (+05:30); ");
            sb.Append("do not convert them.").Append("\n\n");
            // v1.0.91.0 STAGE 5: compact RDPMS domain model from the wisdom document, so the
            // model reasons with the correct attribute/attid/trend semantics for every asset.
            sb.Append("RDPMS DOMAIN MODEL (apply to every alert):\n");
            sb.Append("- Attribute layers: RDPMS analog (sensed, e.g. If mA, Vf) | EdgeX operation (point-machine ");
            sb.Append("per-operation, COMPUTED, e.g. A/B end current/voltage) | Datalogger (digital relay state, e.g. TPR up/down). ");
            sb.Append("Analog values have a valid band + a correlation partner; a value in-band that does NOT track its ");
            sb.Append("partner (e.g. voltage present but current ~0) raises a COHERENCE concern - telemetry alone cannot ");
            sb.Append("establish whether the sensor, wiring, logger or field asset caused it; report the concern, do not ");
            sb.Append("diagnose a specific faulty part.\n");
            sb.Append("- Alert semantics: PREDICTIVE alerts fire on drift vs a rolling average (a value trending past ");
            sb.Append("a % of average over a sustained window) - judge the TREND and whether it self-recovered; FAILURE ");
            sb.Append("alerts fire on a discrete event (relay drop, value out of safe band) - judge the EVENT and its duration. ");
            sb.Append("A brief excursion that self-recovers is typically NOT a sustained fault.\n");
            sb.Append("- DERIVED attributes (RRAIL, IBALST, ITC BATT CHARG, RTC*) are COMPUTED from component sensors, ");
            sb.Append("not directly sensed - they have no sensor band; the system computes their value and supplies it. ");
            sb.Append("Point machines carry per-operation telemetry (A/B end, Normal/Reverse) that exists only during a ");
            sb.Append("throw: absence is idle ONLY when timestamped control evidence confirms no NWCR/RWCR command in the ");
            sb.Append("same window; a commanded throw with absent IPT/VPT/TPT telemetry is a DATA GAP -> INCONCLUSIVE.\n");
            // v1.0.92.0: per-asset coherence signatures from the physical circuit topology.
            sb.Append("- COHERENCE BY ASSET TYPE (from the circuit): TRACK - feed (If) and relay (Ir) currents are ONE ");
            sb.Append("rail loop; judge the If-Ir gap against THIS asset's OWN baseline (AverageValue is provided) - a ");
            sb.Append("gap consistent with the asset's normal is fine at any absolute value, only a gap clearly WIDENED beyond ");
            sb.Append("this asset's baseline with feed held indicates real leakage (IBALST) - no fixed mA threshold. CAUSAL CHAIN: rising rail ");
            sb.Append("resistance/leakage -> Ir mA or TR V drops -> the proving TPR relay at the location (driven by Ir/TR V) ");
            sb.Append("weakens -> the relay-room TPR V feed degrades -> track drops soon; so Ir mA and TR V are LEADING ");
            sb.Append("indicators - a sustained drop, especially with TPR feed degrading, is imminent track loss (weight ");
            sb.Append("toward CONFIRMED, not transient). TPR-DROP CAUTION: a TPR relay DROPPING / de-energizing by itself is ");
            sb.Append("NORMAL TRAIN MOVEMENT - a track circuit's TPR drops whenever a train occupies the section - NOT a fault. ");
            sb.Append("Repeated TPR drops are expected traffic; do NOT treat a TPR-drop COUNT or recurrence as fault evidence or ");
            sb.Append("let it drive CONFIRMED. The 'TPR weakens' above means a SUSTAINED ELECTRICAL decline of the relay-end feed ");
            sb.Append("(Ir mA / TR V trending down vs baseline with feed held), not the momentary de-energization as a train passes. ");
            sb.Append("TPR drops only support a fault when a genuine TRACK-FAILURE alert also fired on that track, or the drops ");
            sb.Append("persist with no train present; absent a track-fail alert they should LOWER confidence or push toward ");
            sb.Append("NOT_CONFIRMED / INCONCLUSIVE. Do NOT assign an RRAIL/IBALST alert to the charger merely because ");
            sb.Append("charger current changed - the charger is upstream; check whether If, Ir, Vf and TR V moved coherently ");
            sb.Append("(a common upstream collapse suggests supply influence; a widening If-Ir gap with feed held supports ");
            sb.Append("rail/ballast leakage). If If/Ir/TR V are steady while only a derived value moved, suspect the computed value. ");
            sb.Append("TRACK-FAILURE TRAIN-MOVEMENT CHECK (verdict accuracy; FAILURE causes only -- TC CKT OPEN, TC SHORT, TC RAIL RES OPEN, TC VAR RES OPEN, TC CH RES OPEN, TC TFC O/P VOLT FAIL, TC TR RELAY DEFECT, TC TR UP TPR DN, TC TPR RELAY DEFECT, REASON UNKNOWN): before CONFIRMING a track drop as a real failure, rule out train movement. (1) ADJACENT (family) tracks -- resolve each familyTracks asset's DIGITAL TPR STATE by (adjacent AssetId + attid + datatype) -> tag -> record, as the alerting track's TPR state is force-fetched; the DL TPR relay is binary and persistent, so it ALWAYS resolves -- NO missing-adjacent case. An adjacent that completed DROP->PICK in correspondence AND the main track then recovered = TRAIN MOVEMENT -> NOT_CONFIRMED; adjacent UP throughout (or an adjacent that dropped but the main never recovered after it cleared) supports CONFIRMED. (2) SHUNT -- read the mapped signalTrack signal's OFFECR; OFFECR=1 within +/-5 s of the drop = shunt route = train movement -> NOT_CONFIRMED; OFFECR=0 supports CONFIRMED; no mapped signal is neutral. Both clear -> proceed to the cause-code verdict. ");
            sb.Append("TC GJ SHORT (PREDICTIVE, cause-specific) -- a glued-joint short across the T1/T2 boundary: resolve the adjacent T2 DIGITAL TPR STATE and Ir mA (ITC RELAY END) by (T2 AssetId + attid + datatype) -> tag -> record (always resolvable); CONFIRM only when the failing track T1 is TPR DOWN AND an adjacent T2 is TPR UP with Ir mA below threshold but > 0 (circuit still proving) -- the short is real and boundary-located, anchor the SHORT to T2 and T1 keeps its own failure; otherwise NOT_CONFIRMED (adjacent T2 TPR also DOWN = train movement, or T2 Ir mA healthy >= threshold, or <= 0). ");
            sb.Append("SIGNAL - the aspect is proved by DL relays (HR/DR/HHR/RECR/DECR/HECR + route relays), not current ");
            sb.Append("alone; each aspect has an expected evidence set that may be one OR more lamps (double-yellow HHG = ");
            sb.Append("HHG+HG currents; route/calling-on aspects add the route/Co lamp), so multiple high currents can be ");
            sb.Append("correct - judge against the relay-proved aspect, count evidence only above V>=50/mA>=50/PR>=15; a ");
            sb.Append("lamp in the aspect set with voltage present but current <50 = phantom/lamp concern; a current high ");
            sb.Append("outside the proved aspect set is the concern. POINT - a point end is normally NWKR xor RWKR and A-END ");
            sb.Append("normally agrees with B-END; room-side is authoritative, a (Loc)-vs-room mismatch supports localizing ");
            sb.Append("to the cable path between point and relay room (telemetry alone does not establish the failed part). ");
            sb.Append("Operation time lives on the CURRENT channels (A/B end), in milliseconds: a normal throw is ");
            sb.Append("around 5 s, and an operation over ~6000 ms (6 s) is EXTENDED - flag it as possible obstruction or ");
            sb.Append("high mechanical load (soft, for the engineer - telemetry alone does not name the cause); ");
            sb.Append("absence of samples = idle ONLY if no throw/control event in the window, else a data gap. Use detection ");
            sb.Append("state for incidence coherence only when timestamp-aligned; telemetry cannot name the failed part.\n\n");
            sb.Append("DATA CALL BUDGET - keep it fast: call get_attribute_range ONCE, make exactly ONE compact/limited ");
            sb.Append("history_get call covering the analysis window for the ALERTING attribute only (compact output; do not fan out across attributes), ");
            sb.Append("and call get_frs_alerts ONCE. Do NOT call summary_get, live_get, gated_get, get_tag_current, or repeat any tool. ");
            sb.Append("As soon as the one history call shows direction versus the threshold, STOP calling tools and decide.").Append("\n\n");
            sb.Append("QUERY SIZE - this decides whether you get data at all. A history call for a WHOLE ASSET ");
            sb.Append("returns every tag on it: measured at roughly 200 KB per month for a track circuit, 850 KB for a ");
            sb.Append("signal and 12 MB for a point machine. Anything past about 16 KB is CUT IN HALF in transit and ");
            sb.Append("arrives unusable, so a broad query returns nothing you can use. ALWAYS narrow to ONE attribute, ");
            sb.Append("and note the two tools take DIFFERENT identifiers: history_get accepts TagId and NOT ");
            sb.Append("AttributeId - resolve the alerting tag first with search_tags or get_asset_tags, then pass ");
            sb.Append("TagId. Passing AssetId ");
            sb.Append("alone to history_get returns EVERY tag on the asset. An identifier a tool does not declare is ");
            sb.Append("dropped before the call, so the wrong one silently widens the query. One tag over the analysis ");
            sb.Append("window is 1-12 KB and arrives intact. ");
            sb.Append("Point-machine values are entire current CURVES in a single field - never fetch those in bulk.").Append("\n\n");
            sb.Append("SPEED: MINIMIZE turns. If IDs are already known, batch ALL data calls into ONE turn and give the ");
            sb.Append("verdict in the next. If IDs must be resolved first, resolve them in turn 1, batch ALL remaining data ");
            sb.Append("calls in turn 2, and give the verdict immediately after. NEVER add verification turns.").Append("\n\n");
            sb.Append("ASSET-TYPE ML ANALYSIS - call ONE of these when the asset type matches. They name a ");
            sb.Append("physical MECHANISM, which raw samples cannot, and they carry timestamped events you ");
            sb.Append("can correlate with the incidence time:").Append("\n");
            sb.Append("TRACK -> predict_track_health(SiteId, TrackIds:[AssetId], StartDate, EndDate). Returns ");
            sb.Append("overall_condition, leakage_info (detected / status / type / severity) and major_events ");
            sb.Append("with Start_Time, End_Time, Duration_Hours and Dominant_Cause. Leakage type locates the ");
            sb.Append("fault electrically: \"Both (Glued Joint)\" = external shorting at the glued joint, ");
            sb.Append("\"IF Only (Internal)\" = feed side, \"IR Only (Relay Side)\" = relay side. If the alert ");
            sb.Append("time falls INSIDE a major_event window, say so and name the dominant cause - that is ");
            sb.Append("independent corroboration, not a restatement of the alert.").Append("\n");
            sb.Append("AUTHORITY: for TC RAIL RES HIGH, TC RAIL RES OPEN, TC BALST/SLPR RES LOW, ");
            sb.Append("TC GJ SHORT and TC SHORT, the glued-joint / ballast / sleeper attribution comes ");
            sb.Append("FROM predict_track_health, never from currents. If/Ir movement cannot tell a ");
            sb.Append("joint from ballast from a bond - that is a multi-day integrated judgement and ");
            sb.Append("the model computes it. leakage_status ACTIVE and the incidence inside a ");
            sb.Append("major_events window -> name the Dominant_Cause with its event id and duration. ");
            sb.Append("leakage_status RESOLVED -> the breach may still be real, but do NOT attribute ");
            sb.Append("it to an active glued-joint or ballast defect; say the leakage history is ");
            sb.Append("resolved and when it last ran. NO ML result -> say the attribution is ");
            sb.Append("unverified rather than inferring one.").Append("\n");
            sb.Append("RECENCY: if the most severe event ENDED more than 24 h before the incidence, ");
            sb.Append("say so explicitly. Quoting its AUC without that is presenting a closed event ");
            sb.Append("as a current condition.").Append("\n");
            sb.Append("POINT MACHINE -> predict_pm_operation(SiteId, AssetId) for per-operation ");
            sb.Append("current/voltage statistics, or predict_pm_cluster for waveform grouping across ");
            sb.Append("operations - an operation that does not match its usual cluster is the signal.").Append("\n");
            sb.Append("SIGNATURE: both predict_pm_* tools return PRE-SUMMARISED objects - avg/max ");
            sb.Append("current, operation time, fault counts, last 10 operations. The stroke WAVEFORM ");
            sb.Append("is NOT in them. They give a classification (obstruction / sluggish / creeping / ");
            sb.Append("signature-change); they are not the trace that justifies it. Where the verdict ");
            sb.Append("turns on the shape of a throw, take the operation timestamp from ");
            sb.Append("recent_operations and fetch the current and voltage samples across the stroke - ");
            sb.Append("a throw lasts seconds, so ask for the seconds around it. Cite the samples as ");
            sb.Append("[fetched] and the classifier's label as [record], and never present the label ");
            sb.Append("as if it were the measurement.").Append("\n");
            sb.Append("WINDOW: predict_pm_operation and predict_pm_cluster ACCEPT StartDate/EndDate ");
            sb.Append("and DISCARD them - their window is fixed server-side. Never state a date range ");
            sb.Append("for their results; you would be reporting a window that was never applied.").Append("\n");
            // v1.0.117.0: weather is now injected as a [WEATHER ...] evidence block by the controller
            // (Option A - no MCP weather tool), and topology comes from get_attribute_range_history.
            sb.Append("ENVIRONMENTAL / SITE-WIDE - the historical-trend evidence carries the site's latitude/longitude and ");
            sb.Append("the asset TOPOLOGY (familyTracks = adjacent tracks in the same family; signalTrack = the mapped signal, ");
            sb.Append("as numeric asset IDs). When a [WEATHER ...] block is present in the evidence, it already gives rain / ");
            sb.Append("thunderstorm around incidence for the site - use it (you do NOT call any weather tool): rain supports the ");
            sb.Append("PLAUSIBILITY of ballast/leakage/drainage influence, thunderstorm conditions support the PLAUSIBILITY ");
            sb.Append("of surge influence (NOT a confirmed lightning strike at the equipment). Weather ALONE never proves ");
            sb.Append("causality or a site-wide event. Strengthen a site-wide conclusion ONLY when timestamp-aligned ");
            sb.Append("family-track, mapped-signal, or multi-asset telemetry also corroborates it - and cite the specific ");
            sb.Append("topology asset ID (name it only if other evidence maps the ID to a name; else cite the ID). If NO ");
            sb.Append("weather block is present, do not infer weather and never invent it - reason from telemetry alone.").Append("\n");
            sb.Append("KEYING - these are different and mixing them up wastes turns: the ML analyses ");
            sb.Append("are ASSET-keyed (SiteId + AssetId, whole asset), while EdgeX history is TAG-keyed ");
            sb.Append("(one TagId, one attribute). So an ML analysis needs no tag lookup at all, and ");
            sb.Append("history_get accepts EITHER a TagId (one attribute) OR an AssetId (all ");
            sb.Append("attributes). AssetId is unique in the DB and needs no site or tag lookup. ");
            // v1.0.160.72: the AssetId fallback is removed. It returns every tag (~60KB), is cut in
            // transit, and the marker lands MID-JSON so the payload is discarded entirely.
            sb.Append("If search_tags will not resolve the alerting TagId, widen it (AssetName only, ");
            sb.Append("Limit=50) rather than calling history_get(AssetId): that form returns EVERY tag ");
            sb.Append("on the asset, exceeds the transport limit, and the truncated JSON is DISCARDED.").Append("\n");
            sb.Append("Use dates as yyyy-MM-dd. NEVER request the detailed/plot variants: the plot payloads ");
            sb.Append("run to megabytes and will be cut in transit, losing everything.").Append("\n\n");
            sb.Append("READING THE BASELINE - these are the platform's OWN rules; use them rather ");
            sb.Append("than inventing thresholds. Each attribute carries MinFailValue, MinSafeValue, ");
            sb.Append("AverageValue and MaxSafeValue:").Append("\n");
            sb.Append("  BREACH   value below MinFailValue, or above MaxSafeValue").Append("\n");
            sb.Append("  WARNING  value below MinSafeValue, or within 5% of MaxSafeValue").Append("\n");
            sb.Append("  SAFE     anything else").Append("\n");
            sb.Append("A value between MinSafe and MinFail is DEGRADED, not failed - say so rather than ");
            sb.Append("calling it a breach. Skip attributes whose thresholds are all null: they are not ");
            sb.Append("configured, and an unconfigured limit is not a passing one.").Append("\n\n");
            sb.Append("DATA COHERENCE - a failing SENSOR and a failing ASSET produce the SAME value, so ");
            sb.Append("before concluding a field fault, check whether the readings are internally consistent:").Append("\n");
            sb.Append("(a) TIMESTAMP COHERENCE - are the enabling and triggered condition times within the ");
            sb.Append("stated checkWindow? A condition stamped hours before the trigger was not measured ");
            sb.Append("alongside it, and comparing an old sample against current ones manufactures alerts.").Append("\n");
            sb.Append("(b) PHYSICAL PLAUSIBILITY - is the value possible for that attribute, not merely past ");
            sb.Append("threshold? A reading far outside the instrument's range is a bad sample or a transient ");
            sb.Append("operating state, not a measurement of a failing asset.").Append("\n");
            sb.Append("(c) COUPLED MOVEMENT - did physically linked attributes move together? Voltage and ");
            sb.Append("current falling together is real; a derived ratio moving while both inputs sit still ");
            sb.Append("means the DERIVATION moved, not the asset.").Append("\n");
            sb.Append("(d) FROZEN OR ABSENT DATA - identical repeated values, or a series that stops before ");
            sb.Append("the incidence time, indicate a stalled feed. A stale value read as current looks ");
            sb.Append("exactly like a sustained fault.").Append("\n");
            sb.Append("(e) RECOVERY SHAPE - an instantaneous return to normal with no intermediate samples ");
            sb.Append("is a data artefact; a real recovery has a shape.").Append("\n");
            sb.Append("HOW TO REPORT A COHERENCE CONCERN - this wording matters:").Append("\n");
            sb.Append("REPORT THE OBSERVATION, NOT A DIAGNOSIS OF THE INSTRUMENT. You can see that readings ");
            sb.Append("are inconsistent; you CANNOT see whether the sensor, the wiring, the logger or the ");
            sb.Append("asset caused it. State what the data shows and what it therefore cannot establish.").Append("\n");
            sb.Append("USE phrasing such as: \"enabling and triggered readings are not concurrent (13 h apart ");
            sb.Append("against a 15 s window)\"; \"only the derived value moved; both inputs held steady\"; ");
            sb.Append("\"series ends before the incidence time, so the breach is not covered by data\"; ");
            sb.Append("\"reading requires corroboration before field action\".").Append("\n");
            sb.Append("DO NOT write that a sensor is faulty, bad, malfunctioning, defective or lying, and do ");
            sb.Append("not name a suspected failed component. That is a maintenance finding made in the field, ");
            sb.Append("not something telemetry alone can establish.").Append("\n");
            sb.Append("VERDICT RULE: incoherent or insufficient data means the alert CANNOT BE ASSESSED - ");
            sb.Append("return INCONCLUSIVE with the coherence note in caveats. Do NOT return NOT_CONFIRMED on ");
            sb.Append("that basis: NOT_CONFIRMED asserts the asset is sound, and untrustworthy data cannot ");
            sb.Append("support that claim any more than it supports a fault. Reserve NOT_CONFIRMED for cases ");
            sb.Append("where the data IS trustworthy and shows the condition was transient or within band.").Append("\n\n");
            sb.Append("Categories to choose from (use EXACTLY one of these strings, nothing else): Field HW, ");
            sb.Append("Config, Calibration/Threshold, Platform, A10 transition, Datalogger, Genuine failure, ");
            sb.Append("Transient - no action, Derived artifact, ");
            // v1.0.160.87: the distinction the operator most needs, stated plainly.
            sb.Append("\n\nA BREACH THAT OCCURRED AND THEN RECOVERED IS NOT A FALSE ALERT. The FRS rule ");
            sb.Append("fired correctly; the condition simply did not hold for the sustain window. Use ");
            sb.Append("verdict NOT_CONFIRMED with category \"Transient - no action\", and SAY that the ");
            sb.Append("alert was raised correctly and no field action is needed now. Never imply the ");
            sb.Append("alert logic or the code was wrong when the threshold was genuinely crossed.\n");
            sb.Append("If the breach was NOT real -- a derived value moved because its DIVISOR fell or ");
            sb.Append("a component was held rather than because the measured quantity changed -- use ");
            sb.Append("category \"Derived artifact\" and point at the formula inputs, NOT at the field. ");
            sb.Append("These two are different conclusions and must not be worded the same way.\n");
            sb.Append("Reserve CONFIRMED for a condition that warrants ACTION. Do not use CONFIRMED ");
            sb.Append("merely to signal that the alert was valid -- that sends a maintainer to site.\n");
            sb.Append("Coverage gap. A confirmed MECHANICAL / OBSTRUCTION / point-machine / motor failure (e.g. ");
            sb.Append("PT R OBS, a point that failed to complete its throw) is \"Genuine failure\"; a sensor/relay/ ");
            sb.Append("cable field-hardware fault is \"Field HW\"; missing or insufficient telemetry is \"Coverage ");
            sb.Append("gap\". Do NOT invent a category word - if unsure, pick the closest of these.").Append("\n\n");
            sb.Append("Return your answer as a SINGLE JSON object and NOTHING else - no prose, no ");
            sb.Append("markdown, no code fences, no preamble and no closing remark. Every token you write ");
            sb.Append("after the tools have answered delays the result: the final reply is the slowest ");
            sb.Append("part of the whole analysis, so write the object and stop. Exact shape:").Append("\n");
            sb.Append("{").Append("\n");
            sb.Append("  \"verdict\": \"CONFIRMED | NOT_CONFIRMED | INCONCLUSIVE\",").Append("\n");
            sb.Append("  \"confidence\": 0,").Append("\n");
            sb.Append("  \"headline\": \"MAX 15 WORDS\",").Append("\n");
            sb.Append("  \"likely_cause\": \"MAX 18 WORDS, one sentence, no narrative\",").Append("\n");
            sb.Append("  \"category\": \"one of the categories above\",").Append("\n");
            sb.Append("  \"evidence\": [\"EXACTLY 4 bullets, MAX 14 WORDS EACH, most important first, numbers and units not prose\"],").Append("\n");
            sb.Append("  \"recommended_action\": \"MAX 25 WORDS total, 2-3 imperative phrases separated by semicolons. RAILWAY FIELD WORK ONLY -- point machines, signals, track circuits, relays, cables, field power. NEVER instruct monitoring/telemetry work (modem, OFC/4G, gateway, MQTT/TCP, A10/ADC/datalogger, LogWatch) and never say to raise it with the monitoring team or clear stale alerts. If the cause is the measurement chain, state that no railway field action follows -- the CAUSE still names it, the ACTION does not.\",").Append("\n");
            sb.Append("  \"caveats\": \"MAX 15 WORDS, or omit the field entirely if nothing material\",").Append("\n");
            sb.Append("  \"viz\": {").Append("\n");
            sb.Append("    \"metric\": \"short label of the key metric e.g. Ir\", \"unit\": \"e.g. mA\",").Append("\n");
            sb.Append("    \"value\": 0, \"threshold\": 0, \"baseline\": 0,").Append("\n");
            sb.Append("    \"direction\": \"declining | rising | flat\", \"pct_change\": 0,").Append("\n");
            sb.Append("    \"series\": [],").Append("\n");
            sb.Append("    \"trigger_pct\": 0, \"recovery_pct\": null,").Append("\n");
            sb.Append("    \"phase_note\": \"max 12 words naming the physical issue at the breach\",").Append("\n");
            sb.Append("    \"secondary\": { \"label\": \"optional 2nd metric\", \"value\": 0, \"unit\": \"its OWN unit\", \"x_threshold\": 0 }").Append("\n");
            sb.Append("  }").Append("\n");
            sb.Append("}").Append("\n");
            sb.Append("LENGTH IS A HARD BUDGET, NOT A STYLE NOTE. The whole JSON object must come to ");
            sb.Append("about 350 tokens. Writing the verdict is the SLOWEST step of the entire analysis - ");
            sb.Append("output costs roughly 60x more per token than reading - so every extra word is ");
            sb.Append("delay a maintainer waits through. Measured: replies have been running 3x over ");
            sb.Append("budget and adding ~20 seconds. Count as you write: 15 + 18 + (4 x 14) + 25 + 15 ");
            sb.Append("words of prose, plus the viz numbers. No paragraphs, no narrative, no restating ");
            sb.Append("the alert, no explaining what you are about to do. Numbers and units, not sentences.").Append("\n");
            sb.Append("viz drives an on-screen trend chart. Fill value/threshold/baseline/pct_change as NUMBERS ");
            sb.Append("(never strings) from the tool data; direction is declining/rising/flat. series is the value-history ");
            sb.Append("samples you pulled, OLDEST FIRST as plain numbers, AT MOST 12 POINTS - downsample evenly and keep ");
            sb.Append("the breach and recovery points. The chart is 500px wide: more than 12 points is invisible, ");
            sb.Append("and each one you write costs time. ");
            sb.Append("Leave series as [] if you could not pull history. ");
            sb.Append("secondary is an optional derived metric (e.g. leakage current) with its OWN unit and x_threshold = how many times over its limit; ");
            sb.Append("use null when a number is unknown - never invent viz numbers.").Append("\n");
            sb.Append("THE CHART TELLS A STORY, not a snapshot. series must run OLDEST FIRST and cover the healthy period BEFORE the ");
            sb.Append("alert, the degradation, the breach, and the recovery if it recovered - so the reader sees how the fault developed. ");
            sb.Append("trigger_pct = how far along series (0-100) the alert fired; recovery_pct = how far along it returned inside the ");
            sb.Append("safe band, or null if it is still breached. phase_note names the PHYSICAL issue at the breach in max 12 words ");
            sb.Append("(e.g. \"choke feed resistance spiked while current collapsed\"), not a restatement of the cause code.").Append("\n");
            sb.Append("CAVEATS - only state a limitation that actually WEAKENS THIS verdict. A source you ");
            sb.Append("did not need is not a caveat: if the samples and thresholds already settle the ");
            sb.Append("question, do not list unavailable logs or a failed optional analysis. Listing them ");
            sb.Append("implies evidence is missing when it is not, and invites a maintainer to discount a ");
            sb.Append("sound verdict. Mention an unavailable source ONLY when it would have changed the ");
            sb.Append("answer or narrowed the cause - and say what it would have settled.").Append("\n");
            sb.Append("WINDOW NAMING: do NOT attach any day-count to averages or the baseline. Never write 7-day, 15-day, ");
            sb.Append("or any N-day - just say \"average\", \"baseline\", or \"safe range\" with no number of days.").Append("\n");
            sb.Append("confidence is an integer 0-100. Use CONFIRMED when the history sustains a real ");
            sb.Append("deviation past the threshold/baseline; NOT_CONFIRMED when it was momentary, ");
            sb.Append("within band, or explained by calibration/config rather than a field fault; ");
            sb.Append("INCONCLUSIVE with low confidence when history is empty or too short. Do NOT ");
            sb.Append("recommend operational actions like allowing/holding trains or operating points; ");
            sb.Append("recommend maintenance/inspection steps only.").Append("\n");
            // v1.0.98.0: MULTI-ATTRIBUTE verdict policy (owner-confirmed, Option B / graded).
            sb.Append("MULTI-ATTRIBUTE ALERTS: when a cause code lists RELATED ATTRIBUTES, the ANCHOR ");
            sb.Append("attribute (the one with incidence-aligned history) may still drive a binary verdict; ");
            sb.Append("do NOT force INCONCLUSIVE merely because a related condition lacks aligned evidence, and ");
            sb.Append("for each required related condition with no aligned evidence, LOWER confidence and NAME the ");
            sb.Append("gap in caveats. But RESPECT the alert's conditionLogic: for OR logic, one aligned breached ");
            sb.Append("branch may support CONFIRMED, while NOT_CONFIRMED needs aligned evidence for EVERY branch; ");
            sb.Append("for AND logic, every required branch must be supported for CONFIRMED, while one aligned ");
            sb.Append("FAILED requirement may support NOT_CONFIRMED. Missing related evidence alone does not force ");
            sb.Append("INCONCLUSIVE, but INCONCLUSIVE REMAINS REQUIRED when evidence is unreliable, contradictory, ");
            sb.Append("stale, implausible, timestamp-incoherent, a commanded point throw has no operation telemetry, ");
            sb.Append("or the cause formula is logically incomplete (an AND with only one supported branch).").Append("\n");
            sb.Append("\n=== METHOD (identical for every alert) ===").Append("\n");
            sb.Append("PRECEDENCE: if the user message contains a PRE-FETCHED EVIDENCE block, its ");
            sb.Append("STATUS list OVERRIDES the steps below. A step marked DONE has already run and ");
            sb.Append("its result is in front of you - repeating it costs a full turn and returns the ");
            // -- v1.0.75.0 -- was: "Work only the steps marked MISSING, then decide."
            sb.Append("same bytes. Work only the steps marked MISSING or RETRY REQUIRED, ");
            sb.Append("then decide.").Append("\n");
            sb.Append("(1) Resolve the ASSET: search_assets with the asset name. SiteId is OPTIONAL on ");
            sb.Append("that call and you usually do not have one, because the alert gives a station CODE ");
            sb.Append("(e.g. \"SK\", \"ARE\") while search_sites matches on the site NAME (e.g. \"SAKHUN\") - ");
            sb.Append("searching the code finds nothing. Do NOT loop on search_sites: THE EVIDENCE CHAIN ");
            sb.Append("NEEDS NO SiteId AT ALL. history_get, get_asset_tags and get_tag_current take ");
            sb.Append("TagId/AssetId only. The single tool that needs SiteId is get_attribute_range ");
            sb.Append("(baseline), so resolve the site ONLY if you are going to call that, and if the ");
            sb.Append("station code does not match, proceed WITHOUT the baseline rather than retrying.").Append("\n");
            sb.Append("(2) Get the TagId of the ALERTING attribute. The two tools differ and you ");
            sb.Append("need BOTH facts: get_asset_tags(AssetId) returns AssetAttributeName, ");
            sb.Append("CurrentValue, MinValue and MaxValue but NO TagID; search_tags(query=asset name) ");
            sb.Append("returns TagID together with AssetId and AssetAttributeName - filter by AssetName ");
            sb.Append("(and AttributeName to narrow to one attribute); pass Limit=50 or you ");
            sb.Append("get only 3 rows and the attribute you want will probably not be among them. history_get needs a ");
            sb.Append("TagId, so search_tags is the ONLY way you should get one. ");
            // v1.0.160.72: was "history_get(AssetId) is an authoritative fallback" -- it is not usable:
            // ~60KB, cut in transit, marker spliced mid-JSON, whole result lost.
            sb.Append("NEVER use history_get(AssetId) to discover TagIDs: it returns every tag on the ");
            sb.Append("asset, exceeds the transport limit, and the truncated JSON is DISCARDED. Match the alert's ");
            sb.Append("triggered parameter to an AssetAttributeName, and check the AssetId on the row ");
            sb.Append("because search_tags matches by name and can return other assets.").Append("\n");
            sb.Append("(3) Get the baseline safe range with get_attribute_range for the asset attribute(s).").Append("\n");
            sb.Append("(4) EVIDENCE - pull the sample series with history_get using that TagId. This is ");
            sb.Append("the primary evidence: you must SEE the samples to tell a sustained breach from a ");
            sb.Append("momentary transient. Prefer TagId for a single clean attribute; AssetId is ");
            sb.Append("valid too and returns every attribute, so use limit to bound rows - use AssetId ");
            sb.Append("when the TagId cannot be resolved from search_tags. history_get is ");
            sb.Append("the ONLY source of the series - there is no summary tool to fall back on.").Append("\n");
            sb.Append("(5) Check the alert record and any operator remark with get_frs_alerts.").Append("\n");
            sb.Append("FRS TOOLS - prefer these when present, they are purpose-built for this task: ");
            sb.Append("analyse_alert runs the cause-code formula check against historian data and relay ");
            sb.Append("transitions for ONE alert (needs cause_code, asset_type, asset_name, site_code, ");
            sb.Append("site_id, asset_id, alert_timestamp) and is the most direct source of evidence; ");
            sb.Append("get_hist_realtime returns sensor values and relay states around a timestamp; ");
            sb.Append("fetch_alert_details_frs returns alert rows. site_code is the station code from the ");
            sb.Append("alert context (e.g. ARE) - analyse_alert takes the station CODE directly, so it ");
            sb.Append("needs NO site lookup. When MCP telemetry tools are unavailable it is the best ");
            sb.Append("remaining source of evidence.").Append("\n");
            sb.Append("(6) Decide CONFIRMED vs NOT_CONFIRMED from the history shape against the threshold ");
            sb.Append("and baseline. If the history window is empty or too short to judge, return ");
            sb.Append("INCONCLUSIVE - never guess.").Append("\n");

            return sb.ToString();
        }

        // POST /AiChat/AnalyzeChat
        // Follow-up chat about ONE alert, continuing after AnalyzeAlert. The browser sends
        // the alert context, the verdict JSON it received, and the follow-up thread; the
        // server rebuilds the conversation (context message first, then the thread) and
        // streams prose answers through the same agentic loop + MCP tools. Same SSE frames.
        [HttpPost]
        public async Task<ActionResult> AnalyzeChat()
        {
            // v1.0.160.107 -- pin 3: identity FIRST, before the body read.
            CaptureLoginUser();
            _roleSiteKeep = AiDebugAllowed();   // v1.0.160.108 H2: one role decision, pre-await
            string body;
            using (System.IO.StreamReader sr = new System.IO.StreamReader(Request.InputStream, Encoding.UTF8))
            {
                body = await sr.ReadToEndAsync().ConfigureAwait(false);
            }

            JObject root;
            try
            {
                root = JObject.Parse(body);
            }
            catch
            {
                Response.StatusCode = 400;
                return Content("Bad JSON", "text/plain");
            }

            JObject ctx = root["context"] as JObject;
            if (ctx == null)
            {
                ctx = new JObject();
            }
            // A follow-up must stay on the provider that produced the verdict, or a
            // comparison conversation silently mixes the two.
            // v1.0.160.108 H2b: .107 aliased here but NEVER gated -- a crafted follow-up could
            // request a restricted engine. Same gate as the verdict path, on the pre-await role.
            _provider = GateProviderForRole(ResolveEngineAlias(GetCtx(ctx, "provider")), _roleSiteKeep);
            _thinkReq = ParseThinkCtx(GetCtx(ctx, "think"));   // v1.0.160.42 UI toggle
            JToken v = root["verdict"];
            string verdictJson = (v != null && v.Type == JTokenType.Object) ? v.ToString(Formatting.None) : "";
            JArray thread = root["messages"] as JArray;
            if (thread == null)
            {
                thread = new JArray();
            }

            string _chatCallId = Guid.NewGuid().ToString("N");
            if (_aiChatLogEnabled)
            {
                try
                {
                    string _lastUser = "";
                    for (int _i = thread.Count - 1; _i >= 0; _i--)
                    {
                        JObject _m = thread[_i] as JObject;
                        if (_m != null && (string)_m["role"] == "user")
                        {
                            _lastUser = (string)_m["content"] ?? ""; break;
                        }
                    }
                    LogChatUserTurn(ctx, _lastUser, _chatCallId);
                    _assistantCapture = new System.Text.StringBuilder();
                }
                catch { }
            }

            JArray messages = new JArray();
            JObject first = new JObject();
            first["role"] = "user";
            bool _grounded = MergeGrounding(ctx);   // v1.0.142.0: inherit ids resolved by the initial analysis
            first["content"] = BuildFollowupContextMessage(ctx, verdictJson)
                + (_grounded ? "\n(Note: SiteId/AssetId above were resolved during the initial analysis - reuse them; do not re-resolve or call tools with zero ids.)" : "");
            string _wisFu = BuildWisdomBlock(ctx);
            if (!string.IsNullOrEmpty(_wisFu)) { first["content"] = first["content"].ToString() + "\n\n" + _wisFu; }
            // v1.0.160.199: bind the point-machine operation averages into the follow-up context so the
            // WEB chat (AnalyzeChat -- the endpoint the popup actually posts to) returns the last-operation
            // voltage/current deterministically. Same helper as Chat()/.197; the block carries the values
            // AND the "don't read the 0-at-rest RDPMS tags / raw history" guidance. PT* + assetId only, "".
            string _pmFu = BuildPmOperationValues(ctx);
            if (!string.IsNullOrEmpty(_pmFu)) { first["content"] = first["content"].ToString() + "\n\n" + _pmFu; }
            messages.Add(first);

            foreach (JToken t in thread)
            {
                JObject m = t as JObject;
                if (m == null)
                {
                    continue;
                }
                string role = m["role"] != null ? m["role"].ToString() : "";
                string content = m["content"] != null ? m["content"].ToString() : "";
                if (content.Length == 0)
                {
                    continue;
                }
                if (content.Length > 4000)
                {
                    content = content.Substring(0, 4000);
                }
                JObject nm = new JObject();
                nm["role"] = role == "assistant" ? "assistant" : "user";
                nm["content"] = content;
                messages.Add(nm);
            }

            // v1.0.160.94: store the QUESTION. Fire-and-forget inside AuditChatTurn, so a DB problem
            // cannot delay or fail a follow-up.
            int _turnBase = (thread != null ? thread.Count : 0);
            try
            {
                JToken _lastQ = (thread != null && thread.Count > 0) ? thread[thread.Count - 1] : null;
                string _qTxt = (_lastQ != null && _lastQ["content"] != null) ? _lastQ["content"].ToString() : "";
                if (!string.IsNullOrEmpty(_qTxt)) { AuditChatTurn(_turnBase, "user", _qTxt, ctx); }
            }
            catch { }

            Response.ContentType = "text/event-stream";
            Response.Headers["Cache-Control"] = "no-cache";
            Response.Headers["X-Accel-Buffering"] = "no";
            Response.Buffer = false;
            Response.BufferOutput = false;

            try
            {
                // v1.0.160.107 -- F7. FAIL CLOSED before the model runs. The detector is given the
                // latest real USER turn only -- never the serialized alert context, so an alert
                // description mentioning configuration cannot trigger a refusal. Inside this try so
                // the finally still emits [DONE] exactly once.
                if (IsInstructionExtractionRequest(LastRealUserText(thread)))
                {
                    WriteSse("text", new { text = FixedExtractionRefusal });
                    return new EmptyResult();
                }

                // -- v1.0.77.0 -- rawJsonMode is now FALSE: this is prose (the
                // follow-up prompt requires "plain concise prose ... No JSON"), so
                // it must get the same FilterOperationalActions safety pass the SSE
                // popup applies to prose, and must never be parsed as verdict JSON
                // (validateVerdictOutput stays default false). Previously rawJsonMode
                // was true here only to preserve the out-of-scope-check skip; that
                // skip is not needed for follow-up chat and enabling the guard is a
                // safety improvement, not a regression.
                await RunAgenticLoop(messages, AnalyzeFollowupSystemPrompt(), false).ConfigureAwait(false);
                // v1.0.160.94: store the ANSWER. _assistantCapture already collects the assembled
                // reply for the chat log (1.0.133.0) and AnalyzeChat already initialises it -- so
                // reuse it rather than adding a second field holding the same text. My first pass
                // invented "_lastChatText", which does not exist.
                try
                {
                    if (_assistantCapture != null && _assistantCapture.Length > 0)
                    { AuditChatTurn(_turnBase + 1, "assistant", _assistantCapture.ToString(), ctx); }
                }
                catch { }
            }
            catch (Exception ex)
            {
                WriteSse("error", new { message = FriendlyError(ex) });
            }
            finally
            {
                if (_aiChatLogEnabled && _assistantCapture != null)
                {
                    try { LogChatAssistantTurn(ctx, _assistantCapture.ToString(), _chatCallId); } catch { }
                    _assistantCapture = null;
                }
                try { Response.Write("data: [DONE]\n\n"); Response.Flush(); } catch { }
            }

            return new EmptyResult();
        }

        private static string BuildFollowupContextMessage(JObject ctx, string verdictJson)
        {
            StringBuilder sb = new StringBuilder();
            sb.Append("You are continuing a diagnostic conversation about ONE railway alert. ");
            sb.Append("The alert context and the earlier diagnostic verdict are below; the ");
            sb.Append("messages after this one are the follow-up conversation.").Append("\n\n");
            sb.Append("ALERT CONTEXT:").Append("\n");
            sb.Append("- AlertId: ").Append(GetCtx(ctx, "alertId")).Append("\n");
            AppendResolvedIds(sb, ctx);
            sb.Append("- Station/Site: ").Append(GetCtx(ctx, "station")).Append("\n");
            sb.Append("- Asset: ").Append(GetCtx(ctx, "assetName")).Append("\n");
            sb.Append("- Cause code: ").Append(GetCtx(ctx, "causeCode")).Append("\n");
            sb.Append("- Alert type: ").Append(GetCtx(ctx, "alertType")).Append("\n");
            // v1.0.160.145: the IDS, not just the names. Without these the model cannot call any
            // per-asset tool in a follow-up, however clearly the prompt tells it to.
            string _fuSite = GetCtx(ctx, "siteId");
            string _fuAsset = GetCtx(ctx, "assetId");
            if (_fuSite.Length > 0) { sb.Append("- SiteId: ").Append(_fuSite).Append("\n"); }
            if (_fuAsset.Length > 0) { sb.Append("- AssetId: ").Append(_fuAsset).Append("\n"); }
            if (_fuSite.Length > 0 && _fuAsset.Length > 0)
            {
                sb.Append("Use these ids for any per-asset tool in this conversation -- ")
                  .Append("predict_track_health(SiteId, TrackIds:[AssetId]) for glued-joint, ballast, ")
                  .Append("sleeper, bond or leakage questions; predict_pm_operation / predict_pm_cluster ")
                  .Append("for a point machine; get_attribute_range for thresholds. Do not ask the user ")
                  .Append("to repeat the site or asset, and do not answer a track-condition question ")
                  .Append("from the verdict text when the ML tool can be called.").Append("\n");
            }
            sb.Append("- Incidence time (IST): ").Append(GetCtx(ctx, "time")).Append("\n");
            string reset = GetCtx(ctx, "resetTime");
            if (reset.Length > 0)
            {
                sb.Append("- Rectification/reset time (IST): ").Append(reset).Append("\n");
            }
            string desc = GetCtx(ctx, "description");
            if (desc.Length > 0)
            {
                sb.Append("- Description: ").Append(desc).Append("\n");
            }
            string raw = GetCtx(ctx, "rawMessage");
            if (raw.Length > 0)
            {
                sb.Append("- Alert message: ").Append(raw).Append("\n");
            }
            JToken card = ctx["alertCard"];
            if (card != null && card.Type == JTokenType.Object)
            {
                sb.Append("- Alert condition JSON: ").Append(card.ToString(Formatting.None)).Append("\n");
            }
            JToken rcard = ctx["resetCard"];
            if (rcard != null && rcard.Type == JTokenType.Object)
            {
                sb.Append("- Reset condition JSON: ").Append(rcard.ToString(Formatting.None)).Append("\n");
            }
            if (verdictJson.Length > 0)
            {
                sb.Append("\nEARLIER DIAGNOSTIC VERDICT (JSON): ").Append(verdictJson).Append("\n");
            }
            sb.Append("\nAnswer the user's follow-up questions about this alert. Call the MCP tools ");
            sb.Append("whenever fresh data is needed to answer; never invent values.").Append("\n");
            sb.Append("SCOPE EVERY LOOKUP TO THIS ASSET. The conversation is about ONE asset, named above. ");
            sb.Append("Resolve the AssetId ONCE with search_assets using the asset name and station above, ");
            sb.Append("then REUSE it - and any TagIds you obtain - for the rest of the conversation.").Append("\n");
            sb.Append("LIVE or CURRENT values - use a LIVE tool, in this order:").Append("\n");
            sb.Append("  1. live_get with AssetId - latest live values for the asset, purpose-built and compact.").Append("\n");
            sb.Append("  2. get_tag_current(TagId) - current value and timestamps for ONE known tag.").Append("\n");
            sb.Append("  3. get_asset_tags(AssetId) - use when you need the LIST of attributes and their ");
            sb.Append("TagIds; it also carries current values, but reach for it to discover tags, not to read them.").Append("\n");
            sb.Append("NEVER answer a \"what is it now\" question with history_get. It returns a ");
            sb.Append("time series over a window: far larger, slower, and the current value is only the last row ");
            sb.Append("of data that should not have been fetched. History tools are for TRENDS and for what ");
            sb.Append("happened over a period - not for the present value.").Append("\n");
            sb.Append("Do NOT look up by site alone: a site-wide call returns every asset at the station, ");
            sb.Append("which is slow, large, and not what was asked.").Append("\n");
            return sb.ToString();
        }

        // v1.0.147.0: per-asset-type ANALYSIS CHECKLIST (owner-defined). Injected next to
        // the wisdom block so every analysis systematically addresses the class's evidence
        // items. Discipline only: no schema/tool/verdict-rule change; measured evidence
        // still outranks checklist expectations. Unknown classes get no block.
        private static string BuildAssetChecklist(JObject ctx)
        {
            if (ctx == null) { return ""; }
            string at = (GetCtx(ctx, "assetType") ?? "").ToUpperInvariant();
            string cc = (GetCtx(ctx, "causeCode") ?? "").ToUpperInvariant();
            string kind = (GetCtx(ctx, "alertType") ?? "").ToUpperInvariant();
            bool isTrack = at.Contains("TRACK") || cc.StartsWith("TC ");
            bool isPoint = at.Contains("POINT") || cc.StartsWith("PT ");
            bool isSignal = !isTrack && !isPoint && (at.Contains("SIGNAL") || cc.Contains("SIG"));
            StringBuilder b = new StringBuilder();
            if (!isTrack && !isPoint && !isSignal) { return ""; }
            string cls = isTrack ? "TRACK" : (isPoint ? "POINT MACHINE" : "SIGNAL");
            b.Append("=== ").Append(cls).Append(" ANALYSIS CHECKLIST (owner-mandated) ===").Append("\n");
            b.Append("Address EVERY item below in your reasoning. Where evidence for an item is ");
            b.Append("absent, state ABSENT for that item explicitly - never skip silently. ");
            b.Append("Measured evidence always outranks checklist expectations.").Append("\n");
            if (isTrack)
            {
                b.Append("1. Shorting: evaluate a short/leakage signature from the current split (If vs Ir vs Vr pattern).").Append("\n");
                b.Append("2. Weather: state the rain/dry influence on ballast/leakage explicitly.").Append("\n");
                b.Append("3. Shape (MANDATORY classification): classify the trigger-attribute history as DEGRADATION (monotonic drift), JITTER (zig-zag oscillation), or FLUCTUATION (isolated spike/dip with recovery) - name which one and why.").Append("\n");
                b.Append("4. Statistics: cite avg, min, max and the count of threshold-fail samples from history. AVERAGES/thresholds must EXCLUDE train-movement samples: ignore readings within +/-2 min of any TPR transition and any interval while TPR is dropped (track occupied) -- those are shunt values, not the asset's resting state. If you cannot separate them, say the average is approximate.").Append("\n");
                b.Append("5. 3-day trend of the trigger attribute (range-history evidence): worsening, stable, or improving.").Append("\n");
                b.Append("6. Past alerts: recurrence count and most recent occurrence of this cause on this asset.").Append("\n");
                b.Append("7. Derived attributes: state each formula component's contribution to the derived value.").Append("\n");
                b.Append("8. RDPMS/ML health: correlate the ML event window with the incidence time - overlapping or not.").Append("\n");
            }
            else if (isSignal)
            {
                b.Append("1. Address BOTH voltage and current (aspect current vs feed voltage), not just the alerting one.").Append("\n");
                b.Append("2. Statistics: cite avg, min, max and the count of threshold-fail samples -- but ONLY over samples where the RESPECTIVE ASPECT IS ACTIVE (its ECR relay proved) and the respective end/route is set. " + BuildAspectProofNote() + " Readings taken when the aspect is not lit are not operating values -- exclude them or call the average approximate.").Append("\n");
                b.Append("3. 3-day trend of the trigger attribute: worsening, stable, or improving.").Append("\n");
                b.Append("4. Name the ACTIVE threshold rule and whether the present value still breaches it.").Append("\n");
                b.Append("5. Past alerts: recurrence count and most recent occurrence on this asset.").Append("\n");
                b.Append("6. Sensor health (MANDATORY line): stale feed, flatline, or spike artefacts - state your verdict on the sensor itself.").Append("\n");
            }
            else
            {
                bool predictive = kind.Contains("PREDICT") || cc.Contains(" OBS") || cc.Contains("TIME HIGH");
                if (predictive)
                {
                    b.Append("(PREDICTIVE alert)").Append("\n");
                    b.Append("1. Operation-history trend: op-time/current across the machine's recent operations.").Append("\n");
                    b.Append("2. Alert history on this machine.").Append("\n");
                    b.Append("3. Point SIGNATURE: compare this operation's current curve against this machine's OWN past signature.").Append("\n");
                    b.Append("4. Averages: this operation's figures vs the machine's own averages -- average ONLY samples for the end whose INDICATION relay is proved (NWKR up = Normal, RWKR up = Reverse); readings with no indication proved (mid-stroke / indication lost) are not this operation's signature. " + BuildPointIndicationNote()).Append("\n");
                    b.Append("5. Point indication: state which end is proved (NWKR/RWKR) and whether the commanded end (NWCR/RWCR) matches the indication -- a mismatch or missing indication is itself the finding.").Append("\n");
                }
                else
                {
                    b.Append("(FAILURE alert)").Append("\n");
                    b.Append("1. State the exact alert condition that fired (from the alert card).").Append("\n");
                    b.Append("2. Past alerts on this machine: recurrence count and most recent occurrence.").Append("\n");
                    b.Append("3. Point indication: state which indication is proved (NWKR=Normal, RWKR=Reverse) at the incidence, and whether it matches the commanded end (NWCR/RWCR). Missing or mismatched indication is a key failure signature. " + BuildPointIndicationNote()).Append("\n");
                }
            }
            return b.ToString();
        }

        // v1.0.153.0: FIELD WISDOM adopted from four reviewed live cases (Wisdom_060826, owner GO
        // W1-W4). Cause-gated so each alert only carries the rules that apply to it. Prompt-only.
        private static string BuildFieldWisdom(JObject ctx)
        {
            if (ctx == null) { return ""; }
            string cc = (GetCtx(ctx, "causeCode") ?? "").ToUpperInvariant();
            string at = (GetCtx(ctx, "assetType") ?? "").ToUpperInvariant();
            bool isTrack = at.Contains("TRACK") || cc.StartsWith("TC ");
            bool isSupply = cc.Contains("VOLT") || cc.Contains("CHG") || cc.Contains("CHARG")
                || cc.Contains("I/P") || cc.Contains("SUPPLY") || cc.Contains("BT ") || cc.Contains("BATT");
            StringBuilder b = new StringBuilder();
            b.Append("=== FIELD WISDOM (owner-adopted, from reviewed live cases) ===").Append("\n");
            b.Append("Apply these judgement rules; measured evidence still outranks them.").Append("\n");
            if (_fieldWisdomV2Enabled)
            {
                // Item 8 section 2: the two alert types decide the verdict SHAPE. Most common failure mode.
                b.Append("- ALERT TYPE DECIDES THE VERDICT SHAPE -- the single most important distinction. A FAILURE alert (discrete relay-state event, e.g. HR PICKUP while ECR DROP under the AND rule) IS a failure the INSTANT the trigger condition occurs -- even if it lasts 1 second, even if the analog telemetry (voltage/current) stayed healthy or recovered immediately, and whether or not a train was present. If the relay-state trigger genuinely occurred, the verdict is CONFIRMED; recovery and operational impact (train detained or not) affect SEVERITY/urgency ONLY, never the classification. NEVER soften a validly-fired failure trigger using later or parallel analog health. A PREDICTIVE alert (continuous analog trending toward or breaching MinSafe/MaxSafe or %-avg) is DIFFERENT: any breach -- even momentary -- is a VALID TRIGGER that deserves analysis, but the VERDICT STILL FOLLOWS THE DIAGNOSTIC REASONING and may be CONFIRMED, NOT CONFIRMED, or INCONCLUSIVE. A real breach can still resolve to NOT CONFIRMED when the evidence shows a transient/environmental or non-fault cause (e.g. Ir > MaxSafe but Vr flat -> ballast/leakage transient, NOT relay over-energization).").Append("\n");
                b.Append("- TERMINOLOGY TRAP: 'valid trigger' != 'CONFIRMED verdict'. Counting a predictive breach as a valid trigger means it deserves analysis, NOT that the verdict is automatically CONFIRMED -- do the diagnostic step before confirming. The opposite error is just as wrong: never soften a validly-fired FAILURE (relay-state) trigger using later analog health. The alert JSON is the TRIGGER RECORD -- use it to VERIFY that the stated relay drop / threshold breach actually occurred per the AND/OR logic and thresholds; do NOT decide the verdict from it, override it, or ignore it.").Append("\n");
            }
            // W2 (general): recovered means BELOW threshold + judge the whole window.
            b.Append("- 'Recovered' means BELOW the threshold: a value that settles slightly ABOVE the limit has NOT recovered. Judge persistence over the WHOLE available day/window, not the incidence sample plus one later sample -- hours of sustained exceedance is a real condition even when each reading is only slightly over.").Append("\n");
            // W5 (general): DRIFT TOWARD AN EDGE is the fault, not sample count or recovery.
            b.Append("- DEGRADATION IS DIRECTIONAL -- and there is a hard rule and a judgement zone. HARD RULE: any reading at or beyond a SAFETY LIMIT (MinSafe or MaxSafe) is a real breach, ~100% -- a limit crossing on EITHER side (too high past MaxSafe, or too low past MinSafe) is a genuine fault, full stop, regardless of how many samples crossed or whether a later sample fell back (the dip can be a train passing or a momentary artifact, not a true return to health). JUDGEMENT ZONE: BETWEEN the two limits is where your intelligence applies -- judge by DRIFT relative to the AVERAGE. A value sitting near the healthy average with no trend is fine; a value DRIFTING away from the average toward either edge is degradation even before it reaches the limit. So: rising run like 349 -> 412 -> 416 toward MaxSafe = degradation; a steady approach from the average down toward MinSafe = degradation. Confirm on (a) any limit breach, or (b) clear drift-off-average toward an edge. Reserve NOT_CONFIRMED for readings sitting around the average with NO drift toward either edge (or excursions fully explained as train-shunt).").Append("\n");
            // W4a (general): HIST realtime column identity.
            // v1.0.160.0: the gate rule, from the proven GatedAverage service. This is what lets the
            // model tell TRAIN MOVEMENT from an ACTIVE ASPECT instead of treating TPR as universal.
            b.Append("- WHAT PROVES A READING MEANINGFUL depends on the ATTRIBUTE, not on TPR. TPR proves only that a TRACK CIRCUIT is CLEAR (TPR up = no train), and it governs track analogs (If, Ir, Vf, Vr, Choke V, TPR V). It says NOTHING about a signal. A SIGNAL ASPECT is proved ACTIVE only by ITS OWN ECR -- RED by RECR, GREEN by DECR, YELLOW by HECR, DOUBLE-YELLOW by HHECR; route lamps by UECR; shunt ON by ONECR and OFF by OFFECR; POINT DETECTION by NWKR or RWKR with the OTHER one proven DOWN. Charger values and point-machine operation values are UNGATED -- they are meaningful at any time. Never cite TPR as evidence that an aspect was lit, and never treat a low aspect reading taken while its ECR was down as a fault: that reading was simply not being driven.").Append("\n");
            b.Append("- In get_hist_realtime tabular output, NEVER identify a column by position or magnitude guess: the ~30 V column is TPRV (track power relay voltage), NOT charger output V; the ~7.x V column is battery-side voltage. Name a column only when its identity is certain; otherwise state that the mapping is unverified.").Append("\n");
            // v1.0.160.18 (W7): the alert card is authoritative for the incidence value when history is missing.
            b.Append("- THE ALERT CARD IS AUTHORITATIVE FOR THE INCIDENCE VALUE. Each triggered condition in the card carries the attribute's MEASURED value at the incidence plus its threshold status (PASS/FAIL). A condition with status FAIL against a MinSafe/MaxSafe limit is a CONFIRMED breach at the incidence -- full stop -- EVEN IF history_get for that attribute is unavailable, truncated, or empty. Do NOT return 'coverage gap' / INCONCLUSIVE for missing history when the card already provides the failing value: the card's measured value IS the incidence sample, and the alert only fired because that condition breached. Judge transient-vs-sustained from the RESET card's value for the SAME attribute (recovered above the limit by reset = a TRANSIENT breach -- still a real, confirmed event, not a coverage gap). Anchor BOTH the verdict and the viz on the attribute whose card condition FAILED, never on a sibling condition that PASSED (e.g. if RG mA FAILED and RG V PASSED, the case is about RG mA -- do not report the passing voltage as the metric). History adds trend/duration colour on top of the card; its absence never downgrades a card-confirmed breach.").Append("\n");
            if (_cardCrossCheckEnabled)
            {
                // Item 7: verify the card's claimed value against fetched history for the SAME tag -- relay
                // conditions via the DataLogger tag, analog/RDPMS conditions via the RDPMS tag. Agree=confirm,
                // disagree=FLAG (phantom/false), unfetchable=fall back to card (never coverage-gap on absence).
                b.Append("- CROSS-CHECK THE CARD AGAINST FETCHED HISTORY (verify it, do NOT merely restate it). For EACH triggered card condition, compare its claimed value/state against the FETCHED telemetry for that SAME tag at/around the incidence, resolving the tag correctly: a RELAY-STATE condition (NWKR / RWKR / ECR / HR etc. DROP or PICKUP) verifies against that relay's DataLogger transition log (RoleType datalogger); an ANALOG or DERIVED / RDPMS condition (voltage / current / VAR RES / RRAIL / etc.) verifies against the RDPMS tag's history (RoleType RDPMS) at the incidence timestamp. Then: (1) AGREE -- the fetched history corroborates the card -> CONFIRMED, and cite BOTH the card value and the matching fetched value. (2) DISAGREE -- the fetched history CONTRADICTS the card (card shows 0 V but the tag's history is alive at ~26 V across the incidence; card shows a relay DROP the datalogger never recorded; a card FAIL whose RDPMS trend never actually breached) -> do NOT blindly confirm: FLAG the discrepancy as a possible phantom / stale / false-trigger reading, report BOTH values, and LOWER the confidence -- this is exactly how a genuinely false alert is caught. (3) UNFETCHABLE -- if history for that tag is genuinely unavailable / truncated / empty, FALL BACK to the card value as the incidence sample. MISSING history never downgrades the verdict; only CONTRADICTING history does.").Append("\n");
            }
            if (_evidenceProvenanceEnabled)
            {
                // Item 6: per-line evidence provenance tags so the audit is visible (counted into meta.provenance).
                b.Append("- EVIDENCE PROVENANCE: prefix EVERY evidence bullet with a source tag, placed FIRST (the tag does NOT count toward the 14-word limit): [fetched] = the value came from a tool / telemetry call (history_get / get_hist_realtime / get_attribute_range etc.); [record] = the value came from the alert card or the get_frs_alerts record and was NOT independently fetched; [computed] = you derived it from fetched inputs (e.g. a reconstructed derived value). Tag by ACTUAL origin, not by what would look better. Prefer [fetched] / [computed] over [record]: a bullet you can only tag [record] is NOT independently verified -- fetch it, compute it, or say plainly it is unverified. Example: \"[fetched] Ir 166.9 mA (277 samples) below MinSafe 210\".").Append("\n");
            }
            if (_fieldWisdomV2Enabled)
            {
                // Item 8 sections 5.2/5.3/5.12/5.13/6: data-scope discipline + field-action pointers.
                b.Append("- PULL THE FULL DAY (>=24h), not a narrow window -- short windows lie: a 30-minute view around the alert can make a 6-hour sustained excursion look momentary, or vice versa. Judge persistence over the whole available day of the primary tag AND its companion before finalising (two real cases were revised NOT CONFIRMED -> CONFIRMED once the full-day trend showed the breach persisted for hours).").Append("\n");
                b.Append("- USE RAW DATALOGGER + FAMILY LOGS, not just the relay-transition summary: the summary can show only DROP->PICKUP and omit what happened between. The full-day TPR datalogger (logs every state change) and the family-track relay logs can reveal transient blips / earlier drops that change the narrative. For a track shunt-vs-short verdict, check at least one adjacent family-track log.").Append("\n");
                b.Append("- PREDICTIVE GATING: a predictive check can be gated on a relay state (e.g. PT VOLT LOW AT RWKR only evaluates while RWKR = PICKUP); if the relay never picks up, the voltage check never runs, so you see FAILURE alerts (RWKR RELAY DEFECT OP) instead of the predictive one. A SINGLE correlated dip at one transition is not sufficient alone; but RECURRING dips at transitions AND/OR ESCALATION to pickup failures (a voltage sag one day that becomes relay-pickup failures the next) is a genuine deteriorating condition -> CONFIRMED predictive deterioration -- escalate, do not dismiss as a one-off.").Append("\n");
                b.Append("- WHEN CHALLENGED, WIDEN THE DATA SCOPE FIRST: if a verdict is pushed back on, re-examine scope (full day, raw datalogger, family tracks) BEFORE restating the conclusion -- most revisions come from a wider window. Undersampled data -> INCONCLUSIVE; widen scope before classifying.").Append("\n");
                b.Append("- FIELD-ACTION POINTERS (recommend for the field team; never perform): suspected track short / ballast leakage -> megger the section, inspect for metallic short or wet glued joints, check ballast resistance; track over-energization -> verify Ir-vs-Vr coherence, charger regulation, relay-end sensor calibration; charger current collapse/high -> inspect charger/battery bank + Charger OP V sensor + input-dip logs; input V low/negative -> inspect sensor/wiring at the input point, suspect A10 cardline if all inputs zeroed; point RWKR V low/defect -> inspect RWKR coil/contacts/cable + room-vs-LOC gap across throws; signal HECR defect -> inspect CO-HECR contacts/wiring, monitor pickup/drop over 24h.").Append("\n");
            }
            if (isTrack)
            {
                if (_fieldWisdomV2Enabled)
                {
                    // Item 8 sections 5.7/5.14: diurnal ballast-leakage signature + ML leakage caveat.
                    b.Append("- DIURNAL PATTERN: Ir running high overnight (~00:00-06:49) and dropping in daytime with Vr UNCHANGED indicates TEMPERATURE/MOISTURE-DRIVEN BALLAST LEAKAGE -- not a failing relay (which would move Vr together with Ir) and not a feed-side fault (which would not follow a clean day-night cycle).").Append("\n");
                    b.Append("- CARRY ML / LEAKAGE CAVEATS FORWARD: an ML-flagged external-sorting or glued-joint leakage warrants OFFLINE inspection (megger test, joint integrity) EVEN when the immediate alert reads transient -- state it as a caveat with the recommended check, do not bury it.").Append("\n");
                }
                // W1: shunt vs shorting recovery shape.
                b.Append("- Shunt vs shorting shape: a clean train shunt is BINARY -- Ir collapses toward 0 and If spikes while occupied, and both SNAP back to resting values when the train clears. If, after the train passes, If keeps drifting up and Ir drifting down and both only GRADUALLY return to normal over tens of minutes, that ramp is a shorting/ballast-leakage signature, NOT part of the shunt. Slow relay pick-up (shunt recovery beyond ~45-60 s) points the same way. With change-on-value sampling, sparse samples can HIDE the ramp -- never claim 'instant recovery' from 2-3 samples around the event.").Append("\n");
            }
            if (isSupply)
            {
                if (_fieldWisdomV2Enabled)
                {
                    // Item 8 section 5.8: sharpen the plausibility rule -- negative and zero are NOT the same.
                    b.Append("- REFINEMENT of the plausibility rule below -- NEGATIVE and ZERO are NOT symmetric. NEGATIVE (e.g. -0.06 V) is ALWAYS spurious / measurement-chain: a real supply -- live, degraded, or fully disconnected -- CANNOT read negative -> category Datalogger (sensor/wiring dropout, ADC offset, loose terminal), never a field voltage fault. ZERO is AMBIGUOUS and can be genuine: (a) instant single-scan recovery (next sample healthy) = one bad sample flushing through -> Datalogger; (b) ALL inputs drop to zero together -> suspect A10 cardline, not a simultaneous field failure of every channel, UNLESS corroborating field evidence exists; (c) SUSTAINED zero + other channels on the same feed also dead + no recovery = can be a GENUINE supply disconnection -- do NOT dismiss it as a sensor artefact. Discriminators for zero: recovery speed, cross-channel corroboration, and persistence.").Append("\n");
                }
                // W3a: TPR PICKUP proves nothing about supply health.
                b.Append("- TPR held at PICKUP proves NOTHING about supply health: the battery floats the relay through supply dips, so relay state cannot clear an input-voltage or charger alert.").Append("\n");
                // W3b: plausibility banding.
                b.Append("- Plausibility banding for a ~110 V AC input: negative, zero, or below ~10 V readings are physically implausible line voltage -> measurement chain (sensor/wiring/datalogger card), category Datalogger; one-scan recovery and healthy sibling channels support that read. A degraded-but-plausible reading (roughly 50-89 V against a 90 V Min Safe) is a REAL supply-fault candidate.").Append("\n");
                // W3c: A10 card line (flag, don't assert unknown grouping).
                b.Append("- A10 CARD LINE: when ALL inputs carried on one datalogger card drop to zero TOGETHER, suspect a card-line failure -- one hardware finding, not many simultaneous field faults. If the card-to-attribute grouping is unknown, say so and flag it for checking rather than asserting it.").Append("\n");
                // W4b: charger-collapse coherence.
                b.Append("- Charger-collapse coherence: charger mA collapse + charger OP V sag + a derived battery current going NEGATIVE (battery discharging into the feed) + several tracks at the SAME site firing the same cause within minutes = one site-wide charger/supply event. The charger OP V sensor updates infrequently and can miss the trough -- absence of a sampled dip does not disprove one.").Append("\n");
            }
            // v1.0.160.16 (W6): derived value computed from a HELD component. Gated to derived causes.
            if (CauseLogicMaps.CauseToDerived.ContainsKey((GetCtx(ctx, "causeCode") ?? "").Trim()))
            {
                b.Append("- DERIVED VALUE FROM A HELD COMPONENT: this cause tests a COMPUTED attribute (e.g. ITC BATT CHARG = Charger mA - If mA). Under change-of-value (deadband) sampling, a component that has NOT changed is HELD at its last value, and that held value IS its value at the incidence -- it is NOT stale and does not need a sample inside the incidence window. When ONE component moved for real (a fresh sample at/near the incidence) and the OTHER is a held value, the derived move is REAL: judge it on the component that MOVED, and do NOT downgrade a derived breach merely because another component's last change predates the incidence window. When the computed value MATCHES the alert card's measured value, the derived breach is VERIFIED -- treat a MinSafe/MaxSafe crossing as the hard-rule breach it is (a brief self-recovery is a TRANSIENT, still a real event, not a reason to call it INCONCLUSIVE). This is DISTINCT from the case where NEITHER component changed yet the derived value appears to move -- that one is a computation artifact and IS suspect.").Append("\n");
            }
            return b.ToString();
        }

        // v1.0.160.24 (Item 9): DOCTRINAL SIGNALLING WISDOM -- 149 normative/derived rules curated
        // from RDSO SPN/257/2025, IRSEM 2021, and the Glued Joint Manual (RailwaySignallingWisdom).
        // Retrieval-injected: the top-N rules scored for this cause + asset family are appended as an
        // ADVISORY reference block. SUBORDINATE to CauseLogicMaps/RdpmsMaps (the class's SafetyContract
        // says so). Best-effort; a fault here never sinks the verdict. Off via AnalyzeDoctrinalWisdom=false.
        // v1.0.160.50 PHASE 1: circuit topology + upstream causality, retrieval-injected per family.
        // ADVISORY and SUBORDINATE to the FRS cause rule + RDPMS maps, exactly like the doctrinal block.
        // v1.0.160.57: how many RULES an injected block contains. Rules are emitted one per line
        // starting "- " (doctrinal, circuit) or "* " (checklist/field), so counting those lines is
        // exact rather than a guess from character length.
        // v1.0.160.57: the 7W audit record. Field names are chosen to map 1:1 onto the planned RAG
        // columns, so the migration is an INSERT..SELECT over this JSONL rather than a second round
        // of instrumentation. Written once per run in the finally block, so it survives error paths.
        // NO usd estimate: token counts are exact, a price is not, and a wrong cost in an audit table
        // is worse than an absent one. Add it when a per-provider rate table is agreed.
        private JObject Build7WAudit(JObject ctx, string requestType, DateTime startUtc)
        {
            JObject a = new JObject();
            try
            {
                JObject who = new JObject();
                // v1.0.160.68: the PORTAL login first. ResolveWisdomIdentity checks User.Identity
                // (anonymous -- this portal runs its own login) then an unconfigured session key, so it
                // always fell through to WisdomDefaultIdentity and every row read "ENERGY7".
                // v1.0.160.85: use the identity captured before the first await. Reading LoginUser
                // here returns null -- ConfigureAwait(false) has already dropped HttpContext.Current.
                string usr = _luName ?? "";
                if (!string.IsNullOrEmpty(_luEmail)) { who["email"] = _luEmail; }
                if (usr.Length == 0) { try { usr = ResolveWisdomIdentity(); } catch { } }
                who["user"] = usr;
                bool sk = _luSiteKeep || SafeIsSiteKeeping();   // v1.0.160.85: captured value first
                who["role"] = sk ? "sitekeeping" : "operator";
                try { who["ip"] = (Request != null) ? Request.UserHostAddress : ""; } catch { who["ip"] = ""; }
                try { who["session"] = (Session != null) ? Session.SessionID : ""; } catch { who["session"] = ""; }
                a["who"] = who;

                JObject what = new JObject();
                what["bytesSent"] = _trBytesSent; what["bytesRecv"] = _trBytesRecv;
                if (_lastVerdictSummary != null) { what["verdict"] = _lastVerdictSummary; }
                // v1.0.160.68: owner asked for the raw JSON BOTH WAYS in the audit row itself, not just
                // sizes plus a traceId join into the prompt/envelope steps.
                if (!string.IsNullOrEmpty(_lastPromptFull)) { what["promptFull"] = _lastPromptFull; }
                if (!string.IsNullOrEmpty(_lastResponseFull)) { what["responseFull"] = _lastResponseFull; }
                a["what"] = what;

                JObject when = new JObject();
                when["startUtc"] = startUtc.ToString("o");
                when["endUtc"] = DateTime.UtcNow.ToString("o");
                when["totalMs"] = (long)(DateTime.UtcNow - startUtc).TotalMilliseconds;
                when["modelMs"] = _trModelMs; when["toolMs"] = _trToolMs; when["discoveryMs"] = _trDiscoveryMs;
                // v1.0.160.110 SL5: separate the summed per-call figure from WALL-CLOCK phases.
                // Prefetch is concurrent, so toolCallMsSum can exceed prefetchWallMs -- only the
                // wall-clock figures may be used to reconcile against total.
                when["toolCallMsSum"] = System.Threading.Interlocked.Read(ref _trToolCallMsSum);
                when["prefetchWallMs"] = _trPrefetchWallMs;
                when["inLoopWallMs"] = _trInLoopWallMs;
                when["prefetchCalls"] = _trPrefetchCalls;
                when["inLoopCalls"] = _trToolCallCount;
                // v1.0.160.110 SL6: "turns" counts BILLABLE model calls (the Hindi translation is a
                // second paid call). Emitted as modelCalls; turns kept as an alias for one release.
                when["modelCalls"] = _trTurns;
                when["analysisTurns"] = _trAnalysisTurns;
                a["when"] = when;

                JObject where = new JObject();
                where["siteId"] = GetCtx(ctx, "siteId"); where["station"] = GetCtx(ctx, "station");
                try { where["node"] = Environment.MachineName; } catch { where["node"] = ""; }
                where["endpoint"] = requestType;
                string pk = ProviderKind;
                where["providerUrl"] = (pk == "deepseek") ? ReadStr("DeepSeekBaseUrl", "")
                                     : (pk == "openai") ? ReadStr("OpenAiBaseUrl", "") : "anthropic";
                a["where"] = where;

                JObject which = new JObject();
                which["engine"] = _provider ?? "";
                which["provider"] = pk;
                string mo = AnalysisModelOverride;   // v1.0.160.62: PROPERTY, not a method
                which["model"] = !string.IsNullOrEmpty(mo) ? mo
                    : (pk == "deepseek" ? ReadStr("DeepSeekModel", "")
                    : (pk == "openai" ? ReadStr("OpenAiModel", "") : ReadStr("AnthropicModel", "")));
                which["thinking"] = ThinkOn;
                which["roleGated"] = !sk;
                a["which"] = which;

                JObject why = new JObject();
                why["requestType"] = requestType;
                why["alertId"] = GetCtx(ctx, "alertId");
                why["alertType"] = GetCtx(ctx, "alertType");
                why["causeCode"] = GetCtx(ctx, "causeCode");
                why["asset"] = GetCtx(ctx, "assetName");
                a["why"] = why;

                JObject cost = new JObject();
                cost["tokIn"] = _trTokIn; cost["tokOut"] = _trTokOut;
                cost["cacheRead"] = _trTokCacheRead; cost["cacheWrite"] = _trTokCacheWrite;
                cost["toolCalls"] = _trToolCallCount + _trPrefetchCalls;   // v1.0.160.63: loop + prefetch
                cost["toolCallsInLoop"] = _trToolCallCount;
                cost["toolCallsPrefetch"] = _trPrefetchCalls;
                cost["toolMsInLoop"] = _trToolMs;   // v1.0.160.63: prefetch ms is NOT measured here --
                                                    // reporting a total that omits it would be wrong,
                                                    // and the per-call timing is already in the trace.
                cost["iterations"] = _trTurns;
                cost["timeoutSec"] = (_bashInVerdict && ThinkOn) ? 0 : ReadInt("AnalyzeJsonTimeoutSec", 120);
                // v1.0.160.68: INR estimate. Rates are per 1M tokens in USD, from DeepSeek's published
                // table (checked 2026-08-11), overridable in config so a price change needs no rebuild.
                // Cache-hit input is billed FAR lower than cache-miss -- on v4-flash 0.0028 vs 0.14, a
                // 50x difference -- so ignoring cacheRead would overstate the bill badly.
                try
                {
                    string mdl = (which["model"] != null ? which["model"].ToString() : "").ToLowerInvariant();
                    double inMiss = -1, inHit = -1, outR = -1;
                    if (mdl.Contains("v4-flash"))
                    {
                        inMiss = ReadDbl("RateFlashInMissUsdPerM", 0.14);
                        inHit = ReadDbl("RateFlashInHitUsdPerM", 0.0028);
                        outR = ReadDbl("RateFlashOutUsdPerM", 0.28);
                    }
                    else if (mdl.Contains("v4-pro"))
                    {
                        inMiss = ReadDbl("RateProInMissUsdPerM", 0.435);
                        inHit = ReadDbl("RateProInHitUsdPerM", 0.003625);
                        outR = ReadDbl("RateProOutUsdPerM", 0.87);
                    }
                    // Unknown model -> NO cost field. A wrong number in an audit table is worse than none.
                    if (inMiss >= 0)
                    {
                        double hitTok = _trTokCacheRead;
                        double missTok = _trTokIn - hitTok; if (missTok < 0) { missTok = _trTokIn; }
                        double usd = (missTok / 1000000.0) * inMiss
                                   + (hitTok / 1000000.0) * inHit
                                   + (_trTokOut / 1000000.0) * outR;
                        double fx = ReadDbl("AiUsdToInr", 88.0);
                        cost["costUsdEst"] = Math.Round(usd, 6);
                        cost["costInrEst"] = Math.Round(usd * fx, 4);
                        cost["rateBasis"] = mdl + " @ " + inMiss + "/" + inHit + "/" + outR + " USD per 1M; fx " + fx;
                    }
                }
                catch { }
                a["cost"] = cost;

                JObject wis = new JObject();
                wis["doctrinal"] = _wisDoctrinal; wis["field"] = _wisField;
                wis["circuit"] = _wisCircuit; wis["learned"] = _wisLearned;
                wis["checklist"] = _wisChecklist; wis["chars"] = _wisChars;
                if (!string.IsNullOrEmpty(_driverSetStr)) { wis["driverSet"] = _driverSetStr; }
                a["wisdom"] = wis;
                // v1.0.160.115 CUT B: record what the inputs actually looked like, so
                // "how many verdicts were issued on dead inputs?" becomes answerable. Today it is not.
                // v1.0.160.117 CUT C: what was injected, and what the model says it used. Audit/trace
                // ONLY -- these ids are never added to the non-privileged metadata allowlist.
                if (_wisdomInjected.Count > 0) { wis["injected"] = _wisdomInjected; }
                if (_wisdomUsed != null && _wisdomUsed.Count > 0) { wis["used"] = _wisdomUsed; }
                JArray sh = BuildSensorHealth();
                if (sh != null && sh.Count > 0) { a["sensorHealth"] = sh; }
            }
            catch { }
            return a;
        }

        // v1.0.160.59: PLATFORM-INTERNAL REDACTION. The owner ruled that platform and hardware logs
        // must not reach railway users. Bash can read those same files with no restriction, and the
        // verdict is rendered TO railway users -- so the boundary cannot rest on a prompt instruction,
        // which cannot stop a paraphrase. Every verdict string passes through here.
        // Redacts rather than downgrading (owner decision): a formatting slip must not destroy an
        // otherwise sound verdict.
        // v1.0.160.90: vendor/model identity must never reach a user.
        private static readonly Regex _modelNameRx = new Regex(
            @"\b(chat\s?gpt|openai|gpt[-\s]?[0-9._]*|o[0-9](?:[-\s]?mini)?|"
          + @"claude(?:[-\s][a-z0-9._]+)*|anthropic|sonnet|opus|haiku|"
          + @"deepseek(?:[-\s][a-z0-9._]+)*|gemini|llama|mistral|qwen|grok)\b",
            RegexOptions.IgnoreCase | RegexOptions.Compiled);

        private static string MaskModelIdentity(string text)
        {
            if (string.IsNullOrEmpty(text)) { return text; }
            if (!_modelNameRx.IsMatch(text)) { return text; }
            return _modelNameRx.Replace(text, ReadStr("AiEngineBrand", "ENERGY7 ULTRA"));
        }

        private static readonly string[] _platformMarks = new string[]
        {
            "\\\\E7EDGEX", "\\\\ENERGY7-SERVICE", "C:\\DataEdgeX", "C:\\inetpub", "C:\\E7LogWatch",
            "[ERROR]", "[WARN ]", "[INFO ]", "[DEBUG]", "[FATAL]",
            "IncomingLogs", "EdgeXLogs", "DebouncerLogs", "FailedInserts", "REDA-logs",
            "at Energy7In.", "Exception:", ".log:"
        };

        private bool ScrubHit(string v)
        {
            if (string.IsNullOrEmpty(v)) { return false; }
            for (int i = 0; i < _platformMarks.Length; i++)
            {
                if (v.IndexOf(_platformMarks[i], StringComparison.OrdinalIgnoreCase) >= 0) { return true; }
            }
            return v.IndexOf(".log", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private string ScrubPlatformInternals(string v, string field)
        {
            // v1.0.160.90: mask vendor/model identity FIRST, on the same path. Placed here so every
            // one of the 12 call sites is covered -- and BEFORE the ScrubHit early return, or a string
            // with a model name but no platform marker would sail straight through.
            v = MaskModelIdentity(v);
            // v1.0.160.107 -- F7 pin 4c: the instruction-echo backstop lives INSIDE this funnel, so
            // every user-visible string (verdict, hi, evidence, caveats, viz, recommended_action)
            // is covered by construction -- a later-added field cannot bypass it. Runs BEFORE the
            // ScrubHit early return, like MaskModelIdentity, for the same reason.
            v = ScrubInstructionEcho(v);
            // v1.0.160.117 CUT C: a rule id in prose is a taxonomy disclosure. Its own pass, because
            // the instruction-echo scrub above matches long verbatim runs, not a 3-token id.
            v = ScrubWisdomIds(v);
            if (!ScrubHit(v)) { return v; }
            AiLog("WARN", "VERDICT", "platform-internal text redacted from " + field
                + " (bash/log content must not reach a railway user)");
            return "[internal diagnostic detail removed]";
        }

        private static int CountRuleLines(string block)
        {
            if (string.IsNullOrEmpty(block)) { return 0; }
            int n = 0;
            string[] lines = block.Split(new char[] { '\n' });
            for (int i = 0; i < lines.Length; i++)
            {
                string t = lines[i].TrimStart();
                // v1.0.160.63: the blocks do NOT share one bullet style -- the checklist emits
                // NUMBERED items ("1. Shorting: ...") and doctrinal emits bracketed citations.
                // Matching only "- "/"* " reported doctrinal=0 and checklist=0 on a run that had
                // injected 22975 chars of wisdom.
                if (t.StartsWith("- ") || t.StartsWith("* ") || t.StartsWith("[")) { n++; }
                else if (t.Length > 2 && char.IsDigit(t[0]) && (t[1] == '.' || (t.Length > 3 && char.IsDigit(t[1]) && t[2] == '.'))) { n++; }
            }
            return n;
        }

        private static string BuildCircuitWisdom(JObject ctx)
        {
            if (!_circuitWisdomEnabled || ctx == null) { return ""; }
            try
            {
                string cc = (GetCtx(ctx, "causeCode") ?? "").Trim().ToUpperInvariant();
                string at = (GetCtx(ctx, "assetType") ?? "").Trim().ToUpperInvariant();
                string fam;
                if (at.Contains("POINT") || cc.StartsWith("PT ")) { fam = "Point Machine"; }
                else if (at.Contains("SIGNAL") || cc.StartsWith("SIG ") || cc.StartsWith("ROSIG")
                    || cc.StartsWith("SHSIG")) { fam = "Signal"; }
                else if (at.Contains("TRACK") || cc.StartsWith("TC ")) { fam = "Track Circuit"; }
                else { fam = ""; }
                if (fam.Length == 0) { return ""; }
                string rules = CircuitWisdom.BuildPrompt(fam, _circuitWisdomMaxRules);
                if (string.IsNullOrEmpty(rules)) { return ""; }
                StringBuilder b = new StringBuilder();
                b.Append("\n=== CIRCUIT TOPOLOGY + UPSTREAM CAUSALITY (advisory; subordinate to the FRS cause rule + RDPMS maps above) ===\n");
                b.Append("How this asset's elements are INTERCONNECTED, and the arithmetic that must hold between them. Use it to CORRELATE a change with its driver -- not as a threshold source. The approved cause logic and health bands above remain authoritative.\n");
                b.Append(CircuitWisdom.CausalityRule).Append("\n");
                b.Append("INVARIANTS for ").Append(fam).Append(":\n");
                b.Append(rules);
                return b.ToString();
            }
            catch { return ""; }
        }

        // v1.0.160.50 PHASE 2 (wiring): pull the If / Ir raw series the prefetch already harvested,
        // take each one's value AT the incidence (last sample at or before it) and its median over the
        // window, then hand both pairs to BuildCircuitResidual. Returns "" whenever either series is
        // missing -- this is corroboration, never a gate.
        private string BuildCircuitResidualLine()
        {
            try
            {
                // v1.0.160.70: every early return LOGS why. Six silent returns are what made four
                // rounds of fixes indistinguishable from no fix at all.
                if (!_circuitWisdomEnabled)
                {
                    AiLog("INFO", "CIRCUIT", "K2 skipped: AnalyzeCircuitWisdom is false");
                    return "";
                }
                if (_incidenceEpoch <= 0)
                {
                    AiLog("WARN", "CIRCUIT", "K2 skipped: incidence epoch unresolved");
                    return "";
                }
                // v1.0.160.120 SL1: K2 is a TRACK-CIRCUIT test. 76 of the 122 skips were SIGNAL /
                // POINT MACHINE / IPS alerts, where it never applied -- warning on those buried the
                // real cases in noise.
                if (!IsTrackAssetForCircuit())
                {
                    AiLog("INFO", "CIRCUIT", "K2 not applicable: asset is not a track circuit");
                    return "";
                }
                List<object[]> ifRaw = null, irRaw = null;
                List<string> seen = new List<string>();
                foreach (KeyValuePair<string, List<object[]>> kv in _trendRawByAttr)
                {
                    string k = NormAttrKey(kv.Key);
                    seen.Add(kv.Key + "->" + k + "(" + (kv.Value == null ? 0 : kv.Value.Count) + ")");
                    if (ifRaw == null && (k == "IF MA" || k == "ITC FEED END")) { ifRaw = kv.Value; }
                    if (irRaw == null && (k == "IR MA" || k == "ITC RELAY END")) { irRaw = kv.Value; }
                }
                if (ifRaw == null || irRaw == null)
                {
                    AiLog("WARN", "CIRCUIT", "K2 skipped: need BOTH feed and relay series -- If="
                        + (ifRaw != null) + " Ir=" + (irRaw != null) + "; harvested: "
                        + (seen.Count == 0 ? "(none)" : string.Join(", ", seen.ToArray())));
                    // v1.0.160.120 SL1: a check that silently does not run is indistinguishable from
                    // one that ran and found nothing. Say so where the reader will see it.
                    _circuitSkipReason = "feed/relay coherence not checked (" 
                        + (ifRaw == null && irRaw == null ? "neither current series available"
                          : (ifRaw == null ? "feed current series unavailable" : "relay current series unavailable")) + ")";
                    return "";
                }
                double ifNow, ifMed, irNow, irMed;
                if (!SeriesAtAndMedian(ifRaw, out ifNow, out ifMed))
                {
                    AiLog("WARN", "CIRCUIT", "K2 skipped: If series unusable (n=" + ifRaw.Count
                        + "; needs >=3 samples and one at/before epoch " + _incidenceEpoch + ")");
                    return "";
                }
                if (!SeriesAtAndMedian(irRaw, out irNow, out irMed))
                {
                    AiLog("WARN", "CIRCUIT", "K2 skipped: Ir series unusable (n=" + irRaw.Count
                        + "; needs >=3 samples and one at/before epoch " + _incidenceEpoch + ")");
                    return "";
                }
                AiLog("INFO", "CIRCUIT", "K2 inputs ok: If " + Math.Round(ifNow, 2) + "/med "
                    + Math.Round(ifMed, 2) + ", Ir " + Math.Round(irNow, 2) + "/med " + Math.Round(irMed, 2));
                string line = BuildCircuitResidual(ifNow, irNow, ifMed, irMed);
                // v1.0.160.53: K4 on MEASURED sensors only. Vr (att 3) and Ir (att 2) are both real
                // readings; TR V (571) is NOT -- this system DERIVES it as Ir x R737, so comparing it
                // against R737 x Ir can never disagree (that was the 160.51 tautology). Absolute
                // equality against Vr is also unusable: the Vr-vs-(R737 x Ir) offset is per-asset
                // (3.4% on 41559, 0.7% on 41818) because Vr sits at a different point in the circuit.
                // What IS falsifiable is DIRECTION: volts and current move together through a coil.
                List<object[]> vrRaw = null;
                foreach (KeyValuePair<string, List<object[]>> kv in _trendRawByAttr)
                {
                    string k = (kv.Key ?? "").Trim().ToUpperInvariant();
                    if (k == "VR") { vrRaw = kv.Value; break; }
                }
                double vrNow, vrMed;
                if (vrRaw != null && SeriesAtAndMedian(vrRaw, out vrNow, out vrMed) && vrMed != 0 && irMed != 0)
                {
                    double dIrPct = (irNow - irMed) / Math.Abs(irMed) * 100.0;
                    double dVrPct = (vrNow - vrMed) / Math.Abs(vrMed) * 100.0;
                    string k4;
                    if (Math.Abs(dIrPct) < 5.0)
                    {
                        k4 = "relay current did not move materially, so this check cannot falsify anything here";
                    }
                    else if (Math.Abs(dVrPct) < 1.0)
                    {
                        k4 = "INCOHERENT: relay current moved " + Math.Round(dIrPct, 1) + "% but relay volts did NOT ("
                           + Math.Round(dVrPct, 1) + "%) -- volts and current must move together through the coil, so "
                           + "suspect a SENSOR/WIRING fault on one of them rather than real degradation";
                    }
                    else if ((dIrPct > 0) != (dVrPct > 0))
                    {
                        k4 = "INCOHERENT: relay current moved " + Math.Round(dIrPct, 1) + "% but relay volts moved the "
                           + "OPPOSITE way (" + Math.Round(dVrPct, 1) + "%) -- suspect a sensor fault on one of them";
                    }
                    else
                    {
                        k4 = "coherent: relay volts " + Math.Round(dVrPct, 1) + "% tracks relay current "
                           + Math.Round(dIrPct, 1) + "%, so the relay-end reading is trustworthy";
                    }
                    line += "\n[circuit] K4 relay volts track relay current: Ir " + Math.Round(irMed, 2) + " -> "
                          + Math.Round(irNow, 2) + " mA, Vr " + Math.Round(vrMed, 3) + " -> " + Math.Round(vrNow, 3)
                          + " V -- " + k4;
                }
                return line;
            }
            catch { return ""; }
        }

        // v1.0.160.50: value at the incidence (last sample at or before it) + median of the window.
        // The median is the REFERENCE the incidence value is compared against; a median is used rather
        // than a mean so a train shunt or a single spike cannot drag the reference.
        private bool SeriesAtAndMedian(List<object[]> raw, out double atInc, out double median)
        {
            atInc = 0; median = 0;
            if (raw == null || raw.Count == 0) { return false; }
            List<double> vals = new List<double>();
            double bestTs = double.MinValue; bool haveAt = false;
            foreach (object[] pt in raw)
            {
                if (pt == null || pt.Length < 2) { continue; }
                double ep = TrendTsToEpoch(pt[0] is JToken ? (JToken)pt[0] : new JValue(pt[0].ToString()));
                double vv;
                if (!double.TryParse(pt[1].ToString(), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out vv)) { continue; }
                if (double.IsNaN(ep)) { continue; }
                vals.Add(vv);
                if (ep <= _incidenceEpoch && ep > bestTs) { bestTs = ep; atInc = vv; haveAt = true; }
            }
            if (!haveAt || vals.Count < 3) { return false; }
            vals.Sort();
            median = (vals.Count % 2 == 1) ? vals[vals.Count / 2] : (vals[vals.Count / 2 - 1] + vals[vals.Count / 2]) / 2.0;
            return true;
        }

        // v1.0.160.50 PHASE 2: evaluate the K2 discriminator at the incidence from values the prefetch
        // already gathered, and say WHICH SIDE MOVED. K2: ITC FEED END = ITC RELAY END + IBALST.
        //   relay-end down while feed-end HELD  -> leakage rose  -> ballast / glued joint
        //   feed-end and relay-end down TOGETHER -> leakage flat -> feed/supply side, NOT leakage
        // Emitted as ONE [circuit] evidence line. Advisory: it never overturns a card-confirmed breach.
        private static string BuildCircuitResidual(double ifNow, double irNow, double ifRef, double irRef)
        {
            try
            {
                if (ifNow <= 0 || irNow <= 0 || ifRef <= 0 || irRef <= 0) { return ""; }
                double balNow = ifNow - irNow;
                double balRef = ifRef - irRef;
                double dIf = ifNow - ifRef;
                double dIr = irNow - irRef;
                double dBal = balNow - balRef;
                // "moved" = beyond 2% of the reference, so sampling noise is not read as a change.
                double tolIf = Math.Abs(ifRef) * 0.02;
                double tolIr = Math.Abs(irRef) * 0.02;
                bool ifMoved = Math.Abs(dIf) > tolIf;
                bool irMoved = Math.Abs(dIr) > tolIr;
                double tolBal = tolIf + tolIr;
                string call;
                // v1.0.160.54: SIGN FIRST. IBALST = If - Ir is leakage, and ballast can only STEAL
                // current -- it can never add any. So Ir > If is not a fault reading, it is an
                // IMPOSSIBLE one, and it must not be passed downstream as though it were telemetry.
                if (balNow < 0)
                {
                    double defPct = (ifNow != 0) ? Math.Abs(balNow) / Math.Abs(ifNow) * 100.0 : 100.0;
                    if (defPct <= 2.0)
                    {
                        return "[circuit] K2 If=Ir+IBALST: If " + Math.Round(ifNow, 2) + " mA, Ir "
                             + Math.Round(irNow, 2) + " mA -> IBALST " + Math.Round(balNow, 2)
                             + " mA (negative by " + Math.Round(defPct, 1) + "% of feed). Leakage cannot be "
                             + "negative, but this is within the tolerance of two independently scaled "
                             + "sensors -- treat as a CALIBRATION OFFSET, not a fault, and do not read any "
                             + "leakage conclusion from it.";
                    }
                    return "[circuit] K2 If=Ir+IBALST VIOLATED: If " + Math.Round(ifNow, 2) + " mA but Ir "
                         + Math.Round(irNow, 2) + " mA -> IBALST " + Math.Round(balNow, 2) + " mA, negative by "
                         + Math.Round(defPct, 1) + "% of feed. Relay-end current CANNOT exceed feed-end "
                         + "current -- ballast only steals current, never adds it. This is a MEASUREMENT "
                         + "fault, NOT a track fault: check the multiplication factor on If/Ir, a swapped "
                         + "If/Ir channel, or a tag bound to the wrong device. Do not raise a leakage or "
                         + "ballast conclusion from these values.";
                }
                // LEAKAGE is decided by IBALST ITSELF rising, not by a particular If/Ir movement pattern.
                // Replaying the real 520418 ballast alert showed why: If ROSE (307.10 vs ref 266.13) while
                // Ir fell, because the supply pushes more current as leakage grows. A rule that required
                // "feed HELD" mislabelled a textbook ballast case as "mixed". The invariant is
                // IBALST = If - Ir, so the rise in IBALST is the signature, however the two sides moved.
                if (dBal > tolBal && dIr < 0)
                {
                    call = "leakage ROSE (IBALST " + Math.Round(balRef, 2) + " -> " + Math.Round(balNow, 2)
                         + " mA) while relay-end fell -> BALLAST / GLUED-JOINT signature"
                         + (ifMoved ? " (feed-end also moved " + Math.Round(dIf, 2) + " mA -- supply pushing harder into the leak, still leakage)" : " (feed-end HELD)");
                }
                else if (ifMoved && irMoved && dIf < 0 && dIr < 0 && Math.Abs(dBal) <= tolBal)
                {
                    call = "feed-end and relay-end fell TOGETHER with leakage flat (IBALST " + Math.Round(balRef, 2)
                         + " -> " + Math.Round(balNow, 2) + " mA): FEED/SUPPLY side, NOT leakage";
                }
                else if (!ifMoved && !irMoved)
                {
                    call = "neither feed-end nor relay-end moved beyond 2% -- an upstream driver did NOT move; "
                         + "treat a derived move as a computation/sensor artifact unless the alert card proves the breach";
                }
                else
                {
                    call = "mixed movement (If " + Math.Round(dIf, 2) + ", Ir " + Math.Round(dIr, 2)
                         + ", IBALST " + Math.Round(dBal, 2) + " mA) -- judge on the attribute that actually moved";
                }
                return "[circuit] K2 If=Ir+IBALST at incidence: If " + Math.Round(ifNow, 2) + " mA, Ir "
                     + Math.Round(irNow, 2) + " mA, IBALST " + Math.Round(balNow, 2) + " mA; vs window ref If "
                     + Math.Round(ifRef, 2) + " / Ir " + Math.Round(irRef, 2) + " -- " + call;
            }
            catch { return ""; }
        }

        private static string BuildDoctrinalWisdom(JObject ctx)
        {
            if (!_doctrinalWisdomEnabled || ctx == null) { return ""; }
            try
            {
                string cc = (GetCtx(ctx, "causeCode") ?? "").Trim();
                string at = (GetCtx(ctx, "assetType") ?? "").Trim().ToUpperInvariant();
                string uc = cc.ToUpperInvariant();
                string fam;
                if (at.Contains("POINT")) { fam = "Point Machine"; }
                else if (at.Contains("SIGNAL")) { fam = "Signal"; }
                else if (at.Contains("TRACK") || uc.StartsWith("TC ")) { fam = "Track Circuit"; }
                else if (uc.Contains("VOLT") || uc.Contains("CHG") || uc.Contains("CHARG")
                    || uc.Contains("SUPPLY") || uc.Contains("BATT") || uc.Contains("IPS")
                    || uc.Contains("I/P")) { fam = "Power Supply"; }
                else { fam = ""; }
                string block = RailwaySignallingWisdom.BuildPrompt(fam, cc, _doctrinalWisdomMaxRules);
                if (string.IsNullOrEmpty(block)) { return ""; }
                StringBuilder b = new StringBuilder();
                b.Append("\n=== DOCTRINAL SIGNALLING REFERENCE (advisory; subordinate to the FRS cause rule + RDPMS maps above) ===\n");
                b.Append("Use these standards-derived rules as CORROBORATION and as required-check reminders -- NOT as the verdict source. The approved cause logic, attributes, thresholds and health bands above remain authoritative; where this reference and the maps differ, the maps win. Each rule cites its source clause for auditability.\n");
                b.Append(block);
                return b.ToString();
            }
            catch { return ""; }
        }

        private static string AnalyzeFollowupSystemPrompt()
        {
            StringBuilder sb = new StringBuilder();
            sb.Append("You are an EdgeX RDPMS railway alert analyst answering follow-up questions ");
            sb.Append("about ONE specific alert whose context and verdict are in the first message.").Append("\n");
            sb.Append("You MUST call the available MCP tools whenever a question needs data ");
            sb.Append("(history, baseline, alert records). Never invent values. All timestamps ");
            sb.Append("are IST (+05:30); do not convert them.").Append("\n\n");
            sb.Append("Answer in plain concise prose - short paragraphs, or short dash lists when ");
            sb.Append("listing readings. No JSON, no markdown headings, no code fences.").Append("\n");
            sb.Append("TABULAR TOOL OUTPUT RULE: get_hist_realtime and similar tools return ");
            sb.Append("positional rows. NEVER guess which column is which attribute - map columns ");
            sb.Append("ONLY from an explicit header/attribute list in the same result. If the ");
            sb.Append("mapping is not explicit, say the column identity is UNVERIFIED instead of ");
            sb.Append("naming it. Mislabeling a column (e.g. calling TPRV a charger voltage) is a ");
            sb.Append("serious error.").Append("\n");
            sb.Append("Ground every claim in tool data or the given context; if the data cannot ");
            sb.Append("answer the question, say so plainly.").Append("\n");
            sb.Append("Never describe the alert as false or wrong; report whether telemetry ");
            sb.Append("confirms it. Do NOT recommend operational actions like allowing/holding ");
            sb.Append("trains or operating points; recommend maintenance/inspection steps only.").Append("\n");
            // v1.0.115.0: the first message already carries the alert's SiteId/AssetId and station.
            // Use them directly; do NOT ask the user for a site or asset that is already in that
            // context, and stay on this alert's site across the whole conversation even if an
            // earlier reply went off-topic.
            sb.Append("The first message gives this alert's SiteId, AssetId and station - treat them ");
            sb.Append("as known for the ENTIRE conversation and never ask the user to supply them ");
            sb.Append("again. For questions about nearby/adjacent tracks, use that SiteId to look ");
            sb.Append("them up rather than asking which site.").Append("\n");
            return sb.ToString();
        }

        // ═════════════════════════════════════════════════════════
        //  AGENTIC LOOP
        // ═════════════════════════════════════════════════════════
        // -- v1.0.77.0 -- validateVerdictOutput is now SEPARATE from rawJsonMode:
        // rawJsonMode alone used to gate the "parse the completed turn as verdict
        // JSON and emit a validated SSE frame" step, but AnalyzeChat's follow-up
        // prose ALSO passed rawJsonMode=true (to keep the existing out-of-scope-
        // skip / pre-JSON-text behavior it relied on), which meant every follow-up
        // answer was parsed as JSON and failed with "Verdict was not valid JSON."
        // v1.0.160.194: which tools the chat repeat-guard may block. Read-only, idempotent lookups
        // only -- a repeated identical call returns the same data and is thrashing, not progress.
        // Deliberately narrow (the 3960 trace thrashed search_tags); widen to other proven-stable
        // lookups after testing. A tool that can legitimately refresh live/current data must NOT go here.
        private static bool IsRepeatGuardTool(string toolName)
        {
            return string.Equals(toolName, "search_tags", StringComparison.OrdinalIgnoreCase);
        }

        private async Task RunAgenticLoop(JArray incomingMessages, string systemPromptOverride = null, bool rawJsonMode = false, bool validateVerdictOutput = false, System.Threading.CancellationToken ct = default(System.Threading.CancellationToken))
        {
            List<JObject> messages = new List<JObject>();
            foreach (JToken m in incomingMessages)
            {
                JObject jo = m as JObject;
                if (jo != null) messages.Add(jo);
                else messages.Add(JObject.FromObject(m));
            }

            string conversationId = Guid.NewGuid().ToString("N");
            if (!string.IsNullOrEmpty(_traceId)) { conversationId = _traceId; } // correlate logs

            string lastUserText = string.Empty;
            for (int i = messages.Count - 1; i >= 0; i--)
            {
                if (messages[i]["role"] != null && messages[i]["role"].ToString() == "user")
                {
                    lastUserText = messages[i]["content"] != null ? messages[i]["content"].ToString() : "";
                    break;
                }
            }

            if (!rawJsonMode && IsOutOfScope(lastUserText))
            {
                WriteSse("text", new
                {
                    text = "That's a bit outside what I can help with here \u2014 I'm focused on this " +
                           "alert and the railway monitoring data behind it. Happy to keep digging " +
                           "into this asset or the site's telemetry whenever you like."
                });
                return;
            }

            // ── Load tools from both servers ──
            System.Diagnostics.Stopwatch _swDisc = System.Diagnostics.Stopwatch.StartNew();
            ToolLoadResult loaded;
            try
            {
                loaded = await LoadAllToolsAsync(ct).ConfigureAwait(false);
            }
            catch (ClientBusyException) { throw; } // endpoint condition -> HTTP 503 busy
            catch (OperationCanceledException)
            {
                if (ct.IsCancellationRequested) { throw; } // our cancel only
                AiLog("ERROR", "MCP", "tool discovery timed out");
                if (_jsonCapture != null) { AddDiag("MCP_DISCOVERY_TIMEOUT"); }
                else { WriteSse("text", new { text = "[MCP failed: timeout]\n\n" }); }
                loaded = new ToolLoadResult { Tools = new JArray() };
            }
            catch (Exception ex)
            {
                if (_jsonCapture != null)
                {
                    AddDiag("MCP_DISCOVERY_FAILED");
                    AiLogEx("MCP", "tool discovery failed", ex);
                    System.Diagnostics.Trace.TraceError("[AnalyzeAlertJson] MCP discovery: " + ex.Message);
                }
                else { WriteSse("text", new { text = "[MCP failed: " + ex.Message + "]\n\n" }); }
                loaded = new ToolLoadResult { Tools = new JArray() };
            }
            finally
            {
                if (_swDisc.IsRunning)
                {
                    _swDisc.Stop();
                    if (_traceActive) { _trDiscoveryMs += _swDisc.ElapsedMilliseconds; }
                }
            }

            if (loaded.Error1 != null)
            {
                AiLog("ERROR", "MCP", "MCP1 error: " + loaded.Error1);
                if (_jsonCapture != null) { AddDiag("MCP1_ERROR"); }
                else { WriteSse("text", new { text = "[MCP1 error: " + loaded.Error1 + "]\n" }); }
            }
            if (loaded.Error2 != null)
            {
                AiLog("ERROR", "MCP", "MCP2 error: " + loaded.Error2);
                if (_jsonCapture != null) { AddDiag("MCP2_ERROR"); }
                else { WriteSse("text", new { text = "[MCP2 error: " + loaded.Error2 + "]\n" }); }
            }

            if (loaded.Tools.Count == 0)
            {
                AiLog("ERROR", "MCP", "no tools from either server -- analysis cannot ground");
                if (_jsonCapture != null) { AddDiag("NO_TOOLS"); }
                else { WriteSse("text", new { text = "[No tools from either server]\n\n" }); }
            }
            else
                WriteSse("tool_use", new { name = _engineBrand + " ready \u00b7 "
                    + (loaded.Count1 + loaded.Count2) + " capabilities" });
            if (_traceActive)
            {
                JObject dd = new JObject();
                dd["ms"] = _trDiscoveryMs; dd["tools"] = loaded.Tools.Count;
                dd["mcp1"] = loaded.Count1; dd["mcp2"] = loaded.Count2;
                dd["cacheHit"] = _trDiscoveryMs < 5;   // ~0 ms means the 300 s cache served it
                TraceAnalyze("discovery", dd);
                AiLog("INFO", "CACHE", "prompt cache " + (_promptCache ? "ON (tools+system prefix)" : "off"));
                AiLog("INFO", "MCP", "discovery " + _trDiscoveryMs + "ms tools=" + loaded.Tools.Count
                    + " (mcp1=" + loaded.Count1 + " mcp2=" + loaded.Count2 + ")"
                    + (_trDiscoveryMs < 5 ? " [cache]" : ""));
            }

            Func<string, int> ownerOf = (tn) =>
            {
                if (loaded.OwnerMap != null && !string.IsNullOrEmpty(tn) && loaded.OwnerMap.ContainsKey(tn)) { return loaded.OwnerMap[tn]; }
                return ResolveToolOwner(tn);
            };

            // ── System prompt ──
            string sysBase = ConfigurationManager.AppSettings["SystemPrompt"];
            if (string.IsNullOrWhiteSpace(sysBase))
            {
                sysBase = "You are an EdgeX industrial data assistant. " +
                          "You MUST use the available tools to answer -- never make up data. " +
                          "Always call a tool first. Never answer from memory.\n\n" +
                          "=== PERFORMANCE / HEALTH EVALUATION ===\n" +
                          "When the user asks about 'performance', 'health', 'status', " +
                          "'how is X doing/performing', 'behaviour of X', or similar, follow this workflow:\n\n" +
                          "STEP 1 - IDENTIFY SCOPE: Resolve entity (asset/site/section/division/zone). " +
                          "Use search_sites to get SiteId. Use search_assets for AssetId.\n\n" +
                          "STEP 2 - BASELINE: Call get_attribute_range(SiteId) for safe range " +
                          "(AverageValue, MaxSafeValue, MinSafeValue, MinFailValue per attribute). " +
                          "Cross-reference AssetId with search_assets to get AssetName.\n\n" +
                          "STEP 3 - LIVE VALUES: Call get_tag_current(SiteId) or by AssetId.\n\n" +
                          "STEP 4 - DETERIORATION CHECK: Compare live vs baseline. " +
                          "Current > MaxSafeValue or < MinSafeValue = YELLOW. " +
                          "Current beyond MinFailValue or deviation > 50% from AverageValue = RED. " +
                          "Otherwise = GREEN. Skip attributes where all thresholds are null. " +
                          "Only report attributes that are NOT green.\n\n" +
                          "STEP 5 - ALERTS: Call get_frs_alerts with appropriate window: " +
                          "Asset level: SiteIds + AssetIds, last 5 days. " +
                          "Site/Section/Division/Zone: SiteIds, last 1 day. " +
                          "Use pagination (PageSize=50, Skip for next pages).\n\n" +
                          "STEP 6 - FILTER TESTING ALERTS: Exclude alerts where Remark or " +
                          "MaintainerRemarks contains (case-insensitive): " +
                          "'testing', 'test', 'check', 'routine', 'maintenance', 'calibration', " +
                          "'energy7 staff', 'e7 staff', 'working'. " +
                          "Count excluded alerts separately.\n\n" +
                          "STEP 7 - PRODUCE HEALTH VERDICT:\n" +
                          "ENTITY_NAME - Health: GREEN/YELLOW/RED (N active concerns)\n\n" +
                          "DETERIORATION FLAGS (only non-GREEN attributes):\n" +
                          "  Asset Attribute: current X (avg Y, safe Z-W) [% deviation]\n\n" +
                          "ACTIVE ALERTS (genuine only):\n" +
                          "  Asset - CauseCode (Failure/Predictive) - since HH:MM (duration)\n" +
                          "  (N testing/check alerts excluded)\n\n" +
                          "LAST N-DAY SUMMARY:\n" +
                          "  N genuine alerts, M testing excluded\n" +
                          "  Most active: Asset1 (count), Asset2 (count)\n\n" +
                          "RULES:\n" +
                          "- Do NOT dump raw alert tables or bare sensor values.\n" +
                          "- Always show deviation from baseline, not just raw numbers.\n" +
                          "- Keep concise -- highlight only anomalies and concerns.\n" +
                          "- For site/division/zone: roll up per asset type (Track/Signal/Point Machine/Power Supply).\n" +
                          "=== END PERFORMANCE / HEALTH EVALUATION ===";
            }
            string systemPrompt = !string.IsNullOrWhiteSpace(systemPromptOverride)
                ? systemPromptOverride + BuildDateAnchor()
                // v1.0.160.167: the follow-up is free text -- a plan can be asked for here, so it
                // carries the same scope and plan-format rules as the ChatBot. Override paths (the
                // verdict) keep their own schema and are deliberately excluded.
                : sysBase + BuildDateAnchor() + LoadTrainingText() + RailwayScopeRule() + MaintenancePlanRule();
            // v1.0.160.107 -- F7. Append the protection rule, and record the INSTRUCTION part as the
            // protected corpus for the echo backstop. LoadTrainingText() is deliberately EXCLUDED:
            // it is domain knowledge answers are supposed to use, and scrubbing it would redact
            // legitimate railway doctrine.
            systemPrompt = systemPrompt + InstructionProtectionRule();
            _protectedCorpus = (!string.IsNullOrWhiteSpace(systemPromptOverride) ? systemPromptOverride : sysBase)
                             + InstructionProtectionRule();

            // ---- DOMAIN WISDOM (analysis paths only; independent of prefetch) ----
            if (_prefetchCtx != null && messages.Count > 0)
            {
                // v1.0.147.0: owner-mandated per-asset-type checklist rides with the wisdom
                // block (same injection point, same guard).
                // v1.0.160.57: build each block separately so the AUDIT can record what was actually
                // injected. Concatenating them inline made "did wisdom reach the model?" unanswerable.
                string _bChk = BuildAssetChecklist(_prefetchCtx);
                string _bFld = BuildFieldWisdom(_prefetchCtx);
                string _bDoc = BuildDoctrinalWisdom(_prefetchCtx);
                string _bCir = BuildCircuitWisdom(_prefetchCtx);
                _wisChecklist = CountRuleLines(_bChk); _wisField = CountRuleLines(_bFld);
                _wisDoctrinal = CountRuleLines(_bDoc); _wisCircuit = CountRuleLines(_bCir);
                // v1.0.160.117 CUT C: tag AFTER counting, so the existing counts are unchanged.
                _bChk = TagWisdomBlock(_bChk, "CHK"); _bFld = TagWisdomBlock(_bFld, "FLD");
                _bDoc = TagWisdomBlock(_bDoc, "DOC"); _bCir = TagWisdomBlock(_bCir, "CIR");
                string _chk = _bChk + _bFld + _bDoc + _bCir;   // v1.0.153.0: adopted field wisdom rides the same injection; v1.0.160.24: doctrinal reference appended (Item 9); v1.0.160.50: circuit topology + upstream causality appended
                // v1.0.160.59: bash purpose contract, injected only when bash is actually available
                // here. Advisory by nature -- the enforceable half is ScrubPlatformInternals.
                if (_bashInVerdict)
                {
                    _chk += "\n=== bash (available, " + _bashMaxCalls + " calls max) ===\n"
                          + "Use bash ONLY for computation or data queries that VERIFY telemetry -- for example "
                          + "checking whether raw samples exist in the store around the incidence. It is not a "
                          + "general shell for this analysis.\n"
                          + "NEVER quote, paste, summarise or characterise platform or hardware log content in "
                          + "the verdict. Those are internal operational logs and this verdict is read by railway "
                          + "maintainers. State any conclusion as a MEASURED FACT about the asset (e.g. 'no "
                          + "samples exist between 09:58 and 10:04'), never as a log excerpt or file path.\n";
                }
                if (!string.IsNullOrEmpty(_chk))
                {
                    JObject _cf = messages[0] as JObject;
                    if (_cf != null && _cf["content"] != null)
                    {
                        _cf["content"] = _cf["content"].ToString() + "\n\n" + _chk;
                    }
                }
                string _wis = BuildWisdomBlock(_prefetchCtx);
                _wisLearned = CountRuleLines(_wis);
                _wis = TagWisdomBlock(_wis, "LRN");
                _wisChars = (_chk == null ? 0 : _chk.Length) + (_wis == null ? 0 : _wis.Length);
                if (!string.IsNullOrEmpty(_wis))
                {
                    JObject _wf = messages[0] as JObject;
                    if (_wf != null && _wf["content"] != null)
                    {
                        _wf["content"] = _wf["content"].ToString() + "\n\n" + _wis;
                    }
                }
            }

            // ---- PRE-FETCH -------------------------------------------------
            if (_prefetch && _prefetchCtx != null && loaded.Tools.Count > 0)
            {
                string ev = null;
                try
                {
                    ev = await PrefetchEvidenceAsync(_prefetchCtx, loaded, ct).ConfigureAwait(false);
                }
                catch (ClientBusyException) { throw; }
                catch (OperationCanceledException) { if (ct.IsCancellationRequested) { throw; } }
                catch (Exception pex) { AiLogEx("PREFETCH", "failed; falling back to model-driven tools", pex); }

                if (!string.IsNullOrEmpty(ev) && messages.Count > 0)
                {
                    JObject first = messages[0] as JObject;
                    if (first != null && first["content"] != null)
                    {
                        first["content"] = first["content"].ToString() + "\n\n" + ev;
                    }
                }
            }

            // SYNTHESIS MODE. If pre-fetch already grounded the analysis, there is
            // nothing left for the model to fetch -- so send NO tools at all. That
            // removes the tool schemas (~2,000 tokens), removes the tool-use system
            // prompt the API injects alongside them, and makes a second turn
            // structurally impossible rather than merely discouraged. Three prompt
            // revisions failed to stop the model looping; taking the tools away
            // settles it.
            // Gated on _jsonGotHistory: without telemetry the model still needs the
            // ability to go and find it, and speed must not cost grounding.
            _synthesisMode = _prefetch && rawJsonMode && _prefetchComplete && _prefetchCtx != null;
            if (!_synthesisMode && _prefetch && _prefetchGap != null)
            {
                AiLog("INFO", "SYNTH", "staying agentic -- " + _prefetchGap);
            }
            if (_synthesisMode)
            {
                systemPrompt = AnalyzeSynthesisPrompt() + InstructionProtectionRule();   // v1.0.160.107 -- F7
                _protectedCorpus = AnalyzeSynthesisPrompt() + InstructionProtectionRule();
                AiLog("INFO", "SYNTH", "grounded by pre-fetch -- single call, no tools, compact prompt");
            }

            List<object> workMessages = TrimHistory(messages, _maxHistory).Cast<object>().ToList();
            // Verdict mode permits 9 tools but was sending all 22 schemas to the
            // model on EVERY turn: wasted input tokens twice per analysis, and it
            // invited calls to forbidden tools that were then denied, burning a
            // whole turn. Send only what is actually callable.
            // Applied on BOTH paths now. The streaming popup was shipping all 28
            // schemas on every turn (measured: 9 turns x 28 schemas), which cost
            // tokens and invited calls to tools that cannot help a verdict.
            JArray toolsForModel = loaded.Tools;
            {
                JArray permitted = new JArray();
                foreach (JToken tool in loaded.Tools)
                {
                    string tn = tool["name"] != null ? tool["name"].ToString() : "";
                    if (_jsonToolCaps.ContainsKey(tn)) { permitted.Add(tool); }
                    // v1.0.160.40 (D1 fix): bash is FREE-CHAT only. _jsonCapture alone was the wrong
                    // signal -- it is set only by the JSON-verdict helper, so the STREAMING AnalyzeAlert
                    // path (rawJsonMode:true, validateVerdictOutput:true) left it null and would have
                    // exposed bash to the automated verdict loop. Gate on the loop's own intent flags:
                    // Chat() and AnalyzeChat() (operator follow-up) pass both false -> bash allowed;
                    // both verdict paths pass rawJsonMode:true -> bash withheld.
                    // v1.0.160.60: bash is a TOOL, so it follows the owner rule -- site-keeping users
                    // and the config emails only. It had NO role check before, and the follow-up chat
                    // box is open to every authenticated user, so an ordinary railway user could have
                    // reached platform log content through a follow-up question.
                    // v1.0.160.191: also withhold bash from a GROUNDED alert follow-up chat
                    // (systemPromptOverride set = alert context injected). It wastes steps re-probing
                    // when the card+logic are already in front of the model. Pure free-chat
                    // (no grounding, systemPromptOverride == null) is unchanged.
                    else if (!rawJsonMode && !validateVerdictOutput && _jsonCapture == null
                             && systemPromptOverride == null
                             && AiDebugAllowed()
                             && string.Equals(tn, "bash", StringComparison.OrdinalIgnoreCase)) { permitted.Add(tool); }
                    // v1.0.160.59: bash during ANALYSIS too, when explicitly enabled. Owner ruled BOTH
                    // paths (streaming and the unattended JSON batch), so this does not test the
                    // verdict-intent flags -- the flag itself is the decision.
                    else if (_bashInVerdict && AiDebugAllowed()
                             && string.Equals(tn, "bash", StringComparison.OrdinalIgnoreCase)) { permitted.Add(tool); }
                }
                if (permitted.Count > 0) { toolsForModel = permitted; }
            }

            // empty array => AnthropicClient omits "tools" from the request entirely
            object[] toolsArray = _synthesisMode ? new object[0] : toolsForModel.ToObject<object[]>();

            // v1.0.89.0: cache diagnostics. cache_read/write were 0 on single-turn
            // synthesis runs; this records the facts that decide WHY, so a run tells us
            // instead of guessing: the cached-prefix token estimate (Anthropic requires
            // >=1024 tokens to cache at all), whether tools are present (the ~2k tool
            // schema block is the main thing worth caching; synthesis mode drops it),
            // the synthesis flag, and whether the estimated prefix clears the minimum.
            if (_promptCache)
            {
                int sysTokEst = EstimateTokens(new List<object>(), systemPrompt);
                int toolTokEst = 0;
                if (toolsArray != null && toolsArray.Length > 0)
                {
                    try { toolTokEst = Encoding.UTF8.GetByteCount(JsonConvert.SerializeObject(toolsArray)) / 4; }
                    catch { toolTokEst = 0; }
                }
                int cachedPrefixEst = sysTokEst + toolTokEst;
                AiLog("INFO", "CACHE", "prefix diag: systemTok~" + sysTokEst
                    + " toolsTok~" + toolTokEst + " (tools=" + (toolsArray == null ? 0 : toolsArray.Length) + ")"
                    + " cachedPrefixTok~" + cachedPrefixEst
                    + " synthesis=" + _synthesisMode
                    + " meetsAnthropic1024min=" + (cachedPrefixEst >= 1024 ? "yes" : "NO -> Anthropic will not cache")
                    + (_synthesisMode ? " NOTE: synthesis drops the tool block, so only the compact system prompt is cacheable" : ""));
            }

            // v1.0.160.194: chat is bounded by a higher backstop + progress guard; analyze keeps
            // _maxIter. Kill-switch: when _chatLoopGuard is false, loopCap == _maxIter and every
            // guard branch below is gated off -- chat behaves exactly as 1.0.160.193.
            int loopCap = rawJsonMode || !_chatLoopGuard ? _maxIter : _chatMaxIter;
            bool chatForceAnswer = false;
            HashSet<string> chatToolSigs = new HashSet<string>();
            System.Diagnostics.Stopwatch chatWall = System.Diagnostics.Stopwatch.StartNew();
            for (int iter = 0; iter < loopCap; iter++)
            {
                ct.ThrowIfCancellationRequested();
                // v1.0.160.194: on the last permitted chat turn, or once the wall budget is spent,
                // force a tool-less answer turn so the loop ends on a reply, never a dead step-limit line.
                if (!rawJsonMode && _chatLoopGuard
                    && (iter == loopCap - 1 || chatWall.Elapsed.TotalSeconds >= _chatMaxWallSec))
                {
                    chatForceAnswer = true;
                }
                int est = EstimateTokens(workMessages, systemPrompt);
                if (est > _warnTokens)
                    System.Diagnostics.Trace.TraceWarning("[AiChat] est_tokens=" + est);

                // MUST be initialised: the finally below reads it to record recvBytes,
                // and a finally can run before the assignment completes -- an
                // uninitialised local there is a definite-assignment error (CS0165).
                string raw = null;
                // exact bytes on the wire for THIS turn (system + messages + tools)
                long _sentBytes = 0;
                if (_traceDeep && _traceActive)
                {
                    try
                    {
                        _sentBytes = Encoding.UTF8.GetByteCount(systemPrompt ?? "")
                                   + Encoding.UTF8.GetByteCount(JsonConvert.SerializeObject(workMessages))
                                   + Encoding.UTF8.GetByteCount(JsonConvert.SerializeObject(toolsArray));
                    }
                    catch { _sentBytes = -1; }
                }
                WriteSse("step", new { phase = "model_start", iter = iter, engine = _engineName1 });
                System.Diagnostics.Stopwatch _swModel = System.Diagnostics.Stopwatch.StartNew();
                try
                {
                    try
                    {
                        // v1.0.160.194: a forced-answer chat turn sends NO tools, so the model must
                        // synthesize a reply from what it already gathered (same as synthesis mode, 19323).
                        object[] turnTools = !rawJsonMode && chatForceAnswer ? new object[0] : toolsArray;
                        raw = await AwaitWithCancel(
                            WithClientLock(_aiLock, () => CallModelAsync(workMessages.ToArray(), turnTools, systemPrompt), ct, _jsonCapture != null), ct)
                            .ConfigureAwait(false);
                    }
                    finally
                    {
                        // failed/cancelled turns still contribute elapsed time
                        _swModel.Stop();
                        if (_traceActive)
                        {
                            _trTurns++; _trAnalysisTurns++; _trModelMs += _swModel.ElapsedMilliseconds;
                            _trBytesSent += (_sentBytes > 0 ? _sentBytes : 0);
                            long _recvBytes = string.IsNullOrEmpty(raw) ? 0 : Encoding.UTF8.GetByteCount(raw);
                            _trBytesRecv += _recvBytes;

                            JObject mt = new JObject();
                            mt["iter"] = iter;
                            mt["ms"] = _swModel.ElapsedMilliseconds;
                            mt["sentBytes"] = _sentBytes;
                            mt["recvBytes"] = _recvBytes;
                            mt["estTokensIn"] = est;
                            mt["msgCount"] = workMessages.Count;
                            mt["toolSchemas"] = toolsArray == null ? 0 : toolsArray.Length;
                            // REAL token usage from the model reply beats any estimate
                            JObject u = ReadUsage(raw);
                            if (u != null)
                            {
                                mt["usage"] = u;
                                _trTokIn += ReadLong(u, "input_tokens");
                                _trTokOut += ReadLong(u, "output_tokens");
                                _trTokCacheRead += ReadLong(u, "cache_read_input_tokens");
                                _trTokCacheWrite += ReadLong(u, "cache_creation_input_tokens");
                            }
                            TraceAnalyze("model_turn", mt);
                        }
                        WriteSse("step", new
                        {
                            phase = "model_done",
                            iter = iter,
                            ms = _swModel.ElapsedMilliseconds,
                            tokIn = _trTokIn,
                            tokOut = _trTokOut
                        });
                    }
                }
                catch (AnthropicRateLimitException)
                {
                    WriteSse("error", new { message = "Rate limit. Wait ~60s." });
                    return;
                }
                catch (AnthropicAuthException)
                {
                    WriteSse("error", new { message = "AI auth failed." });
                    return;
                }

                JObject resp = JObject.Parse(raw);
                string stopReason = resp["stop_reason"] != null ? resp["stop_reason"].ToString() : "";
                JArray content = resp["content"] as JArray;
                if (content == null) content = new JArray();

                List<JToken> toolUseBlocks = new List<JToken>();
                List<JToken> textBlocks = new List<JToken>();
                foreach (JToken block in content)
                {
                    string t = block["type"] != null ? block["type"].ToString() : "";
                    if (t == "tool_use") toolUseBlocks.Add(block);
                    if (t == "text") textBlocks.Add(block);
                }

                // ── TOOL USE ──
                if (stopReason == "tool_use" && toolUseBlocks.Count > 0)
                {
                    foreach (JToken block in toolUseBlocks)
                    {
                        string toolName = block["name"] != null ? block["name"].ToString() : "";
                        int owner = ownerOf(toolName);
                        WriteSse("tool_use", new { name = toolName + " \u00b7 " + EngineName(owner) });
                    }

                    workMessages.Add(new { role = "assistant", content = content });

                    List<object> toolResults = new List<object>();
                    if (_jsonCapture != null)
                    {
                        // verdict mode: permit + clamp first, then execute in
                        // parallel chunks (<=4); ALL side-effects (logs, counters,
                        // results) are applied sequentially after the join, so
                        // LogToolEvent and the counters stay single-threaded.
                        List<JObject> execs = new List<JObject>();
                        foreach (JToken block in toolUseBlocks)
                        {
                            string toolName = block["name"] != null ? block["name"].ToString() : "";
                            string toolId = block["id"] != null ? block["id"].ToString() : "";
                            JToken toolArgs = block["input"];
                            int owner = ownerOf(toolName);
                            ct.ThrowIfCancellationRequested();
                            string denyReason;
                            if (!JsonToolPermitted(toolName, out denyReason))
                            {
                                LogToolEvent(conversationId, "denied", iter, toolId, toolName, owner, toolArgs, denyReason, null, 0);
                                AiLog("WARN", "TOOL", "denied " + toolName + " -- " + denyReason);
                                toolResults.Add(new { type = "tool_result", tool_use_id = toolId, content = denyReason });
                                continue;
                            }
                            string already = PrefetchAlreadyHas(toolName, toolArgs as JObject);
                            if (already != null)
                            {
                                LogToolEvent(conversationId, "denied", iter, toolId, toolName, owner, toolArgs, already, null, 0);
                                AiLog("INFO", "TOOL", "skipped " + toolName + " -- already pre-fetched");
                                toolResults.Add(new { type = "tool_result", tool_use_id = toolId, content = already });
                                continue;
                            }
                            // v1.0.160.194: chat progress guard. A repeated identical call to a
                            // read-only lookup is thrashing, not progress -- skip the re-run, tell the
                            // model it already has that result, and force the next turn to answer with
                            // no tools. Scoped to IsRepeatGuardTool (search_tags) so a tool that may
                            // legitimately refresh live data is never blocked; widen only after testing.
                            if (!rawJsonMode && _chatLoopGuard && IsRepeatGuardTool(toolName))
                            {
                                string callSig = toolName + "|"
                                    + (toolArgs != null ? toolArgs.ToString(Newtonsoft.Json.Formatting.None) : "");
                                if (!chatToolSigs.Add(callSig))
                                {
                                    string repeatNote = "You already ran '" + toolName
                                        + "' with these arguments; the result is already available above."
                                        + " Do not repeat the tool. Answer the user's question from the"
                                        + " evidence already gathered.";
                                    LogToolEvent(conversationId, "denied", iter, toolId, toolName, owner, toolArgs, "repeat call -- chat progress guard", null, 0);
                                    AiLog("INFO", "TOOL", "chat repeat blocked: " + toolName);
                                    toolResults.Add(new { type = "tool_result", tool_use_id = toolId, content = repeatNote });
                                    chatForceAnswer = true;
                                    continue;
                                }
                            }
                            string zeroId = ZeroIdentifier(toolArgs);
                            if (zeroId != null)
                            {
                                denyReason = "Refused: '" + toolName + "' was called with " + zeroId
                                    + "=0, which identifies nothing. Resolve the real id first "
                                    + "(search_assets for AssetId, get_asset_tags for TagId). If it cannot "
                                    + "be resolved, say so and return INCONCLUSIVE - do not call with zeros.";
                                LogToolEvent(conversationId, "denied", iter, toolId, toolName, owner, toolArgs, denyReason, null, 0);
                                AiLog("WARN", "TOOL", "refused " + toolName + " with " + zeroId + "=0");
                                toolResults.Add(new { type = "tool_result", tool_use_id = toolId, content = denyReason });
                                continue;
                            }
                            if (loaded.OwnerMap == null || !loaded.OwnerMap.ContainsKey(toolName))
                            {
                                // verdict mode never falls back to shared routing state:
                                // the tool must exist in THIS request's discovery snapshot
                                denyReason = "Tool '" + toolName + "' is not in this request's discovered toolset.";
                                LogToolEvent(conversationId, "denied", iter, toolId, toolName, owner, toolArgs, denyReason, null, 0);
                                toolResults.Add(new { type = "tool_result", tool_use_id = toolId, content = denyReason });
                                continue;
                            }
                            HashSet<string> declaredArgs = null;
                            if (loaded.ArgMap != null && loaded.ArgMap.ContainsKey(toolName)) { declaredArgs = loaded.ArgMap[toolName]; }
                            toolArgs = ClampToolArgs(toolName, toolArgs, declaredArgs); // mechanical cost bound
                            CollectAssetHints(toolArgs);
                            LogToolEvent(conversationId, "requested", iter, toolId, toolName, owner, toolArgs, null, null, -1);
                            JObject e0 = new JObject();
                            e0["toolName"] = toolName; e0["toolId"] = toolId; e0["owner"] = owner; e0["args"] = toolArgs;
                            execs.Add(e0);
                        }
                        int chunkSize = _jsonParallelTools ? _jsonMaxChunk : 1; // parallel OFF by default until client thread-safety is certified
                        for (int c0 = 0; c0 < execs.Count; c0 += chunkSize)
                        {
                            int cN = Math.Min(chunkSize, execs.Count - c0);
                            Task<string>[] tasks = new Task<string>[cN];
                            System.Diagnostics.Stopwatch swAll = System.Diagnostics.Stopwatch.StartNew();
                            for (int k = 0; k < cN; k++)
                            {
                                JObject e0 = execs[c0 + k];
                                // children carry NO token: the outer WhenAll wrapper owns
                                // cancellation AND the abandonment weight (no double count)
                                tasks[k] = CallToolRoutedAsync(e0["toolName"].ToString(), e0["args"], System.Threading.CancellationToken.None, (int)e0["owner"]);
                            }
                            try
                            {
                                await AwaitWithCancel((Task)Task.WhenAll(tasks), ct, cN).ConfigureAwait(false);
                            }
                            catch (OperationCanceledException)
                            {
                                if (ct.IsCancellationRequested) { throw; } // our cancel: in-flight chunk drains, observed
                            }
                            catch { /* individual faults handled per task below */ }
                            finally
                            {
                                swAll.Stop();
                                if (_traceActive)
                                {
                                    _trToolMs += swAll.ElapsedMilliseconds;
                                    // v1.0.160.110 SL5: in-loop WALL-CLOCK, kept separate from the
                                    // summed per-call figure so total can be reconciled honestly.
                                    _trInLoopWallMs += swAll.ElapsedMilliseconds;
                                }
                            }
                            // lock contention is an ENDPOINT condition (503 busy), not a
                            // per-tool failure: surface it instead of burying it in a
                            // tool_result. Previously WhenAll faults were swallowed and
                            // ClientBusyException became "internal error".
                            for (int k = 0; k < cN; k++)
                            {
                                AggregateException tag = tasks[k].Exception;
                                if (tag != null && tag.GetBaseException() is ClientBusyException) { throw tag.GetBaseException(); }
                            }
                            for (int k = 0; k < cN; k++)
                            {
                                JObject e0 = execs[c0 + k];
                                string toolName = e0["toolName"].ToString();
                                string toolId = e0["toolId"].ToString();
                                int owner = (int)e0["owner"];
                                JToken toolArgs = e0["args"];
                                string result;
                                Task<string> tk = tasks[k];
                                if (tk.Status == TaskStatus.RanToCompletion)
                                {
                                    string rawResult = tk.Result;
                                    result = NarrowAttributeRange(toolName, rawResult);
                                    bool usable = LooksUsableToolResult(result, IsEvidenceTool(toolName));
                                    if (_traceActive)
                                    {
                                        long rawLen = rawResult == null ? 0 : rawResult.Length;
                                        long keptLen = result == null ? 0 : result.Length;
                                        _trToolCallCount++;
                                        _trToolBytes += rawLen;
                                        _trToolBytesKept += keptLen;
                                        JObject tc = new JObject();
                                        tc["tool"] = toolName;
                                        tc["server"] = "srv" + owner;
                                        tc["iter"] = iter;
                                        tc["ms"] = swAll.ElapsedMilliseconds;
                                        tc["argsBytes"] = toolArgs == null ? 0
                                            : Encoding.UTF8.GetByteCount(toolArgs.ToString(Formatting.None));
                                        tc["resultChars"] = rawLen;
                                        tc["keptChars"] = keptLen;
                                        tc["narrowed"] = keptLen != rawLen;
                                        tc["truncatedInTransit"] = rawResult != null && _truncMarker.IsMatch(rawResult);
                                        tc["usable"] = usable;
                                        tc["evidenceClass"] = IsEvidenceTool(toolName);
                                        tc["historyClass"] = IsHistoryFamily(toolName);
                                        if (!usable) { tc["rejectReason"] = RejectReason(result, IsEvidenceTool(toolName)); }
                                        try { tc["args"] = CloneAndRedact(toolArgs); } catch { }
                                        TraceAnalyze("tool_call", tc);
                                        if (rawResult != null && _truncMarker.IsMatch(rawResult))
                                        {
                                            AiLog("WARN", "TOOL", toolName + " TRUNCATED in transit at "
                                                + rawLen + " chars -- narrow the query");
                                        }
                                        if (keptLen != rawLen)
                                        {
                                            AiLog("INFO", "TOOL", toolName + " narrowed " + rawLen + " -> " + keptLen + " chars");
                                        }
                                        if (!usable)
                                        {
                                            AiLog("WARN", "TOOL", toolName + " UNUSABLE (" + rawLen + "ch) "
                                                + RejectReason(result, IsEvidenceTool(toolName)));
                                        }
                                    }
                                    if (_jsonToolTrace != null && _jsonToolTrace.Count < 20)
                                    {
                                        string entry = toolName + (usable ? ":ok(" : ":UNUSABLE(")
                                            + (result == null ? "null" : result.Length + "ch") + ")";
                                        if (!usable)
                                        {
                                            entry += " [" + RejectReason(result, IsEvidenceTool(toolName)) + "] >>"
                                                + TracePreview(result);
                                        }
                                        _jsonToolTrace.Add(entry);
                                    }
                                    if (usable)
                                    {
                                        _jsonToolOk++;
                                        if (IsEvidenceTool(toolName)) { _jsonGotEvidence = true; }
                                        // v1.0.76.0: a successful model-issued search_tags is the
                                        // ONLY route to a presumed alerting tag, resolved mechanically.
                                        if (string.Equals(toolName, "search_tags", StringComparison.OrdinalIgnoreCase))
                                        {
                                            TryResolveAlertingTagFromSearch(result);
                                        }
                                        if (IsHistoryFamily(toolName))
                                        {
                                            _jsonGotHistory = true;
                                            if (_jsonEvidenceArgs == null)
                                            {
                                                try
                                                {
                                                    JObject ev = new JObject();
                                                    // identity FIRST: truncation must never drop the hash
                                                    ev["resultSha"] = ShortHash(result);
                                                    ev["resultLen"] = result == null ? 0 : result.Length;
                                                    ev["tool"] = toolName;
                                                    ev["server"] = "srv" + owner;
                                                    ev["args"] = LimitForLog(CloneAndRedact(toolArgs).ToString(Formatting.None), 400);
                                                    _jsonEvidenceArgs = LimitForLog(ev.ToString(Formatting.None), 900);
                                                }
                                                catch { }
                                            }
                                        }
                                    }
                                    LogToolEvent(conversationId, "response", iter, toolId, toolName, owner, toolArgs, result, null, swAll.ElapsedMilliseconds);
                                    RecordToolTiming(toolName, toolArgs, result, iter, swAll.ElapsedMilliseconds);
                                    // v1.0.75.0: coverage stamps are only readable for the true series
                                    // tool. analyse_alert/get_hist_realtime stay in _jsonHistoryFamily
                                    // for grounding, but their report shapes carry no series to verify.
                                    if (usable && IsCoverageCheckedTool(toolName))
                                    {
                                        string cov = HistoryCoverageNote(result, HistoryTagFromArgs(toolArgs as JObject));
                                        if (cov != null)
                                        {
                                            result = result + "\n" + cov;
                                            AddDiag("HISTORY_SHORT");
                                            AiLog("WARN", "TOOL", toolName + " " + cov);
                                        }
                                    }
                                    if (!usable)
                                    {
                                        // verdict mode: unusable/error payloads (which may embed raw
                                        // backend text from the MCP dispatcher) never reach the model
                                        result = IsOptionalEnrichment(toolName)
                                            ? "Optional enrichment '" + toolName + "' is unavailable this cycle. "
                                              + "It is supplementary only: the verdict does not depend on it. "
                                              + "Do NOT mention it in caveats or evidence -- an unavailable "
                                              + "optional source is not a limitation of this analysis."
                                            : "Tool '" + toolName + "' returned no usable data.";
                                    }
                                }
                                else
                                {
                                    Exception tex = tk.Exception != null ? tk.Exception.GetBaseException() : null;
                                    if (tk.IsCanceled || (tex is OperationCanceledException && !ct.IsCancellationRequested))
                                    {
                                        result = "Tool '" + toolName + "' failed: timeout"; // cancelled/timed-out child
                                    }
                                    else
                                    {
                                        result = "Tool '" + toolName + "' failed: " + SanitizeToolFailure(tex);
                                    }
                                    if (_jsonToolTrace != null && _jsonToolTrace.Count < 20) { _jsonToolTrace.Add(toolName + ":FAIL"); }
                                    AiLogEx("TOOL", "call failed " + toolName + " (srv" + owner + ")", tex);
                                    LogToolEvent(conversationId, "error", iter, toolId, toolName, owner, toolArgs, result, tex, swAll.ElapsedMilliseconds);
                                }
                                toolResults.Add(new { type = "tool_result", tool_use_id = toolId, content = result });
                            }
                        }
                    }
                    else
                    {
                        foreach (JToken block in toolUseBlocks)
                        {
                            string toolName = block["name"] != null ? block["name"].ToString() : "";
                            string toolId = block["id"] != null ? block["id"].ToString() : "";
                            JToken toolArgs = block["input"];
                            int owner = ownerOf(toolName);

                            ct.ThrowIfCancellationRequested();

                            // ---- same policy as the verdict path ----
                            string sseDeny = null;
                            if (_jsonToolUsed != null && !JsonToolPermitted(toolName, out sseDeny)) { }
                            string sseAlready = PrefetchAlreadyHas(toolName, toolArgs as JObject);
                            if (sseAlready != null) { sseDeny = sseAlready; }
                            string sseZero = ZeroIdentifier(toolArgs);
                            if (sseZero != null)
                            {
                                sseDeny = "Refused: '" + toolName + "' was called with " + sseZero
                                    + "=0, which identifies nothing. Resolve the real id first.";
                            }
                            if (sseDeny != null)
                            {
                                AiLog("WARN", "TOOL", "denied " + toolName + " -- " + sseDeny);
                                LogToolEvent(conversationId, "denied", iter, toolId, toolName, owner, toolArgs, sseDeny, null, 0);
                                WriteSse("step", new { phase = "tool_done", name = toolName,
                                                       engine = EngineName(owner), ms = 0, chars = 0, ok = false });
                                toolResults.Add(new { type = "tool_result", tool_use_id = toolId, content = sseDeny });
                                continue;
                            }
                            HashSet<string> sseDeclared = null;
                            if (loaded.ArgMap != null && loaded.ArgMap.ContainsKey(toolName)) { sseDeclared = loaded.ArgMap[toolName]; }
                            toolArgs = ClampToolArgs(toolName, toolArgs, sseDeclared);
                            CollectAssetHints(toolArgs);

                            LogToolEvent(
                                conversationId,
                                "requested",
                                iter,
                                toolId,
                                toolName,
                                owner,
                                toolArgs,
                                null,
                                null,
                                -1);

                            string result;
                            System.Diagnostics.Stopwatch sw = System.Diagnostics.Stopwatch.StartNew();
                            try
                            {
                                string sseRaw = await CallToolRoutedAsync(toolName, toolArgs, ct, owner)
                                    .ConfigureAwait(false);
                                sw.Stop();
                                result = NarrowAttributeRange(toolName, sseRaw);
                                bool sseUsable = LooksUsableToolResult(result, IsEvidenceTool(toolName));
                                // v1.0.76.0: same mechanical resolution as the JSON path.
                                if (sseUsable && string.Equals(toolName, "search_tags", StringComparison.OrdinalIgnoreCase))
                                {
                                    TryResolveAlertingTagFromSearch(result);
                                }
                                if (sseUsable && IsCoverageCheckedTool(toolName))
                                {
                                    string cov = HistoryCoverageNote(result, HistoryTagFromArgs(toolArgs as JObject));
                                    if (cov != null) { result = result + "\n" + cov; AiLog("WARN", "TOOL", toolName + " " + cov); }
                                }
                                if (!sseUsable)
                                {
                                    AiLog("WARN", "TOOL", toolName + " UNUSABLE (" + (sseRaw == null ? 0 : sseRaw.Length)
                                        + "ch) " + RejectReason(result, IsEvidenceTool(toolName)));
                                    result = IsOptionalEnrichment(toolName)
                                        ? "Optional enrichment '" + toolName + "' is unavailable this cycle. "
                                          + "It is supplementary only; do not treat its absence as a limitation."
                                        : "Tool '" + toolName + "' returned no usable data.";
                                }
                                LogToolEvent(
                                    conversationId,
                                    "response",
                                    iter,
                                    toolId,
                                    toolName,
                                    owner,
                                    toolArgs,
                                    result,
                                    null,
                                    sw.ElapsedMilliseconds);
                            }
                            catch (OperationCanceledException)
                            {
                                if (ct.IsCancellationRequested) { throw; } // our cancel only
                                sw.Stop();
                                result = "Tool '" + toolName + "' failed: timeout"; // recoverable (rev2 parity)

                                LogToolEvent(
                                    conversationId,
                                    "error",
                                    iter,
                                    toolId,
                                    toolName,
                                    owner,
                                    toolArgs,
                                    result,
                                    null,
                                    sw.ElapsedMilliseconds);
                            }
                            catch (ClientBusyException) { throw; } // surfaces as HTTP 503 busy
                            catch (Exception ex)
                            {
                                sw.Stop();
                                result = "Tool '" + toolName + "' failed: " + SanitizeToolFailure(ex);

                                LogToolEvent(
                                    conversationId,
                                    "error",
                                    iter,
                                    toolId,
                                    toolName,
                                    owner,
                                    toolArgs,
                                    result,
                                    ex,
                                    sw.ElapsedMilliseconds);
                            }

                            // Streaming path only: the popup renders these into the live
                            // progress trail. Verdict mode captures instead of streaming,
                            // so emitting there would be a no-op.
                            WriteSse("step", new
                            {
                                phase = "tool_done",
                                name = toolName,
                                engine = EngineName(owner),
                                ms = sw.ElapsedMilliseconds,
                                chars = result == null ? 0 : result.Length,
                                ok = !result.StartsWith("Tool '", StringComparison.Ordinal)
                                     && !result.StartsWith("Refused:", StringComparison.Ordinal)
                                     && !result.StartsWith("Optional enrichment", StringComparison.Ordinal)
                            });

                            toolResults.Add(new
                            {
                                type = "tool_result",
                                tool_use_id = toolId,
                                content = result
                            });
                        }

                    }

                    workMessages.Add(new { role = "user", content = toolResults });
                    continue;
                }

                // ── TEXT ──
                if (textBlocks.Count > 0)
                {
                    StringBuilder sb = new StringBuilder();
                    foreach (JToken b in textBlocks)
                        if (b["text"] != null) sb.Append(b["text"].ToString());

                    // v1.0.160.60: scrub the CHAT/FOLLOW-UP prose too. rawJsonMode is JSON and is
                    // sanitised field-by-field later; this branch is the reply a user reads, and
                    // it is where bash output would land if it were pasted into an answer.
                    string fullText = rawJsonMode ? sb.ToString()
                        : ScrubPlatformInternals(FilterOperationalActions(sb.ToString()), "chat");
                    if (_assistantCapture != null) { try { _assistantCapture.Append(fullText); } catch { } }   // v1.0.133.0

                // SAFETY. rawJsonMode skips FilterOperationalActions because the text is
                // JSON, and the popup then parsed that JSON in the browser -- so the
                // operator-visible path applied NONE of the verdict contract: no
                // movement-directive filter, no category check, no numeric validation,
                // no word limits, no unknown-field stripping. Those ran only on the
                // service endpoint. Validate here (validateVerdictOutput, NOT rawJsonMode
                // -- AnalyzeChat also sends rawJsonMode=true but is prose, never a verdict)
                // and emit the sanitised object as its own frame; the client prefers it
                // over anything it parsed itself.
                if (validateVerdictOutput && _jsonCapture == null && !string.IsNullOrWhiteSpace(fullText))
                {
                    JObject vObj = null;
                    try { vObj = JObject.Parse(fullText.Trim()); }
                    catch { vObj = ExtractFirstJsonObject(fullText); }

                    if (vObj != null)
                    {
                        string vReason;
                        if (ValidateAndSanitizeVerdict(vObj, out vReason))
                        {
                            // v1.0.111.0: attach server-computed derived_inputs on the popup path
                            // too - suppressed on INCONCLUSIVE / inadequate coverage.
                            if (ShouldAttachDerivedInputs(vObj)) { vObj["derived_inputs"] = _derivedInputs; }
                            // v1.0.111.0: attach server-VERIFIED triage (computed from the parsed
                            // same-asset/same-cause alert history), also suppressed on INCONCLUSIVE.
                            AttachTriageIfEligible(vObj);
                            if (_weatherCard != null) { vObj["weather"] = _weatherCard; }   // v1.0.119.0
                            if (_trainContext != null) { vObj["train_context"] = _trainContext; }   // v1.0.160.33
                            // v1.0.108.0 / hardened 1.0.111.0: bilingual on the popup path. vObj is
                            // sanitized; AttachHinglishAsync now runs under the AI lock with its own
                            // timeout+cancellation and records its tokens. Best-effort - a failure
                            // leaves the English verdict frame unchanged.
                            if (_bilingualHindi)
                            {
                                try { await AttachHinglishAsync(vObj, ct).ConfigureAwait(false); }
                                catch (Exception exTrP) { AiLog("WARN", "HI", "popup hinglish translate failed (English unaffected): " + SanitizeJsonError(exTrP.Message)); }
                            }
                            // v1.0.160.113: the POPUP is fed by SSE, not by the JSON envelope, so
                            // context_patch / asset_condition / snapshot must be emitted HERE too --
                            // adding them only to env (AnalyzeAlertJson) left the view with nothing
                            // to render, which is exactly the transport mismatch to avoid.
                            try
                            {
                                if (_prefetchCtx != null)
                                {
                                    JObject _pp = new JObject();
                                    string _st = GetCtx(_prefetchCtx, "station");
                                    string _at = GetCtx(_prefetchCtx, "assetType");
                                    if (_st.Length > 0) { _pp["station"] = _st; }
                                    if (_at.Length > 0) { _pp["assetType"] = _at; }
                                    // v1.0.160.130: the SSE path is the one the POPUP reads. Adding
                                    // resetTime only to the JSON envelope would leave the banner
                                    // exactly as wrong as before -- the same transport mismatch.
                                    string _rs = GetCtx(_prefetchCtx, "resetTime");
                                    if (_rs.Length > 0) { _pp["resetTime"] = _rs; }
                                    if (_pp.Count > 0) { WriteSse("context_patch", new { patch = _pp }); }
                                }
                                JObject _ac = BuildAssetCondition();
                                if (_ac != null) { WriteSse("asset_condition", new { condition = _ac }); }
                                if (_snapshotRetrievedAt != DateTime.MinValue)
                                {
                                    JObject _sn = new JObject();
                                    _sn["retrievedAt"] = _snapshotRetrievedAt.ToString("dd/MM/yyyy HH:mm:ss");
                                    DateTime _incS;
                                    if (_prefetchCtx != null && TryParseAlertTime(GetCtx(_prefetchCtx, "time"), out _incS))
                                    { _sn["ageFromIncidenceSec"] = (long)(_snapshotRetrievedAt - _incS).TotalSeconds; }
                                    if (_snapshotValues != null && _snapshotValues.Count > 0) { _sn["values"] = _snapshotValues; }
                                    WriteSse("snapshot", new { snapshot = _sn });
                                }
                                // v1.0.160.176: point machine -> fetch v4 analysis SERVER-SIDE and
                                // stream it as a 'pm' event (server->server, so no browser CORS /
                                // mixed-content). The view sets window._aiPm and renders the PM tab.
                                // Best-effort: a failure here never breaks the verdict stream.
                                try
                                {
                                    string _pmType = GetCtx(_prefetchCtx, "assetType") ?? "";
                                    string _pmAid = GetCtx(_prefetchCtx, "assetId");
                                    if (_pmType.ToUpperInvariant().Contains("POINT") && !string.IsNullOrEmpty(_pmAid))
                                    {
                                        string _pmSid = GetCtx(_prefetchCtx, "siteId");
                                        string _pmUrl = "http://172.31.25.102:8005/api/asset/ai-prediction/pm-operation-v4/"
                                                      + (string.IsNullOrEmpty(_pmSid) ? "" : _pmSid + "/") + _pmAid;
                                        // v1.0.160.178: log this server-side fetch to the MCP/tool log
                                        // (ai-tool jsonl) via LogToolEvent -- success and failure both land
                                        // there as a 'pm-operation-v4' entry with latency + error, so a
                                        // silent bind failure is diagnosable.
                                        string _pmConv = string.IsNullOrEmpty(_traceId) ? "prefetch" : _traceId;
                                        JObject _pmArgs = new JObject(); _pmArgs["url"] = _pmUrl;
                                        System.Diagnostics.Stopwatch _pmSw = System.Diagnostics.Stopwatch.StartNew();
                                        try
                                        {
                                            using (System.Net.Http.HttpClient _pmHc = new System.Net.Http.HttpClient())
                                            {
                                                _pmHc.Timeout = TimeSpan.FromSeconds(60);
                                                string _pmRes = await _pmHc.GetStringAsync(_pmUrl).ConfigureAwait(false);
                                                JObject _pmObj = JObject.Parse(_pmRes);
                                                if (_pmObj["a"] is JObject _pmA) { _pmA.Remove("ops"); }
                                                if (_pmObj["b"] is JObject _pmB) { _pmB.Remove("ops"); }
                                                _pmSw.Stop();
                                                LogToolEvent(_pmConv, "response", -1, "pm-v4", "pm-operation-v4", 0, _pmArgs, _pmObj.ToString(), null, _pmSw.ElapsedMilliseconds);
                                                WriteSse("pm", new { pm = _pmObj });
                                            }
                                        }
                                        catch (Exception _pmEx)
                                        {
                                            _pmSw.Stop();
                                            LogToolEvent(_pmConv, "error", -1, "pm-v4", "pm-operation-v4", 0, _pmArgs, null, _pmEx, _pmSw.ElapsedMilliseconds);
                                        }
                                    }
                                }
                                catch { }
                            }
                            catch { }
                            // v1.0.160.154: attach the asset-history summary so the story's pie
                            // chapter renders from the verdict itself -- including on REUSED opens,
                            // because the .149 store copies vObj.
                            if (_assetHistory != null)
                            {
                                try
                                {
                                    vObj["asset_history"] = _assetHistory;
                                }
                                catch { }
                            }
                            // v1.0.160.153: a verdict produced while the E7 API was failing is
                            // stamped BEFORE emit and store, so the browser, the diagnostic download
                            // and the cache row all carry the same mark. TryServeFromCache refuses
                            // rows carrying it (541980: the degraded row said NOT_CONFIRMED 72, the
                            // healthy re-run said CONFIRMED 82).
                            if (_e7ApiInputFailed)
                            {
                                try
                                {
                                    vObj["degraded_inputs"] = true;
                                    vObj["degraded_note"] = "Analysed while the E7 API was failing"
                                        + " (403 / session expired): envelopes, FRS row and range"
                                        + " history were unavailable, so evidence is reduced."
                                        + " Re-run once upstream is healthy.";
                                }
                                catch { }
                            }
                            WriteSse("verdict", new { verdict = vObj });
                            // v1.0.160.144: store the FULL verdict for the cache, here, where vObj
                            // is in scope. .141 stored _lastVerdictSummary instead -- four fields
                            // (verdict/confidence/category/headline) and nothing else -- so a served
                            // row rendered INCONCLUSIVE 0% with every field blank. The log said it
                            // outright: "payload (364 chars)". What is written must be what the
                            // browser was sent, or a reused verdict is not the same verdict.
                            // v1.0.160.149: store EVERYTHING the fresh render used, not just the
                            // verdict. A fresh run also emits asset_condition, snapshot and
                            // context_patch as separate SSE events; storing only the verdict meant a
                            // reused analysis could never be a clone of the original -- no Live data
                            // chapter, no asset-health band, no station/assetType fill. Replaying the
                            // same blocks is what makes "reused" mean the same answer, not a subset.
                            try
                            {
                                JObject _store = new JObject();
                                _store["verdict"] = vObj;
                                // BuildAssetCondition() is the same call the fresh path makes.
                                // (_assetCondition and _incF were my invention -- neither exists.)
                                JObject _acStore = BuildAssetCondition();
                                if (_acStore != null) { _store["asset_condition"] = _acStore; }
                                if (_snapshotRetrievedAt != DateTime.MinValue)
                                {
                                    JObject _ss = new JObject();
                                    _ss["retrievedAt"] = _snapshotRetrievedAt.ToString("dd/MM/yyyy HH:mm:ss");
                                    DateTime _incStore;
                                    if (_prefetchCtx != null
                                        && TryParseAlertTime(GetCtx(_prefetchCtx, "time"), out _incStore)
                                        && _incStore != DateTime.MinValue)
                                    { _ss["ageFromIncidenceSec"] = (long)(_snapshotRetrievedAt - _incStore).TotalSeconds; }
                                    if (_snapshotValues != null && _snapshotValues.Count > 0) { _ss["values"] = _snapshotValues; }
                                    _store["snapshot"] = _ss;
                                }
                                JObject _cp = new JObject();
                                string _cs = GetCtx(_prefetchCtx, "station");
                                string _ca = GetCtx(_prefetchCtx, "assetType");
                                string _cr = GetCtx(_prefetchCtx, "resetTime");
                                if (_cs.Length > 0) { _cp["station"] = _cs; }
                                if (_ca.Length > 0) { _cp["assetType"] = _ca; }
                                if (_cr.Length > 0) { _cp["resetTime"] = _cr; }
                                if (_cp.Count > 0) { _store["context_patch"] = _cp; }
                                _lastResponseFull = _store.ToString(Newtonsoft.Json.Formatting.None);
                            }
                            catch { }
                            // v1.0.160.146: SAY WHAT THE VERDICT WAS. The SSE path logs the row open,
                            // the tool calls and the completion size -- and never the verdict itself.
                            // So a run that produced INCONCLUSIVE/0%/blank and a run that produced a
                            // full answer look identical in the log, and the only way to tell them
                            // apart is to have been watching the screen. That is the third time this
                            // week a missing log line has cost a round of guessing.
                            try
                            {
                                string _vv = vObj["verdict"] != null ? vObj["verdict"].ToString() : "(none)";
                                string _vc = vObj["confidence"] != null ? vObj["confidence"].ToString() : "-";
                                string _vl = vObj["likely_cause"] != null ? vObj["likely_cause"].ToString() : "";
                                bool _thin = (_vv == "(none)" || _vv.Length == 0 || _vl.Length == 0);
                                AiLog(_thin ? "WARN" : "INFO", "VERDICT",
                                    "verdict=" + _vv + " confidence=" + _vc
                                    + " likely_cause=" + (_vl.Length > 0 ? Trunc(_vl, 60) : "(EMPTY)")
                                    + " fields=" + vObj.Count
                                    + " payload=" + (_lastResponseFull != null ? _lastResponseFull.Length : 0) + " chars"
                                    + (_thin ? " -- THIN VERDICT, the model returned little or nothing usable" : ""));
                            }
                            catch { }
                            try
                            {
                                WriteSse("stats", new {
                                    tokIn = _trTokIn, tokOut = _trTokOut,
                                    cacheRead = _trTokCacheRead, cacheWrite = _trTokCacheWrite,
                                    modelMs = _trModelMs, toolMs = _trToolMs, discoveryMs = _trDiscoveryMs
                                });
                            }
                            catch { }
                            try
                            {
                                if (_trendCandidate != null)
                                {
                                    // v1.0.152.0: multi-series frame + deterministic train mask.
                                    JObject tf = BuildTrendFrame();
                                    WriteSse("trend", tf);   // v1.0.146.0: real telemetry for the viz
                                }
                                else
                                {
                                    AiLog("INFO", "TREND", "no series captured this run (chart falls back to modelled shape)");
                                }
                            }
                            catch { }
                            try
                            {
                                _lastVerdictSummary = new JObject();
                                _lastVerdictSummary["verdict"] = vObj["verdict"];
                                _lastVerdictSummary["confidence"] = vObj["confidence"];
                                _lastVerdictSummary["category"] = vObj["category"];
                                _lastVerdictSummary["headline"] = vObj["headline"];
                            }
                            catch { }
                        }
                        else
                        {
                            AiLog("WARN", "VERDICT", "popup verdict failed validation: " + vReason);
                            LogRejectedReply(fullText);   // v1.0.137.0
                            WriteSse("error", new { message = "Verdict failed validation: " + vReason });
                        }
                    }
                    else
                    {
                        AiLog("WARN", "VERDICT", "popup verdict was not JSON");
                        LogRejectedReply(fullText);   // v1.0.137.0
                        WriteSse("error", new { message = "Verdict was not valid JSON." });
                    }
                }
                    if (_jsonCapture != null)
                    {
                        // lossless: capture the untouched turn text; no chunking
                        _jsonCapture.Append(fullText);
                    }
                    else
                    {
                        // The joining space lives INSIDE a chunk, so when a chunk was
                        // flushed the next one started bare and the browser concatenated
                        // them with no gap ("threshold4.67"). Carry the boundary space
                        // into the next chunk.
                        string[] words = fullText.Split(' ');
                        StringBuilder chunk = new StringBuilder();
                        bool emittedAny = false;
                        for (int w = 0; w < words.Length; w++)
                        {
                            if (chunk.Length > 0) { chunk.Append(' '); }
                            else if (emittedAny) { chunk.Append(' '); }
                            chunk.Append(words[w]);
                            if (chunk.Length > 60 || w == words.Length - 1)
                            {
                                WriteSse("text", new { text = chunk.ToString() });
                                chunk.Clear();
                                emittedAny = true;
                            }
                        }
                    }
                }
                else if (stopReason == "end_turn")
                {
                    WriteSse("text", new { text = "[No response generated]" });
                }
                return;
            }

            WriteSse("text", new { text = "\n\n[Reached " + _maxIter + "-step limit.]" });
        }

        // -- v1.0.5 AnalyzeAlertJson -- when capture is active, SSE output is
        // redirected into a buffer instead of the HTTP response. Streaming
        // endpoints are unaffected (capture is null for them).
        private StringBuilder _jsonCapture;
        private string _jsonCaptureError;

        private void WriteSse(string type, object data)
        {
            try
            {
                JObject payload = JObject.FromObject(data);
                payload["type"] = type;
                if (_jsonCapture != null)
                {
                    // text is captured losslessly at the fullText site in the loop;
                    // here only record the first error and swallow everything else.
                    if (type == "error" && payload["message"] != null && _jsonCaptureError == null)
                    {
                        _jsonCaptureError = payload["message"].ToString();
                    }
                    return; // never touch Response in capture mode
                }
                Response.Write("data: " + payload.ToString(Formatting.None) + "\n\n");
                Response.Flush();
            }
            catch { }
        }

        private static List<JObject> TrimHistory(List<JObject> messages, int maxTurns)
        {
            if (messages.Count <= 2 || maxTurns <= 0) return messages;
            List<int> realUserIdx = new List<int>();
            for (int i = 0; i < messages.Count; i++)
            {
                if (messages[i]["role"] == null || messages[i]["role"].ToString() != "user") continue;
                JToken c = messages[i]["content"];
                bool isToolResult = false;
                JArray arr = c as JArray;
                if (arr != null && arr.Count > 0 && arr[0]["type"] != null)
                    isToolResult = arr[0]["type"].ToString() == "tool_result";
                if (!isToolResult) realUserIdx.Add(i);
            }
            if (realUserIdx.Count <= maxTurns) return messages;
            return messages.Skip(realUserIdx[realUserIdx.Count - maxTurns]).ToList();
        }

        private static int EstimateTokens(IEnumerable<object> messages, string system)
        {
            int total = Chars(system);
            foreach (object msg in messages)
            {
                JObject j;
                JObject jo = msg as JObject;
                j = jo != null ? jo : JObject.FromObject(msg);
                JToken c = j["content"];
                if (c == null) continue;
                if (c.Type == JTokenType.String)
                    total += Chars(c.ToString());
                else if (c.Type == JTokenType.Array)
                    foreach (JToken b in (JArray)c)
                    {
                        string t = b["type"] != null ? b["type"].ToString() : "";
                        if (t == "text" && b["text"] != null) total += Chars(b["text"].ToString());
                        if (t == "tool_use" && b["input"] != null) total += Chars(JsonConvert.SerializeObject(b["input"]));
                        if (t == "tool_result" && b["content"] != null) total += Chars(b["content"].ToString());
                    }
            }
            return total;
        }

        private static int Chars(string s)
        {
            if (string.IsNullOrEmpty(s)) return 0;
            return (int)Math.Ceiling(s.Length / 4.0);
        }

        // Resolve India Standard Time (Asia/Kolkata, UTC+05:30) once, with fallbacks
        // so it works on Windows ("India Standard Time"), Linux/ICU ("Asia/Kolkata"),
        // or a hard-coded +05:30 offset if the OS has no tz database entry.
        private static readonly Lazy<TimeZoneInfo> _istZone =
            new Lazy<TimeZoneInfo>(ResolveIstZone);

        private static TimeZoneInfo ResolveIstZone()
        {
            try { return TimeZoneInfo.FindSystemTimeZoneById("India Standard Time"); }
            catch { }
            try { return TimeZoneInfo.FindSystemTimeZoneById("Asia/Kolkata"); }
            catch { }
            return TimeZoneInfo.CreateCustomTimeZone(
                "IST", TimeSpan.FromMinutes(330), "India Standard Time", "IST");
        }

        private static string BuildDateAnchor()
        {
            DateTime utcNow = DateTime.UtcNow;
            DateTime istNow = TimeZoneInfo.ConvertTimeFromUtc(utcNow, _istZone.Value);

            // -- v1.0.81.0 -- HOUR granularity, deliberately. Second-precision here
            // put a value that changes every second INTO the cached system block, so
            // Anthropic's prompt cache never matched the prefix across the turns of an
            // analysis (0 cache reads, full ~7.8k-token prefix re-sent each turn). The
            // model only needs "now" for relative window reasoning (the alert's own
            // incidence time comes from the evidence block, not here), so rounding to
            // the hour is analytically identical for a 2-turn run seconds apart and
            // restores caching. Round DOWN to the hour so the string is stable within
            // the hour.
            DateTime istHour = new DateTime(istNow.Year, istNow.Month, istNow.Day,
                istNow.Hour, 0, 0, DateTimeKind.Unspecified);
            string edgexIst = istHour.ToString("ddMMyyyy") + "_" + istHour.ToString("HHmmss");

            return "\n\n=== CURRENT DATE/TIME ===\n"
                 + "Today in India (Asia/Kolkata, IST, UTC+05:30) is "
                 + istNow.ToString("yyyy-MM-dd") + " (about " + istHour.ToString("HH:00") + " IST).\n"
                 + "The EdgeX data source stores and returns ALL timestamps in IST (+05:30) "
                 + "e.g. fields like TimestampEdgeX / TimestampLocal / TimestampDevice / TimestampEvent "
                 + "look like \"2026-07-10T19:11:53+05:30\". Do NOT convert these; they are already IST.\n"
                 + "EdgeX timestamp for \"now\" (IST, hour-rounded): " + edgexIst + "\n"
                 + "Current IST 'now' as ISO (hour-rounded): " + istHour.ToString("yyyy-MM-ddTHH:00:00") + "+05:30\n"
                 + "Interpret the user's 'today', 'yesterday', 'last hour' in IST, and "
                 + "ALWAYS present dates and times to the user in IST (Asia/Kolkata, UTC+05:30).\n"
                 + "CRITICAL: When a tool accepts a time range / from / to / start / end / window / period "
                 + "parameter, ALWAYS pass EXPLICIT values computed from the IST 'now' above. "
                 + "Do NOT rely on a tool's default 'now' or omit the end time - the server computes its "
                 + "default in UTC, which is 5h30m behind IST and produces a wrong report window and "
                 + "'Report Generated' stamp. e.g. for 'last 1 hour' pass from="
                 + istNow.AddHours(-1).ToString("yyyy-MM-ddTHH:mm:ss") + "+05:30 to="
                 + istNow.ToString("yyyy-MM-ddTHH:mm:ss") + "+05:30 .\n"
                 + "If a tool result shows a 'Report Period' end or 'Report Generated' time that is about "
                 + "5.5 hours behind the IST 'now' above, it is a UTC server value: add 5h30m and label it IST "
                 + "when you present it (do NOT alter the individual alert incidence times, which are already IST).\n"
                 //+ "Ignore any zero/epoch timestamps like \"0001-01-01T00:00:00+00:00\" - they mean the value was never set.\n"
                 + "Do NOT infer a date from training data.\n"
                 + "ALWAYS call a tool before speculating about data availability.\n"
                 + "=== END CURRENT DATE/TIME ===";
        }

        // v1.0.115.0: keep only clearly-unrelated topics. Removed keywords that mis-fired on
        // legitimate railway follow-ups: "translate" (users ask for Hindi), "weather" (relevant to
        // track/ballast condition and a feature in progress), "email"/"math"/"news"/"time in"
        // (substring-matched innocent words like "email the report", "estimate", "renews"). The
        // remaining list is genuinely off-domain; even these now get a SOFT redirect, not a canned
        // "not trained" line, and the alert context is preserved for the next question.
        private static readonly string[] OutOfScope = new string[]
        {
            "recipe","cook","poem","write a joke","tell me a joke","tell a joke",
            "capital of","python error","2+2","bitcoin price","stock price"
        };

        private static bool IsOutOfScope(string text)
        {
            if (string.IsNullOrEmpty(text)) return false;
            string lower = text.ToLowerInvariant();
            for (int i = 0; i < OutOfScope.Length; i++)
                if (lower.Contains(OutOfScope[i])) return true;
            return false;
        }

        // Directing train or signalling movements is the thing that must never be
        // produced. This list is applied to EVERY field.
        private static readonly Regex OpPattern = new Regex(
            @"\b(allow train|hold train|dispatch|send train|clear signal|" +
            @"change aspect|throw point|operate point)\b",
            RegexOptions.IgnoreCase | RegexOptions.Compiled);

        // Advisory / system-action words. These are ONLY suppressed in the
        // recommended_action field. They were previously applied everywhere, which
        // wiped out factual EVIDENCE lines: "reset", "should" and "must" are
        // ordinary analytical words -- "the alert reset at 12:02" is an
        // observation, not an instruction -- and a matching line was replaced
        // wholesale by the refusal text.
        private static readonly Regex OpPatternAdvisory = new Regex(
            @"\b(should|must|acknowledge alert|ack alert|override)\b",
            RegexOptions.IgnoreCase | RegexOptions.Compiled);

        private const string _opRefusal =
            "I cannot make that determination. Operational decisions belong to the section controller.";

        private static string FilterOperationalActions(string text)
        {
            if (text != null && OpPattern.IsMatch(text)) { return _opRefusal; }
            return text;
        }

        // recommended_action is where operational advice would actually appear, so
        // it carries the wider net as well.
        // v1.0.160.165: monitoring/telemetry WORK sentences. The action field is what a technician
        // is sent to do, and that is railway signalling work only. Matches the instruction, not the
        // noun: "modem" inside a diagnosis is fine, "check the modem" as an action is not.
        private static readonly Regex _monActionRx = new Regex(
            @"\b(?:check|inspect|verify|test|replace|restart|reboot|reset|reseat|swap|raise|report|"
          + @"escalate|clear|acknowledge|ack|chase|follow\s+up|contact|inform)\b[^.;]*?"
          + @"\b(?:modem|OFC|4G|GSM|SIM|RSSI|signal\s+strength|gateway|MQTT|TCP|broker|"
          + @"A10|ADC|datalogger|data\s+logger|telemetry|monitoring(?:\s+team)?|RDPMS|EdgeX|"
          + @"DataReceiver|LogWatch|ingestion|network|connectivity|stale\s+alerts?)\b",
            RegexOptions.IgnoreCase | RegexOptions.Compiled);

        private const string _noRailwayAction =
            "No railway field action follows from this alert.";

        // Strip monitoring-work sentences from an action, keeping the railway ones. When nothing
        // railway-side survives, say so plainly rather than leaving an empty or half-sentence field.
        private static string FilterMonitoringAction(string text)
        {
            if (string.IsNullOrEmpty(text)) { return text; }
            string[] parts = text.Split(new char[] { ';', '.' }, StringSplitOptions.RemoveEmptyEntries);
            StringBuilder kept = new StringBuilder();
            for (int i = 0; i < parts.Length; i++)
            {
                string p = parts[i].Trim();
                if (p.Length == 0)
                {
                    continue;
                }
                if (_monActionRx.IsMatch(p))
                {
                    continue;
                }
                if (kept.Length > 0)
                {
                    kept.Append("; ");
                }
                kept.Append(p);
            }
            if (kept.Length == 0)
            {
                return _noRailwayAction;
            }
            string outp = kept.ToString();
            // Stripping the FIRST clause can leave the field starting mid-sentence
            // ("inspect point machine slide chairs") -- restore the capital.
            if (outp.Length > 0 && char.IsLower(outp[0]))
            {
                outp = char.ToUpperInvariant(outp[0]) + outp.Substring(1);
            }
            if (!outp.EndsWith(".") && !outp.EndsWith(";"))
            {
                outp = outp + ".";
            }
            return outp;
        }

        private static string FilterRecommendedAction(string text)
        {
            if (text == null) { return null; }
            if (OpPattern.IsMatch(text) || OpPatternAdvisory.IsMatch(text)) { return _opRefusal; }
            // v1.0.160.165: railway-only scope for the instruction (owner rule).
            return FilterMonitoringAction(text);
        }

        // Exception TYPE plus a redacted, truncated message. Types are safe to expose
        // and name the fault; the message is redacted through the same filter used for
        // prompts so nothing sensitive rides along. Includes the innermost exception,
        // which is where an await usually hides the real cause.
        // OPTIONAL PARAMETERS DO NOT SURVIVE AN ASSEMBLY MISMATCH.
        // C# bakes the default into the CALL SITE, so compiling against
        // AnthropicClient 1.0.1.0 emits a 4-argument call even where the source
        // passes three. If the deployed Domain.dll still has the 3-parameter method,
        // the JIT throws MissingMethodException on the FIRST model call and the whole
        // analysis dies with nothing but "internal error" -- which is exactly what
        // happened, and it cost a full deploy cycle to identify.
        //
        // Fall back through reflection to the old signature so a mismatched deploy
        // degrades to "works, without prompt caching" instead of failing outright,
        // and says so once in the log.
        private static volatile bool _aiCacheParamMissing;
        private static System.Reflection.MethodInfo _aiSend3;

        // v1.0.108.0: translate the ALREADY-SANITIZED verdict into Hinglish (Romanized Hindi)
        // and attach it as verdictObj["hi"]. Runs AFTER ValidateAndSanitizeVerdict, so every
        // string it sees has already passed FilterOperationalActions + TrimWords - the Hinglish
        // therefore inherits that safety and cannot introduce an operational directive. Only the
        // display text fields are translated; verdict/confidence/category/viz stay as-is. A
        // separate single-shot model call with NO tools. Best-effort - the caller swallows any
        // failure and ships the English verdict unchanged.
        // v1.0.111.0: translate the SANITIZED verdict into Hinglish and attach as v["hi"].
        // Hardened per review: takes a cancellation token, runs the single translation call under
        // the shared AI lock (the model clients' thread-safety is unverified) with its OWN short
        // timeout, and records its tokens/time into the trace counters so the reported cost is
        // honest. It extracts the assistant text from the RAW API reply correctly (content blocks),
        // and re-runs the operational-action filter on the output. recommended_action is NOT
        // translated - it stays English until Hinglish directive filtering is mechanically reliable,
        // so the one field that could carry a movement instruction is always filter-checked English.
        private async Task AttachHinglishAsync(JObject v, System.Threading.CancellationToken ct)
        {
            if (v == null) { return; }
            // sanitized display strings to translate - NOTE: recommended_action intentionally excluded
            JObject src = new JObject();
            string[] trFields = { "headline", "likely_cause", "caveats" };
            for (int i = 0; i < trFields.Length; i++)
            {
                JToken t = v[trFields[i]];
                if (t != null && t.Type == JTokenType.String && t.ToString().Length > 0) { src[trFields[i]] = t.ToString(); }
            }
            JArray ev = v["evidence"] as JArray;
            if (ev != null && ev.Count > 0) { src["evidence"] = ev; }
            if (src.Count == 0) { return; }

            string sys =
                "You are a translator for Indian Railway signalling staff. Translate the given verdict fields "
                + "into HINGLISH (Romanized Hindi in Latin script, the way railway field staff speak - NOT "
                + "Devanagari). RULES: (1) Keep every technical term, tag name, and abbreviation as-is in Latin "
                + "(Ir, If, TPR, RRAIL, IBALST, mA, V, ballast, glued joint, threshold, CONFIRMED, NOT_CONFIRMED, "
                + "INCONCLUSIVE). (2) Keep ALL numbers, units and values EXACTLY unchanged. (3) Translate ONLY - "
                + "do not add, remove, soften or invent any content, and never add an operational instruction. "
                + "(4) Natural field engineer tone. Return ONLY a JSON object with the SAME keys as the input "
                + "(headline, likely_cause, caveats as strings; evidence as an array of strings). No preamble, "
                + "no markdown, no extra keys.";
            object[] messages = new object[]
            {
                new { role = "user", content = "Translate these verdict fields to Hinglish. Return only the JSON object:\n" + src.ToString(Formatting.None) }
            };

            // dedicated short timeout for the translation, linked to the caller's token
            string raw = null;
            System.Diagnostics.Stopwatch swHi = System.Diagnostics.Stopwatch.StartNew();
            using (System.Threading.CancellationTokenSource hiCts = System.Threading.CancellationTokenSource.CreateLinkedTokenSource(ct))
            {
                hiCts.CancelAfter(TimeSpan.FromSeconds(_hindiTimeoutSec));
                // v1.0.112.0: actually SERIALIZE against the shared model client. The previous
                // WithClientLock(..., mustOwn:false) SKIPPED the lock (mustOwn=false short-circuits
                // it), and AwaitWithCancel registers background-abandonment against _jsonBgReserved
                // - which this call never reserved, so it must NOT be used here. Take _aiLock
                // directly (honouring _serializeClients), observe the timeout, and always release.
                bool locked = false;
                try
                {
                    if (_serializeClients)
                    {
                        locked = await _aiLock.WaitAsync(_clientLockMs, hiCts.Token).ConfigureAwait(false);
                        if (!locked)
                        {
                            AiLog("WARN", "HI", "translation client lock timeout - skipping Hinglish (English verdict unaffected)");
                            return;
                        }
                    }
                    hiCts.Token.ThrowIfCancellationRequested();
                    raw = await CallModelAsync(messages, new object[0], sys).ConfigureAwait(false);
                }
                finally
                {
                    if (locked) { _aiLock.Release(); }
                    swHi.Stop();
                }
            }
            if (string.IsNullOrEmpty(raw)) { return; }

            // token/time accounting - the translation is a SECOND paid call; record it so the
            // trace does not under-report cost (turns is incremented too, so turns=1 is not a lie).
            if (_traceActive)
            {
                _trModelMs += swHi.ElapsedMilliseconds;
                _trTurns++;
                JObject u = ReadUsage(raw);
                if (u != null)
                {
                    _trTokIn += ReadLong(u, "input_tokens");
                    _trTokOut += ReadLong(u, "output_tokens");
                    _trTokCacheRead += ReadLong(u, "cache_read_input_tokens");
                    _trTokCacheWrite += ReadLong(u, "cache_creation_input_tokens");
                }
            }

            // extract the assistant TEXT from the raw API reply (content blocks) - CallModelAsync
            // returns the full envelope, not the text.
            string outText = ExtractAssistantText(raw);
            if (string.IsNullOrEmpty(outText)) { return; }
            if (outText.IndexOf("```", StringComparison.Ordinal) >= 0)
            { outText = outText.Replace("```json", "").Replace("```", "").Trim(); }

            JObject hi = null;
            try { hi = JObject.Parse(outText); }
            catch { hi = ExtractFirstJsonObject(outText); }
            if (hi == null) { return; }

            // belt-and-braces: re-run the operational-action filter on the Hinglish output.
            JObject hiClean = new JObject();
            for (int i = 0; i < trFields.Length; i++)
            {
                JToken t = hi[trFields[i]];
                if (t != null && t.Type == JTokenType.String)
                { hiClean[trFields[i]] = ScrubPlatformInternals(FilterOperationalActions(t.ToString()), "hi." + trFields[i]); }
            }
            JArray hiEv = hi["evidence"] as JArray;
            if (hiEv != null)
            {
                JArray outEv = new JArray();
                for (int i = 0; i < hiEv.Count; i++)
                {
                    if (hiEv[i] != null && hiEv[i].Type == JTokenType.String)
                    { outEv.Add(ScrubPlatformInternals(FilterOperationalActions(hiEv[i].ToString()), "hi.evidence")); }
                }
                if (outEv.Count > 0) { hiClean["evidence"] = outEv; }
            }
            // carry the English recommended_action into the hi block UNCHANGED, clearly marked,
            // so the card can show it under the Hinglish section without an unfiltered translation.
            if (v["recommended_action"] != null && v["recommended_action"].Type == JTokenType.String)
            { hiClean["recommended_action_en"] = ScrubPlatformInternals(v["recommended_action"].ToString(), "hi.recommended_action_en"); }
            if (hiClean.Count > 0) { v["hi"] = hiClean; }
        }

        // Extract concatenated assistant text ("text" content blocks) from a raw Anthropic reply.
        private static string ExtractAssistantText(string raw)
        {
            if (string.IsNullOrEmpty(raw)) { return null; }
            try
            {
                JObject resp = JObject.Parse(raw);
                JArray content = resp["content"] as JArray;
                if (content == null) { return null; }
                StringBuilder sb = new StringBuilder();
                foreach (JToken block in content)
                {
                    string t = block["type"] != null ? block["type"].ToString() : "";
                    if (t == "text" && block["text"] != null) { sb.Append(block["text"].ToString()); }
                }
                return sb.ToString();
            }
            catch { return null; }
        }

        // v1.0.128.0: model-call retry. CallModelAsync now wraps CallModelOnceAsync (the raw
        // single call, below) and retries a TRANSIENT failure before it becomes a model_error.
        // Never retries ClientBusyException (that is 503 backpressure) or cancellation, and skips
        // the retry once elapsed exceeds the budget, so a slow-failing call cannot double the
        // latency or hold _aiLock too long. Call sites are unchanged. Config (all optional):
        // AnalyzeModelRetries (default 1), AnalyzeModelRetryBackoffMs (1500), AnalyzeModelRetryMaxElapsedMs (15000).
        // v1.0.160.181: name the REAL cause of a model-call failure. ex.Message on an
        // HttpRequestException is the generic "An error occurred while sending the request.";
        // the actual reason -- DNS failure, outbound 443 blocked, TLS handshake, dead host --
        // lives in the INNER exception chain, which the old log line threw away (it logged only
        // SanitizeJsonError(ex.Message), flattened to "internal error"). This walks the whole
        // chain to the SERVER log (never the client -- H4 unchanged), surfacing the decisive
        // fields: SocketException.SocketErrorCode (HostNotFound=DNS, ConnectionRefused/TimedOut=
        // firewall/dead host) and WebException.Status (TrustFailure/SecureChannelFailure=TLS/CA).
        private static string DescribeException(Exception ex)
        {
            System.Text.StringBuilder sb = new System.Text.StringBuilder();
            int depth = 0;
            for (Exception e = ex; e != null && depth < 8; e = e.InnerException, depth++)
            {
                if (depth > 0) { sb.Append(" <- "); }
                sb.Append(e.GetType().Name).Append(": ").Append(e.Message);
                System.Net.Sockets.SocketException se = e as System.Net.Sockets.SocketException;
                if (se != null) { sb.Append(" [SocketError=").Append(se.SocketErrorCode).Append("]"); }
                System.Net.WebException we = e as System.Net.WebException;
                if (we != null) { sb.Append(" [WebStatus=").Append(we.Status).Append("]"); }
            }
            return sb.ToString();
        }

        private static readonly int _modelRetries = ClampCfg(ReadInt("AnalyzeModelRetries", 1), 0, 3);
        private static readonly int _modelRetryBackoffMs = ClampCfg(ReadInt("AnalyzeModelRetryBackoffMs", 1500), 250, 10000);
        private static readonly int _modelRetryMaxElapsedMs = ClampCfg(ReadInt("AnalyzeModelRetryMaxElapsedMs", 15000), 2000, 60000);

        private async Task<string> CallModelAsync(object[] messages, object[] tools, string systemPrompt)
        {
            int attempts = 1 + _modelRetries;
            System.Diagnostics.Stopwatch swRetry = System.Diagnostics.Stopwatch.StartNew();
            for (int a = 0; a < attempts; a++)
            {
                try
                {
                    return await CallModelOnceAsync(messages, tools, systemPrompt).ConfigureAwait(false);
                }
                catch (ClientBusyException) { throw; }          // 503 backpressure, not transient
                catch (OperationCanceledException) { throw; }    // cancellation, not transient
                catch (MissingMethodException) { throw; }        // DLL mismatch, handled in CallModelOnceAsync
                catch (Exception ex)
                {
                    // v1.0.160.181: log the TRUE cause (inner chain) to the server log before the
                    // message is sanitized to "internal error". This is the line that names DNS vs
                    // firewall vs TLS vs dead-host for a bytesRecv=0 connection failure.
                    AiLog("ERROR", "AI", "model call exception [engine=" + (_provider ?? "?")
                        + "]: " + DescribeException(ex));
                    bool more = (a + 1) < attempts;
                    if (!more || swRetry.ElapsedMilliseconds > _modelRetryMaxElapsedMs)
                    {
                        AiLog("WARN", "AI", "model call failed, no retry" +
                            (more ? " (past retry budget)" : "") + ": " + SanitizeJsonError(ex.Message));
                        throw;
                    }
                    AiLog("WARN", "AI", "model call transient failure, retry " + (a + 1) + "/" +
                        (attempts - 1) + " after " + _modelRetryBackoffMs + "ms: " + SanitizeJsonError(ex.Message));
                    await Task.Delay(_modelRetryBackoffMs).ConfigureAwait(false);
                }
            }
            return null; // unreachable: the loop either returns or throws
        }

        // v1.0.158.0: per-model client cache for the NEXUS/ORION variants (they reuse the
        // anthropic/openai transport but with a different model string). Keyed by model so we
        // build each variant once, not per call.
        private static readonly System.Collections.Concurrent.ConcurrentDictionary<string, object> _variantClients
            = new System.Collections.Concurrent.ConcurrentDictionary<string, object>(StringComparer.OrdinalIgnoreCase);

        private Task<string> CallModelOnceAsync(object[] messages, object[] tools, string systemPrompt)
        {
            string modelOverride = AnalysisModelOverride;   // v1.0.158.0: NEXUS/ORION variant model string, else null
            if (UseDeepSeek)
            {
                // DeepSeek is OpenAI-compatible and caches repeated prefixes automatically.
                // v1.0.160.42: this branch previously ignored modelOverride (only the Anthropic and
                // OpenAI branches honoured it), so QUANTUM 1.1 would have run the base PRO model.
                // Variant clients are cached per model+thinking+maxTokens: PRO/FLASH x THINK/NO-THINK.
                bool think = ThinkOn;
                bool dsDefaultThink = ReadBool("DeepSeekThinking", false);
                if (string.IsNullOrEmpty(modelOverride) && think == dsDefaultThink)
                {
                    DeepSeekClient dc0 = _synthesisMode ? _deepseekSynth.Value : _deepseek.Value;
                    return dc0.SendMessageAsync(messages, tools, systemPrompt);
                }
                string dsModel = string.IsNullOrEmpty(modelOverride) ? ReadStr("DeepSeekModel", "deepseek-v4-pro") : modelOverride;
                int dsMax = _synthesisMode ? ClampCfg(ReadInt("AnalyzeSynthesisMaxTokens", 1200), 400, 4000) : ReadInt("DeepSeekMaxTokens", 8096);
                string dsKey = "ds:" + dsModel + ":" + (think ? "1" : "0") + ":" + dsMax;
                DeepSeekClient dc = (DeepSeekClient)_variantClients.GetOrAdd(dsKey, k =>
                    new DeepSeekClient(
                        ConfigurationManager.AppSettings["DeepSeekApiKey"],
                        dsModel,
                        dsMax,
                        ReadStr("DeepSeekBaseUrl", "https://api.deepseek.com/v1"),
                        think));
                return dc.SendMessageAsync(messages, tools, systemPrompt);
            }
            if (UseOpenAi)
            {
                // no cache_control plumbing here: OpenAI caches repeated prefixes
                // automatically, so there is nothing to pass.
                OpenAiClient oc;
                if (!string.IsNullOrEmpty(modelOverride))   // ORION 1.6/1.7 -> GPT-5.6 / Sol (or configured)
                {
                    oc = (OpenAiClient)_variantClients.GetOrAdd("oai:" + modelOverride, k =>
                        new OpenAiClient(
                            ConfigurationManager.AppSettings["OpenAiApiKey"],
                            modelOverride,
                            _synthesisMode ? ClampCfg(ReadInt("AnalyzeSynthesisMaxTokens", 1200), 400, 4000) : ReadInt("AnthropicMaxTokens", 8096),
                            ReadStr("OpenAiBaseUrl", "https://api.openai.com/v1")));
                }
                else { oc = _synthesisMode ? _oaiSynth.Value : _oai.Value; }
                return oc.SendMessageAsync(messages, tools, systemPrompt);
            }

            AnthropicClient client;
            if (!string.IsNullOrEmpty(modelOverride))   // NEXUS 1.6/1.9/4.9 -> Opus 4.6 / 4.8 / Fable (or configured)
            {
                client = (AnthropicClient)_variantClients.GetOrAdd("ant:" + modelOverride, k =>
                    new AnthropicClient(
                        ConfigurationManager.AppSettings["AnthropicApiKey"],
                        modelOverride,
                        _synthesisMode ? ClampCfg(ReadInt("AnalyzeSynthesisMaxTokens", 1200), 400, 4000) : ReadInt("AnthropicMaxTokens", 8096)));
            }
            else { client = _synthesisMode ? _aiSynth.Value : _ai.Value; }
            if (!_aiCacheParamMissing)
            {
                try
                {
                    // v1.0.113.0: pass the 1-hour-TTL flag. Requires AnthropicClient 1.0.2.0+
                    // (5-arg overload). On an older DLL this throws MissingMethodException and we
                    // fall back to the 4-arg call below (5-min cache) or the 3-arg reflection path.
                    return client.SendMessageAsync(messages, tools, systemPrompt, _promptCache, _promptCache && _promptCache1h);
                }
                catch (MissingMethodException)
                {
                    // 5-arg overload absent - try the 4-arg (cacheSystem only, 5-min TTL).
                    try
                    {
                        return client.SendMessageAsync(messages, tools, systemPrompt, _promptCache);
                    }
                    catch (MissingMethodException)
                    {
                        _aiCacheParamMissing = true;
                        AiLog("ERROR", "AI",
                            "deployed AnthropicClient has no cacheSystem parameter -- Domain.dll is older "
                            + "than this controller. Continuing WITHOUT prompt caching; deploy "
                            + "AnthropicClient 1.0.2.0 to restore it (1.0.1.0 for 5-min cache only).");
                    }
                }
            }

            if (_aiSend3 == null)
            {
                _aiSend3 = client.GetType().GetMethod("SendMessageAsync",
                    new Type[] { typeof(object[]), typeof(object[]), typeof(string) });
            }
            if (_aiSend3 == null)
            {
                throw new InvalidOperationException(
                    "AnthropicClient exposes no compatible SendMessageAsync overload. Deploy Domain.dll "
                    + "built from AnthropicClient 1.0.1.0.");
            }
            return (Task<string>)_aiSend3.Invoke(client, new object[] { messages, tools, systemPrompt });
        }

        private static string DescribeFault(Exception ex)
        {
            if (ex == null) { return null; }
            Exception inner = ex;
            int guard = 0;
            while (inner.InnerException != null && guard++ < 5) { inner = inner.InnerException; }
            string msg = RedactSecretText(inner.Message ?? "");
            if (msg.Length > 200) { msg = msg.Substring(0, 200) + "..."; }
            string outerType = ex.GetType().Name;
            string innerType = inner.GetType().Name;
            return outerType == innerType
                ? outerType + ": " + msg
                : outerType + " -> " + innerType + ": " + msg;
        }

        private static string FriendlyError(Exception ex)
        {
            if (ex is AnthropicRateLimitException) return "Rate limit. Wait ~60s.";
            if (ex is AnthropicAuthException) return "Auth failed. Check web.config.";
            string msg = ex.Message ?? "";
            if (msg.Contains("529")) return "API overloaded. Try again.";
            // v1.0.160.118: a provider exception quotes the model string ("model deepseek-v4-flash
            // ..."), and this message is written straight to the client via WriteSse("error", ...).
            // Run it through the same scrub the verdict text uses instead of returning it raw.
            return ScrubEngineIdentity(msg);
        }

        // v1.0.160.118: strip vendor and model identifiers from any string bound for a browser.
        private static readonly Regex _vendorIdRx = new Regex(
            // LONGEST alternatives FIRST: regex alternation is left-biased, so a bare "deepseek"
            // listed before "deepseek-v4-flash" matches the prefix and leaves "-v4-flash" behind.
            @"\b(deepseek-[a-z0-9.\-]+|gpt-[a-z0-9.\-]+|claude-[a-z0-9.\-]+|gemini-[a-z0-9.\-]+|mistral-[a-z0-9.\-]+|llama-[a-z0-9.\-]+|grok-[a-z0-9.\-]+|qwen[a-z0-9.\-]*|anthropic|openai|deepseek|claude|gemini|mistral|llama|grok|gpt)\b",
            RegexOptions.IgnoreCase | RegexOptions.Compiled);

        private static string ScrubEngineIdentity(string v)
        {
            if (string.IsNullOrEmpty(v)) { return v; }
            if (!_vendorIdRx.IsMatch(v)) { return v; }
            return _vendorIdRx.Replace(v, "the engine");
        }
    }
}